def _normalized_rights_and_access(record: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Project a batch authorization into source-safe page-level eligibility metadata."""

    source = dict(record or {})
    allowed_uses = {
        **RIGHTS_DEFAULT["allowedUses"],
        **dict(source.get("allowedUses") or {}),
    }
    normalized: dict[str, Any] = {
        "rightsStatus": str(source.get("rightsStatus") or RIGHTS_DEFAULT["rightsStatus"]),
        "reviewStatus": str(source.get("reviewStatus") or "pending"),
        "accessClassification": "private_research",
        "allowedUses": allowed_uses,
    }
    authorization_digest = source.get("authorizationRecordDigest") or source.get("recordDigest")
    if authorization_digest:
        normalized["authorizationRecordDigest"] = str(authorization_digest)
    authorization_revision = source.get("authorizationRevision", source.get("revision"))
    if authorization_revision is not None:
        normalized["authorizationRevision"] = int(authorization_revision)
    return normalized


