    review_dir = (
        Path(private_root).expanduser().resolve()
        / "batches"
        / batch_id
        / "extraction"
        / partition
        / "review"
        / "analysis"
        / EVENT_COUNT_REPLAY_SCHEMA_VERSION
        / "localization-review"
    )
    summary_path = review_dir / "packet-summary.json"
    packet_path = review_dir / "packet.json"
    if not summary_path.exists() or not packet_path.exists():
        raise ExtractionWorkflowError("Event-localization submission references a missing packet.")
    summary = _read_json(summary_path)
    packet = _read_json(packet_path)
    if packet_digest != str(summary.get("packetDigest") or ""):
        raise ExtractionWorkflowError("Event-localization submission targets a stale packet.")
    expected = {
        (str(item.get("inputId") or ""), str(item.get("tabSystemId") or ""))
        for item in packet.get("systems") or []
    }
    normalized: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for raw_review in reviews:
        if not isinstance(raw_review, Mapping):
            raise ExtractionWorkflowError("Every event-localization review must be an object.")
        key = (str(raw_review.get("inputId") or ""), str(raw_review.get("tabSystemId") or ""))
        status = str(raw_review.get("status") or "")
        comment = str(raw_review.get("comment") or "").strip() or None
        if key not in expected or key in seen or status not in {"accept", "feedback"}:
            raise ExtractionWorkflowError("Event-localization review has an unknown or repeated target.")
        if status == "feedback" and comment is None:
            raise ExtractionWorkflowError("A requested localization correction needs a comment.")
        seen.add(key)
        normalized.append(
            {
                "inputId": key[0],
                "tabSystemId": key[1],
                "status": status,
                "comment": comment,
            }
        )
    if seen != expected:
        raise ExtractionWorkflowError("Every localization system must be reviewed before submission.")
    submission_digest = _sha256_json(
        {
            "reviewType": "event_localization",
            "batchId": batch_id,
            "partition": partition,
            "packetDigest": packet_digest,
            "reviews": normalized,
        }
    )
    submission_id = f"event-localization-submission-{submission_digest[:20]}"
    submissions_dir = review_dir / "submissions"
    submissions_dir.mkdir(parents=True, exist_ok=True)
    os.chmod(submissions_dir, 0o700)
    submission_path = submissions_dir / f"{submission_id}.jsonl"
    deduplicated = submission_path.exists()
    if not deduplicated:
        _write_jsonl(submission_path, normalized)
    elif _sha256_json(_read_jsonl(submission_path)) != _sha256_json(normalized):
        raise ExtractionWorkflowError("Existing localization submission differs from its stable ID.")
    return {
        "submissionId": submission_id,
        "submissionDigest": submission_digest,
        "reviewCount": len(normalized),
        "deduplicated": deduplicated,
        "status": "received_not_applied",
    }


