def _align_events(
    score_events: Sequence[Mapping[str, Any]],
    tab_events: Sequence[Mapping[str, Any]],
    *,
    include_movement_only: bool = False,
) -> list[dict[str, Any]]:
    """Align score pitch states to tablature events.

    General extraction keeps its conservative attack-only behavior. A complete
    human-reviewed line may opt into every sounding tab state so a tied slide or
    pedal/lever change can correspond to a changed score pitch without being
    mislabeled as a new pick.
    """

    if include_movement_only:
        tab_events = [
            event for event in tab_events if event.get("steelActions")
        ]
    else:
        tab_events = [
            event
            for event in tab_events
            if any(bool(action.get("attack", True)) for action in event.get("steelActions") or [])
        ]
    score_groups = _score_attack_groups(score_events)
    tie_continuations = sorted(
        (
            event
            for event in score_events
            if not event.get("rest")
            and "stop"
            in (
                {str(event.get("tie"))}
                if isinstance(event.get("tie"), str)
                else {str(value) for value in event.get("tie") or []}
            )
        ),
        key=lambda item: (
            int(item.get("measure") or 0),
            float(item.get("beat") or 0.0),
            str(item.get("scoreEventId") or ""),
        ),
    )
    if not score_groups or not tab_events:
        return []
    score_pitch_sets = [
        {int(item["pitchValue"]) for item in group if item.get("pitchValue") is not None} for group in score_groups
    ]
    raw_tab_pitch_sets = [
        {int(item["soundingPitchValue"]) for item in event.get("steelActions", [])} for event in tab_events
    ]

    def tied_continuations_for(
        score_index: int, score_pitches: set[int]
    ) -> list[Mapping[str, Any]]:
        current = score_groups[score_index][0]
        lower = (
            int(current.get("measure") or 0),
            float(current.get("beat") or 0.0),
        )
        upper = None
        if score_index + 1 < len(score_groups):
            following = score_groups[score_index + 1][0]
            upper = (
                int(following.get("measure") or 0),
                float(following.get("beat") or 0.0),
            )
        return [
            event
            for event in tie_continuations
            if (
                int(event.get("measure") or 0),
                float(event.get("beat") or 0.0),
            )
            > lower
            and (
                upper is None
                or (
                    int(event.get("measure") or 0),
                    float(event.get("beat") or 0.0),
                )
                < upper
            )
            and event.get("pitchValue") is not None
            and int(event["pitchValue"]) in score_pitches
        ]

    def normalize_positions(values: Sequence[float | None]) -> list[float]:
        known = [float(value) for value in values if value is not None]
        minimum = min(known) if known else 0.0
        maximum = max(known) if known else 0.0
        normalized: list[float] = []
        for index, value in enumerate(values):
            fallback = index / max(1, len(values) - 1)
            if value is None or maximum <= minimum:
                normalized.append(fallback)
            else:
                normalized.append((float(value) - minimum) / (maximum - minimum))
        return normalized

    score_positions = normalize_positions(
        [
            (
                sum(float(item["defaultX"]) for item in group if item.get("defaultX") is not None)
                / sum(item.get("defaultX") is not None for item in group)
            )
            if any(item.get("defaultX") is not None for item in group)
            else None
            for group in score_groups
        ]
    )
    tab_positions = normalize_positions(
        [
            float(event["horizontalPosition"]) if event.get("horizontalPosition") is not None else None
            for event in tab_events
        ]
    )

    def pitch_cost(tab_pitches: set[int], score_pitches: set[int]) -> float:
        if not tab_pitches or not score_pitches:
            return 1.0
        if tab_pitches.issubset(score_pitches) or score_pitches.issubset(tab_pitches):
            return 0.0
        overlap = len(tab_pitches & score_pitches)
        if overlap:
            return min(0.6, 0.2 + 0.4 * (1.0 - overlap / min(len(tab_pitches), len(score_pitches))))
        nearest = min(abs(tab_pitch - score_pitch) for tab_pitch in tab_pitches for score_pitch in score_pitches)
        return min(1.0, 0.42 + nearest / 18.0)

    if len(score_groups) == len(tab_events):
        candidate_offsets = (-24, -12, 0, 12, 24)

        def ordered_offset_score(offset: int) -> tuple[int, float, int, bool]:
            exact_count = 0
            total_cost = 0.0
            for score_pitches, raw_tab_pitches in zip(
                score_pitch_sets,
                raw_tab_pitch_sets,
                strict=True,
            ):
                adjusted = {value + offset for value in raw_tab_pitches}
                exact = (bool(adjusted) and adjusted.issubset(score_pitches)) or (
                    bool(score_pitches) and score_pitches.issubset(adjusted)
                )
                exact_count += exact
                total_cost += pitch_cost(adjusted, score_pitches)
            return exact_count, -total_cost, -abs(offset), offset == 0

        notation_offset = max(candidate_offsets, key=ordered_offset_score)
        alignments: list[dict[str, Any]] = []
        for score_index, (score_group, tab_event) in enumerate(
            zip(score_groups, tab_events, strict=True)
        ):
            score_pitches = score_pitch_sets[score_index]
            raw_tab_pitches = raw_tab_pitch_sets[score_index]
            adjusted_tab_pitches = {value + notation_offset for value in raw_tab_pitches}
            adjusted_exact = (
                bool(adjusted_tab_pitches) and adjusted_tab_pitches.issubset(score_pitches)
            ) or (bool(score_pitches) and score_pitches.issubset(adjusted_tab_pitches))
            raw_exact = (bool(raw_tab_pitches) and raw_tab_pitches.issubset(score_pitches)) or (
                bool(score_pitches) and score_pitches.issubset(raw_tab_pitches)
            )
            first_score_event = score_group[0]
            position_delta = abs(score_positions[score_index] - tab_positions[score_index])
            continuations = tied_continuations_for(score_index, score_pitches)
            event_ids = [
                event.get("scoreEventId") for event in [*score_group, *continuations]
            ]
            alignments.append(
                {
                    "eventAlignmentId": _stable_id(
                        "alignment",
                        tab_event.get("tabEventId"),
                        *event_ids,
                    ),
                    "scoreEventIds": event_ids,
                    "tabEventIds": [tab_event.get("tabEventId")],
                    "alignmentType": (
                        "sustained_pitch_change"
                        if not any(
                            bool(action.get("attack", True))
                            for action in tab_event.get("steelActions") or []
                        )
                        else "sustained_tab_event"
                        if continuations
                        else "grip"
                        if len(tab_event.get("steelActions") or []) > 1
                        else "score_note_to_tab_action"
                    ),
                    "sustainInheritedScoreEventIds": [
                        event.get("scoreEventId") for event in continuations
                    ],
                    "soundingPitchAgreement": raw_exact,
                    "notationAdjustedPitchAgreement": adjusted_exact,
                    "scoreNotationTranspositionSemitones": notation_offset,
                    "transpositionEvidenceClass": "deterministic_derivation",
                    "pitchAgreementScore": round(
                        1.0 - pitch_cost(adjusted_tab_pitches, score_pitches),
                        4,
                    ),
                    "alignmentCost": round(position_delta * 0.1, 4),
                    "alignmentMethod": (
                        "ordered_sounding_state_v1"
                        if include_movement_only
                        else "ordered_attack_group_v3"
                    ),
                    "scoreMeasure": first_score_event.get("measure"),
                    "scoreBeat": first_score_event.get("beat"),
                    "tabMeasure": tab_event.get("measure"),
                    "measureAgreement": (
                        int(tab_event["measure"]) == int(first_score_event["measure"])
                        if tab_event.get("measure") is not None
                        and first_score_event.get("measure") is not None
                        else None
                    ),
                    "scoreHorizontalPosition": round(score_positions[score_index], 7),
                    "tabHorizontalPosition": round(tab_positions[score_index], 7),
                    "evidenceClass": "deterministic_derivation",
                    "confidence": round(max(0.0, 1.0 - position_delta * 0.1), 4),
                    "reviewState": "needs_human_review",
                }
            )
        return alignments

    def monotonic_path(offset: int) -> tuple[float, list[int], list[float]]:
        tab_pitch_sets = [{value + offset for value in pitches} for pitches in raw_tab_pitch_sets]
        tab_count = len(tab_events)
        score_count = len(score_groups)
        match_costs: list[list[float]] = []
        for tab_index in range(tab_count):
            row: list[float] = []
            for score_index in range(score_count):
                pitch = pitch_cost(tab_pitch_sets[tab_index], score_pitch_sets[score_index])
                position = abs(tab_positions[tab_index] - score_positions[score_index])
                order = abs(tab_index / max(1, tab_count - 1) - score_index / max(1, score_count - 1))
                tab_measure = tab_events[tab_index].get("measure")
                score_measure = score_groups[score_index][0].get("measure")
                measure_penalty = (
                    1.0
                    if tab_measure is not None and score_measure is not None and int(tab_measure) != int(score_measure)
                    else 0.0
                )
                row.append(pitch * 0.75 + measure_penalty * 0.18 + position * 0.05 + order * 0.02)
            match_costs.append(row)
        dp = [[math.inf] * score_count for _ in range(tab_count)]
        previous_index = [[-1] * score_count for _ in range(tab_count)]
        for score_index in range(score_count):
            dp[0][score_index] = match_costs[0][score_index] + score_index * 0.015
        for tab_index in range(1, tab_count):
            for score_index in range(score_count):
                best_cost = math.inf
                best_previous = -1
                for prior_score_index in range(score_index + 1):
                    repeated_group_penalty = 0.03 if prior_score_index == score_index else 0.0
                    skipped_score_penalty = max(0, score_index - prior_score_index - 1) * 0.015
                    candidate = (
                        dp[tab_index - 1][prior_score_index]
                        + match_costs[tab_index][score_index]
                        + repeated_group_penalty
                        + skipped_score_penalty
                    )
                    if candidate < best_cost:
                        best_cost = candidate
                        best_previous = prior_score_index
                dp[tab_index][score_index] = best_cost
                previous_index[tab_index][score_index] = best_previous
        final_score_index = min(
            range(score_count),
            key=lambda index: dp[-1][index] + (score_count - index - 1) * 0.01,
        )
        total = dp[-1][final_score_index] + (score_count - final_score_index - 1) * 0.01
        path = [final_score_index]
        for tab_index in range(tab_count - 1, 0, -1):
            path.append(previous_index[tab_index][path[-1]])
        path.reverse()
        return total / max(1, tab_count), path, [match_costs[index][path[index]] for index in range(tab_count)]

    offset_scores: Counter[int] = Counter()
    for tab_index, tab_pitches in enumerate(raw_tab_pitch_sets):
        target = tab_index * (len(score_groups) - 1) / max(1, len(tab_events) - 1)
        nearby = range(
            max(0, int(math.floor(target)) - 1),
            min(len(score_groups), int(math.ceil(target)) + 2),
        )
        for score_index in nearby:
            for tab_pitch in tab_pitches:
                for score_pitch in score_pitch_sets[score_index]:
                    delta = score_pitch - tab_pitch
                    if delta in {-24, -12, 0, 12, 24}:
                        offset_scores[delta] += 1
    notation_offset = max(
        (-24, -12, 0, 12, 24),
        key=lambda value: (offset_scores[value], -abs(value), value == 0),
    )
    _average_cost, score_path, alignment_costs = monotonic_path(notation_offset)
    alignments: list[dict[str, Any]] = []
    previous_score_index = 0
    for tab_index, tab_event in enumerate(tab_events):
        raw_tab_pitches = {int(item["soundingPitchValue"]) for item in tab_event.get("steelActions", [])}
        tab_pitches = {value + notation_offset for value in raw_tab_pitches}
        baseline_score_index = score_path[tab_index]
        target = tab_index * (len(score_groups) - 1) / max(1, len(tab_events) - 1)
        exact_candidates = [
            score_index
            for score_index, score_pitches in enumerate(score_pitch_sets)
            if (
                (bool(tab_pitches) and tab_pitches.issubset(score_pitches))
                or (bool(score_pitches) and score_pitches.issubset(tab_pitches))
            )
            and (abs(score_positions[score_index] - tab_positions[tab_index]) <= 0.28 or abs(score_index - target) <= 3)
        ]
        if exact_candidates:
            same_measure_candidates = [
                index
                for index in exact_candidates
                if tab_event.get("measure") is not None
                and score_groups[index][0].get("measure") is not None
                and int(tab_event["measure"]) == int(score_groups[index][0]["measure"])
            ]
            if same_measure_candidates:
                exact_candidates = same_measure_candidates
            score_index = min(
                exact_candidates,
                key=lambda index: (
                    0.18 if index < previous_score_index else 0.0,
                    abs(score_positions[index] - tab_positions[tab_index]),
                    abs(index - target) / max(1, len(score_groups)),
                ),
            )
            position = abs(score_positions[score_index] - tab_positions[tab_index])
            order = abs(tab_index / max(1, len(tab_events) - 1) - score_index / max(1, len(score_groups) - 1))
            cost = position * 0.07 + order * 0.03
        else:
            score_index = baseline_score_index
            cost = alignment_costs[tab_index]
        previous_score_index = max(previous_score_index, score_index)
        score_pitches = score_pitch_sets[score_index]
        exact = (bool(tab_pitches) and tab_pitches.issubset(score_pitches)) or (
            bool(score_pitches) and score_pitches.issubset(tab_pitches)
        )
        raw_exact = (bool(raw_tab_pitches) and raw_tab_pitches.issubset(score_pitches)) or (
            bool(score_pitches) and score_pitches.issubset(raw_tab_pitches)
        )
        aligned_score_events = list(score_groups[score_index])
        tie_events = tied_continuations_for(score_index, score_pitches)
        aligned_score_events.extend(tie_events)
        inherited_score_event_ids: list[str] = [
            str(event.get("scoreEventId")) for event in tie_events if event.get("scoreEventId")
        ]
        sustain_requested = any(bool(action.get("sustain")) for action in tab_event.get("steelActions", []))
        if sustain_requested:
            next_score_boundary = (
                max(score_index + 1, score_path[tab_index + 1])
                if tab_index + 1 < len(tab_events)
                else len(score_groups)
            )
            for inherited_group in score_groups[score_index + 1 : next_score_boundary]:
                matching_events = [
                    event
                    for event in inherited_group
                    if event.get("pitchValue") is not None and int(event["pitchValue"]) in tab_pitches
                ]
                existing_ids = {
                    str(event.get("scoreEventId"))
                    for event in aligned_score_events
                    if event.get("scoreEventId")
                }
                new_matching_events = [
                    event
                    for event in matching_events
                    if str(event.get("scoreEventId") or "") not in existing_ids
                ]
                aligned_score_events.extend(new_matching_events)
                inherited_score_event_ids.extend(
                    str(event.get("scoreEventId"))
                    for event in new_matching_events
                    if event.get("scoreEventId")
                )
        first_score_event = aligned_score_events[0]
        alignments.append(
            {
                "eventAlignmentId": _stable_id(
                    "alignment",
                    tab_event.get("tabEventId"),
                    *[item.get("scoreEventId") for item in aligned_score_events],
                ),
                "scoreEventIds": [item.get("scoreEventId") for item in aligned_score_events],
                "tabEventIds": [tab_event.get("tabEventId")],
                "alignmentType": (
                    "sustained_tab_event"
                    if inherited_score_event_ids
                    else "grip"
                    if len(tab_event.get("steelActions", [])) > 1
                    else "score_note_to_tab_action"
                ),
                "sustainInheritedScoreEventIds": inherited_score_event_ids,
                "soundingPitchAgreement": raw_exact,
                "notationAdjustedPitchAgreement": exact,
                "scoreNotationTranspositionSemitones": notation_offset,
                "transpositionEvidenceClass": "deterministic_derivation",
                "pitchAgreementScore": round(1.0 - pitch_cost(tab_pitches, score_pitches), 4),
                "alignmentCost": round(cost, 4),
                "alignmentMethod": "monotonic_pitch_position_v2",
                "scoreMeasure": first_score_event.get("measure"),
                "scoreBeat": first_score_event.get("beat"),
                "tabMeasure": tab_event.get("measure"),
                "measureAgreement": (
                    int(tab_event["measure"]) == int(first_score_event["measure"])
                    if tab_event.get("measure") is not None and first_score_event.get("measure") is not None
                    else None
                ),
                "scoreHorizontalPosition": round(score_positions[score_index], 7),
                "tabHorizontalPosition": round(tab_positions[tab_index], 7),
                "evidenceClass": "deterministic_derivation",
                "confidence": round(max(0.0, 1.0 - cost), 4),
                "reviewState": "needs_human_review",
            }
        )
    return alignments


def _repair_repeated_score_glyph(
    *,
    score_payload: dict[str, Any],
    score_measure: int,
    tab_events: Sequence[Mapping[str, Any]],
    source_image: Image.Image,
    staff_lines: Sequence[int],
    grid: GridDetection,
    system_id: str,
) -> dict[str, Any] | None:
    """Repair one repeated score chord from an independently recognized twin glyph."""

    if len(staff_lines) != 5 or len(tab_events) < 2:
        return None
    measure_events = [
        event
        for event in score_payload.get("scoreEvents") or []
        if int(event.get("measure") or 0) == score_measure and not event.get("rest")
    ]
    score_groups: list[list[dict[str, Any]]] = []
    for _position, items in __import__("itertools").groupby(
        sorted(
            measure_events,
            key=lambda item: (
                float(item.get("beat") or 0.0),
                int(item.get("voice") or 1),
                str(item.get("pitch") or ""),
            ),
        ),
        key=lambda item: round(float(item.get("beat") or 0.0), 6),
    ):
        score_groups.append(list(items))
    if len(score_groups) != len(tab_events):
        return None
    alignments = _align_events(measure_events, tab_events)
    if len(alignments) != len(tab_events):
        return None
    valid_indices = {
        index
        for index, alignment in enumerate(alignments)
        if bool(alignment.get("notationAdjustedPitchAgreement"))
    }
    invalid_indices = [index for index in range(len(tab_events)) if index not in valid_indices]
    if not valid_indices or not invalid_indices:
        return None

    chord_contexts = sorted(
        (
            context
            for context in score_payload.get("chordContexts") or []
            if int(context.get("measure") or 0) == score_measure
        ),
        key=lambda context: float(context.get("beat") or 1.0),
    )

    def chord_symbol(beat: float) -> str | None:
        active = [
            str(context.get("symbol") or "").strip()
            for context in chord_contexts
            if float(context.get("beat") or 1.0) <= beat
            and str(context.get("symbol") or "").strip()
        ]
        return active[-1] if active else None

    gap = float(np.median(np.diff(staff_lines)))
    gray = np.asarray(source_image.convert("L"))
    y0 = max(0, int(round(float(staff_lines[0]) - gap * 2.0)))
    y1 = min(gray.shape[0], int(round(float(staff_lines[-1]) + gap * 2.0)))
    if y1 <= y0:
        return None

    def event_patch(event: Mapping[str, Any]) -> np.ndarray:
        x = int(
            round(
                grid.x0
                + float(event.get("horizontalPosition") or 0.0)
                * max(1, grid.x1 - grid.x0)
            )
        )
        half_width = max(8, int(round(gap)))
        left = max(0, x - half_width)
        right = min(gray.shape[1], x + half_width)
        patch = gray[y0:y1, left:right]
        if patch.size == 0:
            return np.zeros((160, 96), dtype=bool)
        resized = Image.fromarray(patch).resize((96, 160), Image.Resampling.BILINEAR)
        return np.asarray(resized) < 125

    patches = [event_patch(event) for event in tab_events]

    def similarity(first: np.ndarray, second: np.ndarray) -> float:
        values: list[float] = []
        for shift in range(-6, 7):
            if shift < 0:
                values.append(float(np.mean(first[:, :shift] == second[:, -shift:])))
            elif shift > 0:
                values.append(float(np.mean(first[:, shift:] == second[:, :-shift])))
            else:
                values.append(float(np.mean(first == second)))
        return max(values)

    original_events = copy.deepcopy(score_payload.get("scoreEvents") or [])
    repairs: list[dict[str, Any]] = []
    for target_index in invalid_indices:
        target_group = score_groups[target_index]
        target_beat = float(target_group[0].get("beat") or 0.0)
        target_symbol = chord_symbol(target_beat)
        candidates = [
            (
                similarity(patches[target_index], patches[reference_index]),
                reference_index,
            )
            for reference_index in valid_indices
            if (
                target_symbol is None
                or chord_symbol(float(score_groups[reference_index][0].get("beat") or 0.0))
                == target_symbol
            )
        ]
        if not candidates:
            continue
        best_similarity, reference_index = max(candidates)
        required_similarity = 0.92 if target_symbol else 0.935
        if best_similarity < required_similarity:
            continue
        reference_group = sorted(
            score_groups[reference_index],
            key=lambda event: (int(event.get("pitchValue") or 0), str(event.get("scoreEventId") or "")),
        )
        existing_group = sorted(
            target_group,
            key=lambda event: (int(event.get("pitchValue") or 0), str(event.get("scoreEventId") or "")),
        )
        rebuilt_group: list[dict[str, Any]] = []
        target_default_x = next(
            (event.get("defaultX") for event in existing_group if event.get("defaultX") is not None),
            None,
        )
        for event_index, reference in enumerate(reference_group, start=1):
            if event_index <= len(existing_group):
                rebuilt = copy.deepcopy(existing_group[event_index - 1])
            else:
                rebuilt = copy.deepcopy(existing_group[0])
                rebuilt["tie"] = []
                rebuilt["articulations"] = []
                rebuilt["phraseBoundaries"] = []
            for field in (
                "pitch",
                "pitchValue",
                "pitchStep",
                "pitchAlter",
                "octave",
            ):
                rebuilt[field] = copy.deepcopy(reference.get(field))
            existing_same_pitch = next(
                (
                    event
                    for event in existing_group
                    if event.get("pitchValue") == reference.get("pitchValue")
                ),
                None,
            )
            rebuilt["writtenAccidental"] = (
                existing_same_pitch.get("writtenAccidental") if existing_same_pitch else None
            )
            rebuilt["chordMember"] = event_index > 1
            rebuilt["defaultX"] = target_default_x
            rebuilt["scoreEventId"] = _stable_id(
                "score-event",
                system_id,
                score_measure,
                target_beat,
                event_index,
                rebuilt.get("pitch"),
                False,
            )
            rebuilt["evidenceClass"] = "deterministic_derivation"
            rebuilt["confidence"] = round(
                min(float(reference.get("confidence") or 0.9), best_similarity),
                4,
            )
            rebuilt["scoreGlyphRepair"] = {
                "method": "repeated_source_glyph_v1",
                "referenceScoreEventIds": [
                    str(event.get("scoreEventId") or "") for event in reference_group
                ],
                "sourceGlyphSimilarity": round(best_similarity, 4),
                "tabUsedAsValidatorOnly": True,
                "reviewState": "needs_human_review",
            }
            rebuilt_group.append(rebuilt)
        score_payload["scoreEvents"] = [
            event
            for event in score_payload.get("scoreEvents") or []
            if not (
                int(event.get("measure") or 0) == score_measure
                and round(float(event.get("beat") or 0.0), 6) == round(target_beat, 6)
                and not event.get("rest")
            )
        ] + rebuilt_group
        repairs.append(
            {
                "targetBeat": target_beat,
                "referenceBeat": float(reference_group[0].get("beat") or 0.0),
                "sourceGlyphSimilarity": round(best_similarity, 4),
                "sharedChordContext": target_symbol,
                "repairedNoteheadCount": len(rebuilt_group),
            }
        )

    repaired_measure_events = [
        event
        for event in score_payload.get("scoreEvents") or []
        if int(event.get("measure") or 0) == score_measure and not event.get("rest")
    ]
    repaired_alignments = _align_events(repaired_measure_events, tab_events)
    if not repairs or len(repaired_alignments) != len(tab_events) or not all(
        bool(alignment.get("notationAdjustedPitchAgreement"))
        for alignment in repaired_alignments
    ):
        score_payload["scoreEvents"] = original_events
        return None
    score_payload["scoreEvents"] = sorted(
        score_payload.get("scoreEvents") or [],
        key=lambda event: (
            int(event.get("measure") or 0),
            float(event.get("beat") or 0.0),
            int(event.get("voice") or 1),
            str(event.get("pitch") or ""),
        ),
    )
    return {
        "method": "repeated_source_glyph_v1",
        "scoreMeasure": score_measure,
        "repairCount": len(repairs),
        "repairs": repairs,
        "tabUsedAsValidatorOnly": True,
    }


def _separate_verified_alignments(
    candidates: Sequence[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Keep pitch-supported correspondences as facts and quarantine all other candidates."""

    verified: list[dict[str, Any]] = []
    unresolved: list[dict[str, Any]] = []
    for raw_candidate in candidates:
        candidate = copy.deepcopy(dict(raw_candidate))
        if bool(candidate.get("notationAdjustedPitchAgreement")):
            verified.append(candidate)
            continue
        unresolved.append(
            {
                "kind": "unverified_score_tab_alignment",
                "candidateAlignmentId": candidate.get("eventAlignmentId"),
                "scoreEventIds": copy.deepcopy(candidate.get("scoreEventIds") or []),
                "tabEventIds": copy.deepcopy(candidate.get("tabEventIds") or []),
                "candidateAlignment": candidate,
                "reason": "pitch_mismatch",
                "excludedFromNormalizedFacts": True,
                "blocking": False,
                "evidenceClass": "unknown_or_unresolved",
                "reviewState": "needs_human_review",
            }
        )
    return verified, unresolved


def _promote_confirmed_source_discrepancy(
    record: MutableMapping[str, Any],
    unresolved: list[dict[str, Any]],
    operation: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Preserve a human-confirmed mismatch without treating it as training agreement."""

    system_id = str(operation.get("scoreSystemId") or "")
    tab_event_id = str(operation.get("feedbackTargetId") or "")
    score_system = next(
        (
            system
            for system in record.get("scoreSystems") or []
            if str(system.get("scoreSystemId") or "") == system_id
        ),
        None,
    )
    if score_system is None:
        raise ExtractionWorkflowError("A source-discrepancy correction lost its score system.")
    score_events = {
        str(event.get("scoreEventId") or ""): event
        for event in score_system.get("scoreEvents") or []
    }
    paired_tab_id = str(score_system.get("pairedTabSystemId") or "")
    paired_tab = next(
        (
            system
            for system in record.get("tabSystems") or []
            if str(system.get("tabSystemId") or "") == paired_tab_id
        ),
        None,
    )
    if paired_tab is None:
        raise ExtractionWorkflowError("A source-discrepancy correction lost its tab system.")
    tab_event = next(
        (
            event
            for event in paired_tab.get("tabEvents") or []
            if str(event.get("tabEventId") or "") == tab_event_id
        ),
        None,
    )
    if tab_event is None:
        raise ExtractionWorkflowError("A source-discrepancy correction lost its tab event.")

    matches = [
        item
        for item in unresolved
        if item.get("kind") == "unverified_score_tab_alignment"
        and tab_event_id in {str(value) for value in item.get("tabEventIds") or []}
        and any(str(value) in score_events for value in item.get("scoreEventIds") or [])
    ]
    if len(matches) != 1:
        raise ExtractionWorkflowError(
            "A confirmed source discrepancy must identify exactly one proposed score/tab alignment."
        )
    unresolved_item = matches[0]
    candidate = copy.deepcopy(unresolved_item.get("candidateAlignment") or {})
    actual_score_pitches = sorted(
        {
            str(score_events[str(event_id)].get("pitch") or "")
            for event_id in candidate.get("scoreEventIds") or []
            if str(event_id) in score_events
        }
        - {""}
    )
    actual_tab_pitches = sorted(
        {
            str(action.get("soundingPitch") or "")
            for action in tab_event.get("steelActions") or []
            if str(action.get("soundingPitch") or "")
        }
    )
    expected_score_pitches = sorted(
        {str(value) for value in operation.get("expectedScorePitches") or []}
    )
    expected_tab_pitches = sorted(
        {str(value) for value in operation.get("expectedTabPitches") or []}
    )
    expert_target_pitches = sorted(
        {str(value) for value in operation.get("expertTargetPitches") or []}
    )
    if not expected_score_pitches or not expected_tab_pitches:
        raise ExtractionWorkflowError(
            "A confirmed source discrepancy must pin both printed score and sounding tab pitches."
        )
    if actual_score_pitches != expected_score_pitches or actual_tab_pitches != expected_tab_pitches:
        raise ExtractionWorkflowError("The source-discrepancy correction targets stale pitch facts.")
    if expert_target_pitches and expert_target_pitches != actual_score_pitches:
        raise ExtractionWorkflowError(
            "An expert target for a source discrepancy must pin the captured score pitches."
        )
    if bool(candidate.get("notationAdjustedPitchAgreement")):
        raise ExtractionWorkflowError("A source-discrepancy correction cannot override a matching pair.")

    discrepancy_id = _stable_id(
        "source-score-tab-discrepancy",
        system_id,
        tab_event_id,
        *actual_score_pitches,
        *actual_tab_pitches,
    )
    candidate.update(
        {
            "sourcePitchDiscrepancyConfirmed": True,
            "sourceScoreTabDiscrepancyId": discrepancy_id,
            "pitchValidationState": "human_confirmed_source_discrepancy",
            "eligibleForTransformationTraining": False,
            "expertCorrectedTargetPitches": expert_target_pitches,
            "evidenceClass": "direct_visual_observation",
            "reviewState": "needs_human_review",
        }
    )
    discrepancy = {
        "sourceScoreTabDiscrepancyId": discrepancy_id,
        "scoreSystemId": system_id,
        "scoreEventIds": copy.deepcopy(candidate.get("scoreEventIds") or []),
        "tabEventIds": [tab_event_id],
        "scorePitches": actual_score_pitches,
        "tabSoundingPitches": actual_tab_pitches,
        "expertCorrectedTargetPitches": expert_target_pitches,
        "reasonCode": str(operation.get("reasonCode") or "printed_score_tab_pitch_mismatch"),
        "evidenceClass": "explicit_text",
        "reviewState": "needs_human_review",
        "eligibleForTransformationTraining": False,
        "eligibleForMechanicalValidation": True,
    }
    unresolved.remove(unresolved_item)
    return candidate, discrepancy


def _merge_current_source_discrepancies(
    existing: Sequence[Mapping[str, Any]],
    confirmed: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Replace stale discrepancy facts that target the same score/tab relationship."""

    replacement_scopes = {
        (
            str(item.get("scoreSystemId") or ""),
            frozenset(str(value) for value in item.get("tabEventIds") or []),
        )
        for item in confirmed
    }
    current = [
        copy.deepcopy(dict(item))
        for item in existing
        if (
            str(item.get("scoreSystemId") or ""),
            frozenset(str(value) for value in item.get("tabEventIds") or []),
        )
        not in replacement_scopes
    ]
    return current + [copy.deepcopy(dict(item)) for item in confirmed]


def _replace_tab_event_from_score_audit(
    record: dict[str, Any],
    operation: Mapping[str, Any],
    *,
    feedback_id: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Replace one normalized tab event while retaining the literal source observation."""

    system_id = str(operation.get("scoreSystemId") or "")
    score_system = next(
        (
            system
            for system in record.get("scoreSystems") or []
            if str(system.get("scoreSystemId") or "") == system_id
        ),
        None,
    )
    if score_system is None:
        raise ExtractionWorkflowError("A targeted tab correction lost its score system.")
    tab_system_id = str(score_system.get("pairedTabSystemId") or "")
    tab_system = next(
        (
            system
            for system in record.get("tabSystems") or []
            if str(system.get("tabSystemId") or "") == tab_system_id
        ),
        None,
    )
    if tab_system is None:
        raise ExtractionWorkflowError("A targeted tab correction lost its paired tab system.")
    tab_event_id = str(operation.get("feedbackTargetId") or "")
    tab_event = _tab_event_for_correction(tab_system, tab_event_id)
    original_event = copy.deepcopy(tab_event)
    original_digest = _sha256_json(original_event)
    if str(operation.get("expectedTabEventDigest") or "") != original_digest:
        raise ExtractionWorkflowError("A targeted tab correction references stale tab facts.")

    replacement_specs = list(operation.get("replacementSteelActions") or [])
    if not replacement_specs:
        raise ExtractionWorkflowError("A targeted tab correction needs replacementSteelActions.")
    replacement_actions: list[dict[str, Any]] = []
    seen_strings: set[int] = set()
    operation_id = str(operation.get("operationId") or "")
    for spec in replacement_specs:
        string = int(spec.get("string") or 0)
        if string < 1 or string > 10 or string in seen_strings:
            raise ExtractionWorkflowError(
                "A targeted tab correction must use unique E9 string numbers from 1 through 10."
            )
        seen_strings.add(string)
        replacement_actions.append(
            _new_correction_action(
                record,
                tab_system,
                tab_event,
                spec,
                operation_id=operation_id,
                feedback_item_ids=[feedback_id],
            )
        )
    tab_event["steelActions"] = replacement_actions
    tab_event["candidateStrings"] = sorted(seen_strings)
    tab_event["simultaneous"] = len(replacement_actions) > 1
    tab_event["gripId"] = (
        _stable_id("grip", tab_event_id, "expert-corrected")
        if tab_event["simultaneous"]
        else None
    )
    tab_event["evidenceClass"] = "explicit_text"
    tab_event["reviewState"] = "needs_human_review"
    tab_event["eligibleForTransformationTraining"] = False
    tab_event["correctionBasisScoreAuditFeedbackIds"] = [feedback_id]
    _refresh_event_execution(tab_event)

    correction_id = _stable_id(
        "targeted-tab-correction",
        record.get("inputId"),
        tab_event_id,
        original_digest,
        replacement_specs,
        feedback_id,
    )
    original_observation = {
        "targetedTabCorrectionId": correction_id,
        "scoreSystemId": system_id,
        "tabSystemId": tab_system_id,
        "tabEventId": tab_event_id,
        "literalSourceTabEventDigest": original_digest,
        "literalSourceTabEvent": original_event,
        "correctedSteelActionRequest": copy.deepcopy(replacement_specs),
        "scoreAuditFeedbackId": feedback_id,
        "evidenceClass": "explicit_text",
        "literalObservationEvidenceClass": "direct_visual_observation",
        "reviewState": "needs_human_review",
        "priorTabApprovalSupersededForEvent": True,
        "eligibleForTransformationTraining": False,
    }
    applied = {
        "operationId": operation_id,
        "type": "replace_tab_event_with_expert_solution",
        "scoreSystemId": system_id,
        "tabSystemId": tab_system_id,
        "feedbackTargetId": tab_event_id,
        "scoreAuditFeedbackId": feedback_id,
        "targetedTabCorrectionId": correction_id,
        "expectedTabEventDigest": original_digest,
        "replacementSteelActions": copy.deepcopy(replacement_specs),
        "evidenceClass": "explicit_text",
        "reviewState": "needs_human_review",
        "priorTabApprovalSupersededForEvent": True,
        "eligibleForTransformationTraining": False,
    }
    return applied, original_observation


def _core_counts(record: Mapping[str, Any]) -> dict[str, int]:
    score_systems = list(record.get("scoreSystems") or [])
    tab_systems = list(record.get("tabSystems") or [])
    tab_events = [event for system in tab_systems for event in system.get("tabEvents", [])]
    actions = [action for event in tab_events for action in event.get("steelActions", [])]
    return {
        "pageRegionCount": len(record.get("pageRegions") or []),
        "scoreSystemCount": len(score_systems),
        "scoreEventCount": sum(len(system.get("scoreEvents", [])) for system in score_systems),
        "tabSystemCount": len(tab_systems),
        "tabEventCount": len(tab_events),
        "steelActionCount": len(actions),
        "gripCount": len(record.get("grips") or []),
        "eventAlignmentCount": len(record.get("eventAlignments") or []),
        "movementSequenceCount": len(record.get("movementSequences") or []),
        "derivedDecisionCount": len(record.get("derivedDecisions") or []),
        "teachingConceptCount": len(record.get("teachingConcepts") or []),
        "exerciseCount": len(record.get("exercises") or []),
        "unresolvedCount": len(record.get("unresolved") or []),
    }


def _collect_page_regions(
    page_id: str,
    explicit_text: Sequence[Mapping[str, Any]],
    score_systems: Sequence[Mapping[str, Any]],
    tab_systems: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    regions: dict[str, dict[str, Any]] = {}

    def add(owner_id: object, role: str, item: Mapping[str, Any]) -> None:
        coordinates = item.get("pageRegion")
        if not isinstance(coordinates, Mapping):
            return
        region_id = str(item.get("pageRegionId") or _stable_id("page-region", page_id, role, owner_id))
        regions[region_id] = {
            "pageRegionId": region_id,
            "sourcePageId": page_id,
            "sourceObjectId": owner_id,
            "role": role,
            "coordinates": copy.deepcopy(dict(coordinates)),
            "evidenceClass": "direct_visual_observation",
            "confidence": float(item.get("confidence") or item.get("detectionConfidence") or 0.9),
            "reviewState": str(item.get("reviewState") or "needs_human_review"),
        }

    for item in explicit_text:
        add(item.get("explicitTextId"), "explicit_text", item)
    for system in score_systems:
        add(system.get("scoreSystemId"), "score_system", system)
    for system in tab_systems:
        add(system.get("tabSystemId"), "tab_system", system)
        for event in system.get("tabEvents") or []:
            for action in event.get("steelActions") or []:
                add(action.get("steelActionId"), "steel_action", action)
    return list(regions.values())


def _hard_review_blockers(record: Mapping[str, Any]) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    actions = [
        action
        for system in record.get("tabSystems") or []
        for event in system.get("tabEvents", [])
        for action in event.get("steelActions", [])
    ]
    invalid_actions = [
        str(action.get("steelActionId"))
        for action in actions
        if not bool(action.get("mechanicalValidation", {}).get("valid"))
    ]
    if invalid_actions:
        blockers.append(
            {
                "kind": "invalid_mechanical_actions",
                "count": len(invalid_actions),
                "objectIds": invalid_actions,
            }
        )
    invalid_grips = [
        str(grip.get("gripId"))
        for grip in record.get("grips") or []
        if not bool(grip.get("mechanicalValidation", {}).get("valid"))
    ]
    if invalid_grips:
        blockers.append(
            {
                "kind": "invalid_mechanical_grips",
                "count": len(invalid_grips),
                "objectIds": invalid_grips,
            }
        )
    mismatched_alignments = [
        str(alignment.get("eventAlignmentId"))
        for alignment in record.get("eventAlignments") or []
        if not bool(alignment.get("notationAdjustedPitchAgreement"))
    ]
    if mismatched_alignments:
        blockers.append(
            {
                "kind": "pitch_mismatched_alignments",
                "count": len(mismatched_alignments),
                "objectIds": mismatched_alignments,
            }
        )
    classification = str(record.get("pageClassification", {}).get("primary") or "")
    score_system_count = len(record.get("scoreSystems") or [])
    tab_system_count = len(record.get("tabSystems") or [])
    if classification in {
        "score_with_aligned_tab",
        "chordal_arrangement",
        "single_note_melody",
        "harmonized_melody",
        "lick_or_fill",
        "scale_or_position_exercise",
    } and score_system_count != tab_system_count:
        blockers.append(
            {
                "kind": "score_tab_system_pairing_requires_correction",
                "scoreSystemCount": score_system_count,
                "tabSystemCount": tab_system_count,
            }
        )
    return blockers


def _region_iou(left: Mapping[str, Any], right: Mapping[str, Any]) -> float:
    left_x0 = float(left.get("x") or 0.0)
    left_y0 = float(left.get("y") or 0.0)
    left_x1 = left_x0 + float(left.get("width") or 0.0)
    left_y1 = left_y0 + float(left.get("height") or 0.0)
    right_x0 = float(right.get("x") or 0.0)
    right_y0 = float(right.get("y") or 0.0)
    right_x1 = right_x0 + float(right.get("width") or 0.0)
    right_y1 = right_y0 + float(right.get("height") or 0.0)
    intersection = max(0.0, min(left_x1, right_x1) - max(left_x0, right_x0)) * max(
        0.0,
        min(left_y1, right_y1) - max(left_y0, right_y0),
    )
    left_area = max(0.0, left_x1 - left_x0) * max(0.0, left_y1 - left_y0)
    right_area = max(0.0, right_x1 - right_x0) * max(0.0, right_y1 - right_y0)
    union = left_area + right_area - intersection
    return intersection / union if union > 0 else 0.0


def _f1(true_positive: int, predicted: int, reference: int) -> float:
    denominator = predicted + reference
    return (2.0 * true_positive / denominator) if denominator else 1.0


def _review_record_counts(machine: Mapping[str, Any], reviewed: Mapping[str, Any]) -> dict[str, int]:
    counts: Counter[str] = Counter()
    for kind in ("scoreSystems", "tabSystems"):
        machine_systems = sorted(machine.get(kind) or [], key=lambda item: int(item.get("systemIndex") or 0))
        reviewed_systems = sorted(reviewed.get(kind) or [], key=lambda item: int(item.get("systemIndex") or 0))
        counts[f"{kind}Predicted"] += len(machine_systems)
        counts[f"{kind}Reference"] += len(reviewed_systems)
        counts[f"{kind}TruePositive"] += sum(
            _region_iou(machine_system.get("pageRegion") or {}, reviewed_system.get("pageRegion") or {}) >= 0.8
            for machine_system, reviewed_system in zip(machine_systems, reviewed_systems, strict=False)
        )

    machine_scores = {
        str(event.get("scoreEventId")): event
        for system in machine.get("scoreSystems") or []
        for event in system.get("scoreEvents") or []
    }
    reviewed_scores = {
        str(event.get("scoreEventId")): event
        for system in reviewed.get("scoreSystems") or []
        for event in system.get("scoreEvents") or []
    }
    counts["scoreEventReference"] += len(reviewed_scores)
    for event_id, reviewed_event in reviewed_scores.items():
        machine_event = machine_scores.get(event_id)
        if machine_event is None:
            counts["scorePitchOrDurationChanged"] += 1
            counts["scorePitchChanged"] += 1
            counts["scoreDurationChanged"] += 1
            counts["measureAlignmentChanged"] += 1
            continue
        pitch_exact = (
            machine_event.get("pitchValue") == reviewed_event.get("pitchValue")
            and bool(machine_event.get("rest")) == bool(reviewed_event.get("rest"))
        )
        duration_exact = machine_event.get("durationBeats") == reviewed_event.get(
            "durationBeats"
        )
        counts["scorePitchExact" if pitch_exact else "scorePitchChanged"] += 1
        counts["scoreDurationExact" if duration_exact else "scoreDurationChanged"] += 1
        if (
            pitch_exact
            and duration_exact
        ):
            counts["scorePitchAndDurationExact"] += 1
        else:
            counts["scorePitchOrDurationChanged"] += 1
        if machine_event.get("measure") == reviewed_event.get("measure") and machine_event.get(
            "beat"
        ) == reviewed_event.get("beat"):
            counts["measureAlignmentExact"] += 1
        else:
            counts["measureAlignmentChanged"] += 1

    def actions(record: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
        return {
            str(action.get("pageRegionId") or action.get("steelActionId")): action
            for system in record.get("tabSystems") or []
            for event in system.get("tabEvents") or []
            for action in event.get("steelActions") or []
        }

    machine_actions = actions(machine)
    reviewed_actions = actions(reviewed)
    counts["tabActionReference"] += len(reviewed_actions)
    for action_id, reviewed_action in reviewed_actions.items():
        machine_action = machine_actions.get(action_id)
        for field, metric in (
            ("string", "stringExact"),
            ("fret", "fretExact"),
            ("controls", "controlsExact"),
        ):
            counts["atomicFieldReference"] += 1
            machine_value = machine_action.get(field) if machine_action is not None else None
            reviewed_value = reviewed_action.get(field)
            if field == "controls":
                machine_value = sorted(machine_value or [])
                reviewed_value = sorted(reviewed_value or [])
            if machine_value == reviewed_value:
                counts[metric] += 1
            else:
                counts["atomicFieldChanged"] += 1

    def alignment_map(record: Mapping[str, Any]) -> dict[tuple[str, ...], tuple[str, ...]]:
        return {
            tuple(sorted(str(value) for value in alignment.get("tabEventIds") or [])): tuple(
                sorted(str(value) for value in alignment.get("scoreEventIds") or [])
            )
            for alignment in record.get("eventAlignments") or []
        }

    machine_alignments = alignment_map(machine)
    reviewed_alignments = alignment_map(reviewed)
    counts["eventAlignmentReference"] += len(reviewed_alignments)
    counts["eventAlignmentExact"] += sum(
        machine_alignments.get(key) == value for key, value in reviewed_alignments.items()
    )

    machine_chords = {
        str(chord.get("chordContextId")): chord.get("symbol")
        for system in machine.get("scoreSystems") or []
        for chord in system.get("chordContexts") or []
    }
    reviewed_chords = {
        str(chord.get("chordContextId")): chord.get("symbol")
        for system in reviewed.get("scoreSystems") or []
        for chord in system.get("chordContexts") or []
    }
    counts["chordContextReference"] += len(reviewed_chords)
    counts["chordContextExact"] += sum(machine_chords.get(key) == value for key, value in reviewed_chords.items())

    machine_concepts = {
        (str(item.get("concept")), str(item.get("evidenceClass"))) for item in machine.get("teachingConcepts") or []
    }
    reviewed_concepts = {
        (str(item.get("concept")), str(item.get("evidenceClass"))) for item in reviewed.get("teachingConcepts") or []
    }
    counts["conceptPageAcceptedWithoutEdit"] += machine_concepts == reviewed_concepts
    counts["approvedMechanicalAction"] += sum(
        bool(action.get("mechanicalValidation", {}).get("valid")) for action in reviewed_actions.values()
    )
    counts["approvedMechanicalActionReference"] += len(reviewed_actions)
    counts["notationAdjustedPitchAgreement"] += sum(
        bool(item.get("notationAdjustedPitchAgreement")) for item in reviewed.get("eventAlignments") or []
    )
    counts["approvedAlignmentReference"] += len(reviewed.get("eventAlignments") or [])
    counts["provenanceCompletePage"] += bool(reviewed.get("provenance", {}).get("assetSha256"))
    rights = reviewed.get("rightsAndAccess") or {}
    counts["rightsCompletePage"] += bool(rights.get("rightsStatus")) and bool(rights.get("accessClassification"))
    reviewed_orientation = reviewed.get("pageOrientation") or {}
    machine_orientation = machine.get("pageOrientation") or {}
    if reviewed_orientation:
        counts["pageOrientationReference"] += 1
        orientation_fields = ("upright", "orientation", "exifOrientationApplied", "deskewDegrees")
        counts["pageOrientationExact"] += tuple(
            machine_orientation.get(field) for field in orientation_fields
        ) == tuple(reviewed_orientation.get(field) for field in orientation_fields)

    def pairing_by_score_index(record: Mapping[str, Any]) -> dict[int, int | None]:
        tab_index_by_id = {
            str(system.get("tabSystemId")): int(system.get("systemIndex") or 0)
            for system in record.get("tabSystems") or []
        }
        return {
            int(system.get("systemIndex") or 0): tab_index_by_id.get(str(system.get("pairedTabSystemId")))
            for system in record.get("scoreSystems") or []
        }

    machine_pairing = pairing_by_score_index(machine)
    reviewed_pairing = pairing_by_score_index(reviewed)
    counts["scoreTabPairingReference"] += len(reviewed_pairing)
    counts["scoreTabPairingExact"] += sum(
        machine_pairing.get(index) == tab_index for index, tab_index in reviewed_pairing.items()
    )
    return dict(counts)


def extraction_acceptance_metrics(
    pairs: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
) -> dict[str, Any]:
    """Score machine records against independent reviewed records with fixed thresholds."""

    totals: Counter[str] = Counter()
    predicted_action_count = 0
    predicted_valid_action_count = 0
    predicted_provenance_complete = 0
    predicted_rights_complete = 0
    for machine, reviewed in pairs:
        totals.update(_review_record_counts(machine, reviewed))
        actions = [
            action
            for system in machine.get("tabSystems") or []
            for event in system.get("tabEvents") or []
            for action in event.get("steelActions") or []
        ]
        predicted_action_count += len(actions)
        predicted_valid_action_count += sum(
            bool(action.get("mechanicalValidation", {}).get("valid")) for action in actions
        )
        predicted_provenance_complete += bool(machine.get("provenance", {}).get("assetSha256"))
        rights = machine.get("rightsAndAccess") or {}
        predicted_rights_complete += bool(rights.get("rightsStatus")) and bool(rights.get("accessClassification"))

    def ratio(numerator: str, denominator: str, *, empty: float = 1.0) -> float:
        value = int(totals[denominator])
        return round(int(totals[numerator]) / value, 6) if value else empty

    page_count = len(pairs)
    system_tp = int(totals["scoreSystemsTruePositive"] + totals["tabSystemsTruePositive"])
    system_predicted = int(totals["scoreSystemsPredicted"] + totals["tabSystemsPredicted"])
    system_reference = int(totals["scoreSystemsReference"] + totals["tabSystemsReference"])
    metrics = {
        "pageOrientationAccuracy": ratio("pageOrientationExact", "pageOrientationReference"),
        "systemDetectionF1AtIou80": round(_f1(system_tp, system_predicted, system_reference), 6),
        "scoreTabSystemPairingAccuracy": ratio("scoreTabPairingExact", "scoreTabPairingReference"),
        "measureAlignmentAccuracy": ratio("measureAlignmentExact", "scoreEventReference"),
        "stringRecognitionAccuracy": ratio("stringExact", "tabActionReference"),
        "fretRecognitionAccuracy": ratio("fretExact", "tabActionReference"),
        "pedalLeverRecognitionAccuracy": ratio("controlsExact", "tabActionReference"),
        "scorePitchAccuracy": ratio("scorePitchExact", "scoreEventReference"),
        "scoreDurationAccuracyDiagnostic": ratio("scoreDurationExact", "scoreEventReference"),
        "scorePitchDurationAccuracyDiagnostic": ratio(
            "scorePitchAndDurationExact", "scoreEventReference"
        ),
        "chordContextAccuracy": ratio("chordContextExact", "chordContextReference"),
        "soundingPitchAgreement": ratio("notationAdjustedPitchAgreement", "approvedAlignmentReference"),
        "approvedMechanicalValidity": round(
            predicted_valid_action_count / predicted_action_count,
            6,
        )
        if predicted_action_count
        else 1.0,
        "conceptAcceptanceWithoutEditRate": round(
            int(totals["conceptPageAcceptedWithoutEdit"]) / max(1, page_count),
            6,
        ),
        "provenanceCompleteness": round(predicted_provenance_complete / max(1, page_count), 6),
        "rightsAccessCompleteness": round(predicted_rights_complete / max(1, page_count), 6),
        "atomicFieldManualCorrectionRate": ratio(
            "atomicFieldChanged",
            "atomicFieldReference",
            empty=0.0,
        ),
        "eventAlignmentManualCorrectionRate": round(
            1.0 - ratio("eventAlignmentExact", "eventAlignmentReference"),
            6,
        ),
    }
    acceptance = {
        "pageOrientation": metrics["pageOrientationAccuracy"] == 1.0,
        "systemDetection": metrics["systemDetectionF1AtIou80"] >= 0.95,
        "scoreTabPairing": metrics["scoreTabSystemPairingAccuracy"] >= 0.98,
        "measureAlignment": metrics["measureAlignmentAccuracy"] >= 0.95,
        "stringAndFret": (metrics["stringRecognitionAccuracy"] >= 0.98 and metrics["fretRecognitionAccuracy"] >= 0.98),
        "pedalLever": metrics["pedalLeverRecognitionAccuracy"] >= 0.95,
        "scorePitch": metrics["scorePitchAccuracy"] >= 0.97,
        "chordContext": metrics["chordContextAccuracy"] >= 0.95,
        "soundingPitch": metrics["soundingPitchAgreement"] >= 0.98,
        "mechanicalValidity": metrics["approvedMechanicalValidity"] == 1.0,
        "conceptAcceptance": metrics["conceptAcceptanceWithoutEditRate"] >= 0.8,
        "provenanceAndRights": (
            metrics["provenanceCompleteness"] == 1.0 and metrics["rightsAccessCompleteness"] == 1.0
        ),
        "atomicCorrectionRate": metrics["atomicFieldManualCorrectionRate"] <= 0.15,
        "alignmentCorrectionRate": metrics["eventAlignmentManualCorrectionRate"] <= 0.25,
    }
    return {
        "pageCount": page_count,
        "metrics": metrics,
        "acceptance": acceptance,
        "allAcceptanceCriteriaPassed": page_count > 0 and all(acceptance.values()),
    }


def _mark_reviewed_objects(record: dict[str, Any]) -> None:
    for region in record.get("pageRegions") or []:
        region["reviewState"] = "human_approved"
    for statement in record.get("explicitText") or []:
        statement["reviewState"] = "human_approved"
    if isinstance(record.get("pageOrientation"), dict):
        record["pageOrientation"]["reviewState"] = "human_approved"
    record["pageClassification"]["reviewState"] = "human_approved"
    for system in record.get("scoreSystems") or []:
        system["reviewState"] = "human_approved"
        for measure in system.get("measures") or []:
            measure["reviewState"] = "human_approved"
        for event in system.get("scoreEvents", []):
            event["reviewState"] = "human_approved"
        for chord in system.get("chordContexts") or []:
            chord["reviewState"] = "human_approved"
        for tempo in system.get("tempoMarkings") or []:
            tempo["reviewState"] = "human_approved"
        for repeat in system.get("repeatStructures") or []:
            repeat["reviewState"] = "human_approved"
    for system in record.get("tabSystems") or []:
        system["reviewState"] = "human_approved"
        for measure in system.get("measures") or []:
            measure["reviewState"] = "human_approved"
        for event in system.get("tabEvents", []):
            event["reviewState"] = "human_approved"
            for action in event.get("steelActions", []):
                action["reviewState"] = "human_approved"
    for alignment in record.get("eventAlignments") or []:
        alignment["reviewState"] = "human_approved"
    for grip in record.get("grips") or []:
        grip["reviewState"] = "human_approved"
    for movement in record.get("movementSequences") or []:
        movement["reviewState"] = "human_approved"
    for decision in record.get("derivedDecisions") or []:
        decision["reviewState"] = "human_approved"
        decision["reviewStatus"] = "reviewed"
        decision["confidence"] = 1.0
    for concept in record.get("teachingConcepts") or []:
        concept["reviewState"] = "human_approved"
    for exercise in record.get("exercises") or []:
        exercise["reviewState"] = "human_approved"


def _mark_tab_only_reviewed_objects(record: dict[str, Any]) -> None:
    """Approve player-reviewed tab mechanics while withholding score-derived facts."""

    if isinstance(record.get("pageOrientation"), dict):
        record["pageOrientation"]["reviewState"] = "human_approved"
    if isinstance(record.get("pageClassification"), dict):
        record["pageClassification"]["reviewState"] = "human_approved"
    for system in record.get("tabSystems") or []:
        system["reviewState"] = "human_approved"
        for measure in system.get("measures") or []:
            measure["reviewState"] = "human_approved"
        for event in system.get("tabEvents") or []:
            event["reviewState"] = "human_approved"
            for action in event.get("steelActions") or []:
                action["reviewState"] = "human_approved"
    for grip in record.get("grips") or []:
        grip["reviewState"] = "human_approved"
    for movement in record.get("movementSequences") or []:
        movement["reviewState"] = "human_approved"


def _mark_score_audited_objects(
    record: dict[str, Any],
    approved_score_system_ids: set[str],
) -> None:
    """Approve only score-derived objects while leaving prior tab facts untouched."""

    approved_event_ids: set[str] = set()
    for system in record.get("scoreSystems") or []:
        system_id = str(system.get("scoreSystemId") or "")
        if system_id not in approved_score_system_ids:
            continue
        system["reviewState"] = "human_approved"
        for key in (
            "measures",
            "scoreEvents",
            "chordContexts",
            "tempoMarkings",
            "repeatStructures",
        ):
            for item in system.get(key) or []:
                item["reviewState"] = "human_approved"
                if key == "scoreEvents":
                    approved_event_ids.add(str(item.get("scoreEventId") or ""))
    for alignment in record.get("eventAlignments") or []:
        score_event_ids = {str(value) for value in alignment.get("scoreEventIds") or []}
        if score_event_ids and score_event_ids.issubset(approved_event_ids):
            alignment["reviewState"] = "human_approved"


def _approve_targeted_tab_corrections(
    record: dict[str, Any],
    approved_score_system_ids: set[str],
    *,
    reviewer_reference: str,
    reviewed_at: str,
) -> list[str]:
    """Approve only tab events explicitly corrected through the score-audit packet."""

    corrections = list(record.get("sourceTabCorrections") or [])
    correction_system_ids = {
        str(item.get("scoreSystemId") or "") for item in corrections
    } - {""}
    if not correction_system_ids:
        return []
    if not correction_system_ids.issubset(approved_score_system_ids):
        raise ExtractionWorkflowError(
            "Every targeted tab correction must be accepted with its score system."
        )
    event_by_id = {
        str(event.get("tabEventId") or ""): event
        for system in record.get("tabSystems") or []
        for event in system.get("tabEvents") or []
    }
    approved_ids: list[str] = []
    for correction in corrections:
        correction_id = str(correction.get("targetedTabCorrectionId") or "")
        event_id = str(correction.get("tabEventId") or "")
        event = event_by_id.get(event_id)
        if not correction_id or event is None:
            raise ExtractionWorkflowError("A targeted tab correction lost its normalized event.")
        event["reviewState"] = "human_approved"
        event["eligibleForTransformationTraining"] = True
        for action in event.get("steelActions") or []:
            action["reviewState"] = "human_approved"
        correction["reviewState"] = "human_approved"
        correction["eligibleForTransformationTraining"] = True
        correction["humanApproval"] = {
            "reviewerReference": reviewer_reference,
            "reviewedAt": reviewed_at,
            "approvedScoreSystemId": str(correction.get("scoreSystemId") or ""),
            "approvedTabEventId": event_id,
        }
        approved_ids.append(correction_id)
    approved_id_set = set(approved_ids)
    for discrepancy in record.get("sourceScoreTabDiscrepancies") or []:
        if str(discrepancy.get("targetedTabCorrectionId") or "") in approved_id_set:
            discrepancy["resolutionState"] = "expert_corrected_normalized_tab_human_approved"
    record["targetedTabCorrectionApproval"] = {
        "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
        "targetedTabCorrectionIds": sorted(approved_ids),
        "reviewerReference": reviewer_reference,
        "reviewedAt": reviewed_at,
        "priorTabApprovalSupersededOnlyForTargetedEvents": True,
    }
    return sorted(approved_ids)


def _apply_pitch_only_score_audit_scope(
    record: dict[str, Any],
    approved_score_system_ids: set[str],
    *,
    reviewer_reference: str,
) -> dict[str, Any]:
    """Keep pitch/tab approval while excluding unreviewed score rhythm fields."""

    approved_event_ids: set[str] = set()
    relationship_findings = {
        str(item.get("eventAlignmentId") or ""): item
        for item in score_tab_pitch_relationship_findings(record)
    }
    explicitly_ineligible_event_ids = {
        str(event_id)
        for alignment in record.get("eventAlignments") or []
        if alignment.get("eligibleForTransformationTraining") is False
        or not bool(
            relationship_findings.get(
                str(alignment.get("eventAlignmentId") or ""), {}
            ).get("eligibleForPitchToTabTraining")
        )
        for event_id in alignment.get("scoreEventIds") or []
    }
    score_event_count = 0
    for system in record.get("scoreSystems") or []:
        system_id = str(system.get("scoreSystemId") or "")
        if system_id not in approved_score_system_ids:
            continue
        system["scoreAuditApprovalScope"] = {
            "pitchAndChordMembership": "human_approved",
            "eventOrderAndMeasureMembership": "human_approved",
            "scoreToTabCorrespondence": "human_approved",
            "noteDuration": "not_reviewed_excluded",
            "rhythmicPosition": "not_reviewed_excluded",
        }
        for event in system.get("scoreEvents") or []:
            event_id = str(event.get("scoreEventId") or "")
            approved_event_ids.add(event_id)
            score_event_count += 1
            event["fieldReviewStates"] = {
                **copy.deepcopy(event.get("fieldReviewStates") or {}),
                "pitch": "not_applicable" if event.get("rest") else "human_approved",
                "chordMembership": "human_approved",
                "duration": "not_reviewed_excluded",
                "rhythmicPosition": "not_reviewed_excluded",
                "tie": "not_reviewed_excluded",
            }
            event["pitchToTabTrainingEligible"] = (
                not bool(event.get("rest")) and event_id not in explicitly_ineligible_event_ids
            )
            event["scoreRhythmTrainingEligible"] = False
    alignment_count = 0
    eligible_alignment_count = 0
    excluded_source_discrepancy_count = 0
    excluded_score_chord_omission_count = 0
    excluded_other_pitch_mismatch_count = 0
    for alignment in record.get("eventAlignments") or []:
        score_event_ids = {str(value) for value in alignment.get("scoreEventIds") or []}
        if score_event_ids and score_event_ids.issubset(approved_event_ids):
            alignment_count += 1
            finding = relationship_findings.get(
                str(alignment.get("eventAlignmentId") or ""), {}
            )
            relationship_status = str(finding.get("relationshipStatus") or "mismatch")
            alignment_eligible = bool(finding.get("eligibleForPitchToTabTraining"))
            eligible_alignment_count += int(alignment_eligible)
            excluded_source_discrepancy_count += int(
                bool(alignment.get("sourcePitchDiscrepancyConfirmed"))
                and not alignment_eligible
            )
            excluded_score_chord_omission_count += int(
                relationship_status == "subset_requires_review"
            )
            excluded_other_pitch_mismatch_count += int(
                relationship_status == "mismatch"
                and not bool(alignment.get("sourcePitchDiscrepancyConfirmed"))
            )
            alignment["fieldReviewStates"] = {
                **copy.deepcopy(alignment.get("fieldReviewStates") or {}),
                "pitchCorrespondence": (
                    "human_approved" if alignment_eligible else "excluded_requires_correction"
                ),
                "scoreTabCorrespondence": (
                    "human_approved" if alignment_eligible else "excluded_requires_correction"
                ),
                "durationCorrespondence": "not_reviewed_excluded",
                "rhythmCorrespondence": "not_reviewed_excluded",
            }
            alignment["scoreTabPitchRelationship"] = relationship_status
            alignment["pitchToTabTrainingEligible"] = alignment_eligible
            alignment["scoreRhythmTrainingEligible"] = False
    scope = {
        "schemaVersion": SCORE_AUDIT_SCOPE_SCHEMA_VERSION,
        "reviewerReference": reviewer_reference,
        "approvedFacts": [
            "pitch",
            "chord_membership",
            "event_order",
            "measure_membership",
            "score_to_tab_correspondence",
        ],
        "excludedUnreviewedFacts": [
            "note_duration",
            "rhythmic_position",
            "tie_duration",
            "rhythm_correspondence",
        ],
        "pitchToTabTrainingEligible": True,
        "scoreRhythmTrainingEligible": False,
        "scoreEventCount": score_event_count,
        "eventAlignmentCount": alignment_count,
        "pitchToTabEligibleAlignmentCount": eligible_alignment_count,
        "excludedSourceDiscrepancyCount": excluded_source_discrepancy_count,
        "excludedScoreChordOmissionCount": excluded_score_chord_omission_count,
        "excludedOtherPitchMismatchCount": excluded_other_pitch_mismatch_count,
        "requiresExactPitchAndOctaveSets": True,
    }
    record["scoreAuditApprovalScope"] = scope
    record["trainingEligibility"] = {
        **copy.deepcopy(record.get("trainingEligibility") or {}),
        "pitchToTab": True,
        "scoreRhythm": False,
    }
    return scope


def _revalidate_corrected_record(
    record: dict[str, Any],
    profile: Any,
    *,
    include_movement_only_tab_system_ids: Collection[str] = (),
) -> None:
    regenerated_validation_unresolved: list[dict[str, Any]] = []
    supported_controls = set(profile.controls_by_id())
    for system in record.get("tabSystems") or []:
        for event in system.get("tabEvents", []):
            regenerated_actions: list[dict[str, Any]] = []
            for action in event.get("steelActions", []):
                controls = [str(control).upper() for control in action.get("controls") or []]
                token = (
                    f"{str(action.get('notationPrefix') or '')}{int(action['fret'])}"
                    f"{''.join(controls)}{str(action.get('notationSuffix') or '')}"
                )
                region_id = str(action.get("pageRegionId") or action.get("steelActionId") or event.get("tabEventId"))
                regenerated, unresolved = _tab_action_from_token(
                    token,
                    string=int(action["string"]),
                    profile=profile,
                    confidence=float(action.get("confidence") or 1.0),
                    region_id=region_id,
                )
                if regenerated is None:
                    raise ExtractionWorkflowError("A corrected steel action could not be deterministically decoded.")
                if action.get("pageRegion") is not None:
                    regenerated["pageRegion"] = copy.deepcopy(action["pageRegion"])
                structured_notation_fields = (
                    "attack",
                    "halfStop",
                    "slide",
                    "barMovement",
                    "slant",
                    "harmonic",
                    "sustain",
                    "repeatedPick",
                    "rakeOrGrip",
                    "engagementTiming",
                    "releaseTiming",
                    "controlTransition",
                    "correctionBasisFeedbackItemIds",
                )
                for field in structured_notation_fields:
                    if field in action:
                        regenerated[field] = copy.deepcopy(action[field])
                transition = regenerated.get("controlTransition")
                if transition is not None:
                    if not isinstance(transition, Mapping):
                        raise ExtractionWorkflowError(
                            "A corrected control transition must be an object."
                        )
                    before_controls = sorted(
                        {str(value).upper() for value in transition.get("beforeControls") or []}
                    )
                    after_controls = sorted(
                        {str(value).upper() for value in transition.get("afterControls") or []}
                    )
                    if not set(before_controls + after_controls).issubset(supported_controls):
                        raise ExtractionWorkflowError(
                            "A corrected control transition contains an unsupported control."
                        )
                    regenerated["controlTransition"] = {
                        "beforeControls": before_controls,
                        "afterControls": after_controls,
                        "timing": str(transition.get("timing") or "during_sustain"),
                    }
                if regenerated.get("halfStop"):
                    raw_deltas = [int(value) for value in regenerated.get("controlSemitoneChanges") or []]
                    unique_raw_deltas = sorted(set(raw_deltas))
                    if len(unique_raw_deltas) != 1 or abs(unique_raw_deltas[0]) != 2:
                        raise ExtractionWorkflowError(
                            "A corrected half-stop action requires one two-semitone source control."
                        )
                    half_delta = 1 if unique_raw_deltas[0] > 0 else -1
                    pitch_value = (
                        profile.open_pitch_values_by_string()[int(regenerated["string"])]
                        + int(regenerated["fret"])
                        + half_delta
                    )
                    regenerated["controlSemitoneChanges"] = [half_delta]
                    regenerated["soundingPitchValue"] = pitch_value
                    regenerated["soundingPitch"] = scientific_pitch_for_value(pitch_value)
                regenerated_actions.append(regenerated)
                notation_resolved = any(action.get(field) is not None for field in structured_notation_fields)
                if unresolved is not None and not (
                    unresolved.get("kind") == "uncertain_tab_modifier" and notation_resolved
                ):
                    regenerated_validation_unresolved.append(unresolved)
            event["steelActions"] = regenerated_actions
            for control_change in event.get("controlChanges") or []:
                control = str(control_change.get("control") or "").upper()
                action = str(control_change.get("action") or "")
                if control not in supported_controls or action not in {"engage", "release"}:
                    raise ExtractionWorkflowError("A corrected event contains an invalid explicit control change.")
                control_change["control"] = control
                control_change["evidenceClass"] = "direct_visual_observation"
                control_change["reviewState"] = "needs_human_review"
            _refresh_event_execution(event)

    score_by_index = {
        int(system.get("systemIndex") or index): system
        for index, system in enumerate(record.get("scoreSystems") or [], start=1)
    }
    alignment_candidates: list[dict[str, Any]] = []
    for index, tab_system in enumerate(record.get("tabSystems") or [], start=1):
        system_index = int(tab_system.get("systemIndex") or index)
        score_system = score_by_index.get(system_index)
        if score_system is not None:
            alignment_candidates.extend(
                _align_events(
                    score_system.get("scoreEvents") or [],
                    tab_system.get("tabEvents") or [],
                    include_movement_only=(
                        str(tab_system.get("tabSystemId") or "")
                        in set(include_movement_only_tab_system_ids)
                    ),
                )
            )
    alignments, alignment_unresolved = _separate_verified_alignments(alignment_candidates)
    record["eventAlignments"] = alignments
    grip_candidates = _derive_grips(record.get("tabSystems") or [])
    grips, grip_unresolved, ineligible_grip_events = _separate_verified_grips(grip_candidates)
    _mark_grip_event_eligibility(record.get("tabSystems") or [], ineligible_grip_events)
    record["grips"] = grips
    record["movementSequences"] = _derive_movement_sequences(
        record.get("tabSystems") or [],
        str(record["objectId"]),
    )
    record["teachingConcepts"] = _derive_teaching_concepts(
        record.get("explicitText") or [],
        record.get("tabSystems") or [],
        record["movementSequences"],
        str(record["objectId"]),
    )
    record["exercises"] = _derive_exercises(
        record.get("pageClassification") or {},
        record.get("explicitText") or [],
        record.get("tabSystems") or [],
        record["teachingConcepts"],
        str(record["objectId"]),
    )
    record["derivedDecisions"] = derive_decision_annotations(record, profile)
    record["pageRegions"] = _collect_page_regions(
        str(record["objectId"]),
        record.get("explicitText") or [],
        record.get("scoreSystems") or [],
        record.get("tabSystems") or [],
    )
    remaining_unresolved = [
        copy.deepcopy(item)
        for item in record.get("unresolved") or []
        if item.get("kind")
        not in {
            "mechanical_validation_error",
            "mechanically_invalid_tab_candidate",
            "mechanically_invalid_grip_candidate",
            "uncertain_tab_modifier",
            "unverified_score_tab_alignment",
        }
    ]
    record["unresolved"] = (
        remaining_unresolved + regenerated_validation_unresolved + grip_unresolved + alignment_unresolved
    )
    actions = [
        action
        for system in record.get("tabSystems") or []
        for event in system.get("tabEvents", [])
        for action in event.get("steelActions", [])
    ]
    record["validationSummary"] = {
        "steelActionCount": len(actions),
        "mechanicallyValidCount": sum(bool(action.get("mechanicalValidation", {}).get("valid")) for action in actions),
        "soundingPitchAgreementCount": sum(bool(alignment.get("soundingPitchAgreement")) for alignment in alignments),
        "notationAdjustedPitchAgreementCount": sum(
            bool(alignment.get("notationAdjustedPitchAgreement")) for alignment in alignments
        ),
        "alignmentCount": len(alignments),
        "provenanceComplete": True,
        "rightsAndAccessComplete": True,
    }


def _tab_system_for_correction(record: Mapping[str, Any], tab_system_id: str) -> dict[str, Any]:
    for system in record.get("tabSystems") or []:
        if str(system.get("tabSystemId") or "") == tab_system_id:
            return system
    raise ExtractionWorkflowError(f"Correction references unknown tab system {tab_system_id!r}.")


def _tab_event_for_correction(system: Mapping[str, Any], tab_event_id: str) -> dict[str, Any]:
    for event in system.get("tabEvents") or []:
        if str(event.get("tabEventId") or "") == tab_event_id:
            return event
    raise ExtractionWorkflowError(f"Correction references unknown tab event {tab_event_id!r}.")


def _steel_action_for_correction(event: Mapping[str, Any], steel_action_id: str) -> dict[str, Any]:
    for action in event.get("steelActions") or []:
        if str(action.get("steelActionId") or "") == steel_action_id:
            return action
    raise ExtractionWorkflowError(f"Correction references unknown steel action {steel_action_id!r}.")


def _correction_action_region(
    record: Mapping[str, Any],
    system: Mapping[str, Any],
    event: Mapping[str, Any],
    string: int,
) -> dict[str, float]:
    width = max(1, int(record.get("derivative", {}).get("width") or 1))
    height = max(1, int(record.get("derivative", {}).get("height") or 1))
    centers = list(system.get("stringCenters") or [])
    page_region = system.get("pageRegion") or {}
    if len(centers) >= string:
        center_y = float(centers[string - 1]) / height
    else:
        center_y = float(page_region.get("y") or 0.0) + (
            float(page_region.get("height") or 0.1) * (string - 0.5) / 10
        )
    event_x = float(event.get("horizontalPosition") or 0.0)
    if 0 <= event_x <= 1 and page_region:
        event_x = float(page_region.get("x") or 0.0) + event_x * float(page_region.get("width") or 1.0)
    return {
        "x": round(max(0.0, min(0.995, event_x - 6 / width)), 7),
        "y": round(max(0.0, min(0.995, center_y - 7 / height)), 7),
        "width": round(min(1.0, 24 / width), 7),
        "height": round(min(1.0, 14 / height), 7),
    }


def _new_correction_action(
    record: Mapping[str, Any],
    system: Mapping[str, Any],
    event: Mapping[str, Any],
    spec: Mapping[str, Any],
    *,
    operation_id: str,
    feedback_item_ids: Sequence[str],
) -> dict[str, Any]:
    string = int(spec["string"])
    fret = int(spec["fret"])
    controls = sorted({str(value).upper() for value in spec.get("controls") or []})
    action_id = str(
        spec.get("steelActionId")
        or _stable_id("steel-action-correction", record.get("inputId"), operation_id, string, fret, controls)
    )
    region_id = str(spec.get("pageRegionId") or _stable_id("page-region-correction", action_id))
    action: dict[str, Any] = {
        "steelActionId": action_id,
        "string": string,
        "fret": fret,
        "controls": controls,
        "attack": bool(spec.get("attack", True)),
        "notationPrefix": spec.get("notationPrefix"),
        "notationSuffix": spec.get("notationSuffix"),
        "confidence": float(spec.get("confidence") or 1.0),
        "evidenceClass": "direct_visual_observation",
        "reviewState": "needs_human_review",
        "pageRegionId": region_id,
        "pageRegion": copy.deepcopy(
            spec.get("pageRegion") or _correction_action_region(record, system, event, string)
        ),
        "correctionBasisFeedbackItemIds": sorted(set(feedback_item_ids)),
    }
    for field in (
        "halfStop",
        "slide",
        "barMovement",
        "slant",
        "harmonic",
        "sustain",
        "repeatedPick",
        "rakeOrGrip",
        "engagementTiming",
        "releaseTiming",
        "controlTransition",
    ):
        if field in spec:
            action[field] = copy.deepcopy(spec[field])
    return action


def _apply_feedback_correction_operation(
    record: dict[str, Any],
    operation: Mapping[str, Any],
    *,
    feedback_item_ids: Sequence[str],
) -> None:
    operation_type = str(operation.get("type") or "")
    operation_id = str(operation.get("operationId") or _stable_id("feedback-correction-operation", operation))
    system_id = str(operation.get("tabSystemId") or "")
    systems = record.get("tabSystems") or []

    if operation_type == "remove_tab_system":
        before = len(systems)
        record["tabSystems"] = [
            system for system in systems if str(system.get("tabSystemId") or "") != system_id
        ]
        if len(record["tabSystems"]) == before:
            raise ExtractionWorkflowError(f"Correction references unknown tab system {system_id!r}.")
        return

    if operation_type == "remove_score_system":
        score_system_id = str(operation.get("scoreSystemId") or "")
        score_systems = list(record.get("scoreSystems") or [])
        record["scoreSystems"] = [
            system
            for system in score_systems
            if str(system.get("scoreSystemId") or "") != score_system_id
        ]
        if len(record["scoreSystems"]) == len(score_systems):
            raise ExtractionWorkflowError(
                f"Correction references unknown score system {score_system_id!r}."
            )
        return

    if operation_type == "record_score_feedback_pending":
        score_system_id = str(operation.get("scoreSystemId") or "")
        if not score_system_id or not any(
            str(system.get("scoreSystemId") or "") == score_system_id
            for system in record.get("scoreSystems") or []
        ):
            raise ExtractionWorkflowError(
                f"Correction references unknown score system {score_system_id!r}."
            )
        pending = record.setdefault("pendingScoreFeedbackCorrections", [])
        pending.append(
            {
                "operationId": operation_id,
                "scoreSystemId": score_system_id,
                "feedbackItemIds": sorted(set(feedback_item_ids)),
                "reviewState": "unresolved_requires_score_candidate_correction",
                "humanApprovalGranted": False,
            }
        )
        return

    system = _tab_system_for_correction(record, system_id)
    event_id = str(operation.get("tabEventId") or "")

    if operation_type == "replace_tab_system_events":
        event_specs = operation.get("tabEvents")
        if not isinstance(event_specs, list) or not 1 <= len(event_specs) <= 128:
            raise ExtractionWorkflowError(
                "A replace_tab_system_events correction requires 1-128 complete events."
            )
        replacement: list[dict[str, Any]] = []
        prior_x = -1.0
        for event_index, event_spec in enumerate(event_specs, start=1):
            if not isinstance(event_spec, Mapping):
                raise ExtractionWorkflowError("A replacement tab event must be an object.")
            horizontal_position = float(event_spec.get("horizontalPosition") or 0.0)
            if not 0.0 <= horizontal_position <= 1.0 or horizontal_position < prior_x:
                raise ExtractionWorkflowError(
                    "Replacement tab-event positions must be ordered from zero to one."
                )
            prior_x = horizontal_position
            inserted_id = str(
                event_spec.get("tabEventId")
                or _stable_id(
                    "tab-event-system-recapture",
                    record.get("inputId"),
                    system_id,
                    operation_id,
                    event_index,
                )
            )
            inserted: dict[str, Any] = {
                "tabEventId": inserted_id,
                "eventIndex": event_index,
                "measure": event_spec.get("measure"),
                "measureHorizontalPosition": event_spec.get("measureHorizontalPosition"),
                "horizontalPosition": horizontal_position,
                "candidateStrings": [],
                "steelActions": [],
                "simultaneous": False,
                "gripId": None,
                "evidenceClass": "direct_visual_observation",
                "confidence": float(event_spec.get("confidence") or 1.0),
                "reviewState": "needs_human_review",
                "correctionBasisFeedbackItemIds": sorted(set(feedback_item_ids)),
            }
            action_specs = event_spec.get("steelActions")
            if not isinstance(action_specs, list) or not action_specs:
                raise ExtractionWorkflowError(
                    "Every replacement tab event requires at least one steel action."
                )
            inserted["steelActions"] = [
                _new_correction_action(
                    record,
                    system,
                    inserted,
                    action_spec,
                    operation_id=f"{operation_id}-event-{event_index}",
                    feedback_item_ids=feedback_item_ids,
                )
                for action_spec in action_specs
            ]
            candidate_strings = [int(action["string"]) for action in inserted["steelActions"]]
            if len(candidate_strings) != len(set(candidate_strings)):
                raise ExtractionWorkflowError(
                    "A replacement tab event cannot contain duplicate strings."
                )
            inserted["candidateStrings"] = sorted(candidate_strings)
            inserted["simultaneous"] = len(candidate_strings) > 1
            inserted["gripId"] = (
                _stable_id("grip", inserted_id, "system-recapture")
                if inserted["simultaneous"]
                else None
            )
            for field in ("controlChanges", "barMovement", "sustainBehavior"):
                if field in event_spec:
                    inserted[field] = copy.deepcopy(event_spec[field])
            _refresh_event_execution(inserted)
            replacement.append(inserted)
        system["tabEvents"] = replacement
        system["recapture"] = {
            "operationId": operation_id,
            "expectedEventCount": len(replacement),
            "feedbackItemIds": sorted(set(feedback_item_ids)),
            "reviewState": "needs_human_review",
        }
        return

    if operation_type == "remove_tab_event":
        events = list(system.get("tabEvents") or [])
        remaining = [event for event in events if str(event.get("tabEventId") or "") != event_id]
        if len(remaining) == len(events):
            raise ExtractionWorkflowError(f"Correction references unknown tab event {event_id!r}.")
        system["tabEvents"] = remaining
        return

    if operation_type == "merge_tab_events":
        target = _tab_event_for_correction(system, event_id)
        source_ids = {str(value) for value in operation.get("sourceTabEventIds") or []}
        if not source_ids:
            raise ExtractionWorkflowError("A merge_tab_events correction requires sourceTabEventIds.")
        source_events = [
            event for event in system.get("tabEvents") or [] if str(event.get("tabEventId") or "") in source_ids
        ]
        if {str(event.get("tabEventId") or "") for event in source_events} != source_ids:
            raise ExtractionWorkflowError("A merge_tab_events correction references an unknown source event.")
        actions_by_string = {int(action["string"]): copy.deepcopy(action) for action in target.get("steelActions") or []}
        for source in source_events:
            for action in source.get("steelActions") or []:
                string = int(action["string"])
                if string in actions_by_string and operation.get("sameStringPolicy") == "keep_target":
                    continue
                actions_by_string[string] = copy.deepcopy(action)
        target["steelActions"] = [actions_by_string[string] for string in sorted(actions_by_string)]
        target["simultaneous"] = len(actions_by_string) > 1
        target["gripId"] = (
            _stable_id("grip", target.get("tabEventId"), "corrected") if len(actions_by_string) > 1 else None
        )
        target["correctionBasisFeedbackItemIds"] = sorted(set(feedback_item_ids))
        system["tabEvents"] = [
            event for event in system.get("tabEvents") or [] if str(event.get("tabEventId") or "") not in source_ids
        ]
        _refresh_event_execution(target)
        return

    if operation_type == "insert_tab_event":
        events = list(system.get("tabEvents") or [])
        anchor = _tab_event_for_correction(system, event_id)
        anchor_index = events.index(anchor)
        position = str(operation.get("position") or "before")
        insertion_index = anchor_index if position == "before" else anchor_index + 1
        inserted_id = str(
            operation.get("newTabEventId")
            or _stable_id("tab-event-correction", record.get("inputId"), operation_id)
        )
        if any(str(event.get("tabEventId") or "") == inserted_id for event in events):
            raise ExtractionWorkflowError(f"Correction would duplicate tab event {inserted_id!r}.")
        inserted: dict[str, Any] = {
            "tabEventId": inserted_id,
            "eventIndex": insertion_index + 1,
            "measure": operation.get("measure", anchor.get("measure")),
            "measureHorizontalPosition": operation.get(
                "measureHorizontalPosition", anchor.get("measureHorizontalPosition")
            ),
            "horizontalPosition": float(anchor.get("horizontalPosition") or 0.0)
            + (-0.000001 if position == "before" else 0.000001),
            "candidateStrings": [],
            "steelActions": [],
            "simultaneous": False,
            "gripId": None,
            "evidenceClass": "direct_visual_observation",
            "confidence": 1.0,
            "reviewState": "needs_human_review",
            "correctionBasisFeedbackItemIds": sorted(set(feedback_item_ids)),
        }
        inserted["steelActions"] = [
            _new_correction_action(
                record,
                system,
                inserted,
                action_spec,
                operation_id=operation_id,
                feedback_item_ids=feedback_item_ids,
            )
            for action_spec in operation.get("steelActions") or []
        ]
        if not inserted["steelActions"]:
            raise ExtractionWorkflowError("An inserted tab event requires at least one steel action.")
        inserted["candidateStrings"] = sorted(int(action["string"]) for action in inserted["steelActions"])
        inserted["simultaneous"] = len(inserted["steelActions"]) > 1
        inserted["gripId"] = (
            _stable_id("grip", inserted_id, "corrected") if inserted["simultaneous"] else None
        )
        _refresh_event_execution(inserted)
        events.insert(insertion_index, inserted)
        system["tabEvents"] = events
        return

    event = _tab_event_for_correction(system, event_id)

    if operation_type == "update_tab_event":
        changes = operation.get("changes") or {}
        allowed_fields = {"controlChanges", "barMovement", "sustainBehavior"}
        unknown = set(changes) - allowed_fields
        if unknown:
            raise ExtractionWorkflowError(
                f"Unsupported tab-event correction fields: {', '.join(sorted(unknown))}."
            )
        for field, value in changes.items():
            event[field] = copy.deepcopy(value)
    elif operation_type == "add_steel_action":
        action = _new_correction_action(
            record,
            system,
            event,
            operation.get("steelAction") or {},
            operation_id=operation_id,
            feedback_item_ids=feedback_item_ids,
        )
        if any(int(item["string"]) == int(action["string"]) for item in event.get("steelActions") or []):
            raise ExtractionWorkflowError("An add_steel_action correction would duplicate a string in one event.")
        event.setdefault("steelActions", []).append(action)
    else:
        action_id = str(operation.get("steelActionId") or "")
        if operation_type == "remove_steel_action":
            actions = list(event.get("steelActions") or [])
            remaining = [
                action for action in actions if str(action.get("steelActionId") or "") != action_id
            ]
            if len(remaining) == len(actions):
                raise ExtractionWorkflowError(f"Correction references unknown steel action {action_id!r}.")
            if not remaining:
                system["tabEvents"] = [
                    candidate
                    for candidate in system.get("tabEvents") or []
                    if str(candidate.get("tabEventId") or "") != event_id
                ]
                return
            event["steelActions"] = remaining
        elif operation_type == "update_steel_action":
            action = _steel_action_for_correction(event, action_id)
            changes = operation.get("changes") or {}
            allowed_fields = {
                "string",
                "fret",
                "controls",
                "attack",
                "notationPrefix",
                "notationSuffix",
                "halfStop",
                "slide",
                "barMovement",
                "slant",
                "harmonic",
                "sustain",
                "repeatedPick",
                "rakeOrGrip",
                "engagementTiming",
                "releaseTiming",
                "controlTransition",
            }
            unknown = set(changes) - allowed_fields
            if unknown:
                raise ExtractionWorkflowError(
                    f"Unsupported steel-action correction fields: {', '.join(sorted(unknown))}."
                )
            for field, value in changes.items():
                action[field] = copy.deepcopy(value)
            action["controls"] = sorted({str(value).upper() for value in action.get("controls") or []})
            action["correctionBasisFeedbackItemIds"] = sorted(set(feedback_item_ids))
        elif operation_type == "set_event_execution":
            attack_strings = {int(value) for value in operation.get("attackStrings") or []}
            sustained_strings = {int(value) for value in operation.get("sustainedStrings") or []}
            event_strings = {int(action["string"]) for action in event.get("steelActions") or []}
            if attack_strings & sustained_strings or attack_strings | sustained_strings != event_strings:
                raise ExtractionWorkflowError(
                    "set_event_execution must classify every event string exactly once."
                )
            for event_action in event.get("steelActions") or []:
                event_action["attack"] = int(event_action["string"]) in attack_strings
                event_action["correctionBasisFeedbackItemIds"] = sorted(set(feedback_item_ids))
        else:
            raise ExtractionWorkflowError(f"Unsupported feedback correction operation {operation_type!r}.")

    event["candidateStrings"] = sorted(int(action["string"]) for action in event.get("steelActions") or [])
    event["simultaneous"] = len(event.get("steelActions") or []) > 1
    event["gripId"] = (
        _stable_id("grip", event.get("tabEventId"), "corrected") if event["simultaneous"] else None
    )
    event["correctionBasisFeedbackItemIds"] = sorted(set(feedback_item_ids))
    _refresh_event_execution(event)


def _reindex_corrected_tab_events(record: dict[str, Any]) -> None:
    for score_system_index, score_system in enumerate(record.get("scoreSystems") or [], start=1):
        score_system["systemIndex"] = score_system_index
    for system_index, system in enumerate(record.get("tabSystems") or [], start=1):
        system["systemIndex"] = system_index
        for event_index, event in enumerate(system.get("tabEvents") or [], start=1):
            event["eventIndex"] = event_index
            _refresh_event_execution(event)


class AmazingTablatureExtractor:
    """Run resumable private extraction for one already-partitioned batch."""

    def __init__(
        self,
        private_root: Path | str,
        *,
        repo_root: Path | str | None = None,
        audiveris_binary: Path | None = None,
        vision_model: str = "gemma4:12b",
        vision_base_url: str = "http://127.0.0.1:11434",
        tab_reader: str = "ollama",
    ) -> None:
        self.private_root = Path(private_root).expanduser().resolve()
        self.repo_root = Path(repo_root or Path.cwd()).expanduser().resolve()
        self.ocr = AppleVisionOCR(self.repo_root, self.private_root)
        self.omr = AudiverisReader(audiveris_binary)
        self.tab_vision: AppleTabVisionOCR | LocalTabVision
        if tab_reader == "apple":
            self.tab_vision = AppleTabVisionOCR(self.repo_root, self.private_root)
        elif tab_reader == "ollama":
            self.tab_vision = LocalTabVision(vision_model, vision_base_url)
        else:
            raise ExtractionWorkflowError("tab_reader must be 'apple' or 'ollama'.")
        self.tab_system_vision = LocalTabSystemVision(vision_model, vision_base_url)

    def _read_tab_cells(self, sheet: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
        sheet_path = Path(str(sheet["path"]))
        labels = [str(value) for value in sheet["labels"]]
        sheet_sha = _sha256_bytes(sheet_path.read_bytes())
        model = str(getattr(self.tab_vision, "model", "injected-tab-reader"))
        contract_method = getattr(self.tab_vision, "contract", None)
        reader_contract = contract_method() if callable(contract_method) else {"reader": model}
        cache_path = sheet_path.with_suffix(".tokens.json")
        if cache_path.exists():
            cached = _read_json(cache_path)
            if (
                cached.get("promptVersion") == TAB_VISION_PROMPT_VERSION
                and cached.get("model") == model
                and cached.get("readerContract") == reader_contract
                and cached.get("sheetSha256") == sheet_sha
                and cached.get("labels") == labels
                and isinstance(cached.get("cells"), Mapping)
            ):
                return {str(key): dict(value) for key, value in cached["cells"].items() if isinstance(value, Mapping)}
        cells = self.tab_vision.read(sheet_path, labels, sheet.get("cellBoxes"))
        _write_json(
            cache_path,
            {
                "schemaVersion": EXTRACTION_SCHEMA_VERSION,
                "promptVersion": TAB_VISION_PROMPT_VERSION,
                "model": model,
                "readerContract": reader_contract,
                "sheetSha256": sheet_sha,
                "labels": labels,
                "cells": cells,
            },
        )
        return cells

    def _validation_model_contract(
        self,
        batch_id: str,
        model_id: str,
    ) -> dict[str, Any]:
        registry_path = self.private_root / "training-registry.json"
        if not model_id or not registry_path.exists():
            raise ExtractionWorkflowError(
                "Validation extraction requires an exact canonical discovery model ID."
            )
        registry = _read_json(registry_path)
        model_meta = (registry.get("models") or {}).get(model_id)
        if not isinstance(model_meta, Mapping):
            raise ExtractionWorkflowError(
                "Validation extraction references an unknown discovery model."
            )
        if (
            model_meta.get("datasetEligibility") != "complete_discovery"
            or model_meta.get("canonicalEvaluationEligible") is not True
        ):
            raise ExtractionWorkflowError(
                "Validation extraction requires the complete-discovery canonical challenger."
            )
        artifact_relative = str(model_meta.get("artifact") or "")
        artifact_path = self.private_root / artifact_relative
        if not artifact_relative or not artifact_path.exists():
            raise ExtractionWorkflowError("The canonical challenger artifact is missing.")
        artifact_sha256 = _sha256_bytes(artifact_path.read_bytes())
        if artifact_sha256 != str(model_meta.get("artifactSha256") or ""):
            raise ExtractionWorkflowError(
                "The canonical challenger artifact digest changed before validation extraction."
            )
        model = _read_json(artifact_path)
        if (
            model.get("modelId") != model_id
            or model.get("fullDiscoveryReviewComplete") is not True
            or batch_id not in set(model.get("sourceBatchIds") or [])
        ):
            raise ExtractionWorkflowError(
                "The canonical challenger does not cover this validation cohort."
            )
        return {
            "modelId": model_id,
            "artifactSha256": artifact_sha256,
            "codeRevision": model.get("codeRevision"),
            "discoverySeedId": model.get("discoverySeedId"),
            "fullDiscoveryReviewComplete": True,
            "fullDiscoveryScoreAuditComplete": bool(
                model.get("fullDiscoveryScoreAuditComplete")
            ),
        }

    def _batch_paths(
        self,
        batch_id: str,
        partition: str,
        *,
        validation_model_id: str | None = None,
    ) -> tuple[Path, dict[str, Any], list[dict[str, Any]]]:
        if partition not in {"discovery", "validation"}:
            raise ExtractionWorkflowError("Extraction may read discovery or validation only; sealed test is forbidden.")
        batch_dir = self.private_root / "batches" / batch_id
        manifest_path = batch_dir / "manifest.json"
        work_path = batch_dir / f"{partition}-work.jsonl"
        if not manifest_path.exists() or not work_path.exists():
            raise ExtractionWorkflowError(f"Batch {batch_id} has no sealed {partition} work queue.")
        partition_summary_path = batch_dir / "partition-summary.json"
        if partition_summary_path.exists():
            partition_summary = _read_json(partition_summary_path)
            if partition_summary.get("groupingReviewStatus") != "independent_review_passed":
                raise ExtractionWorkflowError(f"Batch {batch_id} has not passed an independent unopened-split review.")
        if partition == "validation":
            pinned_model_id = str(validation_model_id or "")
            existing_summary_path = batch_dir / "extraction/validation/summary.json"
            if not pinned_model_id and existing_summary_path.exists():
                pinned_model_id = str(
                    (_read_json(existing_summary_path).get("validationModel") or {}).get(
                        "modelId"
                    )
                    or ""
                )
            self._validation_model_contract(batch_id, pinned_model_id)
        return batch_dir, _read_json(manifest_path), _read_jsonl(work_path)

    def run(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        use_ocr: bool = True,
        use_omr: bool = True,
        use_tab_vision: bool = True,
        resume: bool = True,
        workers: int = 1,
        refresh_unreviewed: bool = False,
        refresh_limit: int | None = None,
        refresh_require_tab_systems: bool = False,
        validation_model_id: str | None = None,
    ) -> dict[str, Any]:
        if workers < 1 or workers > 4:
            raise ExtractionWorkflowError("Extraction workers must be between 1 and 4.")
        if refresh_unreviewed and partition != "discovery":
            raise ExtractionWorkflowError("Unreviewed extraction refresh is discovery-only.")
        if refresh_unreviewed and (refresh_limit is None or refresh_limit < 1 or refresh_limit > 100):
            raise ExtractionWorkflowError("Unreviewed extraction refresh limit must be between 1 and 100.")
        batch_dir, manifest, work = self._batch_paths(
            batch_id,
            partition,
            validation_model_id=validation_model_id,
        )
        rights_path = batch_dir / "rights-and-access.json"
        rights_and_access = _normalized_rights_and_access(_read_json(rights_path) if rights_path.exists() else None)
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        if manifest.get("sourceCopedentRevision", profile.revision) != profile.revision:
            raise ExtractionWorkflowError("The batch copedent revision does not match the deterministic profile.")
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        derivatives_dir = output_root / "derivatives"
        review_dir = output_root / "review"
        for directory in (output_root, pages_dir, derivatives_dir, review_dir):
            directory.mkdir(parents=True, exist_ok=True)
            os.chmod(directory, 0o700)
        refresh_target_ids: set[str] = set()
        if refresh_unreviewed:
            existing_summary_path = output_root / "summary.json"
            if not existing_summary_path.exists():
                raise ExtractionWorkflowError("A complete discovery extraction is required before refresh.")
            finalized_rows = _read_jsonl(review_dir / "approved-record-index.jsonl") if (
                review_dir / "approved-record-index.jsonl"
            ).exists() else []
            feedback_rows = _read_jsonl(review_dir / "human-review-feedback.jsonl") if (
                review_dir / "human-review-feedback.jsonl"
            ).exists() else []
            protected_input_ids = {
                str(row.get("inputId") or "") for row in [*finalized_rows, *feedback_rows]
            }
            eligible_items: list[tuple[int, int, str]] = []
            for source_order, item in enumerate(work):
                input_id = str(item["inputId"])
                if input_id in protected_input_ids:
                    continue
                page_path = pages_dir / f"{input_id}.json"
                if not page_path.exists():
                    raise ExtractionWorkflowError(
                        f"Existing extraction record is missing for {input_id}."
                    )
                existing_page = _read_json(page_path)
                if refresh_require_tab_systems and not existing_page.get("tabSystems"):
                    continue
                refresh_metadata = existing_page.get("unreviewedRefresh") or {}
                if (
                    str(existing_page.get("extractorVersion") or "") == EXTRACTOR_VERSION
                    and refresh_metadata.get("schemaVersion") == UNREVIEWED_REFRESH_SCHEMA_VERSION
                ):
                    continue
                complexity = sum(
                    len(system.get("tabEvents") or [])
                    for system in existing_page.get("tabSystems") or []
                ) + 4 * len(existing_page.get("tabSystems") or [])
                eligible_items.append((complexity, source_order, input_id))
            eligible_items.sort()
            refresh_target_ids = {
                input_id
                for _complexity, _source_order, input_id in eligible_items[: int(refresh_limit or 0)]
            }
            if not refresh_target_ids:
                raise ExtractionWorkflowError("No never-reviewed discovery pages are available to refresh.")
        run_contract = {
            "schemaVersion": EXTRACTION_SCHEMA_VERSION,
            "knowledgeSchemaVersion": KNOWLEDGE_SCHEMA_VERSION,
            "extractorVersion": EXTRACTOR_VERSION,
            "decisionDerivationVersion": DECISION_DERIVATION_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "sourceCopedentId": profile.id,
            "sourceCopedentRevision": profile.revision,
            "sourceCopedentDigest": _profile_digest(profile),
            "rightsAuthorizationDigest": rights_and_access.get("authorizationRecordDigest"),
            "stages": {"ocr": use_ocr, "omr": use_omr, "tabVision": use_tab_vision},
            "ocrReaderContract": (
                self.ocr.contract()
                if use_ocr and callable(getattr(self.ocr, "contract", None))
                else {"reader": type(self.ocr).__name__}
                if use_ocr
                else None
            ),
            "omrReaderContract": (
                self.omr.contract()
                if use_omr and callable(getattr(self.omr, "contract", None))
                else {"reader": type(self.omr).__name__}
                if use_omr
                else None
            ),
            "tabReader": str(getattr(self.tab_vision, "model", "injected-tab-reader")),
            "tabReaderContract": (
                self.tab_vision.contract()
                if use_tab_vision and callable(getattr(self.tab_vision, "contract", None))
                else {"reader": str(getattr(self.tab_vision, "model", "injected-tab-reader"))}
            ),
            "inputCount": len(work),
            "refreshMode": "never_reviewed_only" if refresh_unreviewed else None,
            "refreshTargetInputIds": sorted(refresh_target_ids),
            "refreshRequiresTabSystems": refresh_require_tab_systems,
            "validationModel": (
                self._validation_model_contract(
                    batch_id,
                    str(validation_model_id or ""),
                )
                if partition == "validation"
                else None
            ),
        }
        run_digest = _sha256_json(run_contract)
        page_records: list[dict[str, Any]] = []
        failures: list[dict[str, Any]] = []
        pending: list[tuple[int, dict[str, Any], Path]] = []
        for page_number, item in enumerate(work, start=1):
            input_id = str(item["inputId"])
            page_path = pages_dir / f"{input_id}.json"
            if refresh_unreviewed and input_id not in refresh_target_ids:
                if not page_path.exists():
                    raise ExtractionWorkflowError(
                        f"Protected extraction record is missing for {input_id}."
                    )
                page_records.append(_read_json(page_path))
                continue
            if resume and page_path.exists():
                existing = _read_json(page_path)
                if existing.get("runDigest") == run_digest and existing.get("assetSha256") == item["sha256"]:
                    page_records.append(existing)
                    continue
            pending.append((page_number, item, page_path))

        def process_page(task: tuple[int, dict[str, Any], Path]) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
            page_number, item, page_path = task
            input_id = str(item["inputId"])
            try:
                record = self._extract_page(
                    manifest,
                    item,
                    page_number=page_number,
                    output_root=output_root,
                    derivatives_dir=derivatives_dir,
                    profile=profile,
                    run_digest=run_digest,
                    use_ocr=use_ocr,
                    use_omr=use_omr,
                    use_tab_vision=use_tab_vision,
                    rights_and_access=rights_and_access,
                )
                if refresh_unreviewed:
                    record["unreviewedRefresh"] = {
                        "schemaVersion": UNREVIEWED_REFRESH_SCHEMA_VERSION,
                        "refreshRunDigest": run_digest,
                        "extractorVersion": EXTRACTOR_VERSION,
                        "reviewedOrFeedbackEvidencePreserved": True,
                        "refreshedAt": _utc_now(),
                    }
                if refresh_unreviewed and page_path.exists():
                    prior = _read_json(page_path)
                    prior_digest = _sha256_json(prior)
                    archive_path = (
                        review_dir
                        / "unreviewed-refresh-revisions"
                        / input_id
                        / f"{prior_digest}.json"
                    )
                    if not archive_path.exists():
                        _write_json(archive_path, prior)
                _write_json(page_path, record)
                return record, None
            except Exception as exc:  # keep a page failure bounded and reviewable
                failure = {
                    "batchId": batch_id,
                    "inputId": input_id,
                    "kind": "page_extraction_failure",
                    "message": str(exc)[:800],
                    "blocking": True,
                    "reviewState": "needs_human_review",
                }
                _write_json(review_dir / f"{input_id}-failure.json", failure)
                return None, failure

        processed: Iterable[tuple[dict[str, Any] | None, dict[str, Any] | None]]
        if workers == 1:
            processed = map(process_page, pending)
        else:
            executor = concurrent.futures.ThreadPoolExecutor(max_workers=workers)
            processed = executor.map(process_page, pending)
        try:
            for record, failure in processed:
                if record is not None:
                    page_records.append(record)
                if failure is not None:
                    failures.append(failure)
        finally:
            if workers != 1:
                executor.shutdown(wait=True)
        page_records.sort(key=lambda record: str(record["inputId"]))
        review_items = [item for page in page_records for item in page.get("unresolved", [])] + failures
        _write_jsonl(review_dir / "review-queue.jsonl", review_items)
        page_type_counts = Counter(
            str(page.get("pageClassification", {}).get("primary") or "unknown") for page in page_records
        )
        summary = {
            **run_contract,
            "runDigest": run_digest,
            "completedAt": _utc_now(),
            "processedCount": len(page_records),
            "failedPageCount": len(failures),
            "tabGridCount": sum(len(page.get("tabSystems", [])) for page in page_records),
            "scoreSystemCount": sum(len(page.get("scoreSystems", [])) for page in page_records),
            "scoreEventCount": sum(
                len(system.get("scoreEvents", [])) for page in page_records for system in page.get("scoreSystems", [])
            ),
            "tabEventCount": sum(
                len(system.get("tabEvents", [])) for page in page_records for system in page.get("tabSystems", [])
            ),
            "alignmentCount": sum(len(page.get("eventAlignments", [])) for page in page_records),
            "gripCount": sum(len(page.get("grips", [])) for page in page_records),
            "movementSequenceCount": sum(len(page.get("movementSequences", [])) for page in page_records),
            "derivedDecisionCount": sum(len(page.get("derivedDecisions", [])) for page in page_records),
            "teachingConceptCount": sum(len(page.get("teachingConcepts", [])) for page in page_records),
            "exerciseCount": sum(len(page.get("exercises", [])) for page in page_records),
            "blockingReviewItemCount": sum(bool(item.get("blocking")) for item in review_items),
            "reviewItemCount": len(review_items),
            "pageTypeCounts": dict(sorted(page_type_counts.items())),
            "reviewState": "needs_human_review" if review_items or failures else "machine_validated",
            "humanApprovalComplete": False,
            "extractorVersionsPresent": sorted(
                {str(page.get("extractorVersion") or "unknown") for page in page_records}
            ),
            "unreviewedRefresh": (
                {
                    "targetPageCount": len(refresh_target_ids),
                    "targetInputDigest": _sha256_json(sorted(refresh_target_ids)),
                    "protectedReviewedOrFeedbackPagesPreserved": True,
                    "cumulativeRefreshedPageCount": sum(
                        (page.get("unreviewedRefresh") or {}).get("schemaVersion")
                        == UNREVIEWED_REFRESH_SCHEMA_VERSION
                        for page in page_records
                    ),
                }
                if refresh_unreviewed
                else None
            ),
            "sealedTestAccessed": False,
        }
        _write_json(output_root / "summary.json", summary)
        return summary

    def refresh_unreviewed(
        self,
        batch_id: str,
        *,
        limit: int = 25,
        use_ocr: bool = True,
        use_omr: bool = True,
        use_tab_vision: bool = True,
        resume: bool = True,
        workers: int = 1,
        require_tab_systems: bool = False,
    ) -> dict[str, Any]:
        """Refresh only never-reviewed discovery pages while preserving human evidence."""

        return self.run(
            batch_id,
            partition="discovery",
            use_ocr=use_ocr,
            use_omr=use_omr,
            use_tab_vision=use_tab_vision,
            resume=resume,
            workers=workers,
            refresh_unreviewed=True,
            refresh_limit=limit,
            refresh_require_tab_systems=require_tab_systems,
        )

    def replay_event_count_exceptions(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        resume: bool = True,
    ) -> dict[str, Any]:
        """Evaluate a second count reader without mutating reviewed extraction facts."""

        if partition != "discovery":
            raise ExtractionWorkflowError(
                "Event-count rule development is discovery-only; validation and sealed test remain closed."
            )
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        if int(manifest.get("sourceCopedentRevision") or profile.revision) != profile.revision:
            raise ExtractionWorkflowError("The batch copedent revision does not match the deterministic profile.")
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        submissions_dir = review_dir / "submissions"
        if not pages_dir.exists() or not submissions_dir.exists():
            raise ExtractionWorkflowError("Reviewed discovery extraction and count feedback are required first.")

        source_counts: dict[tuple[str, str], int] = {}
        submission_digests: set[str] = set()
        for submission_path in sorted(submissions_dir.glob("*.jsonl")):
            rows = _read_jsonl(submission_path)
            if not rows:
                continue
            for row in rows:
                input_id = str(row.get("inputId") or "")
                raw_counts = row.get("sourceEventCounts") or {}
                if not isinstance(raw_counts, Mapping):
                    continue
                for tab_system_id, raw_count in raw_counts.items():
                    count = int(raw_count)
                    if count < 0 or count > 128:
                        raise ExtractionWorkflowError("A reviewed source event count is out of range.")
                    key = (input_id, str(tab_system_id))
                    if key in source_counts and source_counts[key] != count:
                        raise ExtractionWorkflowError(
                            f"Conflicting reviewed source event counts exist for {input_id}."
                        )
                    source_counts[key] = count
            if any((row.get("sourceEventCounts") or {}) for row in rows):
                submission_digests.add(_sha256_json(rows))
        if not source_counts:
            raise ExtractionWorkflowError("No reviewed source event counts are available for replay.")

        replay_dir = review_dir / "analysis" / EVENT_COUNT_REPLAY_SCHEMA_VERSION
        crop_dir = replay_dir / "source-pairs"
        prediction_dir = replay_dir / "predictions"
        for directory in (replay_dir, crop_dir, prediction_dir):
            directory.mkdir(parents=True, exist_ok=True)
            os.chmod(directory, 0o700)
        reader_contract = self.tab_system_vision.contract()
        reader_contract_digest = _sha256_json(reader_contract)
        counted_cases: list[dict[str, Any]] = []

        for (input_id, tab_system_id), source_count in sorted(source_counts.items()):
            page_path = pages_dir / f"{input_id}.json"
            if not page_path.exists():
                raise ExtractionWorkflowError(f"The discovery page record is missing for {input_id}.")
            record = _read_json(page_path)
            tab_system = next(
                (
                    system
                    for system in record.get("tabSystems") or []
                    if str(system.get("tabSystemId") or "") == tab_system_id
                ),
                None,
            )
            if tab_system is None:
                raise ExtractionWorkflowError(f"The reviewed tab system is missing for {input_id}.")
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("pairedTabSystemId") or "") == tab_system_id
                ),
                None,
            )

            event_sequences: dict[int, int] = {}
            candidate_ids: set[int] = set()
            for sheet in tab_system.get("contactSheets") or []:
                sheet_path = output_root / str(sheet.get("relativePath") or "")
                token_path = sheet_path.with_suffix(".tokens.json")
                if not token_path.exists():
                    continue
                token_cache = _read_json(token_path)
                labels = [str(value) for value in token_cache.get("labels") or []]
                cells = token_cache.get("cells") or {}
                for label in labels:
                    label_match = re.fullmatch(r"e(\d+)s(10|[1-9])", label)
                    if label_match is None:
                        continue
                    event_index = int(label_match.group(1))
                    string = int(label_match.group(2))
                    candidate_ids.add(event_index)
                    cell = cells.get(label)
                    if not isinstance(cell, Mapping):
                        continue
                    sequence, _issue = _tab_action_sequence_from_cell(
                        cell,
                        string=string,
                        profile=profile,
                        region_id=f"event-count-replay:{input_id}:{tab_system_id}:{label}",
                    )
                    if sequence:
                        event_sequences[event_index] = max(
                            event_sequences.get(event_index, 0), len(sequence)
                        )
            recognized_count = sum(event_sequences.values())
            high_recall_count = len(candidate_ids) + sum(
                max(0, length - 1) for length in event_sequences.values()
            )
            base_case = {
                "inputId": input_id,
                "tabSystemId": tab_system_id,
                "systemIndex": int(tab_system.get("systemIndex") or 0),
                "sourceEventCount": source_count,
                "machineEventCount": len(tab_system.get("tabEvents") or []),
                "recognizedEventCount": recognized_count,
                "highRecallEventCount": high_recall_count,
                "scoreAttackCount": (
                    len(_score_attack_groups(score_system.get("scoreEvents") or []))
                    if score_system is not None
                    else None
                ),
            }
            if high_recall_count == source_count:
                counted_cases.append({**base_case, "status": "baseline_exact"})
                continue

            derivative = record.get("derivative") or {}
            derivative_path = output_root / str(derivative.get("relativePath") or "")
            if not derivative_path.exists():
                raise ExtractionWorkflowError(f"The private derivative is missing for {input_id}.")
            regions = [tab_system.get("pageRegion") or {}]
            if score_system is not None:
                regions.insert(0, score_system.get("pageRegion") or {})
            if any(
                float(region.get("width") or 0.0) <= 0.0
                or float(region.get("height") or 0.0) <= 0.0
                for region in regions
            ):
                raise ExtractionWorkflowError(f"The source-pair geometry is incomplete for {input_id}.")
            with Image.open(derivative_path) as opened:
                image = opened.convert("RGB")
            left = max(0.0, min(float(region.get("x") or 0.0) for region in regions) - 0.01)
            top = max(0.0, min(float(region.get("y") or 0.0) for region in regions) - 0.008)
            right = min(
                1.0,
                max(
                    float(region.get("x") or 0.0) + float(region.get("width") or 0.0)
                    for region in regions
                )
                + 0.01,
            )
            bottom = min(
                1.0,
                max(
                    float(region.get("y") or 0.0) + float(region.get("height") or 0.0)
                    for region in regions
                )
                + 0.008,
            )
            crop = image.crop(
                (
                    int(math.floor(left * image.width)),
                    int(math.floor(top * image.height)),
                    int(math.ceil(right * image.width)),
                    int(math.ceil(bottom * image.height)),
                )
            )
            crop_path = crop_dir / f"{input_id}-system-{int(tab_system.get('systemIndex') or 0):02d}.png"
            crop.save(crop_path, format="PNG")
            os.chmod(crop_path, 0o600)
            crop_digest = _sha256_bytes(crop_path.read_bytes())
            prediction_path = prediction_dir / f"{input_id}-{tab_system_id}.json"
            prediction: dict[str, Any]
            if resume and prediction_path.exists():
                cached = _read_json(prediction_path)
                if (
                    cached.get("cropSha256") == crop_digest
                    and cached.get("readerContractDigest") == reader_contract_digest
                    and isinstance(cached.get("prediction"), Mapping)
                ):
                    prediction = dict(cached["prediction"])
                else:
                    prediction = self.tab_system_vision.read_event_count(crop_path)
            else:
                prediction = self.tab_system_vision.read_event_count(crop_path)
            _write_json(
                prediction_path,
                {
                    "schemaVersion": EVENT_COUNT_REPLAY_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "tabSystemId": tab_system_id,
                    "cropSha256": crop_digest,
                    "readerContractDigest": reader_contract_digest,
                    "prediction": prediction,
                    "sourceCountExcludedFromReaderPrompt": True,
                    "reviewedRecordsModified": False,
                },
            )
            counted_cases.append(
                {
                    **base_case,
                    "wholeSystemEventCount": int(prediction["eventCount"]),
                    "wholeSystemConfidence": float(prediction["confidence"]),
                    "wholeSystemUncertain": bool(prediction["uncertain"]),
                    "status": "exception_replayed",
                }
            )

        exception_cases = [case for case in counted_cases if case.get("status") == "exception_replayed"]
        for case in exception_cases:
            case["eligibleForNormalizedEvents"] = False
            case["requiresEventLocalization"] = True
        fusion = _evaluate_event_count_fusion_rules(exception_cases)
        selected_predictions = list(fusion.get("selectedPredictions") or [])
        if selected_predictions:
            if len(selected_predictions) != len(exception_cases):
                raise ExtractionWorkflowError("The event-count fusion result is incomplete.")
            for case, prediction in zip(exception_cases, selected_predictions, strict=True):
                case["diagnosticEventCount"] = int(prediction)
                case["diagnosticCountRule"] = fusion.get("selectedRule")
        report = {
            "schemaVersion": EVENT_COUNT_REPLAY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "extractorVersion": EXTRACTOR_VERSION,
            "sourceCopedentId": profile.id,
            "sourceCopedentRevision": profile.revision,
            "sourceCopedentDigest": _profile_digest(profile),
            "sourceCountSubmissionDigests": sorted(submission_digests),
            "sourceCountSystemCount": len(counted_cases),
            "baselineExactSystemCount": sum(
                case.get("status") == "baseline_exact" for case in counted_cases
            ),
            "exceptionSystemCount": len(exception_cases),
            "readerContract": reader_contract,
            "readerContractDigest": reader_contract_digest,
            "fusionEvaluation": fusion,
            "cases": counted_cases,
            "reviewedRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "completedAt": _utc_now(),
        }
        report_path = replay_dir / "event-count-replay-report.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": EVENT_COUNT_REPLAY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "reportPath": str(report_path),
            "reportDigest": _sha256_bytes(report_path.read_bytes()),
            "sourceCountSystemCount": len(counted_cases),
            "exceptionSystemCount": len(exception_cases),
            "fusionEvaluation": fusion,
            "reviewedRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def prepare_event_localization_review(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        resume: bool = True,
    ) -> dict[str, Any]:
        """Localize count-constrained discovery repairs and prepare one compact review."""

        if partition != "discovery":
            raise ExtractionWorkflowError("Event localization review is discovery-only.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        output_root = batch_dir / "extraction" / partition
        replay_dir = output_root / "review" / "analysis" / EVENT_COUNT_REPLAY_SCHEMA_VERSION
        report_path = replay_dir / "event-count-replay-report.json"
        if not report_path.exists():
            raise ExtractionWorkflowError("The isolated event-count replay must run first.")
        count_report = _read_json(report_path)
        if not bool((count_report.get("fusionEvaluation") or {}).get("gatePassed")):
            raise ExtractionWorkflowError("No event-count fusion rule passed the two-sided error gate.")
        localization_dir = replay_dir / "localization-review"
        candidates_dir = localization_dir / "candidates"
        for directory in (localization_dir, candidates_dir):
            directory.mkdir(parents=True, exist_ok=True)
            os.chmod(directory, 0o700)
        input_names = {
            str(item.get("inputId") or ""): str(item.get("relativePath") or "")
            for item in manifest.get("inputs") or []
        }
        target_cases = [
            case
            for case in count_report.get("cases") or []
            if case.get("status") == "exception_replayed"
            and int(case.get("diagnosticEventCount") or -1) != int(case.get("sourceEventCount") or -2)
        ]
        contract = {
            "model": self.tab_system_vision.model,
            "promptVersion": TAB_SYSTEM_LOCALIZATION_PROMPT_VERSION,
            "temperature": 0,
            "seed": self.tab_system_vision.seed,
            "numCtx": self.tab_system_vision.num_ctx,
        }
        contract_digest = _sha256_json(contract)
        systems: list[dict[str, Any]] = []
        failures: list[dict[str, Any]] = []
        for case in target_cases:
            input_id = str(case["inputId"])
            tab_system_id = str(case["tabSystemId"])
            system_index = int(case["systemIndex"])
            expected_count = int(case["sourceEventCount"])
            crop_path = replay_dir / "source-pairs" / f"{input_id}-system-{system_index:02d}.png"
            if not crop_path.exists():
                failures.append({"inputId": input_id, "tabSystemId": tab_system_id, "kind": "missing_source_pair"})
                continue
            crop_digest = _sha256_bytes(crop_path.read_bytes())
            page_path = output_root / "pages" / f"{input_id}.json"
            if not page_path.exists():
                failures.append({"inputId": input_id, "tabSystemId": tab_system_id, "kind": "missing_page_record"})
                continue
            record = _read_json(page_path)
            tab_system = next(
                (
                    system
                    for system in record.get("tabSystems") or []
                    if str(system.get("tabSystemId") or "") == tab_system_id
                ),
                None,
            )
            if tab_system is None:
                failures.append({"inputId": input_id, "tabSystemId": tab_system_id, "kind": "missing_tab_system"})
                continue
            try:
                localizer_crop = _prepare_event_localization_tab_crop(
                    output_root=output_root,
                    localization_dir=localization_dir,
                    input_id=input_id,
                    record=record,
                    tab_system=tab_system,
                )
            except ExtractionWorkflowError as exc:
                failures.append(
                    {
                        "inputId": input_id,
                        "tabSystemId": tab_system_id,
                        "kind": "localizer_crop_failure",
                        "message": str(exc),
                    }
                )
                continue
            localizer_crop_path = Path(localizer_crop["path"])
            localizer_crop_digest = _sha256_bytes(localizer_crop_path.read_bytes())
            candidate_path = candidates_dir / f"{input_id}-{tab_system_id}.json"
            localization: dict[str, Any] | None = None
            if resume and candidate_path.exists():
                cached = _read_json(candidate_path)
                if (
                    cached.get("cropSha256") == crop_digest
                    and cached.get("localizerCropSha256") == localizer_crop_digest
                    and cached.get("contractDigest") == contract_digest
                    and int(cached.get("expectedEventCount") or 0) == expected_count
                    and isinstance(cached.get("localization"), Mapping)
                ):
                    localization = dict(cached["localization"])
            if localization is None:
                try:
                    localization = self.tab_system_vision.localize_events(
                        localizer_crop_path,
                        expected_event_count=expected_count,
                        control_string_map=_profile_control_string_map(profile),
                    )
                except ExtractionWorkflowError as exc:
                    failures.append(
                        {
                            "inputId": input_id,
                            "tabSystemId": tab_system_id,
                            "kind": "localization_failure",
                            "message": str(exc),
                        }
                    )
                    continue
            _write_json(
                candidate_path,
                {
                    "schemaVersion": EVENT_LOCALIZATION_REVIEW_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "tabSystemId": tab_system_id,
                    "cropSha256": crop_digest,
                    "localizerCropSha256": localizer_crop_digest,
                    "contractDigest": contract_digest,
                    "expectedEventCount": expected_count,
                    "localization": localization,
                    "countConstraintSource": "human_reviewed_discovery_feedback",
                    "eligibleForNormalizedEvents": False,
                },
            )
            mechanical_issues: list[dict[str, Any]] = []
            events: list[dict[str, Any]] = []
            for event in localization.get("events") or []:
                execution = str(event.get("execution") or "uncertain")
                cells: list[dict[str, Any]] = []
                for cell in event.get("cells") or []:
                    string = int(cell["string"])
                    token = str(cell["token"])
                    action, issue = _tab_action_from_token(
                        token,
                        string=string,
                        profile=profile,
                        confidence=float(localization.get("confidence") or 0.0),
                        region_id=f"localization:{input_id}:{tab_system_id}:{event['eventIndex']}:{string}",
                    )
                    valid = bool(action and action.get("mechanicalValidation", {}).get("valid"))
                    if issue is not None or not valid:
                        mechanical_issues.append(
                            {
                                "eventIndex": int(event["eventIndex"]),
                                "string": string,
                                "token": token,
                                "issueKind": (issue or {}).get("kind") or "invalid_action",
                            }
                        )
                    cells.append({"string": string, "token": token, "mechanicalValid": valid})
                if execution == "uncertain":
                    mechanical_issues.append(
                        {
                            "eventIndex": int(event["eventIndex"]),
                            "issueKind": "uncertain_execution",
                        }
                    )
                events.append(
                    {
                        "eventIndex": int(event["eventIndex"]),
                        "x": float(event["x"]),
                        "execution": execution,
                        "cells": cells,
                    }
                )
            mapped_centers = [float(value) for value in localizer_crop["stringCenters"]]
            median_gap = float(np.median(np.diff(mapped_centers)))
            line_ys = [mapped_centers[0] - median_gap / 2.0]
            line_ys.extend(
                (left + right) / 2.0
                for left, right in zip(mapped_centers, mapped_centers[1:], strict=False)
            )
            line_ys.append(mapped_centers[-1] + median_gap / 2.0)
            guided_gray = np.asarray(Image.open(localizer_crop_path).convert("L"))
            visual_grid = GridDetection(
                x0=int(localizer_crop["contentX0"]),
                y0=max(0, int(round(line_ys[0]))),
                x1=int(localizer_crop["contentX1"]) - 1,
                y1=min(int(localizer_crop["height"]) - 1, int(round(line_ys[-1]))),
                line_ys=tuple(int(round(value)) for value in line_ys),
                confidence=float(tab_system.get("detectionConfidence") or 0.0),
            )
            visual_candidates = _tab_event_candidates(guided_gray, visual_grid)
            visual_count_agreement = len(visual_candidates) == expected_count
            position_deltas: list[float] = []
            string_pattern_agreements: list[bool] = []
            if visual_count_agreement:
                content_width = max(
                    1.0,
                    float(localizer_crop["contentX1"]) - float(localizer_crop["contentX0"]),
                )
                full_width = float(localizer_crop["width"])
                for event, candidate in zip(events, visual_candidates, strict=True):
                    model_x = (
                        float(event["x"]) * full_width - float(localizer_crop["contentX0"])
                    ) / content_width
                    candidate_x = float(candidate["x"]) / max(
                        1.0, float(visual_grid.x1 - visual_grid.x0)
                    )
                    position_deltas.append(abs(model_x - candidate_x))
                    string_pattern_agreements.append(
                        {int(cell["string"]) for cell in event["cells"]}
                        == {int(value) for value in candidate["candidateStrings"]}
                    )
            visual_position_agreement = bool(position_deltas) and max(position_deltas) <= 0.065
            visual_string_agreement = bool(string_pattern_agreements) and all(
                string_pattern_agreements
            )
            quality_gate_passed = bool(
                not mechanical_issues
                and not localization.get("uncertain")
                and visual_count_agreement
                and visual_position_agreement
                and visual_string_agreement
            )
            if not quality_gate_passed:
                failures.append(
                    {
                        "inputId": input_id,
                        "tabSystemId": tab_system_id,
                        "kind": "quality_gate_rejected",
                        "mechanicalValid": not mechanical_issues,
                        "visualCandidateEventCount": len(visual_candidates),
                        "expectedEventCount": expected_count,
                        "visualPositionAgreement": visual_position_agreement,
                        "visualStringAgreement": visual_string_agreement,
                    }
                )
                continue
            systems.append(
                {
                    "inputId": input_id,
                    "imageFilename": input_names.get(input_id) or input_id,
                    "tabSystemId": tab_system_id,
                    "systemIndex": system_index,
                    "sourceEventCount": expected_count,
                    "priorDiagnosticEventCount": int(case["diagnosticEventCount"]),
                    "cropUrl": f"../source-pairs/{crop_path.name}",
                    "events": events,
                    "localizationConfidence": float(localization.get("confidence") or 0.0),
                    "localizationUncertain": bool(localization.get("uncertain")),
                    "mechanicalValid": not mechanical_issues,
                    "mechanicalIssues": mechanical_issues,
                    "independentVisualCandidateCount": len(visual_candidates),
                    "independentVisualPositionAgreement": visual_position_agreement,
                    "independentVisualStringAgreement": visual_string_agreement,
                    "qualityGatePassed": quality_gate_passed,
                    "eligibleForNormalizedEvents": False,
                    "reviewState": "needs_human_review",
                }
            )
        if not systems:
            raise ExtractionWorkflowError("No event-localization candidate passed structural parsing.")
        packet_core = {
            "schemaVersion": EVENT_LOCALIZATION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "sourceCopedentId": profile.id,
            "sourceCopedentRevision": profile.revision,
            "countReplayReportDigest": _sha256_bytes(report_path.read_bytes()),
            "systems": systems,
            "failures": failures,
            "reviewedRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_path = localization_dir / "packet.json"
        summary_path = localization_dir / "packet-summary.json"
        console_path = localization_dir / "localization-review-console.html"
        _write_json(packet_path, packet)
        _write_json(
            summary_path,
            {
                "schemaVersion": EVENT_LOCALIZATION_REVIEW_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": partition,
                "packetDigest": packet_digest,
                "systemCount": len(systems),
                "failureCount": len(failures),
                "mechanicallyValidSystemCount": sum(system["mechanicalValid"] for system in systems),
                "reviewedRecordsModified": False,
                "validationAccessed": False,
                "sealedTestAccessed": False,
            },
        )
        _write_private_text(console_path, _event_localization_review_html(packet))
        return {
            "schemaVersion": EVENT_LOCALIZATION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "packetDigest": packet_digest,
            "systemCount": len(systems),
            "failureCount": len(failures),
            "mechanicallyValidSystemCount": sum(system["mechanicalValid"] for system in systems),
            "consolePath": str(console_path),
            "relativeUrl": (
                f"/{batch_id}/extraction/{partition}/review/analysis/"
                f"{EVENT_COUNT_REPLAY_SCHEMA_VERSION}/localization-review/"
                "localization-review-console.html"
            ),
            "reviewedRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def prepare_score_pitch_correspondence_review(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        resume: bool = True,
    ) -> dict[str, Any]:
        """Prepare an independent score-only pitch/octave audit for accepted localization."""

        if partition != "discovery":
            raise ExtractionWorkflowError("Score-pitch correspondence review is discovery-only.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        output_root = batch_dir / "extraction" / partition
        localization_dir = (
            output_root
            / "review"
            / "analysis"
            / EVENT_COUNT_REPLAY_SCHEMA_VERSION
            / "localization-review"
        )
        localization_packet_path = localization_dir / "packet.json"
        if not localization_packet_path.exists():
            raise ExtractionWorkflowError("An event-localization packet must be reviewed first.")
        localization_packet = _read_json(localization_packet_path)
        accepted: set[tuple[str, str]] = set()
        for submission_path in sorted((localization_dir / "submissions").glob("*.jsonl")):
            for review in _read_jsonl(submission_path):
                if str(review.get("status") or "") == "accept":
                    accepted.add(
                        (
                            str(review.get("inputId") or ""),
                            str(review.get("tabSystemId") or ""),
                        )
                    )
        if not accepted:
            raise ExtractionWorkflowError("No accepted event-localization submission is available.")
        audit_dir = localization_dir / "score-pitch-audit"
        candidates_dir = audit_dir / "candidates"
        for directory in (audit_dir, candidates_dir):
            directory.mkdir(parents=True, exist_ok=True)
            os.chmod(directory, 0o700)
        input_names = {
            str(item.get("inputId") or ""): str(item.get("relativePath") or "")
            for item in manifest.get("inputs") or []
        }
        contract = {
            "model": self.tab_system_vision.model,
            "promptVersion": SCORE_PITCH_LOCALIZATION_PROMPT_VERSION,
            "temperature": 0,
            "seed": self.tab_system_vision.seed,
            "numCtx": self.tab_system_vision.num_ctx,
            "tablatureOrExpectedPitchesProvidedToReader": False,
        }
        contract_digest = _sha256_json(contract)
        systems: list[dict[str, Any]] = []
        failures: list[dict[str, Any]] = []
        for localized in localization_packet.get("systems") or []:
            input_id = str(localized.get("inputId") or "")
            tab_system_id = str(localized.get("tabSystemId") or "")
            if (input_id, tab_system_id) not in accepted:
                continue
            page_path = output_root / "pages" / f"{input_id}.json"
            if not page_path.exists():
                failures.append({"inputId": input_id, "kind": "missing_page_record"})
                continue
            record = _read_json(page_path)
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("pairedTabSystemId") or "") == tab_system_id
                ),
                None,
            )
            if score_system is None:
                failures.append({"inputId": input_id, "kind": "missing_paired_score_system"})
                continue
            score_crop_path = _prepare_score_pitch_crop(
                output_root=output_root,
                audit_dir=audit_dir,
                input_id=input_id,
                record=record,
                score_system=score_system,
            )
            score_crop_digest = _sha256_bytes(score_crop_path.read_bytes())
            expected_count = len(localized.get("events") or [])
            candidate_path = candidates_dir / f"{input_id}-{tab_system_id}.json"
            recognition: dict[str, Any] | None = None
            if resume and candidate_path.exists():
                cached = _read_json(candidate_path)
                if (
                    cached.get("scoreCropSha256") == score_crop_digest
                    and cached.get("contractDigest") == contract_digest
                    and int(cached.get("expectedEventCount") or 0) == expected_count
                    and isinstance(cached.get("recognition"), Mapping)
                ):
                    recognition = dict(cached["recognition"])
            if recognition is None:
                try:
                    recognition = self.tab_system_vision.read_score_pitch_events(
                        score_crop_path,
                        expected_event_count=expected_count,
                    )
                except ExtractionWorkflowError as exc:
                    failures.append(
                        {
                            "inputId": input_id,
                            "tabSystemId": tab_system_id,
                            "kind": "score_pitch_localization_failure",
                            "message": str(exc),
                        }
                    )
                    continue
            _write_json(
                candidate_path,
                {
                    "schemaVersion": SCORE_PITCH_AUDIT_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "tabSystemId": tab_system_id,
                    "scoreCropSha256": score_crop_digest,
                    "contractDigest": contract_digest,
                    "expectedEventCount": expected_count,
                    "recognition": recognition,
                    "tablatureOrExpectedPitchesProvidedToReader": False,
                    "eligibleForNormalizedEvents": False,
                },
            )
            comparisons: list[dict[str, Any]] = []
            for score_event, tab_event in zip(
                recognition.get("events") or [], localized.get("events") or [], strict=True
            ):
                tab_pitches: list[tuple[int, str]] = []
                tab_cells: list[dict[str, Any]] = []
                for cell in tab_event.get("cells") or []:
                    action, issue = _tab_action_from_token(
                        str(cell["token"]),
                        string=int(cell["string"]),
                        profile=profile,
                        confidence=1.0,
                        region_id=(
                            f"score-pitch:{input_id}:{tab_system_id}:"
                            f"{tab_event['eventIndex']}:{cell['string']}"
                        ),
                    )
                    if issue is not None or action is None:
                        raise ExtractionWorkflowError(
                            f"Accepted localization contains an invalid action for {input_id}."
                        )
                    tab_pitches.append(
                        (int(action["soundingPitchValue"]), str(action["soundingPitch"]))
                    )
                    tab_cells.append({"string": int(cell["string"]), "token": str(cell["token"])})
                tab_pitches.sort()
                score_values = [int(value) for value in score_event["pitchValues"]]
                tab_values = [value for value, _pitch in tab_pitches]
                score_value_set = set(score_values)
                tab_value_set = set(tab_values)
                score_pitches_represented = score_value_set.issubset(tab_value_set)
                relationship_status = _score_tab_pitch_relationship(score_values, tab_values)
                comparisons.append(
                    {
                        "eventIndex": int(tab_event["eventIndex"]),
                        "scoreX": float(score_event["x"]),
                        "scorePitches": list(score_event["pitches"]),
                        "scorePitchValues": score_values,
                        "tabCells": tab_cells,
                        "tabPitches": [pitch for _value, pitch in tab_pitches],
                        "tabPitchValues": tab_values,
                        "exactPitchMatch": score_values == tab_values,
                        "scorePitchesRepresented": score_pitches_represented,
                        "relationshipStatus": relationship_status,
                        "extraTabPitches": [
                            pitch for value, pitch in tab_pitches if value not in score_value_set
                        ],
                    }
                )
            key_fifths = int(recognition.get("keySignatureFifths") or 0)
            key_labels = {
                -7: "C♭ major / A♭ minor",
                -6: "G♭ major / E♭ minor",
                -5: "D♭ major / B♭ minor",
                -4: "A♭ major / F minor",
                -3: "E♭ major / C minor",
                -2: "B♭ major / G minor",
                -1: "F major / D minor",
                0: "C major / A minor",
                1: "G major / E minor (one sharp)",
                2: "D major / B minor",
                3: "A major / F♯ minor",
                4: "E major / C♯ minor",
                5: "B major / G♯ minor",
                6: "F♯ major / D♯ minor",
                7: "C♯ major / A♯ minor",
            }
            crop_name = f"{input_id}-system-{int(localized.get('systemIndex') or 0):02d}.png"
            review_action_required = not (
                str(recognition.get("captureMethod") or "")
                == "reviewer-corrected-score-pitch-v1"
                and bool(recognition.get("reviewerFeedbackSubmissionDigest"))
            )
            systems.append(
                {
                    "inputId": input_id,
                    "imageFilename": input_names.get(input_id) or input_id,
                    "tabSystemId": tab_system_id,
                    "scoreSystemId": str(score_system.get("scoreSystemId") or ""),
                    "systemIndex": int(localized.get("systemIndex") or 0),
                    "sourcePairUrl": f"../../source-pairs/{crop_name}",
                    "scoreOnlyCropSha256": score_crop_digest,
                    "keySignatureFifths": key_fifths,
                    "keySignatureLabel": key_labels[key_fifths],
                    "events": comparisons,
                    "exactPitchMatchCount": sum(item["exactPitchMatch"] for item in comparisons),
                    "allExactPitchMatches": all(item["exactPitchMatch"] for item in comparisons),
                    "scoreRepresentedCount": sum(
                        item["scorePitchesRepresented"] for item in comparisons
                    ),
                    "allScorePitchesRepresented": all(
                        item["scorePitchesRepresented"] for item in comparisons
                    ),
                    "scoreCaptureMethod": str(
                        recognition.get("captureMethod") or "local_score_vision"
                    ),
                    "recognitionConfidence": float(recognition.get("confidence") or 0.0),
                    "recognitionUncertain": bool(recognition.get("uncertain")),
                    "tablatureOrExpectedPitchesProvidedToReader": recognition.get(
                        "tablatureOrExpectedPitchesProvidedToReader"
                    ),
                    "scoreCaptureIndependence": str(
                        recognition.get("captureIndependence") or "unresolved"
                    ),
                    "reviewerFeedbackSubmissionId": recognition.get(
                        "reviewerFeedbackSubmissionId"
                    ),
                    "reviewerFeedbackSubmissionDigest": recognition.get(
                        "reviewerFeedbackSubmissionDigest"
                    ),
                    "reviewActionRequired": review_action_required,
                    "eligibleForNormalizedEvents": False,
                    "reviewState": (
                        "human_corrected_from_feedback"
                        if not review_action_required
                        else "needs_human_review"
                    ),
                }
            )
        if not systems:
            raise ExtractionWorkflowError("No accepted localization produced a score-pitch audit candidate.")
        packet_core = {
            "schemaVersion": SCORE_PITCH_AUDIT_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "sourceCopedentId": profile.id,
            "sourceCopedentRevision": profile.revision,
            "localizationPacketDigest": str(localization_packet.get("packetDigest") or ""),
            "systems": systems,
            "failures": failures,
            "reviewActionRequired": any(system["reviewActionRequired"] for system in systems),
            "reviewedRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_path = audit_dir / "packet.json"
        summary_path = audit_dir / "packet-summary.json"
        console_path = audit_dir / "score-pitch-audit-console.html"
        _write_json(packet_path, packet)
        _write_json(
            summary_path,
            {
                "schemaVersion": SCORE_PITCH_AUDIT_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": partition,
                "packetDigest": packet_digest,
                "systemCount": len(systems),
                "eventCount": sum(len(system["events"]) for system in systems),
                "exactPitchMatchCount": sum(
                    system["exactPitchMatchCount"] for system in systems
                ),
                "allExactPitchMatches": all(
                    system["allExactPitchMatches"] for system in systems
                ),
                "scoreRepresentedCount": sum(
                    system["scoreRepresentedCount"] for system in systems
                ),
                "allScorePitchesRepresented": all(
                    system["allScorePitchesRepresented"] for system in systems
                ),
                "reviewActionRequired": packet_core["reviewActionRequired"],
                "reviewedRecordsModified": False,
                "validationAccessed": False,
                "sealedTestAccessed": False,
            },
        )
        _write_private_text(console_path, _score_pitch_audit_html(packet))
        return {
            "schemaVersion": SCORE_PITCH_AUDIT_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "packetDigest": packet_digest,
            "systemCount": len(systems),
            "eventCount": sum(len(system["events"]) for system in systems),
            "exactPitchMatchCount": sum(system["exactPitchMatchCount"] for system in systems),
            "allExactPitchMatches": all(system["allExactPitchMatches"] for system in systems),
            "scoreRepresentedCount": sum(system["scoreRepresentedCount"] for system in systems),
            "allScorePitchesRepresented": all(
                system["allScorePitchesRepresented"] for system in systems
            ),
            "reviewActionRequired": packet_core["reviewActionRequired"],
            "consolePath": str(console_path),
            "relativeUrl": (
                f"/{batch_id}/extraction/{partition}/review/analysis/"
                f"{EVENT_COUNT_REPLAY_SCHEMA_VERSION}/localization-review/score-pitch-audit/"
                "score-pitch-audit-console.html"
            ),
            "reviewedRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def replay_score_chord_omission_gate(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Replay strict score-chord completeness across reviewed discovery evidence."""

        if partition != "discovery":
            raise ExtractionWorkflowError("The score-chord omission replay is discovery-only.")
        batch_dir, _manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        audit_dir = review_dir / "score-audit"
        sources: list[dict[str, Any]] = []

        approved_index_path = audit_dir / "approved-score-index.jsonl"
        for entry in _read_jsonl(approved_index_path) if approved_index_path.exists() else []:
            if entry.get("status") != "human_approved":
                continue
            relative_path = str(entry.get("reviewedRecordPath") or "")
            expected_digest = str(entry.get("reviewedRecordDigest") or "")
            path = output_root / relative_path
            if not relative_path or not path.exists():
                raise ExtractionWorkflowError("An approved score record is missing during replay.")
            record = _read_json(path)
            if _sha256_json(record) != expected_digest:
                raise ExtractionWorkflowError("An approved score record changed during replay.")
            sources.append(
                {
                    "inputId": str(entry.get("inputId") or ""),
                    "recordKind": "human_approved_score_record",
                    "recordDigest": expected_digest,
                    "record": record,
                }
            )

        repair_index_path = audit_dir / "repair" / "score-repair-index.jsonl"
        latest_repairs: dict[str, dict[str, Any]] = {}
        for entry in _read_jsonl(repair_index_path) if repair_index_path.exists() else []:
            latest_repairs[str(entry.get("inputId") or "")] = entry
        for input_id, entry in sorted(latest_repairs.items()):
            relative_path = str(entry.get("candidateRecordPath") or "")
            expected_digest = str(entry.get("candidateRecordDigest") or "")
            path = output_root / relative_path
            if not relative_path or not path.exists():
                raise ExtractionWorkflowError("A current score-repair candidate is missing during replay.")
            record = _read_json(path)
            if _sha256_json(record) != expected_digest:
                raise ExtractionWorkflowError("A score-repair candidate changed during replay.")
            sources.append(
                {
                    "inputId": input_id,
                    "recordKind": "current_score_repair_candidate",
                    "recordDigest": expected_digest,
                    "record": record,
                }
            )

        records: list[dict[str, Any]] = []
        counts: Counter[str] = Counter()
        for source in sources:
            findings = score_tab_pitch_relationship_findings(source.pop("record"))
            relationship_counts = Counter(
                str(item.get("relationshipStatus") or "mismatch") for item in findings
            )
            counts.update(relationship_counts)
            records.append(
                {
                    **source,
                    "alignmentCount": len(findings),
                    "relationshipCounts": dict(sorted(relationship_counts.items())),
                    "nonExactRelationships": [
                        item for item in findings if not item["exactPitchAndOctaveSet"]
                    ],
                    "eligibleForPitchToTabTraining": bool(findings)
                    and all(item["eligibleForPitchToTabTraining"] for item in findings),
                }
            )

        isolated_packet_path = (
            review_dir
            / "analysis"
            / EVENT_COUNT_REPLAY_SCHEMA_VERSION
            / "localization-review"
            / "score-pitch-audit"
            / "packet.json"
        )
        isolated_systems: list[dict[str, Any]] = []
        if isolated_packet_path.exists():
            isolated_packet = _read_json(isolated_packet_path)
            packet_core = {
                key: copy.deepcopy(value)
                for key, value in isolated_packet.items()
                if key != "packetDigest"
            }
            if _sha256_json(packet_core) != str(isolated_packet.get("packetDigest") or ""):
                raise ExtractionWorkflowError("The isolated score-pitch packet digest changed.")
            for system in isolated_packet.get("systems") or []:
                relationship_counts = Counter(
                    str(event.get("relationshipStatus") or "mismatch")
                    for event in system.get("events") or []
                )
                counts.update(relationship_counts)
                isolated_systems.append(
                    {
                        "inputId": str(system.get("inputId") or ""),
                        "scoreSystemId": str(system.get("scoreSystemId") or ""),
                        "tabSystemId": str(system.get("tabSystemId") or ""),
                        "packetDigest": str(isolated_packet.get("packetDigest") or ""),
                        "reviewerFeedbackSubmissionId": system.get(
                            "reviewerFeedbackSubmissionId"
                        ),
                        "relationshipCounts": dict(sorted(relationship_counts.items())),
                        "allExactPitchAndOctaveSets": bool(system.get("events"))
                        and all(
                            event.get("relationshipStatus") == "exact"
                            for event in system.get("events") or []
                        ),
                        "eligibleForNormalizedEvents": False,
                        "withheldReason": "page_level_corrections_not_yet_human_approved",
                    }
                )

        report_core = {
            "schemaVersion": SCORE_CHORD_OMISSION_REPLAY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "requiresExactPitchAndOctaveSets": True,
            "recordCount": len(records),
            "isolatedSystemCount": len(isolated_systems),
            "relationshipCounts": dict(sorted(counts.items())),
            "records": records,
            "isolatedReviewedSystems": isolated_systems,
            "reviewedRecordsModified": False,
            "trainingArtifactsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_dir = review_dir / "analysis" / SCORE_CHORD_OMISSION_REPLAY_SCHEMA_VERSION
        report_path = report_dir / "report.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": SCORE_CHORD_OMISSION_REPLAY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "reportDigest": report_digest,
            "reportPath": str(report_path),
            "recordCount": len(records),
            "isolatedSystemCount": len(isolated_systems),
            "relationshipCounts": dict(sorted(counts.items())),
            "nonExactRecordCount": sum(
                bool(item.get("nonExactRelationships")) for item in records
            ),
            "reviewedRecordsModified": False,
            "trainingArtifactsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def prepare_score_chord_omission_review(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Prepare a compact source-beside-tab review for strict-subset cases."""

        if partition != "discovery":
            raise ExtractionWorkflowError("The score-chord omission review is discovery-only.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        analysis_dir = (
            output_root
            / "review"
            / "analysis"
            / SCORE_CHORD_OMISSION_REPLAY_SCHEMA_VERSION
        )
        report_path = analysis_dir / "report.json"
        if not report_path.exists():
            raise ExtractionWorkflowError("Run the score-chord omission replay first.")
        report = _read_json(report_path)
        report_core = {key: value for key, value in report.items() if key != "reportDigest"}
        if _sha256_json(report_core) != str(report.get("reportDigest") or ""):
            raise ExtractionWorkflowError("The score-chord omission replay report changed.")
        flagged_by_input = {
            str(item.get("inputId") or ""): item.get("nonExactRelationships") or []
            for item in report.get("records") or []
            if item.get("recordKind") == "current_score_repair_candidate"
            and any(
                finding.get("relationshipStatus") == "subset_requires_review"
                for finding in item.get("nonExactRelationships") or []
            )
        }
        repair_index_path = (
            output_root
            / "review"
            / "score-audit"
            / "repair"
            / "score-repair-index.jsonl"
        )
        latest_repairs: dict[str, dict[str, Any]] = {}
        for entry in _read_jsonl(repair_index_path):
            latest_repairs[str(entry.get("inputId") or "")] = entry
        input_names = {
            str(item.get("inputId") or ""): str(item.get("relativePath") or "")
            for item in manifest.get("inputs") or []
        }
        review_dir = analysis_dir / "review"
        systems: list[dict[str, Any]] = []
        for input_id, raw_findings in sorted(flagged_by_input.items()):
            entry = latest_repairs.get(input_id)
            if entry is None:
                raise ExtractionWorkflowError("A flagged score-repair record is no longer current.")
            relative_path = str(entry.get("candidateRecordPath") or "")
            expected_digest = str(entry.get("candidateRecordDigest") or "")
            record_path = output_root / relative_path
            record = _read_json(record_path)
            if _sha256_json(record) != expected_digest:
                raise ExtractionWorkflowError("A flagged score-repair record changed.")
            alignments = {
                str(item.get("eventAlignmentId") or ""): item
                for item in record.get("eventAlignments") or []
            }
            score_events = {
                str(event.get("scoreEventId") or ""): (system, event)
                for system in record.get("scoreSystems") or []
                for event in system.get("scoreEvents") or []
            }
            tab_events = {
                str(event.get("tabEventId") or ""): (system, event)
                for system in record.get("tabSystems") or []
                for event in system.get("tabEvents") or []
            }
            grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
            for finding in raw_findings:
                if finding.get("relationshipStatus") != "subset_requires_review":
                    continue
                alignment_id = str(finding.get("eventAlignmentId") or "")
                alignment = alignments.get(alignment_id)
                if alignment is None:
                    raise ExtractionWorkflowError("A flagged score/tab alignment is missing.")
                score_id = str((finding.get("scoreEventIds") or [""])[0])
                tab_id = str((finding.get("tabEventIds") or [""])[0])
                score_system, _score_event = score_events[score_id]
                tab_system, tab_event = tab_events[tab_id]
                actions = [
                    action
                    for action in tab_event.get("steelActions") or []
                    if action.get("attack", True) is not False
                ]
                controls = [
                    "+".join(str(value) for value in action.get("controls") or [])
                    for action in actions
                ]
                description = ", ".join(
                    f"S{int(action['string'])} fret {int(action['fret'])}"
                    + (f" {controls[index]}" if controls[index] else "")
                    for index, action in enumerate(actions)
                )
                grouped.setdefault(
                    (
                        str(score_system.get("scoreSystemId") or ""),
                        str(tab_system.get("tabSystemId") or ""),
                    ),
                    [],
                ).append(
                    {
                        "eventAlignmentId": alignment_id,
                        "scoreHorizontalPosition": float(
                            alignment.get("scoreHorizontalPosition") or 0.0
                        ),
                        "scorePitches": [
                            scientific_pitch_for_value(int(value))
                            for value in finding.get("scorePitchValues") or []
                        ],
                        "tabPitches": [
                            scientific_pitch_for_value(int(value))
                            for value in finding.get("tabPitchValues") or []
                        ],
                        "tabDescription": description,
                    }
                )
            score_systems = {
                str(item.get("scoreSystemId") or ""): item
                for item in record.get("scoreSystems") or []
            }
            tab_systems = {
                str(item.get("tabSystemId") or ""): item
                for item in record.get("tabSystems") or []
            }
            for (score_system_id, tab_system_id), findings in sorted(grouped.items()):
                score_system = score_systems[score_system_id]
                tab_system = tab_systems[tab_system_id]
                crop = _prepare_score_tab_source_crop(
                    output_root=output_root,
                    audit_dir=output_root / "review" / "score-audit",
                    input_id=input_id,
                    record=record,
                    score_system=score_system,
                    tab_system=tab_system,
                )
                systems.append(
                    {
                        "inputId": input_id,
                        "imageFilename": input_names.get(input_id) or input_id,
                        "recordDigest": expected_digest,
                        "scoreSystemId": score_system_id,
                        "tabSystemId": tab_system_id,
                        "systemIndex": int(score_system.get("systemIndex") or 0),
                        "sourcePairUrl": Path(
                            os.path.relpath(
                                output_root / str(crop["relativePath"]),
                                review_dir,
                            )
                        ).as_posix(),
                        "sourcePairSha256": crop["sha256"],
                        "flaggedRelationships": sorted(
                            findings,
                            key=lambda item: item["scoreHorizontalPosition"],
                        ),
                    }
                )
        if not systems:
            raise ExtractionWorkflowError("No current score-chord omission cases need review.")
        systems.sort(
            key=lambda item: (
                str(item.get("imageFilename") or ""),
                int(item.get("systemIndex") or 0),
            )
        )
        packet_core = {
            "schemaVersion": SCORE_CHORD_OMISSION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "replayReportDigest": str(report.get("reportDigest") or ""),
            "systems": systems,
            "reviewedRecordsModified": False,
            "trainingArtifactsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_path = review_dir / "packet.json"
        console_path = review_dir / "score-chord-omission-review-console.html"
        _write_json(packet_path, packet)
        _write_private_text(console_path, _score_chord_omission_review_html(packet))
        return {
            "schemaVersion": SCORE_CHORD_OMISSION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "packetDigest": packet_digest,
            "systemCount": len(systems),
            "relationshipCount": sum(
                len(system["flaggedRelationships"]) for system in systems
            ),
            "consolePath": str(console_path),
            "relativeUrl": (
                f"/{batch_id}/extraction/{partition}/review/analysis/"
                f"{SCORE_CHORD_OMISSION_REPLAY_SCHEMA_VERSION}/review/"
                "score-chord-omission-review-console.html"
            ),
            "reviewedRecordsModified": False,
            "trainingArtifactsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def prepare_full_line_score_recapture_review(
        self,
        batch_id: str,
        constraints: Path | str,
        *,
        partition: str = "discovery",
        resume: bool = True,
    ) -> dict[str, Any]:
        """Recapture complete score lines under human-supplied attack-count constraints."""

        if partition != "discovery":
            raise ExtractionWorkflowError("Full-line score recapture is discovery-only.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        constraint_path = Path(constraints).expanduser().resolve()
        rows = _read_jsonl(constraint_path)
        if not rows or len(rows) > 25:
            raise ExtractionWorkflowError("Full-line score recapture needs 1-25 constraints.")
        output_root = batch_dir / "extraction" / partition
        review_root = output_root / "review"
        analysis_dir = review_root / "analysis" / FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION
        review_dir = analysis_dir / "review"
        candidates_dir = analysis_dir / "candidates"
        for directory in (analysis_dir, review_dir, candidates_dir):
            directory.mkdir(parents=True, exist_ok=True)
            os.chmod(directory, 0o700)
        latest_repairs: dict[str, dict[str, Any]] = {}
        repair_index_path = review_root / "score-audit" / "repair" / "score-repair-index.jsonl"
        for entry in _read_jsonl(repair_index_path):
            latest_repairs[str(entry.get("inputId") or "")] = entry
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        input_names = {
            str(item.get("inputId") or ""): str(item.get("relativePath") or "")
            for item in manifest.get("inputs") or []
        }
        contract = {
            "captureMethod": "digest_pinned_reviewed_score_event_alignment",
            "constraintType": "human_supplied_complete_correspondence_column_count",
            "scoreFactsSource": "current_score_repair_candidate",
            "tabFactsSource": "current_reviewed_tab_events",
        }
        contract_digest = _sha256_json(contract)
        constraint_digest = _sha256_json(rows)
        systems: list[dict[str, Any]] = []
        seen: set[tuple[str, int]] = set()
        for row in rows:
            if row.get("schemaVersion") != FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION:
                raise ExtractionWorkflowError("Unsupported full-line score constraint schema.")
            input_id = str(row.get("inputId") or "")
            system_index = int(row.get("systemIndex") or 0)
            expected_count = int(row.get("expectedScoreEventCount") or 0)
            key = (input_id, system_index)
            if key in seen or expected_count < 1 or expected_count > 64:
                raise ExtractionWorkflowError("Full-line score constraints must be unique and bounded.")
            seen.add(key)
            expected_record_digest = str(row.get("expectedRecordDigest") or "")
            entry = latest_repairs.get(input_id)
            if entry is None:
                entry = _digest_pinned_unindexed_score_repair_entry(
                    output_root,
                    input_id=input_id,
                    candidate_digest=expected_record_digest,
                )
            if entry is None:
                raise ExtractionWorkflowError(f"No digest-pinned score-repair candidate exists for {input_id}.")
            relative_path = str(entry.get("candidateRecordPath") or "")
            if expected_record_digest != str(entry.get("candidateRecordDigest") or ""):
                raise ExtractionWorkflowError(f"The current score candidate changed for {input_id}.")
            record_path = output_root / relative_path
            record = _read_json(record_path)
            if _sha256_json(record) != expected_record_digest:
                raise ExtractionWorkflowError(f"The score candidate digest changed for {input_id}.")
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if int(system.get("systemIndex") or 0) == system_index
                ),
                None,
            )
            if score_system is None or str(score_system.get("scoreSystemId") or "") != str(
                row.get("scoreSystemId") or ""
            ):
                raise ExtractionWorkflowError("A constrained score-system identity changed.")
            tab_system_id = str(row.get("tabSystemId") or "")
            if str(score_system.get("pairedTabSystemId") or "") != tab_system_id:
                raise ExtractionWorkflowError("A constrained score/tab pairing changed.")
            tab_system = next(
                (
                    system
                    for system in record.get("tabSystems") or []
                    if str(system.get("tabSystemId") or "") == tab_system_id
                ),
                None,
            )
            if tab_system is None:
                raise ExtractionWorkflowError("A constrained tab system is missing.")
            ordered_tab_events = sorted(
                tab_system.get("tabEvents") or [],
                key=lambda item: int(item.get("eventIndex") or 0),
            )
            if len(ordered_tab_events) != expected_count:
                raise ExtractionWorkflowError(
                    f"{input_id} line {system_index} has {len(ordered_tab_events)} tab events, "
                    f"not the reviewer-required {expected_count}."
                )
            score_crop_path = _prepare_score_pitch_crop(
                output_root=output_root,
                audit_dir=analysis_dir,
                input_id=input_id,
                record=record,
                score_system=score_system,
            )
            crop_digest = _sha256_bytes(score_crop_path.read_bytes())
            candidate_path = candidates_dir / f"{input_id}-system-{system_index:02d}.json"
            recognized_events, alignment_ids = _full_line_score_recognition_events(
                score_system,
                tab_system,
                record.get("eventAlignments") or [],
                context=f"{input_id} line {system_index}",
            )
            recognition = {
                "events": recognized_events,
                "captureMethod": "digest_pinned_reviewed_score_event_alignment",
                "eventAlignmentIds": alignment_ids,
                "currentRecordDigest": expected_record_digest,
                "humanCountConstraint": expected_count,
            }
            recognized_events = list(recognition.get("events") or [])
            if len(recognized_events) != expected_count:
                raise ExtractionWorkflowError(
                    f"Source-only recapture returned {len(recognized_events)} events for "
                    f"{input_id} line {system_index}; expected {expected_count}."
                )
            if [int(item.get("eventIndex") or 0) for item in recognized_events] != list(
                range(1, expected_count + 1)
            ):
                raise ExtractionWorkflowError("Source-only recapture returned a broken event sequence.")
            if any(not item.get("pitchValues") for item in recognized_events):
                raise ExtractionWorkflowError("A score review column has no pitches.")
            _write_json(
                candidate_path,
                {
                    "schemaVersion": FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "systemIndex": system_index,
                    "scoreSystemId": str(score_system.get("scoreSystemId") or ""),
                    "tabSystemId": tab_system_id,
                    "expectedScoreEventCount": expected_count,
                    "expectedRecordDigest": expected_record_digest,
                    "scoreCropSha256": crop_digest,
                    "contractDigest": contract_digest,
                    "constraintDigest": constraint_digest,
                    "recognition": recognition,
                    "eligibleForNormalizedEvents": False,
                },
            )
            source_pair = _prepare_score_tab_source_crop(
                output_root=output_root,
                audit_dir=output_root / "review" / "score-audit",
                input_id=input_id,
                record=record,
                score_system=score_system,
                tab_system=tab_system,
            )
            source_crop_region = source_pair["normalizedPageRegion"]
            tab_region = tab_system.get("pageRegion") or {}
            comparisons: list[dict[str, Any]] = []
            tab_states_by_id = {
                str(item.get("tabEventId") or ""): item
                for item in _ordered_tab_states(tab_system)
            }
            for score_event, tab_event in zip(
                recognized_events, ordered_tab_events, strict=True
            ):
                tab_event_id = str(tab_event.get("tabEventId") or "")
                tab_state = tab_states_by_id.get(tab_event_id) or {}
                tab_values = sorted(
                    {int(value) for value in tab_state.get("pitchValues") or []}
                )
                score_values = sorted({int(value) for value in score_event["pitchValues"]})
                captured_relationship = (
                    _score_tab_pitch_relationship(score_values, tab_values)
                    if score_values
                    else "not_applicable_movement_only"
                )
                captured_origin = str(
                    score_event.get("scoreFactOrigin") or "captured_score_alignment"
                )
                if captured_origin == (
                    "tab_derived_pitch_hypothesis_requires_visual_confirmation"
                ):
                    displayed_score_values = score_values
                    score_fact_origin = captured_origin
                    relationship_status = "hypothesis_requires_visual_confirmation"
                elif captured_relationship == "exact":
                    displayed_score_values = score_values
                    score_fact_origin = "captured_score_alignment"
                    relationship_status = "exact"
                elif captured_relationship == "not_applicable_movement_only":
                    displayed_score_values = []
                    score_fact_origin = "no_new_score_attack"
                    relationship_status = captured_relationship
                else:
                    displayed_score_values = tab_values
                    score_fact_origin = "tab_derived_pitch_hypothesis_requires_visual_confirmation"
                    relationship_status = "hypothesis_requires_visual_confirmation"
                comparisons.append(
                    {
                        "eventIndex": int(score_event["eventIndex"]),
                        "scoreX": _system_x_in_source_crop(
                            float(tab_event.get("horizontalPosition") or 0.0),
                            system_region=tab_region,
                            source_crop_region=source_crop_region,
                        ),
                        "tabSystemLocalX": float(
                            tab_event.get("horizontalPosition") or 0.0
                        ),
                        "scorePitches": [
                            scientific_pitch_for_value(value)
                            for value in displayed_score_values
                        ],
                        "scorePitchValues": displayed_score_values,
                        "capturedScorePitches": list(score_event["pitches"]),
                        "capturedScorePitchValues": score_values,
                        "capturedRelationshipStatus": captured_relationship,
                        "scoreFactOrigin": score_fact_origin,
                        "scoreStateType": str(score_event.get("stateType") or "attack"),
                        "sourceTabEventIndex": int(tab_event.get("eventIndex") or 0),
                        "tabDescription": _review_tab_event_description(tab_event, profile),
                        "tabPitches": [scientific_pitch_for_value(value) for value in tab_values],
                        "tabPitchValues": tab_values,
                        "relationshipStatus": relationship_status,
                    }
                )
            systems.append(
                {
                    "inputId": input_id,
                    "imageFilename": input_names.get(input_id) or str(row.get("imageFilename") or input_id),
                    "systemIndex": system_index,
                    "scoreSystemId": str(score_system.get("scoreSystemId") or ""),
                    "tabSystemId": tab_system_id,
                    "expectedRecordDigest": expected_record_digest,
                    "expectedScoreEventCount": expected_count,
                    "capturedScoreEventCount": len(recognized_events),
                    "tablatureEventCount": len(ordered_tab_events),
                    "countGatePassed": (
                        len(recognized_events) == expected_count
                        and len(ordered_tab_events) == expected_count
                    ),
                    "scoreCaptureMethod": str(
                        recognition.get("captureMethod") or "source_only_score_vision"
                    ),
                    "scoreCropSha256": crop_digest,
                    "sourcePairSha256": source_pair["sha256"],
                    "sourcePairNormalizedPageRegion": source_crop_region,
                    "markerCoordinateMethod": "tab_system_local_to_source_crop_v1",
                    "sourcePairUrl": Path(
                        os.path.relpath(
                            output_root / str(source_pair["relativePath"]),
                            review_dir,
                        )
                    ).as_posix(),
                    "events": comparisons,
                    "eligibleForNormalizedEvents": False,
                    "reviewState": "needs_human_review",
                }
            )
        systems.sort(
            key=lambda item: (
                str(item.get("imageFilename") or ""),
                int(item.get("systemIndex") or 0),
            )
        )
        if not all(system["countGatePassed"] for system in systems):
            raise ExtractionWorkflowError("A full-line score candidate failed count parity.")
        packet_core = {
            "schemaVersion": FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "constraintDigest": constraint_digest,
            "sourceCopedentId": profile.id,
            "sourceCopedentRevision": profile.revision,
            "systems": systems,
            "reviewedRecordsModified": False,
            "trainingArtifactsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_path = review_dir / "packet.json"
        console_path = review_dir / "full-line-score-recapture-console.html"
        _write_json(packet_path, packet)
        _write_private_text(console_path, _full_line_score_recapture_review_html(packet))

        superseded_dir = (
            review_root
            / "analysis"
            / SCORE_CHORD_OMISSION_REPLAY_SCHEMA_VERSION
            / "review"
        )
        superseded_packet_path = superseded_dir / "packet.json"
        superseded_digest = None
        if superseded_packet_path.exists():
            superseded_packet = _read_json(superseded_packet_path)
            superseded_digest = str(superseded_packet.get("packetDigest") or "")
            supersession = {
                "schemaVersion": FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION,
                "supersededPacketDigest": superseded_digest,
                "replacementPacketDigest": packet_digest,
                "reason": "subset_only_packet_omitted_complete_score_event_sequences",
                "humanSuppliedExpectedEventCount": sum(
                    int(item["expectedScoreEventCount"]) for item in systems
                ),
                "supersededAt": _utc_now(),
            }
            _write_json(superseded_dir / "supersession.json", supersession)
            replacement_url = (
                f"/{batch_id}/extraction/{partition}/review/analysis/"
                f"{FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION}/review/"
                "full-line-score-recapture-console.html"
            )
            _write_private_text(
                superseded_dir / "score-chord-omission-review-console.html",
                "<!doctype html><meta charset='utf-8'><title>Review withdrawn</title>"
                "<style>body{font:18px system-ui;max-width:850px;margin:60px auto;padding:20px}</style>"
                "<h1>This review was withdrawn</h1>"
                "<p>It displayed only anomaly markers instead of every score event. "
                "Do not submit it.</p>"
                f"<p><a href='{replacement_url}?v={packet_digest[:8]}'>Open the complete-line replacement review</a></p>",
            )
        return {
            "schemaVersion": FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "constraintDigest": constraint_digest,
            "packetDigest": packet_digest,
            "systemCount": len(systems),
            "scoreEventCount": sum(int(item["capturedScoreEventCount"]) for item in systems),
            "allCountGatesPassed": True,
            "supersededPacketDigest": superseded_digest,
            "consolePath": str(console_path),
            "relativeUrl": (
                f"/{batch_id}/extraction/{partition}/review/analysis/"
                f"{FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION}/review/"
                "full-line-score-recapture-console.html"
            ),
            "reviewedRecordsModified": False,
            "trainingArtifactsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def _synchronize_full_line_approvals_with_combined_ledger(
        self,
        *,
        batch_id: str,
        partition: str,
        manifest: Mapping[str, Any],
        output_root: Path,
        analysis_dir: Path,
    ) -> dict[str, Any]:
        """Append current full-line approvals to the canonical training ledger."""

        full_application_dir = analysis_dir / "application"
        full_index_path = full_application_dir / "approved-line-index.jsonl"
        raw_full_lines = _read_jsonl(full_index_path) if full_index_path.exists() else []
        repair_index_path = (
            output_root / "review" / "score-audit" / "repair" / "score-repair-index.jsonl"
        )
        repair_index = _read_jsonl(repair_index_path)
        known_full_decisions = {
            str(item.get("decisionId") or "") for item in raw_full_lines
        }
        recovered_full_lines: list[dict[str, Any]] = []
        for repair in repair_index:
            if str(repair.get("repairVersion") or "") != (
                FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION
            ):
                continue
            record_path_value = str(repair.get("candidateRecordPath") or "")
            record_digest = str(repair.get("candidateRecordDigest") or "")
            record_path = output_root / record_path_value
            if (
                not record_path_value
                or not record_path.exists()
                or _sha256_json(_read_json(record_path)) != record_digest
            ):
                raise ExtractionWorkflowError(
                    "A historical full-line approval lost its digest-pinned record."
                )
            historical = _read_json(record_path)
            review = historical.get("fullLineScoreReview") or {}
            corrected_ids = {
                str(value) for value in review.get("correctedScoreSystemIds") or []
            }
            score_by_id = {
                str(item.get("scoreSystemId") or ""): item
                for item in historical.get("scoreSystems") or []
            }
            for score_system_id in review.get("approvedScoreSystemIds") or []:
                score_system = score_by_id.get(str(score_system_id))
                if score_system is None:
                    raise ExtractionWorkflowError(
                        "A historical full-line approval lost an approved score system."
                    )
                decision_id = str(score_system.get("fullLineReviewDecisionId") or "")
                if not decision_id or decision_id in known_full_decisions:
                    continue
                recovered = {
                    "schemaVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": str(repair.get("inputId") or ""),
                    "scoreSystemId": str(score_system_id),
                    "tabSystemId": str(score_system.get("pairedTabSystemId") or ""),
                    "decisionId": decision_id,
                    "status": (
                        "corrected_and_accepted"
                        if str(score_system_id) in corrected_ids
                        else "accepted"
                    ),
                    "pitchToTabTrainingEligible": True,
                    "scoreRhythmTrainingEligible": False,
                    "submissionDigest": str(review.get("submissionDigest") or ""),
                    "packetDigest": str(review.get("packetDigest") or ""),
                    "applicationDigest": str(review.get("applicationDigest") or ""),
                    "reviewedRecordPath": record_path_value,
                    "reviewedRecordDigest": record_digest,
                    "recoveredFromAppendOnlyRepairHistory": True,
                }
                recovered_full_lines.append(recovered)
                known_full_decisions.add(decision_id)
        if recovered_full_lines:
            raw_full_lines += recovered_full_lines
            _write_jsonl(full_index_path, raw_full_lines)
        current_full_lines = _current_combined_line_entries(raw_full_lines)
        combined_application_dir = (
            output_root / "review" / "combined-score-tab-audit" / "application"
        )
        combined_index_path = combined_application_dir / "approved-line-index.jsonl"
        raw_combined_lines = (
            _read_jsonl(combined_index_path) if combined_index_path.exists() else []
        )
        current_combined = {
            (
                str(item.get("inputId") or ""),
                str(item.get("scoreSystemId") or ""),
            ): item
            for item in _current_combined_line_entries(raw_combined_lines)
        }
        source_copedent_id = str(manifest.get("sourceCopedentId") or "")
        profile = get_e9_copedent_profile(source_copedent_id)
        source_copedent_digest = e9_copedent_profile_digest(profile)
        appended_lines: list[dict[str, Any]] = []
        updated_full_by_decision: dict[str, dict[str, Any]] = {}
        already_synchronized = 0

        for line in current_full_lines:
            decision_id = str(line.get("decisionId") or "")
            key = (
                str(line.get("inputId") or ""),
                str(line.get("scoreSystemId") or ""),
            )
            prior = current_combined.get(key)
            if prior is not None and str(prior.get("decisionId") or "") == decision_id:
                reviewed_path_value = str(prior.get("reviewedRecordPath") or "")
                reviewed_digest = str(prior.get("reviewedRecordDigest") or "")
                reviewed_path = output_root / reviewed_path_value
                if (
                    not reviewed_path_value
                    or not reviewed_path.exists()
                    or _sha256_json(_read_json(reviewed_path)) != reviewed_digest
                ):
                    raise ExtractionWorkflowError(
                        "A synchronized full-line decision lost its reviewed record."
                    )
                already_synchronized += 1
                updated_full_by_decision[decision_id] = {
                    **dict(line),
                    "reviewedRecordPath": reviewed_path_value,
                    "reviewedRecordDigest": reviewed_digest,
                    "combinedLedgerSynchronized": True,
                }
                continue

            relative_path = str(line.get("reviewedRecordPath") or "")
            expected_digest = str(line.get("reviewedRecordDigest") or "")
            record_path = output_root / relative_path
            if (
                not relative_path
                or not record_path.exists()
                or _sha256_json(_read_json(record_path)) != expected_digest
            ):
                raise ExtractionWorkflowError(
                    "A full-line approval lost its digest-pinned reviewed record before ledger sync."
                )
            source_record = _read_json(record_path)
            revised, canonical_line = _promote_full_line_record_to_combined_scope(
                source_record,
                line,
                source_copedent_id=source_copedent_id,
                source_copedent_digest=source_copedent_digest,
            )
            if prior is not None:
                canonical_line["supersedesDecisionId"] = str(
                    prior.get("decisionId") or ""
                )
            revised_digest = _sha256_json(revised)
            target = (
                combined_application_dir
                / "applied-records"
                / str(line.get("inputId") or "")
                / f"{revised_digest}.json"
            )
            _write_json(target, revised)
            canonical_line["reviewedRecordPath"] = str(target.relative_to(output_root))
            canonical_line["reviewedRecordDigest"] = revised_digest
            appended_lines.append(canonical_line)
            current_combined[key] = canonical_line
            updated_full_by_decision[decision_id] = {
                **dict(line),
                "reviewedRecordPath": canonical_line["reviewedRecordPath"],
                "reviewedRecordDigest": revised_digest,
                "combinedLedgerSynchronized": True,
            }
            source_repair = next(
                (
                    item
                    for item in reversed(repair_index)
                    if str(item.get("inputId") or "") == str(line.get("inputId") or "")
                    and str(item.get("candidateRecordDigest") or "") == expected_digest
                ),
                {},
            )
            repair_index.append(
                {
                    "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": str(line.get("inputId") or ""),
                    "baseReviewedRecordDigest": str(
                        source_repair.get("baseReviewedRecordDigest") or ""
                    ),
                    "priorReviewDecisionId": source_repair.get("priorReviewDecisionId"),
                    "candidateRecordPath": canonical_line["reviewedRecordPath"],
                    "candidateRecordDigest": revised_digest,
                    "reviewedTabFactsDigest": _reviewed_tab_facts_digest(revised),
                    "repairVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
                    "fullLineCombinedLedgerDecisionId": decision_id,
                    "priorTabApprovalPreserved": True,
                    "status": "candidate_ready_partial_line_approval",
                    "sealedTestAccessed": False,
                }
            )

        if updated_full_by_decision:
            updated_full_lines = [
                updated_full_by_decision.get(str(item.get("decisionId") or ""), dict(item))
                for item in raw_full_lines
            ]
            _write_jsonl(full_index_path, updated_full_lines)
        if appended_lines:
            combined_application_dir.mkdir(parents=True, exist_ok=True)
            os.chmod(combined_application_dir, 0o700)
            _write_jsonl(combined_index_path, raw_combined_lines + appended_lines)
            _write_jsonl(repair_index_path, repair_index)
        sync_core = {
            "schemaVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "currentFullLineCount": len(current_full_lines),
            "recoveredHistoricalLineCount": len(recovered_full_lines),
            "newlySynchronizedLineCount": len(appended_lines),
            "alreadySynchronizedLineCount": already_synchronized,
            "combinedLedgerEntryCount": len(raw_combined_lines) + len(appended_lines),
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        sync_report = {**sync_core, "syncDigest": _sha256_json(sync_core)}
        _write_json(full_application_dir / "combined-ledger-sync.json", sync_report)
        return sync_report

    def apply_full_line_score_recapture_review(
        self,
        batch_id: str,
        source: Path | str,
        corrections: Path | str,
        *,
        partition: str = "discovery",
        dry_run: bool = False,
    ) -> dict[str, Any]:
        """Apply a complete-line review as pitch-only score truth plus explicit tab fixes.

        The review packet deliberately excluded score duration from its approval scope.  This
        method therefore rebuilds only attack pitch/chord membership and the one-to-one tab
        correspondence.  Free-form feedback is never interpreted as an edit: every feedback
        line must have a digest-pinned structured correction row.
        """

        if partition != "discovery":
            raise ExtractionWorkflowError("Full-line score review application is discovery-only.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        analysis_dir = (
            output_root
            / "review"
            / "analysis"
            / FULL_LINE_SCORE_RECAPTURE_SCHEMA_VERSION
        )
        review_dir = analysis_dir / "review"
        packet_path = review_dir / "packet.json"
        source_path = Path(source).expanduser().resolve()
        correction_path = Path(corrections).expanduser().resolve()
        if (
            source_path.parent != (review_dir / "submissions").resolve()
            or not source_path.name.startswith("full-line-score-submission-")
            or source_path.suffix != ".jsonl"
        ):
            raise ExtractionWorkflowError("Full-line review must use a received private submission.")
        if not packet_path.exists():
            raise ExtractionWorkflowError("The full-line review packet is missing.")
        packet = _read_json(packet_path)
        if str(packet.get("batchId") or "") != batch_id:
            raise ExtractionWorkflowError("The full-line packet belongs to another batch.")
        reviews = _read_jsonl(source_path)
        systems = list(packet.get("systems") or [])
        expected_keys = {
            (str(item.get("inputId") or ""), str(item.get("scoreSystemId") or ""))
            for item in systems
        }
        review_by_key = {
            (str(item.get("inputId") or ""), str(item.get("scoreSystemId") or "")): item
            for item in reviews
        }
        if len(review_by_key) != len(reviews) or set(review_by_key) != expected_keys:
            raise ExtractionWorkflowError("The submitted full-line review is incomplete or duplicated.")
        packet_digest = str(packet.get("packetDigest") or "")
        submission_digest = _sha256_json(
            {
                "reviewType": "full_line_score_recapture",
                "batchId": batch_id,
                "partition": partition,
                "packetDigest": packet_digest,
                "reviews": reviews,
            }
        )
        expected_submission_name = f"full-line-score-submission-{submission_digest[:20]}.jsonl"
        if source_path.name != expected_submission_name:
            raise ExtractionWorkflowError("The full-line submission filename does not match its contents.")

        correction_rows = _read_jsonl(correction_path)
        correction_by_key: dict[tuple[str, str], dict[str, Any]] = {}
        for row in correction_rows:
            if row.get("schemaVersion") != FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION:
                raise ExtractionWorkflowError("Unsupported full-line correction-plan schema.")
            if str(row.get("packetDigest") or "") != packet_digest:
                raise ExtractionWorkflowError("A full-line correction row targets a stale packet.")
            key = (str(row.get("inputId") or ""), str(row.get("scoreSystemId") or ""))
            if key in correction_by_key or key not in expected_keys:
                raise ExtractionWorkflowError("A full-line correction row has an unknown or repeated target.")
            correction_by_key[key] = row
        feedback_keys = {
            key for key, review in review_by_key.items() if str(review.get("status") or "") == "feedback"
        }
        if set(correction_by_key) != feedback_keys:
            raise ExtractionWorkflowError(
                "Structured corrections must cover every feedback line exactly once."
            )
        if any(str(item.get("status") or "") not in {"accept", "feedback"} for item in reviews):
            raise ExtractionWorkflowError("The full-line review contains an unsupported status.")

        correction_digest = _sha256_json(correction_rows)
        application_contract_version = 2
        application_digest = _sha256_json(
            {
                "packetDigest": packet_digest,
                "submissionDigest": submission_digest,
                "correctionDigest": correction_digest,
                "schemaVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
                "applicationContractVersion": application_contract_version,
            }
        )
        application_dir = analysis_dir / "application"
        summary_path = application_dir / "summary.json"
        versioned_summary_path = application_dir / "summaries" / f"{application_digest}.json"
        if versioned_summary_path.exists():
            existing = _read_json(versioned_summary_path)
            if dry_run:
                return {**existing, "deduplicated": True, "dryRun": True}
            sync = self._synchronize_full_line_approvals_with_combined_ledger(
                batch_id=batch_id,
                partition=partition,
                manifest=manifest,
                output_root=output_root,
                analysis_dir=analysis_dir,
            )
            return {
                **existing,
                "deduplicated": True,
                "dryRun": False,
                "combinedLedgerSync": sync,
            }

        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        packet_by_input: dict[str, list[dict[str, Any]]] = {}
        for system in systems:
            packet_by_input.setdefault(str(system.get("inputId") or ""), []).append(system)
        revised_records: dict[str, dict[str, Any]] = {}
        record_results: list[dict[str, Any]] = []
        line_index: list[dict[str, Any]] = []

        def attack_projection(score_system: Mapping[str, Any]) -> list[dict[str, Any]]:
            grouped: dict[tuple[int, float], list[str]] = {}
            for event in score_system.get("scoreEvents") or []:
                if bool(event.get("rest")):
                    continue
                key = (int(event.get("measure") or 0), round(float(event.get("beat") or 0.0), 6))
                grouped.setdefault(key, []).append(str(event.get("pitch") or ""))
            return [
                {"measure": measure, "beat": beat, "pitches": sorted(pitches)}
                for (measure, beat), pitches in sorted(grouped.items())
            ]

        for input_id, packet_systems in sorted(packet_by_input.items()):
            expected_digests = {str(item.get("expectedRecordDigest") or "") for item in packet_systems}
            if len(expected_digests) != 1:
                raise ExtractionWorkflowError("Reviewed lines for one page target different records.")
            expected_record_digest = next(iter(expected_digests))
            repair_entries = [
                item
                for item in _read_jsonl(
                    output_root / "review" / "score-audit" / "repair" / "score-repair-index.jsonl"
                )
                if str(item.get("inputId") or "") == input_id
                and str(item.get("candidateRecordDigest") or "") == expected_record_digest
            ]
            if not repair_entries:
                recovered_entry = _digest_pinned_unindexed_score_repair_entry(
                    output_root,
                    input_id=input_id,
                    candidate_digest=expected_record_digest,
                )
                if recovered_entry is None:
                    raise ExtractionWorkflowError(
                        f"The reviewed score candidate is missing for {input_id}."
                    )
                repair_entries = [recovered_entry]
            current_entry = repair_entries[-1]
            current_path = output_root / str(current_entry.get("candidateRecordPath") or "")
            current = _read_json(current_path)
            if _sha256_json(current) != expected_record_digest:
                raise ExtractionWorkflowError(f"The reviewed score candidate changed for {input_id}.")
            revised = copy.deepcopy(current)
            systems_by_id = {
                str(item.get("scoreSystemId") or ""): item
                for item in revised.get("scoreSystems") or []
            }
            tabs_by_id = {
                str(item.get("tabSystemId") or ""): item
                for item in revised.get("tabSystems") or []
            }
            reviewed_system_ids: set[str] = set()
            corrected_system_ids: set[str] = set()

            for packet_system in packet_systems:
                score_system_id = str(packet_system.get("scoreSystemId") or "")
                tab_system_id = str(packet_system.get("tabSystemId") or "")
                key = (input_id, score_system_id)
                score_system = systems_by_id.get(score_system_id)
                tab_system = tabs_by_id.get(tab_system_id)
                if score_system is None or tab_system is None:
                    raise ExtractionWorkflowError("A reviewed full line no longer exists in its candidate.")
                if str(score_system.get("pairedTabSystemId") or "") != tab_system_id:
                    raise ExtractionWorkflowError("A reviewed score/tab pairing changed.")
                ordered_tab_events = sorted(
                    tab_system.get("tabEvents") or [], key=lambda item: int(item.get("eventIndex") or 0)
                )
                if len(ordered_tab_events) != int(packet_system.get("expectedScoreEventCount") or 0):
                    raise ExtractionWorkflowError("A reviewed full line changed event count.")
                correction = correction_by_key.get(key)
                feedback_id = _stable_id(
                    "full-line-review-feedback", source_path.stem, input_id, score_system_id
                )
                if correction is not None:
                    operations = correction.get("operations") or []
                    if not isinstance(operations, list) or not operations:
                        raise ExtractionWorkflowError("A feedback line needs structured operations.")
                    for operation in operations:
                        if str(operation.get("tabSystemId") or "") != tab_system_id:
                            raise ExtractionWorkflowError("A full-line correction crossed a tab system boundary.")
                        _apply_feedback_correction_operation(
                            revised,
                            operation,
                            feedback_item_ids=[feedback_id],
                        )
                    corrected_system_ids.add(score_system_id)
                    ordered_tab_events = sorted(
                        tab_system.get("tabEvents") or [],
                        key=lambda item: int(item.get("eventIndex") or 0),
                    )
                overrides = {
                    int(item.get("eventIndex") or 0): item
                    for item in (correction or {}).get("scoreColumnOverrides") or []
                }
                replacement_attacks: list[dict[str, Any]] = []
                event_rows = list(packet_system.get("events") or [])
                if len(event_rows) != len(ordered_tab_events):
                    raise ExtractionWorkflowError("A reviewed packet line has broken column parity.")
                beats = int((score_system.get("timeSignature") or {}).get("beats") or 4)
                raw_slots = [
                    _reviewed_tab_event_rhythmic_slot(
                        tab_system,
                        tab_event,
                        beats=beats,
                    )
                    for tab_event in ordered_tab_events
                ]
                slot_counts = Counter(raw_slots)
                slot_offsets: Counter[tuple[int, float]] = Counter()
                provisional_slots: list[tuple[int, float]] = []
                for raw_measure, raw_beat in raw_slots:
                    duplicate_count = int(slot_counts[(raw_measure, raw_beat)])
                    duplicate_index = int(slot_offsets[(raw_measure, raw_beat)])
                    slot_offsets[(raw_measure, raw_beat)] += 1
                    if duplicate_count == 1:
                        provisional_slots.append((raw_measure, raw_beat))
                        continue
                    epsilon = 0.000001
                    if raw_beat + (duplicate_count - 1) * epsilon <= beats:
                        adjusted_beat = raw_beat + duplicate_index * epsilon
                    else:
                        adjusted_beat = raw_beat - (
                            duplicate_count - duplicate_index - 1
                        ) * epsilon
                    provisional_slots.append((raw_measure, round(adjusted_beat, 6)))
                for packet_event, tab_event, (measure, beat) in zip(
                    event_rows,
                    ordered_tab_events,
                    provisional_slots,
                    strict=True,
                ):
                    event_index = int(packet_event.get("eventIndex") or 0)
                    override = overrides.get(event_index) or {}
                    state_type = str(
                        override.get("stateType")
                        or packet_event.get("scoreStateType")
                        or "attack"
                    )
                    pitches = [
                        str(value)
                        for value in override.get("pitches", packet_event.get("scorePitches") or [])
                    ]
                    if state_type == "movement_only_no_score_attack":
                        if pitches:
                            raise ExtractionWorkflowError("A movement-only score override cannot contain pitches.")
                        continue
                    if not pitches:
                        raise ExtractionWorkflowError("An approved score attack has no pitches.")
                    replacement_attacks.append(
                        {
                            "measure": measure,
                            "beat": beat,
                            "pitches": pitches,
                            "defaultX": float(packet_event.get("scoreX") or 0.0),
                            "durationBeats": 1.0,
                        }
                    )
                operation_id = _stable_id(
                    "full-line-score-normalization", application_digest, input_id, score_system_id
                )
                _replace_score_system_attacks_from_review(
                    score_system,
                    {
                        "operationId": operation_id,
                        "expectedScoreAttackDigest": _sha256_json(attack_projection(score_system)),
                        "replacementAttacks": replacement_attacks,
                    },
                )
                score_system["reviewState"] = "human_approved"
                score_system["fullLineReviewDecisionId"] = _stable_id(
                    "full-line-review-decision", application_digest, input_id, score_system_id
                )
                for event in score_system.get("scoreEvents") or []:
                    event["reviewState"] = "human_approved"
                    states = dict(event.get("fieldReviewStates") or {})
                    states["pitch"] = "human_approved"
                    states["chordMembership"] = "human_approved"
                    states["duration"] = "not_reviewed_excluded"
                    states["rhythmicPosition"] = "not_reviewed_excluded"
                    states["tie"] = "not_reviewed_excluded"
                    event["fieldReviewStates"] = states
                tab_system["reviewState"] = "human_approved"
                for tab_event in tab_system.get("tabEvents") or []:
                    tab_event["reviewState"] = "human_approved"
                    for action in tab_event.get("steelActions") or []:
                        action["reviewState"] = "human_approved"
                reviewed_system_ids.add(score_system_id)
                line_index.append(
                    {
                        "schemaVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
                        "batchId": batch_id,
                        "partition": partition,
                        "inputId": input_id,
                        "scoreSystemId": score_system_id,
                        "tabSystemId": tab_system_id,
                        "decisionId": score_system["fullLineReviewDecisionId"],
                        "status": "corrected_and_accepted" if correction is not None else "accepted",
                        "pitchToTabTrainingEligible": True,
                        "scoreRhythmTrainingEligible": False,
                        "submissionDigest": submission_digest,
                        "packetDigest": packet_digest,
                        "applicationDigest": application_digest,
                    }
                )

            reviewed_tab_system_ids = {
                str(item.get("tabSystemId") or "") for item in packet_systems
            }
            _revalidate_corrected_record(
                revised,
                profile,
                include_movement_only_tab_system_ids=reviewed_tab_system_ids,
            )
            tabs_by_id = {
                str(item.get("tabSystemId") or ""): item
                for item in revised.get("tabSystems") or []
            }
            score_by_id = {
                str(item.get("scoreSystemId") or ""): item
                for item in revised.get("scoreSystems") or []
            }
            for packet_system in packet_systems:
                score_system_id = str(packet_system.get("scoreSystemId") or "")
                tab_system_id = str(packet_system.get("tabSystemId") or "")
                score_system = score_by_id[score_system_id]
                tab_system = tabs_by_id[tab_system_id]
                score_system["reviewState"] = "human_approved"
                for score_event in score_system.get("scoreEvents") or []:
                    score_event["reviewState"] = "human_approved"
                tab_system["reviewState"] = "human_approved"
                for tab_event in tab_system.get("tabEvents") or []:
                    tab_event["reviewState"] = "human_approved"
                    for control_change in tab_event.get("controlChanges") or []:
                        control_change["reviewState"] = "human_approved"
                    for action in tab_event.get("steelActions") or []:
                        action["reviewState"] = "human_approved"
                score_event_ids = {
                    str(item.get("scoreEventId") or "") for item in score_system.get("scoreEvents") or []
                }
                tab_event_ids = {
                    str(item.get("tabEventId") or "") for item in tab_system.get("tabEvents") or []
                }
                relevant = [
                    item
                    for item in revised.get("eventAlignments") or []
                    if set(str(value) for value in item.get("scoreEventIds") or []) & score_event_ids
                    or set(str(value) for value in item.get("tabEventIds") or []) & tab_event_ids
                ]
                reviewed_tab_events = list(tab_system.get("tabEvents") or [])
                aligned_tab_ids = {
                    str(value) for item in relevant for value in item.get("tabEventIds") or []
                }
                if aligned_tab_ids != {
                    str(item.get("tabEventId") or "") for item in reviewed_tab_events
                } or any(not bool(item.get("notationAdjustedPitchAgreement")) for item in relevant):
                    raise ExtractionWorkflowError(
                        f"The reviewed full-line alignment did not normalize exactly for {input_id}."
                    )
                for alignment in relevant:
                    alignment["reviewState"] = "human_approved"
                    alignment["fullLineReviewDecisionId"] = _stable_id(
                        "full-line-review-decision", application_digest, input_id, score_system_id
                    )
            revised["revision"] = int(current.get("revision") or 1) + 1
            revised["reviewState"] = "partially_human_approved"
            revised["humanApprovalComplete"] = False
            revised["fullLineScoreReview"] = {
                "schemaVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
                "applicationContractVersion": application_contract_version,
                "applicationDigest": application_digest,
                "packetDigest": packet_digest,
                "submissionDigest": submission_digest,
                "correctionDigest": correction_digest,
                "approvedScoreSystemIds": sorted(reviewed_system_ids),
                "correctedScoreSystemIds": sorted(corrected_system_ids),
                "pitchToTabTrainingEligible": True,
                "scoreRhythmTrainingEligible": False,
                "reviewedAt": _utc_now(),
            }
            revised_digest = _sha256_json(revised)
            revised_records[input_id] = revised
            diagnostics = _score_audit_diagnostics(revised)
            gates = _score_audit_equivalence_gates(revised, diagnostics)
            record_results.append(
                {
                    "inputId": input_id,
                    "priorRecordDigest": expected_record_digest,
                    "reviewedRecordDigest": revised_digest,
                    "approvedSystemCount": len(reviewed_system_ids),
                    "correctedSystemCount": len(corrected_system_ids),
                    "reviewedSystemIds": sorted(reviewed_system_ids),
                    "scoreAuditGatesBySystem": gates,
                    "reviewedTabFactsDigest": _reviewed_tab_facts_digest(revised),
                    "baseReviewedRecordDigest": str(
                        current_entry.get("baseReviewedRecordDigest") or ""
                    ),
                    "priorReviewDecisionId": current_entry.get("priorReviewDecisionId"),
                }
            )

        summary = {
            "schemaVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
            "applicationContractVersion": application_contract_version,
            "batchId": batch_id,
            "partition": partition,
            "applicationDigest": application_digest,
            "packetDigest": packet_digest,
            "submissionDigest": submission_digest,
            "correctionDigest": correction_digest,
            "reviewedLineCount": len(reviews),
            "acceptedUnchangedLineCount": len(reviews) - len(feedback_keys),
            "correctedAndAcceptedLineCount": len(feedback_keys),
            "reviewedPageCount": len(revised_records),
            "pitchToTabTrainingEligibleLineCount": len(reviews),
            "scoreRhythmTrainingEligibleLineCount": 0,
            "dryRun": dry_run,
            "deduplicated": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        if dry_run:
            return summary

        applied_records_dir = application_dir / "applied-records"
        applied_records_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(applied_records_dir, 0o700)
        repair_index_path = (
            output_root / "review" / "score-audit" / "repair" / "score-repair-index.jsonl"
        )
        repair_index = _read_jsonl(repair_index_path)
        for result in record_results:
            input_id = str(result["inputId"])
            revised = revised_records[input_id]
            revised_digest = str(result["reviewedRecordDigest"])
            target = applied_records_dir / input_id / f"{revised_digest}.json"
            _write_json(target, revised)
            relative_path = str(target.relative_to(output_root))
            for item in line_index:
                if str(item.get("inputId") or "") == input_id:
                    item["reviewedRecordPath"] = relative_path
                    item["reviewedRecordDigest"] = revised_digest
            repair_index.append(
                {
                    "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "baseReviewedRecordDigest": result["baseReviewedRecordDigest"],
                    "priorReviewDecisionId": result["priorReviewDecisionId"],
                    "candidateRecordPath": relative_path,
                    "candidateRecordDigest": revised_digest,
                    "reviewedTabFactsDigest": result["reviewedTabFactsDigest"],
                    "repairVersion": FULL_LINE_SCORE_REVIEW_APPLICATION_SCHEMA_VERSION,
                    "scoreSystemCount": len(revised.get("scoreSystems") or []),
                    "scoreAuditGatesBySystem": result["scoreAuditGatesBySystem"],
                    "allGatesPassed": all(
                        bool(item.get("readyForHumanReview"))
                        for item in result["scoreAuditGatesBySystem"].values()
                    ),
                    "priorTabApprovalPreserved": result["correctedSystemCount"] == 0,
                    "fullLineReviewApplicationDigest": application_digest,
                    "status": "candidate_ready",
                    "sealedTestAccessed": False,
                }
            )
        application_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(application_dir, 0o700)
        full_line_index_path = application_dir / "approved-line-index.jsonl"
        existing_full_lines = (
            _read_jsonl(full_line_index_path) if full_line_index_path.exists() else []
        )
        known_full_decisions = {
            str(item.get("decisionId") or "") for item in existing_full_lines
        }
        _write_jsonl(
            full_line_index_path,
            existing_full_lines
            + [
                item
                for item in line_index
                if str(item.get("decisionId") or "") not in known_full_decisions
            ],
        )
        _write_jsonl(repair_index_path, repair_index)
        combined_sync = self._synchronize_full_line_approvals_with_combined_ledger(
            batch_id=batch_id,
            partition=partition,
            manifest=manifest,
            output_root=output_root,
            analysis_dir=analysis_dir,
        )
        summary["combinedLedgerSync"] = combined_sync
        versioned_summary_path.parent.mkdir(parents=True, exist_ok=True)
        os.chmod(versioned_summary_path.parent, 0o700)
        _write_json(versioned_summary_path, summary)
        _write_json(summary_path, summary)
        return summary

    def prepare_feedback_correction_confirmation(
        self,
        batch_id: str,
        corrections: Path | str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Prepare a narrow, tab-only confirmation packet for applied feedback fixes."""

        if partition != "discovery":
            raise ExtractionWorkflowError(
                "Feedback-correction confirmation is restricted to discovery."
            )
        batch_dir, _manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        pages_dir = output_root / "pages"
        plans = _read_jsonl(Path(corrections).expanduser().resolve())
        if not plans:
            raise ExtractionWorkflowError("The feedback correction plan is empty.")
        plan_digest = _sha256_json(plans)
        work_ids = {str(item.get("inputId") or "") for item in work}
        finalized_inputs = {
            str(item.get("inputId") or "")
            for item in _read_jsonl(review_dir / "approved-record-index.jsonl")
        }
        packets: list[dict[str, Any]] = []

        def record_maps(record: Mapping[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
            systems = {
                str(system.get("tabSystemId") or ""): system
                for system in record.get("tabSystems") or []
            }
            events: dict[str, Any] = {}
            actions: dict[str, Any] = {}
            for system in systems.values():
                for event in system.get("tabEvents") or []:
                    events[str(event.get("tabEventId") or "")] = event
                    for action in event.get("steelActions") or []:
                        actions[str(action.get("steelActionId") or "")] = action
            return systems, events, actions

        for plan in plans:
            if str(plan.get("schemaVersion") or "") != FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION:
                raise ExtractionWorkflowError("Unsupported feedback correction plan schema.")
            input_id = str(plan.get("inputId") or "")
            if input_id not in work_ids:
                raise ExtractionWorkflowError(
                    f"Feedback correction plan references unknown discovery input {input_id!r}."
                )
            if input_id in finalized_inputs:
                continue
            record_path = pages_dir / f"{input_id}.json"
            record = _read_json(record_path)
            correction = record.get("machineCorrection") or {}
            expected_correction_plan_digest = str(
                plan.get("correctionPlanDigest") or plan_digest
            )
            if (
                str(correction.get("correctionPlanDigest") or "")
                != expected_correction_plan_digest
            ):
                raise ExtractionWorkflowError(
                    f"Current record for {input_id} is not the result of this correction plan."
                )
            if str(correction.get("priorMachineRecordDigest") or "") != str(
                plan.get("expectedMachineRecordDigest") or ""
            ):
                raise ExtractionWorkflowError(
                    f"Correction lineage for {input_id} does not match the reviewed record."
                )
            record_digest = _sha256_json(record)
            expected_prior_digest = str(plan.get("expectedMachineRecordDigest") or "")
            prior_record: dict[str, Any] | None = None
            revisions_dir = review_dir / "machine-record-revisions" / input_id
            for candidate_path in sorted(revisions_dir.glob("*.json")):
                candidate = _read_json(candidate_path)
                if _sha256_json(candidate) == expected_prior_digest:
                    prior_record = candidate
                    break
            if prior_record is None:
                raise ExtractionWorkflowError(
                    f"Archived pre-correction record is missing for {input_id}."
                )
            current_systems, current_events, current_actions = record_maps(record)
            prior_systems, prior_events, prior_actions = record_maps(prior_record)
            affected_system_ids: set[str] = set()
            corrected_event_ids: set[str] = set()
            corrected_action_ids: set[str] = set()
            change_summaries: list[dict[str, Any]] = []
            for operation in plan.get("operations") or []:
                operation_type = str(operation.get("type") or "")
                tab_system_id = str(operation.get("tabSystemId") or "")
                tab_event_id = str(operation.get("tabEventId") or "")
                action_id = str(operation.get("steelActionId") or "")
                system = current_systems.get(tab_system_id) or prior_systems.get(tab_system_id) or {}
                event = current_events.get(tab_event_id) or prior_events.get(tab_event_id) or {}
                line_number = int(system.get("systemIndex") or 0)
                event_number = int(event.get("eventIndex") or 0)
                summary_event_id = tab_event_id
                if tab_system_id in current_systems:
                    affected_system_ids.add(tab_system_id)
                if tab_event_id in current_events:
                    corrected_event_ids.add(tab_event_id)
                if action_id in current_actions:
                    corrected_action_ids.add(action_id)

                if operation_type in {
                    "remove_score_system",
                    "record_score_feedback_pending",
                }:
                    continue
                if operation_type == "remove_tab_system":
                    label = str(
                        operation.get("confirmationLabel")
                        or f"Removed incorrect tablature line {line_number}."
                    )
                    removed = True
                elif operation_type == "replace_tab_system_events":
                    replacement_events = list(
                        (current_systems.get(tab_system_id) or {}).get("tabEvents") or []
                    )
                    corrected_event_ids.update(
                        str(candidate.get("tabEventId") or "")
                        for candidate in replacement_events
                    )
                    for candidate in replacement_events:
                        corrected_action_ids.update(
                            str(action.get("steelActionId") or "")
                            for action in candidate.get("steelActions") or []
                        )
                    label = (
                        f"Recaptured tablature line {line_number} as "
                        f"{len(replacement_events)} chronological movement columns."
                    )
                    removed = False
                elif operation_type == "insert_tab_event":
                    inserted_event_id = str(operation.get("newTabEventId") or "")
                    inserted_event = current_events.get(inserted_event_id)
                    if inserted_event is None:
                        raise ExtractionWorkflowError(
                            f"Inserted correction event {inserted_event_id!r} is missing."
                        )
                    summary_event_id = inserted_event_id
                    event_number = int(inserted_event.get("eventIndex") or 0)
                    corrected_event_ids.add(inserted_event_id)
                    corrected_action_ids.update(
                        str(action.get("steelActionId") or "")
                        for action in inserted_event.get("steelActions") or []
                    )
                    label = (
                        f"Added the missing movement to line {line_number}, "
                        f"column {event_number}."
                    )
                    removed = False
                elif operation_type == "remove_tab_event":
                    label = f"Removed the extra movement from line {line_number}, column {event_number}."
                    removed = True
                elif operation_type == "remove_steel_action":
                    prior_action = prior_actions.get(action_id) or {}
                    label = (
                        f"Removed the extra string {prior_action.get('string')} entry from "
                        f"line {line_number}, column {event_number}."
                    )
                    removed = True
                elif operation_type == "update_tab_event":
                    changes = operation.get("changes") or {}
                    movement = changes.get("barMovement") or event.get("barMovement") or {}
                    control_changes = changes.get("controlChanges") or []
                    if movement:
                        label = (
                            f"Corrected line {line_number}, column {event_number}: slide from "
                            f"fret {movement.get('fromFret')} to fret {movement.get('toFret')} "
                            "without a new pick."
                        )
                    elif control_changes:
                        releases = [
                            str(change.get("control"))
                            for change in control_changes
                            if change.get("action") == "release"
                        ]
                        engagements = [
                            str(change.get("control"))
                            for change in control_changes
                            if change.get("action") == "engage"
                        ]
                        phrases = []
                        if releases:
                            phrases.append(f"release {'+'.join(releases)}")
                        if engagements:
                            phrases.append(f"engage {'+'.join(engagements)}")
                        label = (
                            f"Corrected line {line_number}, column {event_number}: "
                            f"{' and '.join(phrases)} during the sustain, without a new pick."
                        )
                    else:
                        label = (
                            f"Corrected line {line_number}, column {event_number}: continue the "
                            "sounding strings without a new pick."
                        )
                    removed = False
                else:
                    action = current_actions.get(action_id)
                    if action is None and operation_type == "update_steel_action":
                        action = copy.deepcopy(prior_actions.get(action_id) or {})
                        action.update(copy.deepcopy(operation.get("changes") or {}))
                    if action is None and operation_type == "add_steel_action":
                        requested = operation.get("steelAction") or {}
                        for candidate in (current_events.get(tab_event_id) or {}).get("steelActions") or []:
                            if (
                                int(candidate.get("string") or 0) == int(requested.get("string") or 0)
                                and int(candidate.get("fret") or 0) == int(requested.get("fret") or 0)
                                and list(candidate.get("controls") or []) == list(requested.get("controls") or [])
                            ):
                                action = candidate
                                corrected_action_ids.add(str(candidate.get("steelActionId") or ""))
                                break
                    action = action or operation.get("steelAction") or operation.get("changes") or {}
                    controls = "".join(str(value) for value in action.get("controls") or [])
                    half_stop = " half-stop" if action.get("halfStop") else ""
                    if action.get("attack") is False:
                        slide_value = action.get("slide") or action.get("barMovement") or {}
                        slide = slide_value if isinstance(slide_value, Mapping) else {}
                        if slide:
                            control_suffix = f" with {controls}" if controls else ""
                            label = (
                                f"Corrected line {line_number}, column {event_number}: slide "
                                f"sustained string {action.get('string')} from fret "
                                f"{slide.get('fromFret')} to fret {slide.get('toFret')}"
                                f"{control_suffix}, without a new pick."
                            )
                        elif action.get("releaseTiming"):
                            label = (
                                f"Corrected line {line_number}, column {event_number}: release "
                                f"the prior pedal or lever on sustained string {action.get('string')} "
                                f"at fret {action.get('fret')}, without a new pick."
                            )
                        elif controls:
                            label = (
                                f"Corrected line {line_number}, column {event_number}: engage "
                                f"{controls}{half_stop} on sustained string {action.get('string')} "
                                f"at fret {action.get('fret')}, without a new pick."
                            )
                        else:
                            label = (
                                f"Corrected line {line_number}, column {event_number}: continue "
                                f"sustained string {action.get('string')} at fret "
                                f"{action.get('fret')}, without a new pick."
                            )
                    else:
                        label = (
                            f"Corrected line {line_number}, column {event_number}: string "
                            f"{action.get('string')}, fret {action.get('fret')}{controls}{half_stop}."
                        )
                    removed = False
                change_summaries.append(
                    {
                        "operationId": operation.get("operationId"),
                        "operationType": operation_type,
                        "tabEventId": summary_event_id,
                        "lineNumber": line_number,
                        "eventNumber": event_number,
                        "label": label,
                        "removed": removed,
                    }
                )

            # One human-visible item per corrected musical move. A correction
            # can require several low-level action mutations, but exposing
            # those implementation operations forces the player to audit a
            # developer log instead of the resulting tablature column.
            consolidated: list[dict[str, Any]] = []
            grouped_event_ids: set[str] = set()
            for change in change_summaries:
                event_id = str(change.get("tabEventId") or "")
                current_event = current_events.get(event_id)
                if not event_id or current_event is None:
                    consolidated.append(
                        {
                            "operationId": change.get("operationId"),
                            "_lineNumber": int(change.get("lineNumber") or 0),
                            "_eventNumber": int(change.get("eventNumber") or 0),
                            "label": change.get("label"),
                            "removed": bool(change.get("removed")),
                        }
                    )
                    continue
                if event_id in grouped_event_ids:
                    continue
                grouped_event_ids.add(event_id)
                related = [
                    item for item in change_summaries
                    if str(item.get("tabEventId") or "") == event_id
                ]
                movements = current_event.get("barMovement") or {}
                control_changes = current_event.get("controlChanges") or []
                phrases: list[str] = []
                if movements:
                    phrases.append(
                        f"slide from fret {movements.get('fromFret')} to fret "
                        f"{movements.get('toFret')} without a new pick"
                    )
                releases = [
                    str(item.get("control"))
                    for item in control_changes
                    if item.get("action") == "release"
                ]
                engagements = [
                    str(item.get("control"))
                    for item in control_changes
                    if item.get("action") == "engage"
                ]
                if releases:
                    phrases.append(f"{'+'.join(releases)} comes off during the sustain")
                elif any(
                    action.get("releaseTiming")
                    for action in current_event.get("steelActions") or []
                ):
                    phrases.append("the prior pedal or lever comes off during the sustain")
                if engagements:
                    phrases.append(f"{'+'.join(engagements)} comes on during the sustain")
                cells = []
                for action in sorted(
                    current_event.get("steelActions") or [],
                    key=lambda item: int(item.get("string") or 0),
                ):
                    controls = "".join(str(value) for value in action.get("controls") or [])
                    half_stop = "½" if action.get("halfStop") else ""
                    transition = action.get("controlTransition") or {}
                    slide_value = action.get("slide") or {}
                    slide = slide_value if isinstance(slide_value, Mapping) else {}
                    if action.get("attack") is False and slide and transition:
                        before = "".join(
                            str(value) for value in transition.get("beforeControls") or []
                        )
                        after = "".join(
                            str(value) for value in transition.get("afterControls") or []
                        )
                        token = (
                            f"{slide.get('fromFret')}{before}→"
                            f"{slide.get('toFret')}{before}---"
                            f"{slide.get('toFret')}{after}"
                        )
                    elif action.get("attack") is False and transition:
                        before = "".join(
                            str(value) for value in transition.get("beforeControls") or []
                        )
                        after = "".join(
                            str(value) for value in transition.get("afterControls") or []
                        )
                        token = (
                            f"{action.get('fret')}{before}---"
                            f"{action.get('fret')}{after}"
                        )
                    elif action.get("attack") is False and action.get("releaseTiming"):
                        token = f"---{action.get('fret')}{controls}{half_stop}"
                    elif action.get("attack") is False and slide:
                        token = (
                            f"{slide.get('fromFret')}→{slide.get('toFret')}"
                            f"{controls}{half_stop}"
                        )
                    else:
                        token = f"{action.get('fret')}{controls}{half_stop}"
                    cells.append(f"string {action.get('string')} {token}")
                if cells:
                    phrases.append("resulting column: " + ", ".join(cells))
                line_number = int(change.get("lineNumber") or 0)
                event_number = int(change.get("eventNumber") or 0)
                consolidated.append(
                    {
                        "operationId": "+".join(
                            str(item.get("operationId") or "") for item in related
                        ),
                        "_lineNumber": line_number,
                        "_eventNumber": event_number,
                        "label": (
                            f"Corrected line {line_number}, column {event_number}: "
                            + "; ".join(phrases)
                            + "."
                        ),
                        "removed": False,
                    }
                )
            consolidated.sort(
                key=lambda item: (
                    int(item.get("_lineNumber") or 0),
                    int(item.get("_eventNumber") or 0),
                )
            )
            for change in consolidated:
                change.pop("_lineNumber", None)
                change.pop("_eventNumber", None)
            change_summaries = consolidated
            packets.append(
                {
                    "schemaVersion": FEEDBACK_CORRECTION_CONFIRMATION_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "sourceLabel": Path(str(record["provenance"]["imageFilename"])).name,
                    "derivativeRelativePath": record["derivative"]["relativePath"],
                    "machineRecordDigest": record_digest,
                    "correctionId": correction["correctionId"],
                    "correctionPlanDigest": expected_correction_plan_digest,
                    "changeSummaries": change_summaries,
                    "affectedTabSystemIds": sorted(affected_system_ids),
                    "correctedTabEventIds": sorted(corrected_event_ids),
                    "correctedSteelActionIds": sorted(corrected_action_ids),
                    "machineRecord": record,
                    "approvalScope": "applied_feedback_corrections_only",
                    "scoreApprovalGranted": False,
                    "pageApprovalGranted": False,
                }
            )

        if not packets:
            raise ExtractionWorkflowError(
                "Every page in this correction plan is already finalized."
            )
        packet_digest = _sha256_json(packets)
        packet_path = review_dir / "feedback-correction-confirmation-packet.jsonl"
        packet_dir = review_dir / "feedback-correction-confirmation-packets"
        packet_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(packet_dir, 0o700)
        packet_index: list[dict[str, Any]] = []
        for packet in packets:
            item_path = packet_dir / f"{packet['inputId']}.json"
            _write_json(item_path, packet)
            packet_index.append(
                {
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": packet["inputId"],
                    "sourceLabel": packet["sourceLabel"],
                    "packetUrl": f"./feedback-correction-confirmation-packets/{packet['inputId']}.json",
                    "machineRecordDigest": packet["machineRecordDigest"],
                    "correctionId": packet["correctionId"],
                    "changeCount": len(packet["changeSummaries"]),
                }
            )
        _write_jsonl(packet_path, packets)
        console_path = review_dir / "feedback-correction-confirmation-console.html"
        _write_private_text(
            console_path,
            _feedback_correction_confirmation_console_html(
                packet_index, packet_digest=packet_digest
            ),
        )
        summary = {
            "schemaVersion": FEEDBACK_CORRECTION_CONFIRMATION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "packetDigest": packet_digest,
            "correctionPlanDigest": (
                packets[0]["correctionPlanDigest"]
                if len({packet["correctionPlanDigest"] for packet in packets}) == 1
                else None
            ),
            "correctionPlanDigests": sorted(
                {packet["correctionPlanDigest"] for packet in packets}
            ),
            "confirmationBundleDigest": plan_digest,
            "pageCount": len(packets),
            "changeCount": sum(len(packet["changeSummaries"]) for packet in packets),
            "packetPath": str(packet_path.relative_to(batch_dir)),
            "consolePath": str(console_path.relative_to(batch_dir)),
            "approvalScope": "applied_feedback_corrections_only",
            "scoreApprovalGranted": False,
            "pageApprovalGranted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        _write_json(review_dir / "feedback-correction-confirmation-packet-summary.json", summary)
        return summary

    def apply_feedback_correction_confirmation_review(
        self,
        batch_id: str,
        source: Path | str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Apply tab-only correction confirmations without approving score or page facts."""

        if partition != "discovery":
            raise ExtractionWorkflowError(
                "Feedback-correction confirmation is restricted to discovery."
            )
        batch_dir, _manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        pages_dir = output_root / "pages"
        source_path = Path(source).expanduser().resolve()
        reviews = _read_jsonl(source_path)
        if not reviews:
            raise ExtractionWorkflowError("The feedback-correction confirmation is empty.")
        packet_summary = _read_json(
            review_dir / "feedback-correction-confirmation-packet-summary.json"
        )
        packet_by_input = {
            str(item.get("inputId") or ""): item
            for item in _read_jsonl(
                review_dir / "feedback-correction-confirmation-packet.jsonl"
            )
        }
        work_ids = {str(item.get("inputId") or "") for item in work}
        decision_log_path = review_dir / "feedback-correction-confirmation-decisions.jsonl"
        existing_decisions = _read_jsonl(decision_log_path) if decision_log_path.exists() else []
        existing_ids = {str(item.get("decisionId") or "") for item in existing_decisions}
        feedback_log_path = review_dir / "human-review-feedback.jsonl"
        feedback_log = _read_jsonl(feedback_log_path) if feedback_log_path.exists() else []
        new_decisions: list[dict[str, Any]] = []
        new_feedback: list[dict[str, Any]] = []
        seen: set[str] = set()
        for review in reviews:
            input_id = str(review.get("inputId") or "")
            packet = packet_by_input.get(input_id)
            status = str(review.get("status") or "")
            comment = str(review.get("comment") or "").strip() or None
            if input_id not in work_ids or packet is None or input_id in seen:
                raise ExtractionWorkflowError(
                    "Feedback-correction decision has an unknown or repeated input."
                )
            if status not in {"confirm", "feedback"}:
                raise ExtractionWorkflowError("Unsupported feedback-correction decision status.")
            record = _read_json(pages_dir / f"{input_id}.json")
            record_digest = _sha256_json(record)
            if record_digest != str(review.get("expectedMachineRecordDigest") or "") or record_digest != str(
                packet.get("machineRecordDigest") or ""
            ):
                raise ExtractionWorkflowError(
                    f"Feedback-correction decision for {input_id} targets a stale record."
                )
            correction_id = str((record.get("machineCorrection") or {}).get("correctionId") or "")
            if correction_id != str(review.get("expectedCorrectionId") or "") or correction_id != str(
                packet.get("correctionId") or ""
            ):
                raise ExtractionWorkflowError(
                    f"Feedback-correction decision for {input_id} targets a stale correction."
                )
            if status == "feedback" and comment is None:
                raise ExtractionWorkflowError("A correction that still needs work requires a comment.")
            decision_id = _stable_id(
                "feedback-correction-confirmation",
                batch_id,
                partition,
                input_id,
                record_digest,
                correction_id,
                status,
                comment,
            )
            if decision_id not in existing_ids:
                new_decisions.append(
                    {
                        "schemaVersion": FEEDBACK_CORRECTION_CONFIRMATION_SCHEMA_VERSION,
                        "decisionId": decision_id,
                        "batchId": batch_id,
                        "partition": partition,
                        "inputId": input_id,
                        "machineRecordDigest": record_digest,
                        "correctionId": correction_id,
                        "status": status,
                        "comment": comment,
                        "approvalScope": "applied_feedback_corrections_only" if status == "confirm" else "none",
                        "scoreApprovalGranted": False,
                        "pageApprovalGranted": False,
                        "reviewedAt": _utc_now(),
                    }
                )
                existing_ids.add(decision_id)
            if status == "feedback":
                feedback_submission_id = _stable_id(
                    "extraction-feedback-submission",
                    batch_id,
                    partition,
                    input_id,
                    record_digest,
                    decision_id,
                    comment,
                )
                if not any(
                    str(item.get("feedbackSubmissionId") or "") == feedback_submission_id
                    for item in feedback_log + new_feedback
                ):
                    new_feedback.append(
                        {
                            "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
                            "feedbackSubmissionId": feedback_submission_id,
                            "batchId": batch_id,
                            "partition": partition,
                            "inputId": input_id,
                            "machineRecordDigest": record_digest,
                            "action": "feedback",
                            "reviewerReference": "primary-human-reviewer",
                            "approvedSections": [],
                            "eventFeedback": [],
                            "notes": comment,
                            "submittedAt": _utc_now(),
                            "approvalEffect": "none",
                            "origin": "feedback_correction_confirmation",
                        }
                    )
            seen.add(input_id)
        if seen != set(packet_by_input):
            raise ExtractionWorkflowError(
                "Every corrected page in the packet must have a decision."
            )
        all_decisions = existing_decisions + new_decisions
        _write_jsonl(decision_log_path, all_decisions)
        _write_jsonl(feedback_log_path, feedback_log + new_feedback)
        summary = {
            "schemaVersion": FEEDBACK_CORRECTION_CONFIRMATION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "packetDigest": packet_summary["packetDigest"],
            "reviewedPageCount": len(reviews),
            "confirmedPageCount": sum(str(item.get("status") or "") == "confirm" for item in reviews),
            "feedbackPageCount": sum(str(item.get("status") or "") == "feedback" for item in reviews),
            "tabCorrectionApprovalGranted": all(
                str(item.get("status") or "") == "confirm" for item in reviews
            ),
            "scoreApprovalGranted": False,
            "pageApprovalGranted": False,
            "decisionLogDigest": _sha256_json(all_decisions),
            "feedbackLogDigest": _sha256_json(feedback_log + new_feedback),
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        _write_json(review_dir / "feedback-correction-confirmation-summary.json", summary)
        metadata_path = source_path.with_suffix(".json")
        if metadata_path.exists():
            metadata = _read_json(metadata_path)
            if metadata.get("status") == "received_not_applied":
                metadata["status"] = "applied"
                metadata["appliedAt"] = _utc_now()
                metadata["applicationSummary"] = summary
                _write_json(metadata_path, metadata)
        return summary

    def audit_discovery_completion(self, batch_id: str) -> dict[str, Any]:
        """Classify remaining discovery pages without opening held-out data.

        This audit is deliberately stricter than the page-review console.  It
        creates a private remediation queue, never a human decision, and marks
        a page review-ready only when the current extractor, regression,
        mechanics, unresolved-evidence, and score/tab correspondence gates all
        pass.  Previously finalized pages and pages carrying unresolved current
        feedback are protected from rereview and refresh.  A correction that
        the reviewer already confirmed against the current record is not
        treated as pending feedback again.
        """

        batch_dir, _manifest, work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        approved_index_path = review_dir / "approved-record-index.jsonl"
        feedback_log_path = review_dir / "human-review-feedback.jsonl"
        approved_index = (
            _read_jsonl(approved_index_path) if approved_index_path.exists() else []
        )
        feedback_log = (
            _read_jsonl(feedback_log_path) if feedback_log_path.exists() else []
        )
        confirmation_log_path = (
            review_dir / "feedback-correction-confirmation-decisions.jsonl"
        )
        confirmation_log = (
            _read_jsonl(confirmation_log_path)
            if confirmation_log_path.exists()
            else []
        )
        finalized_ids = {
            str(item.get("inputId") or "")
            for item in approved_index
            if item.get("inputId")
        }
        feedback_by_input: dict[str, list[dict[str, Any]]] = {}
        for feedback in feedback_log:
            feedback_by_input.setdefault(
                str(feedback.get("inputId") or ""), []
            ).append(feedback)
        latest_confirmation_by_input: dict[str, dict[str, Any]] = {}
        for decision in confirmation_log:
            input_id = str(decision.get("inputId") or "")
            if input_id:
                latest_confirmation_by_input[input_id] = decision
        queue: list[dict[str, Any]] = []
        outcome_counts: Counter[str] = Counter()
        reason_counts: Counter[str] = Counter()
        review_kind_counts: Counter[str] = Counter()
        version_counts: Counter[str] = Counter()
        ready_line_count = 0
        current_unprotected_count = 0
        feedback_protected_count = 0
        confirmed_correction_count = 0

        for source_order, item in enumerate(work):
            input_id = str(item["inputId"])
            if input_id in finalized_ids:
                outcome_counts["finalized"] += 1
                continue
            page_path = pages_dir / f"{input_id}.json"
            if not page_path.exists():
                outcome_counts["remediation_required"] += 1
                reason_counts["missing_extraction_record"] += 1
                queue.append(
                    {
                        "inputId": input_id,
                        "sourceOrder": source_order,
                        "outcome": "remediation_required",
                        "reasons": ["missing_extraction_record"],
                    }
                )
                continue
            record = _read_json(page_path)
            record_digest = _sha256_json(record)
            current_feedback = [
                feedback
                for feedback in feedback_by_input.get(input_id, [])
                if not str(feedback.get("machineRecordDigest") or "")
                or str(feedback.get("machineRecordDigest") or "") == record_digest
            ]
            machine_correction = record.get("machineCorrection") or {}
            confirmation = latest_confirmation_by_input.get(input_id) or {}
            correction_confirmed = bool(
                machine_correction
                and str(confirmation.get("status") or "") == "confirm"
                and str(confirmation.get("machineRecordDigest") or "")
                == record_digest
                and str(confirmation.get("correctionId") or "")
                == str(machine_correction.get("correctionId") or "")
            )
            correction_needs_confirmation = bool(
                machine_correction and not correction_confirmed
            )
            if correction_confirmed:
                confirmed_correction_count += 1
            extractor_version = str(record.get("extractorVersion") or "unknown")
            version_counts[extractor_version] += 1
            classification = str(
                (record.get("pageClassification") or {}).get("primary") or "unknown"
            )
            tab_systems = list(record.get("tabSystems") or [])
            score_systems = list(record.get("scoreSystems") or [])
            tab_events = [
                event
                for system in tab_systems
                for event in system.get("tabEvents") or []
            ]
            actions = [
                action
                for event in tab_events
                for action in event.get("steelActions") or []
            ]
            hard_blockers = _hard_review_blockers(record)
            if (
                classification == "lick_or_fill"
                and tab_systems
                and not score_systems
            ):
                # A source can intentionally be tablature-only lick material.
                # Do not reinterpret the absence of a conventional staff as a
                # failed score/tab pairing; every tab mechanic still has to
                # pass below.
                hard_blockers = [
                    value
                    for value in hard_blockers
                    if value.get("kind")
                    != "score_tab_system_pairing_requires_correction"
                ]
            blocking_unresolved = [
                unresolved
                for unresolved in record.get("unresolved") or []
                if unresolved.get("blocking") is not False
            ]
            reasons: list[str] = []
            if current_feedback or correction_needs_confirmation:
                outcome = "protected_feedback_pending"
                feedback_protected_count += 1
                if current_feedback:
                    reasons.append("current_human_feedback_requires_targeted_correction")
                if correction_needs_confirmation:
                    reasons.append("machine_correction_requires_confirmation")
            else:
                current_unprotected_count += 1
                if extractor_version != EXTRACTOR_VERSION:
                    reasons.append("current_extractor_refresh_required")
                refresh = record.get("unreviewedRefresh") or {}
                regression_gate: dict[str, Any] | None = None
                if refresh.get("schemaVersion") == UNREVIEWED_REFRESH_SCHEMA_VERSION:
                    archive_dir = (
                        review_dir / "unreviewed-refresh-revisions" / input_id
                    )
                    prior_candidates = [
                        _read_json(path) for path in sorted(archive_dir.glob("*.json"))
                    ]
                    if prior_candidates:
                        prior = max(
                            prior_candidates,
                            key=lambda value: str(
                                value.get("extractedAt")
                                or value.get("completedAt")
                                or value.get("extractorVersion")
                                or ""
                            ),
                        )
                        regression_gate = _unreviewed_refresh_regression_gate(
                            prior, record
                        )
                        if not regression_gate["passed"]:
                            reasons.extend(
                                f"refresh_regression:{value}"
                                for value in regression_gate["reasons"]
                            )
                    else:
                        reasons.append("refresh_baseline_missing")
                if hard_blockers:
                    reasons.extend(
                        f"hard_blocker:{value.get('kind')}"
                        for value in hard_blockers
                    )
                if blocking_unresolved:
                    reasons.append("blocking_unresolved_evidence")
                if tab_systems and not tab_events:
                    reasons.append("empty_tab_events")
                if tab_events and not actions:
                    reasons.append("empty_steel_actions")
                if actions and not all(
                    bool((action.get("mechanicalValidation") or {}).get("valid"))
                    for action in actions
                ):
                    reasons.append("mechanically_invalid_action")

                score_gates = (
                    _score_audit_equivalence_gates(record)
                    if score_systems
                    else {}
                )
                score_ready = bool(score_gates) and all(
                    bool(value.get("readyForHumanReview"))
                    for value in score_gates.values()
                )
                if score_systems and not score_ready:
                    for gate in score_gates.values():
                        reasons.extend(
                            f"score_gate:{value.get('code')}"
                            for value in gate.get("blockingReasons") or []
                        )

                non_tab_ready = bool(
                    not tab_systems
                    and not score_systems
                    and classification in {"prose_concept", "practice_method"}
                    and record.get("explicitText")
                )
                tab_only_ready = bool(
                    tab_systems
                    and not score_systems
                    and classification == "lick_or_fill"
                    and tab_events
                    and actions
                )
                score_tab_ready = bool(
                    tab_systems and score_systems and tab_events and actions and score_ready
                )
                structural_ready = non_tab_ready or tab_only_ready or score_tab_ready
                if reasons:
                    outcome = (
                        "refresh_required"
                        if reasons == ["current_extractor_refresh_required"]
                        else "remediation_required"
                    )
                elif structural_ready:
                    outcome = "review_ready"
                    review_kind = (
                        "non_tab_page_disposition"
                        if non_tab_ready
                        else "tab_only"
                        if tab_only_ready
                        else "score_tab"
                    )
                    review_kind_counts[review_kind] += 1
                    if score_tab_ready:
                        ready_line_count += len(score_gates)
                else:
                    outcome = "remediation_required"
                    reasons.append("unsupported_or_incomplete_page_structure")
            outcome_counts[outcome] += 1
            reason_counts.update(reasons)
            queue.append(
                {
                    "inputId": input_id,
                    "sourceOrder": source_order,
                    "machineRecordDigest": record_digest,
                    "extractorVersion": extractor_version,
                    "classification": classification,
                    "scoreSystemCount": len(score_systems),
                    "tabSystemCount": len(tab_systems),
                    "tabEventCount": len(tab_events),
                    "steelActionCount": len(actions),
                    "outcome": outcome,
                    "reasons": sorted(set(reasons)),
                }
            )

        queue.sort(
            key=lambda value: (
                0 if value["outcome"] == "review_ready" else 1,
                int(value["sourceOrder"]),
                str(value["inputId"]),
            )
        )
        audit_core = {
            "schemaVersion": "amazing-tablature-discovery-completion-audit-v1",
            "batchId": batch_id,
            "partition": "discovery",
            "extractorVersion": EXTRACTOR_VERSION,
            "totalDiscoveryPageCount": len(work),
            "finalizedPageCount": len(finalized_ids),
            "remainingPageCount": len(work) - len(finalized_ids),
            "currentUnprotectedPageCount": current_unprotected_count,
            "outcomeCounts": dict(sorted(outcome_counts.items())),
            "reasonCounts": dict(sorted(reason_counts.items())),
            "reviewKindCounts": dict(sorted(review_kind_counts.items())),
            "readyScoreTabLineCount": ready_line_count,
            "maxExceptionalReviewLines": 10,
            "reviewPacketCreated": False,
            "humanApprovalCreated": False,
            "noRereviewGuard": {
                "finalizedPageCount": len(finalized_ids),
                "feedbackProtectedPageCount": feedback_protected_count,
                "confirmedCorrectionPageCount": confirmed_correction_count,
                "preserved": True,
            },
            "extractorVersionCounts": dict(sorted(version_counts.items())),
            "queueDigest": _sha256_json(queue),
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        audit_id = _stable_id(
            "discovery-completion-audit", batch_id, audit_core["queueDigest"]
        )
        automation_dir = review_dir / "automation" / audit_id
        automation_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(automation_dir, 0o700)
        queue_path = automation_dir / "queue.jsonl"
        audit_path = automation_dir / "summary.json"
        _write_jsonl(queue_path, queue)
        summary = {
            **audit_core,
            "auditId": audit_id,
            "createdAt": _utc_now(),
            "queuePath": str(queue_path.relative_to(output_root)),
        }
        _write_json(audit_path, summary)
        return summary

    def quarantine_discovery_remainder(
        self,
        batch_id: str,
        *,
        approval_reference: str,
        confirm_bulk_quarantine: bool = False,
    ) -> dict[str, Any]:
        """Exclude the audited unresolved remainder from transformation training.

        This is a disposition, not factual approval.  It preserves every raw
        asset, extraction, comment, correction, and audit artifact while
        keeping uncertain pages out of model evidence.  The operation is
        intentionally unavailable without an explicit human authorization and
        an affirmative bulk-quarantine flag.
        """

        reference = str(approval_reference or "").strip()
        if not confirm_bulk_quarantine or len(reference) < 12:
            raise ExtractionWorkflowError(
                "Bulk discovery quarantine requires an explicit approval reference and confirmation flag."
            )
        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_dir = output_root / "review"
        audit = self.audit_discovery_completion(batch_id)
        if audit.get("validationAccessed") or audit.get("sealedTestAccessed"):
            raise ExtractionWorkflowError(
                "Discovery quarantine cannot run after held-out access."
            )
        queue_path = output_root / str(audit.get("queuePath") or "")
        queue = _read_jsonl(queue_path)
        if len(queue) != int(audit.get("remainingPageCount") or 0):
            raise ExtractionWorkflowError(
                "The discovery quarantine queue does not cover the exact remaining cohort."
            )
        allowed_outcomes = {
            "protected_feedback_pending",
            "refresh_required",
            "remediation_required",
            "review_ready",
        }
        if any(str(item.get("outcome") or "") not in allowed_outcomes for item in queue):
            raise ExtractionWorkflowError(
                "The discovery quarantine queue contains an unsupported disposition."
            )
        decisions: list[dict[str, Any]] = []
        outcome_counts: Counter[str] = Counter()
        reason_counts: Counter[str] = Counter()
        for item in queue:
            input_id = str(item.get("inputId") or "")
            machine_digest = str(item.get("machineRecordDigest") or "")
            page_path = output_root / "pages" / f"{input_id}.json"
            if not input_id or not machine_digest or not page_path.exists():
                raise ExtractionWorkflowError(
                    "Every quarantined discovery page must have a current digest-pinned extraction."
                )
            if _sha256_json(_read_json(page_path)) != machine_digest:
                raise ExtractionWorkflowError(
                    f"The discovery quarantine audit is stale for {input_id}."
                )
            outcome = str(item.get("outcome") or "")
            reasons = sorted({str(value) for value in item.get("reasons") or []})
            outcome_counts[outcome] += 1
            reason_counts.update(reasons)
            decisions.append(
                {
                    "inputId": input_id,
                    "expectedMachineRecordDigest": machine_digest,
                    "action": "exclude",
                    "reviewerReference": reference,
                    "approvedSections": [],
                    "notes": (
                        "Excluded from the current structured-input transformation "
                        "training snapshot under the approved automatic-quarantine "
                        "policy; source and teaching evidence are retained privately."
                    ),
                }
            )
        quarantine_core = {
            "schemaVersion": "amazing-tablature-discovery-quarantine-v1",
            "batchId": batch_id,
            "partition": "discovery",
            "auditId": audit["auditId"],
            "auditQueueDigest": audit["queueDigest"],
            "approvalReference": reference,
            "pageCount": len(decisions),
            "outcomeCounts": dict(sorted(outcome_counts.items())),
            "reasonCounts": dict(sorted(reason_counts.items())),
            "factualApprovalGranted": False,
            "sourceAssetsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        quarantine_id = _stable_id(
            "discovery-quarantine", batch_id, _sha256_json(quarantine_core)
        )
        quarantine_dir = review_dir / "automation" / quarantine_id
        decisions_path = quarantine_dir / "decisions.jsonl"
        summary_path = quarantine_dir / "summary.json"
        if summary_path.exists():
            return _read_json(summary_path)
        quarantine_dir.mkdir(parents=True, exist_ok=False)
        os.chmod(quarantine_dir, 0o700)
        _write_jsonl(decisions_path, decisions)
        review_summary = self.apply_review(
            batch_id,
            decisions_path,
            partition="discovery",
        )
        summary = {
            **quarantine_core,
            "quarantineId": quarantine_id,
            "reviewSummaryDigest": _sha256_json(review_summary),
            "remainingPageCount": int(review_summary["remainingPageCount"]),
            "humanApprovalComplete": bool(review_summary["humanApprovalComplete"]),
            "completedAt": _utc_now(),
        }
        _write_json(summary_path, summary)
        return summary

    def remediate_discovery_score_correspondence(
        self,
        batch_id: str,
        *,
        limit: int = 5,
        workers: int = 1,
    ) -> dict[str, Any]:
        """Build fail-closed score-only canaries from current discovery records.

        The current page record is immutable input to this operation.  Only a
        score-repair candidate and a private automation report are written.  A
        candidate cannot become reviewed truth, a training record, or a review
        packet through this method.  Unreviewed records are diagnostic-only;
        only a digest-pinned, reviewer-confirmed correction can ever enter the
        exceptional-review queue.
        """

        if limit < 1 or limit > 10:
            raise ExtractionWorkflowError(
                "Discovery score remediation is limited to 1-10 canary pages."
            )
        if workers < 1 or workers > 4:
            raise ExtractionWorkflowError(
                "Discovery score remediation workers must be between 1 and 4."
            )
        batch_dir, manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        audit = self.audit_discovery_completion(batch_id)
        queue = _read_jsonl(output_root / str(audit["queuePath"]))
        confirmation_path = (
            review_dir / "feedback-correction-confirmation-decisions.jsonl"
        )
        confirmations: dict[str, dict[str, Any]] = {}
        for decision in (
            _read_jsonl(confirmation_path) if confirmation_path.exists() else []
        ):
            input_id = str(decision.get("inputId") or "")
            if input_id:
                confirmations[input_id] = decision
        feedback_path = review_dir / "human-review-feedback.jsonl"
        historical_feedback_ids = {
            str(item.get("inputId") or "")
            for item in (
                _read_jsonl(feedback_path) if feedback_path.exists() else []
            )
            if item.get("inputId")
        }

        eligible: list[dict[str, Any]] = []
        skipped: Counter[str] = Counter()
        for row in queue:
            if str(row.get("outcome") or "") != "remediation_required":
                continue
            if str(row.get("extractorVersion") or "") != EXTRACTOR_VERSION:
                skipped["not_current_extractor"] += 1
                continue
            if any(
                str(reason).startswith("refresh_regression:")
                for reason in row.get("reasons") or []
            ):
                skipped["refresh_regression"] += 1
                continue
            input_id = str(row.get("inputId") or "")
            record_path = pages_dir / f"{input_id}.json"
            if not record_path.exists():
                skipped["missing_current_record"] += 1
                continue
            record = _read_json(record_path)
            record_digest = _sha256_json(record)
            correction = record.get("machineCorrection") or {}
            confirmation = confirmations.get(input_id) or {}
            correction_confirmed = bool(
                correction
                and str(confirmation.get("status") or "") == "confirm"
                and str(confirmation.get("machineRecordDigest") or "")
                == record_digest
                and str(confirmation.get("correctionId") or "")
                == str(correction.get("correctionId") or "")
            )
            if correction_confirmed:
                base_fact_scope = (
                    "digest_pinned_machine_record_with_confirmed_feedback_corrections"
                )
                selection_priority = 0
            elif not correction and input_id not in historical_feedback_ids:
                base_fact_scope = "current_machine_extraction_never_reviewed"
                selection_priority = 1
            else:
                skipped["current_correction_not_confirmed"] += 1
                continue
            score_systems = list(record.get("scoreSystems") or [])
            tab_systems = list(record.get("tabSystems") or [])
            if not score_systems or not tab_systems:
                skipped["not_score_and_tab"] += 1
                continue
            blocking_unresolved = [
                item
                for item in record.get("unresolved") or []
                if item.get("blocking") is not False
            ]
            if blocking_unresolved and not correction_confirmed:
                skipped["unreviewed_blocking_evidence"] += 1
                continue
            actions = [
                action
                for system in tab_systems
                for event in system.get("tabEvents") or []
                for action in event.get("steelActions") or []
            ]
            if not actions or not all(
                bool((action.get("mechanicalValidation") or {}).get("valid"))
                for action in actions
            ):
                skipped["tab_mechanics_not_valid"] += 1
                continue
            tab_ids = {
                str(system.get("tabSystemId") or "") for system in tab_systems
            }
            paired_tab_ids = {
                str(system.get("pairedTabSystemId") or "")
                for system in score_systems
            }
            if (
                "" in paired_tab_ids
                or not paired_tab_ids
                or not paired_tab_ids.issubset(tab_ids)
            ):
                skipped["score_tab_pairing_incomplete"] += 1
                continue
            eligible.append(
                {
                    "inputId": input_id,
                    "sourceOrder": int(row.get("sourceOrder") or 0),
                    "recordDigest": record_digest,
                    "record": record,
                    "confirmationDecisionId": str(
                        confirmation.get("decisionId") or ""
                    ),
                    "baseFactScope": base_fact_scope,
                    "selectionPriority": selection_priority,
                    "systemCount": len(score_systems),
                    "tabEventCount": sum(
                        len(system.get("tabEvents") or []) for system in tab_systems
                    ),
                }
            )
        eligible.sort(
            key=lambda item: (
                int(item["selectionPriority"]),
                int(item["systemCount"]),
                int(item["tabEventCount"]),
                int(item["sourceOrder"]),
                str(item["inputId"]),
            )
        )
        selected = eligible[:limit]
        if not selected:
            raise ExtractionWorkflowError(
                "No current, regression-clean, mechanically valid score/tab discovery "
                "pages are eligible for fail-closed remediation."
            )

        remediation_root = review_dir / "automation" / "score-remediation"
        index_path = remediation_root / "candidate-index.jsonl"
        remediation_root.mkdir(parents=True, exist_ok=True)
        os.chmod(remediation_root, 0o700)
        existing_index = _read_jsonl(index_path) if index_path.exists() else []
        existing_by_lineage = {
            (
                str(item.get("inputId") or ""),
                str(item.get("baseRecordDigest") or ""),
                str(item.get("scoreRepairVersion") or ""),
            ): item
            for item in existing_index
            if item.get("status") == "candidate_ready"
        }

        def evaluate_candidate(
            selected_item: Mapping[str, Any],
            candidate: Mapping[str, Any],
            repair_result: Mapping[str, Any],
            *,
            reused: bool,
        ) -> dict[str, Any]:
            score_gates = _score_audit_equivalence_gates(candidate)
            tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in candidate.get("tabSystems") or []
            }
            comparisons: list[dict[str, Any]] = []
            base_score_by_id = {
                str(system.get("scoreSystemId") or ""): system
                for system in selected_item["record"].get("scoreSystems") or []
            }
            base_tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in selected_item["record"].get("tabSystems") or []
            }
            for score_system in candidate.get("scoreSystems") or []:
                paired_tab_id = str(score_system.get("pairedTabSystemId") or "")
                tab_system = tab_by_id.get(paired_tab_id)
                if tab_system is None:
                    comparisons.append(
                        {
                            "scoreSystemId": score_system.get("scoreSystemId"),
                            "automaticPitchGatePassed": False,
                            "provisionalReviewBlockers": [
                                "score_tab_pairing_incomplete"
                            ],
                        }
                    )
                    continue
                comparison = _combined_score_tab_columns(score_system, tab_system)
                base_score = base_score_by_id.get(
                    str(score_system.get("scoreSystemId") or "")
                )
                base_tab = base_tab_by_id.get(paired_tab_id)
                baseline_comparison = (
                    _combined_score_tab_columns(base_score, base_tab)
                    if base_score is not None and base_tab is not None
                    else {}
                )
                comparisons.append(
                    {
                        "scoreSystemId": score_system.get("scoreSystemId"),
                        "tabSystemId": paired_tab_id,
                        "scoreAttackCount": comparison.get("scoreAttackCount"),
                        "tabAttackCount": comparison.get("tabAttackCount"),
                        "tabMovementCount": comparison.get("tabMovementCount"),
                        "relationshipCounts": copy.deepcopy(
                            comparison.get("relationshipCounts") or {}
                        ),
                        "baselineScoreAttackCount": baseline_comparison.get(
                            "scoreAttackCount"
                        ),
                        "baselineTabAttackCount": baseline_comparison.get(
                            "tabAttackCount"
                        ),
                        "baselineRelationshipCounts": copy.deepcopy(
                            baseline_comparison.get("relationshipCounts") or {}
                        ),
                        "automaticPitchGatePassed": bool(
                            comparison.get("automaticPitchGatePassed")
                        ),
                        "scoreReaderIndependentOfTabPitches": bool(
                            comparison.get("scoreReaderIndependentOfTabPitches")
                        ),
                        "provisionalReviewBlockers": _provisional_joint_review_blockers(
                            comparison,
                            key_signature_known=(
                                score_system.get("keyFifths") is not None
                            ),
                        ),
                    }
                )
            hard_blockers = [
                str(item.get("kind") or "unknown")
                for item in _hard_review_blockers(candidate)
            ]
            blocking_unresolved = [
                str(item.get("kind") or "unknown")
                for item in candidate.get("unresolved") or []
                if item.get("blocking") is not False
            ]
            every_score_gate_passed = bool(score_gates) and all(
                bool(gate.get("readyForHumanReview"))
                for gate in score_gates.values()
            )
            every_joint_gate_passed = bool(comparisons) and all(
                bool(comparison.get("automaticPitchGatePassed"))
                and bool(comparison.get("scoreReaderIndependentOfTabPitches"))
                and not comparison.get("provisionalReviewBlockers")
                for comparison in comparisons
            )
            base_lineage_eligible_for_review = (
                selected_item["baseFactScope"]
                == "digest_pinned_machine_record_with_confirmed_feedback_corrections"
                and bool(selected_item["confirmationDecisionId"])
            )
            exceptional = bool(
                base_lineage_eligible_for_review
                and every_score_gate_passed
                and every_joint_gate_passed
                and not hard_blockers
                and not blocking_unresolved
            )
            return {
                "schemaVersion": DISCOVERY_SCORE_REMEDIATION_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": "discovery",
                "inputId": selected_item["inputId"],
                "baseRecordDigest": selected_item["recordDigest"],
                "baseFactScope": selected_item["baseFactScope"],
                "baseLineageEligibleForReview": base_lineage_eligible_for_review,
                "confirmationDecisionId": selected_item[
                    "confirmationDecisionId"
                ],
                "scoreRepairVersion": SCORE_REPAIR_VERSION,
                "candidateRecordPath": repair_result.get("candidateRecordPath"),
                "candidateRecordDigest": repair_result.get(
                    "candidateRecordDigest"
                ),
                "scoreSystemCount": len(candidate.get("scoreSystems") or []),
                "scoreAuditGatesBySystem": score_gates,
                "jointComparisons": comparisons,
                "hardBlockers": hard_blockers,
                "blockingUnresolvedEvidence": blocking_unresolved,
                "allScoreAuditGatesPassed": every_score_gate_passed,
                "allJointCorrespondenceGatesPassed": every_joint_gate_passed,
                "eligibleForExceptionalHumanReview": exceptional,
                "reviewPacketCreated": False,
                "humanApprovalCreated": False,
                "currentPageRecordModified": False,
                "reusedCandidate": reused,
                "status": "candidate_ready",
                "validationAccessed": False,
                "sealedTestAccessed": False,
            }

        def remediate_one(selected_item: Mapping[str, Any]) -> dict[str, Any]:
            lineage = (
                str(selected_item["inputId"]),
                str(selected_item["recordDigest"]),
                SCORE_REPAIR_VERSION,
            )
            existing = existing_by_lineage.get(lineage)
            if existing is not None:
                relative_path = str(existing.get("candidateRecordPath") or "")
                candidate_path = output_root / relative_path
                if not relative_path or not candidate_path.exists():
                    raise ExtractionWorkflowError(
                        "A reusable discovery score-remediation candidate is missing."
                    )
                candidate = _read_json(candidate_path)
                if _sha256_json(candidate) != str(
                    existing.get("candidateRecordDigest") or ""
                ):
                    raise ExtractionWorkflowError(
                        "A reusable discovery score-remediation candidate changed."
                    )
                return evaluate_candidate(
                    selected_item,
                    candidate,
                    existing,
                    reused=True,
                )
            repair_result = self._build_score_repair_candidate(
                output_root=output_root,
                input_id=str(selected_item["inputId"]),
                base_record=selected_item["record"],
                base_reviewed_record_digest=str(selected_item["recordDigest"]),
                prior_review_decision_id=(
                    str(selected_item["confirmationDecisionId"]) or None
                ),
            )
            relative_path = str(repair_result.get("candidateRecordPath") or "")
            candidate_path = output_root / relative_path
            if not relative_path or not candidate_path.exists():
                raise ExtractionWorkflowError(
                    "Discovery score remediation produced no candidate record."
                )
            candidate = _read_json(candidate_path)
            if _sha256_json(candidate) != str(
                repair_result.get("candidateRecordDigest") or ""
            ):
                raise ExtractionWorkflowError(
                    "Discovery score-remediation candidate digest mismatch."
                )
            return evaluate_candidate(
                selected_item,
                candidate,
                repair_result,
                reused=False,
            )

        results_by_input: dict[str, dict[str, Any]] = {}
        failures: list[dict[str, Any]] = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {
                executor.submit(remediate_one, item): str(item["inputId"])
                for item in selected
            }
            for future in concurrent.futures.as_completed(futures):
                input_id = futures[future]
                try:
                    results_by_input[input_id] = future.result()
                except Exception as exc:
                    failures.append(
                        {
                            "schemaVersion": DISCOVERY_SCORE_REMEDIATION_SCHEMA_VERSION,
                            "batchId": batch_id,
                            "partition": "discovery",
                            "inputId": input_id,
                            "status": "repair_failed",
                            "message": str(exc),
                            "currentPageRecordModified": False,
                            "reviewPacketCreated": False,
                            "humanApprovalCreated": False,
                            "validationAccessed": False,
                            "sealedTestAccessed": False,
                        }
                    )
        results = [results_by_input[key] for key in sorted(results_by_input)]
        results.extend(sorted(failures, key=lambda item: str(item["inputId"])))

        # Fail closed if score repair changed any current discovery input.
        for selected_item in selected:
            current = _read_json(pages_dir / f"{selected_item['inputId']}.json")
            if _sha256_json(current) != str(selected_item["recordDigest"]):
                raise ExtractionWorkflowError(
                    "Discovery score remediation changed a current page record."
                )

        new_index_entries = [
            item
            for item in results
            if item.get("status") == "candidate_ready"
            and (
                str(item.get("inputId") or ""),
                str(item.get("baseRecordDigest") or ""),
                str(item.get("scoreRepairVersion") or ""),
            )
            not in existing_by_lineage
        ]
        _write_jsonl(index_path, existing_index + new_index_entries)
        result_digest = _sha256_json(results)
        run_id = _stable_id(
            "discovery-score-remediation",
            batch_id,
            audit.get("queueDigest"),
            result_digest,
        )
        run_dir = remediation_root / "runs" / run_id
        run_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(run_dir, 0o700)
        result_path = run_dir / "results.jsonl"
        exceptional_path = run_dir / "exceptional-review-queue.jsonl"
        _write_jsonl(result_path, results)
        exceptional = [
            item
            for item in results
            if item.get("eligibleForExceptionalHumanReview") is True
        ]
        _write_jsonl(exceptional_path, exceptional)
        joint_comparisons = [
            comparison
            for item in results
            if item.get("status") == "candidate_ready"
            for comparison in item.get("jointComparisons") or []
        ]

        def count_difference(
            comparison: Mapping[str, Any], score_key: str, tab_key: str
        ) -> int | None:
            score_count = comparison.get(score_key)
            tab_count = comparison.get(tab_key)
            if score_count is None or tab_count is None:
                return None
            return abs(int(score_count) - int(tab_count))

        baseline_count_differences = [
            difference
            for comparison in joint_comparisons
            if (
                difference := count_difference(
                    comparison,
                    "baselineScoreAttackCount",
                    "baselineTabAttackCount",
                )
            )
            is not None
        ]
        candidate_count_differences = [
            difference
            for comparison in joint_comparisons
            if (
                difference := count_difference(
                    comparison, "scoreAttackCount", "tabAttackCount"
                )
            )
            is not None
        ]
        summary = {
            "schemaVersion": DISCOVERY_SCORE_REMEDIATION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "runId": run_id,
            "completionAuditId": audit.get("auditId"),
            "completionQueueDigest": audit.get("queueDigest"),
            "extractorVersion": EXTRACTOR_VERSION,
            "scoreRepairVersion": SCORE_REPAIR_VERSION,
            "sourceCopedentId": manifest.get("sourceCopedentId"),
            "sourceCopedentRevision": manifest.get("sourceCopedentRevision"),
            "eligiblePoolPageCount": len(eligible),
            "selectedPageCount": len(selected),
            "candidateReadyPageCount": sum(
                item.get("status") == "candidate_ready" for item in results
            ),
            "repairFailedPageCount": len(failures),
            "allScoreAuditGatesPassedPageCount": sum(
                item.get("allScoreAuditGatesPassed") is True for item in results
            ),
            "allJointCorrespondenceGatesPassedPageCount": sum(
                item.get("allJointCorrespondenceGatesPassed") is True
                for item in results
            ),
            "exceptionalReviewEligiblePageCount": len(exceptional),
            "diagnosticScoreSystemCount": len(joint_comparisons),
            "baselineCountExactSystemCount": sum(
                difference == 0 for difference in baseline_count_differences
            ),
            "candidateCountExactSystemCount": sum(
                difference == 0 for difference in candidate_count_differences
            ),
            "baselineAbsoluteCountDifference": sum(
                baseline_count_differences
            ),
            "candidateAbsoluteCountDifference": sum(
                candidate_count_differences
            ),
            "baselineExactPitchColumnCount": sum(
                int(
                    (comparison.get("baselineRelationshipCounts") or {}).get(
                        "exact", 0
                    )
                )
                for comparison in joint_comparisons
            ),
            "candidateExactPitchColumnCount": sum(
                int((comparison.get("relationshipCounts") or {}).get("exact", 0))
                for comparison in joint_comparisons
            ),
            "baseLineageEligiblePageCount": sum(
                item.get("baseLineageEligibleForReview") is True
                for item in results
            ),
            "skippedReasonCounts": dict(sorted(skipped.items())),
            "resultDigest": result_digest,
            "resultPath": str(result_path.relative_to(output_root)),
            "exceptionalReviewQueuePath": str(
                exceptional_path.relative_to(output_root)
            ),
            "reviewPacketCreated": False,
            "humanApprovalCreated": False,
            "currentPageRecordsModified": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "completedAt": _utc_now(),
        }
        _write_json(run_dir / "summary.json", summary)
        return summary

    def freeze_source_score_notehead_benchmark(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Freeze corrected discovery score lines into development and shadow sets.

        The benchmark uses only the latest human-approved pitch-only combined
        score/tab line decisions.  Every system from one source page stays in
        one subset.  Once written, the manifest is immutable even if additional
        discovery reviews arrive later.
        """

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_root = output_root / "review"
        approved_index_path = (
            review_root
            / "combined-score-tab-audit"
            / "application"
            / "approved-line-index.jsonl"
        )
        if not approved_index_path.exists():
            raise ExtractionWorkflowError(
                "The discovery score benchmark requires approved combined score/tab lines."
            )
        rows = _read_jsonl(approved_index_path)
        latest_by_system: dict[str, dict[str, Any]] = {}
        for row in rows:
            system_id = str(row.get("scoreSystemId") or "")
            if system_id:
                latest_by_system[system_id] = row

        cases: list[dict[str, Any]] = []
        for system_id, row in latest_by_system.items():
            if str(row.get("status") or "") != "human_approved_pitch_only":
                continue
            input_id = str(row.get("inputId") or "")
            record_relative_path = str(row.get("reviewedRecordPath") or "")
            expected_record_digest = str(row.get("reviewedRecordDigest") or "")
            record_path = output_root / record_relative_path
            if not input_id or not record_relative_path or not record_path.exists():
                continue
            record = _read_json(record_path)
            actual_record_digest = _sha256_json(record)
            if expected_record_digest and actual_record_digest != expected_record_digest:
                raise ExtractionWorkflowError(
                    "A discovery score benchmark record no longer matches its approval digest."
                )
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "") == system_id
                ),
                None,
            )
            recognized = (score_system or {}).get("recognizedMusicXml") or {}
            recognized_relative_path = str(recognized.get("relativePath") or "")
            omr_path = (
                output_root / Path(recognized_relative_path).with_suffix(".omr")
                if recognized_relative_path
                else None
            )
            truth_count = int(row.get("scoreAttackCount") or 0)
            if (
                score_system is None
                or truth_count < 1
                or omr_path is None
                or not omr_path.exists()
            ):
                continue
            baseline_count: int | None = None
            baseline_failure: str | None = None
            try:
                graph = _parse_audiveris_head_graph(omr_path, system_id)
                baseline_count = len(
                    _score_attack_groups(graph.get("scoreEvents") or [])
                )
            except ExtractionWorkflowError as exc:
                baseline_failure = type(exc).__name__
            cases.append(
                {
                    "caseId": _stable_id(
                        "source-score-notehead-case",
                        input_id,
                        system_id,
                        expected_record_digest or actual_record_digest,
                    ),
                    "inputId": input_id,
                    "scoreSystemId": system_id,
                    "reviewDecisionId": str(row.get("decisionId") or ""),
                    "reviewedRecordPath": record_relative_path,
                    "reviewedRecordDigest": expected_record_digest
                    or actual_record_digest,
                    "omrRelativePath": str(omr_path.relative_to(output_root)),
                    "omrSha256": _sha256_bytes(omr_path.read_bytes()),
                    "sourceAttackCount": truth_count,
                    "baselineAttackCount": baseline_count,
                    "baselineFailure": baseline_failure,
                }
            )
        if len(cases) < 10:
            raise ExtractionWorkflowError(
                "The discovery score benchmark requires at least ten approved lines."
            )
        cases.sort(key=lambda item: str(item["caseId"]))
        cases_by_input: dict[str, list[dict[str, Any]]] = {}
        for case in cases:
            cases_by_input.setdefault(str(case["inputId"]), []).append(case)
        page_groups = sorted(
            cases_by_input.items(),
            key=lambda item: _sha256_json(
                [SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION, item[0]]
            ),
        )
        shadow_target = max(5, int(round(len(cases) * 0.30)))
        shadow_inputs: set[str] = set()
        shadow_count = 0
        for input_id, grouped_cases in page_groups:
            if shadow_count >= shadow_target:
                break
            shadow_inputs.add(input_id)
            shadow_count += len(grouped_cases)
        for case in cases:
            case["subset"] = (
                "shadow" if str(case["inputId"]) in shadow_inputs else "development"
            )

        benchmark_root = (
            review_root / "automation" / "source-score-notehead-challenger"
        )
        benchmark_root.mkdir(parents=True, exist_ok=True)
        os.chmod(benchmark_root, 0o700)
        manifest_path = benchmark_root / "benchmark-manifest.json"
        manifest_core = {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "approvedLineIndexSha256": _sha256_bytes(
                approved_index_path.read_bytes()
            ),
            "splitMethod": "page_grouped_stable_hash_70_30_v1",
            "baselineAggregateObservedBeforeSplitFreeze": True,
            "cases": cases,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        manifest_digest = _sha256_json(manifest_core)
        frozen_manifest = {**manifest_core, "manifestDigest": manifest_digest}
        if manifest_path.exists():
            existing = _read_json(manifest_path)
            if existing != frozen_manifest:
                raise ExtractionWorkflowError(
                    "The source-score notehead benchmark is already frozen and cannot change."
                )
        else:
            _write_json(manifest_path, frozen_manifest)
        development = [case for case in cases if case["subset"] == "development"]
        shadow = [case for case in cases if case["subset"] == "shadow"]

        def subset_metrics(items: Sequence[Mapping[str, Any]]) -> dict[str, int]:
            parsed = [item for item in items if item.get("baselineAttackCount") is not None]
            return {
                "caseCount": len(items),
                "parsedCount": len(parsed),
                "failureCount": len(items) - len(parsed),
                "exactCount": sum(
                    int(item["baselineAttackCount"]) == int(item["sourceAttackCount"])
                    for item in parsed
                ),
                "absoluteError": sum(
                    abs(
                        int(item["baselineAttackCount"])
                        - int(item["sourceAttackCount"])
                    )
                    for item in parsed
                ),
            }

        return {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "manifestDigest": manifest_digest,
            "manifestPath": str(manifest_path.relative_to(output_root)),
            "development": subset_metrics(development),
            "shadow": subset_metrics(shadow),
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def evaluate_source_score_notehead_challenger(
        self,
        batch_id: str,
        *,
        subset: str = "development",
    ) -> dict[str, Any]:
        """Evaluate the frozen source-only notehead detector without promotion."""

        if subset not in {"development", "shadow"}:
            raise ExtractionWorkflowError(
                "Source-score notehead evaluation subset must be development or shadow."
            )
        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before evaluation."
            )
        benchmark = _read_json(manifest_path)
        if (
            str(benchmark.get("schemaVersion") or "")
            != SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION
            or str(benchmark.get("batchId") or "") != batch_id
            or str(benchmark.get("partition") or "") != "discovery"
        ):
            raise ExtractionWorkflowError(
                "The frozen source-score notehead benchmark contract is invalid."
            )
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError(
                "The frozen source-score notehead benchmark digest changed."
            )
        contract = {
            "detectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "mergeWidthFactor": SOURCE_SCORE_NOTEHEAD_MERGE_WIDTH_FACTOR,
            "source": "audiveris_internal_notehead_bounds",
            "clefRequired": False,
            "pitchesEmitted": False,
            "tablatureCountProvided": False,
            "tablaturePitchesProvided": False,
        }
        contract_digest = _sha256_json(contract)
        selected_contract_path = benchmark_root / "selected-contract.json"
        if subset == "shadow":
            if not selected_contract_path.exists():
                raise ExtractionWorkflowError(
                    "Freeze a development-passed challenger contract before shadow evaluation."
                )
            selected_contract = _read_json(selected_contract_path)
            if (
                selected_contract.get("challengerContractDigest") != contract_digest
                or selected_contract.get("benchmarkManifestDigest")
                != benchmark_digest
            ):
                raise ExtractionWorkflowError(
                    "Shadow evaluation requires the exact selected challenger contract."
                )

        cases = [
            case
            for case in benchmark.get("cases") or []
            if str(case.get("subset") or "") == subset
        ]
        if not cases:
            raise ExtractionWorkflowError(
                "The frozen source-score benchmark subset is empty."
            )
        results: list[dict[str, Any]] = []
        for case in cases:
            omr_path = output_root / str(case.get("omrRelativePath") or "")
            if (
                not omr_path.exists()
                or _sha256_bytes(omr_path.read_bytes())
                != str(case.get("omrSha256") or "")
            ):
                raise ExtractionWorkflowError(
                    "A frozen source-score benchmark OMR artifact changed."
                )
            prediction: dict[str, Any] | None = None
            failure: str | None = None
            try:
                prediction = _audiveris_notehead_columns(omr_path)
            except ExtractionWorkflowError as exc:
                failure = type(exc).__name__
            truth = int(case.get("sourceAttackCount") or 0)
            baseline = case.get("baselineAttackCount")
            challenger_count = (
                int(prediction["columnCount"]) if prediction is not None else None
            )
            results.append(
                {
                    "caseId": case.get("caseId"),
                    "inputId": case.get("inputId"),
                    "scoreSystemId": case.get("scoreSystemId"),
                    "sourceAttackCount": truth,
                    "baselineAttackCount": baseline,
                    "baselineFailure": case.get("baselineFailure"),
                    "challengerAttackCount": challenger_count,
                    "challengerFailure": failure,
                    "baselineExact": baseline is not None
                    and int(baseline) == truth,
                    "challengerExact": challenger_count is not None
                    and challenger_count == truth,
                    "baselineAbsoluteError": abs(
                        int(baseline) - truth
                    )
                    if baseline is not None
                    else truth,
                    "challengerAbsoluteError": abs(challenger_count - truth)
                    if challenger_count is not None
                    else truth,
                    "prediction": prediction,
                }
            )
        baseline_exact = sum(item["baselineExact"] for item in results)
        challenger_exact = sum(item["challengerExact"] for item in results)
        baseline_error = sum(item["baselineAbsoluteError"] for item in results)
        challenger_error = sum(
            item["challengerAbsoluteError"] for item in results
        )
        baseline_failures = sum(
            item.get("baselineAttackCount") is None for item in results
        )
        challenger_failures = sum(
            item.get("challengerAttackCount") is None for item in results
        )
        exact_gate = challenger_exact > baseline_exact
        error_gate = challenger_error < baseline_error
        coverage_gate = challenger_failures < baseline_failures
        gate_passed = bool(exact_gate and error_gate and coverage_gate)
        report_core = {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "subset": subset,
            "benchmarkManifestDigest": benchmark_digest,
            "challengerContract": contract,
            "challengerContractDigest": contract_digest,
            "caseCount": len(results),
            "baseline": {
                "exactCount": baseline_exact,
                "absoluteErrorIncludingFailuresAsZero": baseline_error,
                "failureCount": baseline_failures,
            },
            "challenger": {
                "exactCount": challenger_exact,
                "absoluteErrorIncludingFailuresAsZero": challenger_error,
                "failureCount": challenger_failures,
            },
            "gates": {
                "exactCountImproved": exact_gate,
                "absoluteErrorImproved": error_gate,
                "failureCountImproved": coverage_gate,
            },
            "gatePassed": gate_passed,
            "results": results,
            "reviewPacketCreated": False,
            "humanApprovalCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = (
            benchmark_root
            / f"{subset}-report-{contract_digest[:12]}.json"
        )
        if report_path.exists():
            existing = _read_json(report_path)
            if existing != report:
                raise ExtractionWorkflowError(
                    "The frozen source-score benchmark result cannot be overwritten."
                )
        else:
            _write_json(report_path, report)
        return {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "subset": subset,
            "benchmarkManifestDigest": benchmark_digest,
            "challengerContractDigest": contract_digest,
            "caseCount": len(results),
            "baseline": report["baseline"],
            "challenger": report["challenger"],
            "gates": report["gates"],
            "gatePassed": gate_passed,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
            "reviewPacketCreated": False,
            "humanApprovalCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def evaluate_source_score_projection_challenger(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Evaluate the fixed projection fusion on opened discovery regressions."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before projection evaluation."
            )
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")
        contract = {
            "detectorVersion": SOURCE_SCORE_PROJECTION_DETECTOR_VERSION,
            "parameters": dict(SOURCE_SCORE_PROJECTION_CONTRACT),
            "anchorDetectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "source": "printed_score_crop_and_audiveris_source_notehead_anchors",
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "pitchesEmitted": False,
        }
        contract_digest = _sha256_json(contract)
        results: list[dict[str, Any]] = []
        for case in benchmark.get("cases") or []:
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            if not record_path.exists():
                raise ExtractionWorkflowError("A projection regression record is missing.")
            record = _read_json(record_path)
            if _sha256_json(record) != str(case.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError("A projection regression record changed.")
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "")
                    == str(case.get("scoreSystemId") or "")
                ),
                None,
            )
            crop_path: Path | None = None
            crop_relative_path = ""
            crop_sha256 = ""
            crop_source = ""
            for source_name, crop in (
                (
                    "omr_prepared_derivative",
                    (score_system or {}).get("omrPreparedDerivative") or {},
                ),
                (
                    "score_repair_source_crop",
                    (score_system or {}).get("scoreRepairSourceCrop") or {},
                ),
            ):
                relative_path = str(crop.get("relativePath") or "")
                expected_sha = str(crop.get("sha256") or "")
                candidate_path = output_root / relative_path
                if (
                    relative_path
                    and candidate_path.exists()
                    and _sha256_bytes(candidate_path.read_bytes()) == expected_sha
                ):
                    crop_path = candidate_path
                    crop_relative_path = relative_path
                    crop_sha256 = expected_sha
                    crop_source = source_name
                    break
            if score_system is None or crop_path is None:
                raise ExtractionWorkflowError(
                    "A digest-pinned score crop is unavailable for projection evaluation."
                )
            omr_path = output_root / str(case.get("omrRelativePath") or "")
            if (
                not omr_path.exists()
                or _sha256_bytes(omr_path.read_bytes())
                != str(case.get("omrSha256") or "")
            ):
                raise ExtractionWorkflowError("A projection regression OMR artifact changed.")
            notehead_prediction = _audiveris_notehead_columns(omr_path)
            projection = _score_projection_fusion(crop_path, notehead_prediction)
            truth = int(case.get("sourceAttackCount") or 0)
            baseline = int(notehead_prediction["columnCount"])
            challenger = int(projection["fusedAttackCount"])
            results.append(
                {
                    "caseId": case.get("caseId"),
                    "inputId": case.get("inputId"),
                    "scoreSystemId": case.get("scoreSystemId"),
                    "subset": case.get("subset"),
                    "sourceAttackCount": truth,
                    "baselineAttackCount": baseline,
                    "challengerAttackCount": challenger,
                    "baselineExact": baseline == truth,
                    "challengerExact": challenger == truth,
                    "baselineAbsoluteError": abs(baseline - truth),
                    "challengerAbsoluteError": abs(challenger - truth),
                    "cropRelativePath": crop_relative_path,
                    "cropSha256": crop_sha256,
                    "cropSource": crop_source,
                    "projection": projection,
                }
            )

        def metrics(items: Sequence[Mapping[str, Any]]) -> dict[str, int]:
            return {
                "caseCount": len(items),
                "baselineExactCount": sum(bool(item["baselineExact"]) for item in items),
                "baselineAbsoluteError": sum(
                    int(item["baselineAbsoluteError"]) for item in items
                ),
                "challengerExactCount": sum(
                    bool(item["challengerExact"]) for item in items
                ),
                "challengerAbsoluteError": sum(
                    int(item["challengerAbsoluteError"]) for item in items
                ),
                "fusionAppliedCount": sum(
                    bool((item.get("projection") or {}).get("fusionApplied"))
                    for item in items
                ),
            }

        aggregate = metrics(results)
        by_subset = {
            subset: metrics(
                [item for item in results if str(item.get("subset") or "") == subset]
            )
            for subset in ("development", "shadow")
        }
        gates = {
            "exactCountImproved": aggregate["challengerExactCount"]
            > aggregate["baselineExactCount"],
            "absoluteErrorImproved": aggregate["challengerAbsoluteError"]
            < aggregate["baselineAbsoluteError"],
        }
        gate_passed = all(gates.values())
        report_core = {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_regression_fit_only",
            "benchmarkManifestDigest": benchmark_digest,
            "contract": contract,
            "contractDigest": contract_digest,
            "aggregate": aggregate,
            "byFrozenSubset": by_subset,
            "gates": gates,
            "gatePassed": gate_passed,
            "parametersExploredAgainstOpenedRegression": True,
            "freshDiscoveryShadowAvailable": False,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "results": results,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = benchmark_root / f"projection-regression-{report_digest[:12]}.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": report["schemaVersion"],
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": report["evaluationClass"],
            "contractDigest": contract_digest,
            "aggregate": aggregate,
            "byFrozenSubset": by_subset,
            "gates": gates,
            "gatePassed": gate_passed,
            "freshDiscoveryShadowAvailable": False,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def evaluate_source_score_component_hybrid_challenger(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Evaluate component recovery after the fixed projection challenger."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError("The source-score benchmark is missing.")
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")
        projection_reports = []
        for report_path in benchmark_root.glob("projection-regression-*.json"):
            report = _read_json(report_path)
            report_digest = str(report.get("reportDigest") or "")
            if report_digest != _sha256_json(
                {key: value for key, value in report.items() if key != "reportDigest"}
            ):
                raise ExtractionWorkflowError(
                    "A source-score projection report digest changed."
                )
            if (
                report.get("benchmarkManifestDigest") == benchmark_digest
                and report.get("gatePassed") is True
                and report.get("promotionEligible") is False
            ):
                projection_reports.append((report_path, report))
        if len(projection_reports) != 1:
            raise ExtractionWorkflowError(
                "Component evaluation requires exactly one passed projection report."
            )
        projection_report_path, projection_report = projection_reports[0]
        case_by_system = {
            str(case.get("scoreSystemId") or ""): case
            for case in benchmark.get("cases") or []
        }
        contract = {
            "detectorVersion": SOURCE_SCORE_HYBRID_DETECTOR_VERSION,
            "projectionDetectorVersion": SOURCE_SCORE_PROJECTION_DETECTOR_VERSION,
            "projectionContract": dict(SOURCE_SCORE_PROJECTION_CONTRACT),
            "componentDetectorVersion": SOURCE_SCORE_COMPONENT_DETECTOR_VERSION,
            "componentContract": dict(SOURCE_SCORE_COMPONENT_CONTRACT),
            "selectionRule": "projection_change_then_component_change_then_baseline",
            "anchorDetectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "source": "printed_score_crop_and_audiveris_source_notehead_anchors",
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "pitchesEmitted": False,
        }
        contract_digest = _sha256_json(contract)
        results: list[dict[str, Any]] = []
        for prior in projection_report.get("results") or []:
            system_id = str(prior.get("scoreSystemId") or "")
            case = case_by_system.get(system_id)
            if case is None:
                raise ExtractionWorkflowError(
                    "A component regression case is absent from the benchmark."
                )
            crop_path = output_root / str(prior.get("cropRelativePath") or "")
            if (
                not crop_path.exists()
                or _sha256_bytes(crop_path.read_bytes())
                != str(prior.get("cropSha256") or "")
            ):
                raise ExtractionWorkflowError(
                    "A component regression score crop changed."
                )
            omr_path = output_root / str(case.get("omrRelativePath") or "")
            if (
                not omr_path.exists()
                or _sha256_bytes(omr_path.read_bytes())
                != str(case.get("omrSha256") or "")
            ):
                raise ExtractionWorkflowError(
                    "A component regression OMR artifact changed."
                )
            notehead_prediction = _audiveris_notehead_columns(omr_path)
            hybrid = _score_projection_component_hybrid(
                crop_path, notehead_prediction
            )
            truth = int(prior.get("sourceAttackCount") or 0)
            reference = int(prior.get("challengerAttackCount") or 0)
            challenger = int(hybrid["fusedAttackCount"])
            results.append(
                {
                    "caseId": prior.get("caseId"),
                    "inputId": prior.get("inputId"),
                    "scoreSystemId": system_id,
                    "subset": prior.get("subset"),
                    "sourceAttackCount": truth,
                    "referenceProjectionAttackCount": reference,
                    "challengerAttackCount": challenger,
                    "referenceExact": reference == truth,
                    "challengerExact": challenger == truth,
                    "referenceAbsoluteError": abs(reference - truth),
                    "challengerAbsoluteError": abs(challenger - truth),
                    "cropRelativePath": prior.get("cropRelativePath"),
                    "cropSha256": prior.get("cropSha256"),
                    "omrRelativePath": case.get("omrRelativePath"),
                    "omrSha256": case.get("omrSha256"),
                    "hybrid": hybrid,
                }
            )

        def metrics(items: Sequence[Mapping[str, Any]]) -> dict[str, int]:
            return {
                "caseCount": len(items),
                "referenceExactCount": sum(
                    bool(item["referenceExact"]) for item in items
                ),
                "referenceAbsoluteError": sum(
                    int(item["referenceAbsoluteError"]) for item in items
                ),
                "challengerExactCount": sum(
                    bool(item["challengerExact"]) for item in items
                ),
                "challengerAbsoluteError": sum(
                    int(item["challengerAbsoluteError"]) for item in items
                ),
                "componentSelectedCount": sum(
                    str((item.get("hybrid") or {}).get("selectedDetector") or "")
                    == SOURCE_SCORE_COMPONENT_DETECTOR_VERSION
                    for item in items
                ),
            }

        aggregate = metrics(results)
        by_subset = {
            subset: metrics(
                [item for item in results if str(item.get("subset") or "") == subset]
            )
            for subset in ("development", "shadow")
        }
        gates = {
            "developmentExactCountImproved": by_subset["development"][
                "challengerExactCount"
            ]
            > by_subset["development"]["referenceExactCount"],
            "developmentAbsoluteErrorImproved": by_subset["development"][
                "challengerAbsoluteError"
            ]
            < by_subset["development"]["referenceAbsoluteError"],
            "openedShadowExactCountImproved": by_subset["shadow"][
                "challengerExactCount"
            ]
            > by_subset["shadow"]["referenceExactCount"],
            "openedShadowAbsoluteErrorImproved": by_subset["shadow"][
                "challengerAbsoluteError"
            ]
            < by_subset["shadow"]["referenceAbsoluteError"],
        }
        gate_passed = all(gates.values())
        report_core = {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_regression_fit_only",
            "benchmarkManifestDigest": benchmark_digest,
            "referenceProjectionReportDigest": projection_report.get("reportDigest"),
            "referenceProjectionReportPath": str(
                projection_report_path.relative_to(output_root)
            ),
            "contract": contract,
            "contractDigest": contract_digest,
            "aggregate": aggregate,
            "byOpenedSubset": by_subset,
            "gates": gates,
            "gatePassed": gate_passed,
            "parametersExploredAgainstOpenedRegression": True,
            "freshDiscoveryShadowAvailable": False,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "results": results,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = (
            benchmark_root / f"component-hybrid-regression-{report_digest[:12]}.json"
        )
        _write_json(report_path, report)
        return {
            "schemaVersion": report["schemaVersion"],
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": report["evaluationClass"],
            "contractDigest": contract_digest,
            "aggregate": aggregate,
            "byOpenedSubset": by_subset,
            "gates": gates,
            "gatePassed": gate_passed,
            "freshDiscoveryShadowAvailable": False,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def freeze_source_score_projection_contract(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Freeze the regression-passed projection detector for future discovery only."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError("The source-score benchmark is missing.")
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        contract = {
            "detectorVersion": SOURCE_SCORE_PROJECTION_DETECTOR_VERSION,
            "parameters": dict(SOURCE_SCORE_PROJECTION_CONTRACT),
            "anchorDetectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "source": "printed_score_crop_and_audiveris_source_notehead_anchors",
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "pitchesEmitted": False,
        }
        contract_digest = _sha256_json(contract)
        matching_reports = []
        for report_path in benchmark_root.glob("projection-regression-*.json"):
            report = _read_json(report_path)
            if (
                report.get("benchmarkManifestDigest") == benchmark_digest
                and report.get("contractDigest") == contract_digest
                and report.get("gatePassed") is True
                and report.get("promotionEligible") is False
            ):
                matching_reports.append((report_path, report))
        if len(matching_reports) != 1:
            raise ExtractionWorkflowError(
                "Freeze exactly one regression-passed projection report before selection."
            )
        report_path, report = matching_reports[0]
        selection_core = {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "benchmarkManifestDigest": benchmark_digest,
            "contract": contract,
            "contractDigest": contract_digest,
            "fitReportDigest": report.get("reportDigest"),
            "fitReportPath": str(report_path.relative_to(output_root)),
            "selectionClass": "frozen_for_future_unseen_discovery_shadow_only",
            "promotionEligible": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "frozenAt": _utc_now(),
        }
        selection = {
            **selection_core,
            "selectionDigest": _sha256_json(selection_core),
        }
        selection_path = benchmark_root / "selected-projection-contract.json"
        if selection_path.exists():
            existing = _read_json(selection_path)
            comparable_existing = {
                key: value
                for key, value in existing.items()
                if key not in {"frozenAt", "selectionDigest"}
            }
            comparable_selection = {
                key: value
                for key, value in selection.items()
                if key not in {"frozenAt", "selectionDigest"}
            }
            if comparable_existing != comparable_selection:
                raise ExtractionWorkflowError(
                    "A different source-score projection contract is already frozen."
                )
            selection = existing
        else:
            _write_json(selection_path, selection)
        return {
            "schemaVersion": selection["schemaVersion"],
            "batchId": batch_id,
            "partition": "discovery",
            "contractDigest": contract_digest,
            "fitReportDigest": report.get("reportDigest"),
            "selectionDigest": selection.get("selectionDigest"),
            "selectionClass": selection["selectionClass"],
            "selectionPath": str(selection_path.relative_to(output_root)),
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def freeze_source_score_component_hybrid_contract(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Freeze the fitted hybrid contract for future unseen discovery only."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError("The source-score benchmark is missing.")
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")
        contract = {
            "detectorVersion": SOURCE_SCORE_HYBRID_DETECTOR_VERSION,
            "projectionDetectorVersion": SOURCE_SCORE_PROJECTION_DETECTOR_VERSION,
            "projectionContract": dict(SOURCE_SCORE_PROJECTION_CONTRACT),
            "componentDetectorVersion": SOURCE_SCORE_COMPONENT_DETECTOR_VERSION,
            "componentContract": dict(SOURCE_SCORE_COMPONENT_CONTRACT),
            "selectionRule": "projection_change_then_component_change_then_baseline",
            "anchorDetectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "source": "printed_score_crop_and_audiveris_source_notehead_anchors",
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "pitchesEmitted": False,
        }
        contract_digest = _sha256_json(contract)
        matching_reports: list[tuple[Path, dict[str, Any]]] = []
        for report_path in benchmark_root.glob("component-hybrid-regression-*.json"):
            report = _read_json(report_path)
            report_digest = str(report.get("reportDigest") or "")
            if report_digest != _sha256_json(
                {key: value for key, value in report.items() if key != "reportDigest"}
            ):
                raise ExtractionWorkflowError(
                    "A source-score component-hybrid report digest changed."
                )
            if (
                report.get("benchmarkManifestDigest") == benchmark_digest
                and report.get("contractDigest") == contract_digest
                and report.get("gatePassed") is True
                and report.get("promotionEligible") is False
                and report.get("evaluationClass")
                == "opened_discovery_regression_fit_only"
            ):
                matching_reports.append((report_path, report))
        if len(matching_reports) != 1:
            raise ExtractionWorkflowError(
                "Freeze exactly one regression-passed component-hybrid report."
            )
        report_path, report = matching_reports[0]
        selection_core = {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "benchmarkManifestDigest": benchmark_digest,
            "contract": contract,
            "contractDigest": contract_digest,
            "fitReportDigest": report.get("reportDigest"),
            "fitReportPath": str(report_path.relative_to(output_root)),
            "selectionClass": "frozen_for_future_unseen_discovery_shadow_only",
            "fitEvidenceClass": "opened_discovery_regression_fit_only",
            "freshDiscoveryShadowRequiredBeforePromotion": True,
            "promotionEligible": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "frozenAt": _utc_now(),
        }
        selection = {
            **selection_core,
            "selectionDigest": _sha256_json(selection_core),
        }
        selection_path = benchmark_root / "selected-component-hybrid-contract.json"
        if selection_path.exists():
            existing = _read_json(selection_path)
            comparable_existing = {
                key: value
                for key, value in existing.items()
                if key not in {"frozenAt", "selectionDigest"}
            }
            comparable_selection = {
                key: value
                for key, value in selection.items()
                if key not in {"frozenAt", "selectionDigest"}
            }
            if comparable_existing != comparable_selection:
                raise ExtractionWorkflowError(
                    "A different source-score component-hybrid contract is already frozen."
                )
            selection = existing
        else:
            _write_json(selection_path, selection)
        return {
            "schemaVersion": selection["schemaVersion"],
            "batchId": batch_id,
            "partition": "discovery",
            "contractDigest": contract_digest,
            "fitReportDigest": report.get("reportDigest"),
            "selectionDigest": selection.get("selectionDigest"),
            "selectionClass": selection["selectionClass"],
            "fitEvidenceClass": selection["fitEvidenceClass"],
            "selectionPath": str(selection_path.relative_to(output_root)),
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def capture_source_score_projection_shadow(
        self,
        batch_id: str,
        *,
        limit: int = 25,
    ) -> dict[str, Any]:
        """Freeze source-only predictions before any human-facing review exposure."""

        if not 1 <= limit <= 100:
            raise ExtractionWorkflowError(
                "Future discovery shadow capture limit must be between 1 and 100."
            )
        batch_dir, manifest, work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_root = output_root / "review"
        benchmark_root = (
            review_root / "automation" / "source-score-notehead-challenger"
        )
        projection_selection_path = benchmark_root / "selected-projection-contract.json"
        hybrid_selection_path = (
            benchmark_root / "selected-component-hybrid-contract.json"
        )
        benchmark_path = benchmark_root / "benchmark-manifest.json"
        if (
            not projection_selection_path.exists()
            or not hybrid_selection_path.exists()
            or not benchmark_path.exists()
        ):
            raise ExtractionWorkflowError(
                "Freeze the projection and component-hybrid contracts plus the opened benchmark before shadow capture."
            )
        projection_selection = _read_json(projection_selection_path)
        projection_selection_digest = str(
            projection_selection.get("selectionDigest") or ""
        )
        if projection_selection_digest != _sha256_json(
            {
                key: value
                for key, value in projection_selection.items()
                if key != "selectionDigest"
            }
        ):
            raise ExtractionWorkflowError("The frozen projection selection digest changed.")
        expected_projection_contract = {
            "detectorVersion": SOURCE_SCORE_PROJECTION_DETECTOR_VERSION,
            "parameters": dict(SOURCE_SCORE_PROJECTION_CONTRACT),
            "anchorDetectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "source": "printed_score_crop_and_audiveris_source_notehead_anchors",
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "pitchesEmitted": False,
        }
        projection_contract_digest = _sha256_json(expected_projection_contract)
        if (
            projection_selection.get("contract") != expected_projection_contract
            or str(projection_selection.get("contractDigest") or "")
            != projection_contract_digest
            or str(projection_selection.get("selectionClass") or "")
            != "frozen_for_future_unseen_discovery_shadow_only"
        ):
            raise ExtractionWorkflowError(
                "Future shadow capture requires the exact frozen projection contract."
            )
        hybrid_selection = _read_json(hybrid_selection_path)
        hybrid_selection_digest = str(hybrid_selection.get("selectionDigest") or "")
        if hybrid_selection_digest != _sha256_json(
            {
                key: value
                for key, value in hybrid_selection.items()
                if key != "selectionDigest"
            }
        ):
            raise ExtractionWorkflowError("The frozen component-hybrid selection digest changed.")
        expected_hybrid_contract = {
            "detectorVersion": SOURCE_SCORE_HYBRID_DETECTOR_VERSION,
            "projectionDetectorVersion": SOURCE_SCORE_PROJECTION_DETECTOR_VERSION,
            "projectionContract": dict(SOURCE_SCORE_PROJECTION_CONTRACT),
            "componentDetectorVersion": SOURCE_SCORE_COMPONENT_DETECTOR_VERSION,
            "componentContract": dict(SOURCE_SCORE_COMPONENT_CONTRACT),
            "selectionRule": "projection_change_then_component_change_then_baseline",
            "anchorDetectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "source": "printed_score_crop_and_audiveris_source_notehead_anchors",
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "pitchesEmitted": False,
        }
        hybrid_contract_digest = _sha256_json(expected_hybrid_contract)
        if (
            hybrid_selection.get("contract") != expected_hybrid_contract
            or str(hybrid_selection.get("contractDigest") or "")
            != hybrid_contract_digest
            or str(hybrid_selection.get("selectionClass") or "")
            != "frozen_for_future_unseen_discovery_shadow_only"
        ):
            raise ExtractionWorkflowError(
                "Future shadow capture requires the exact frozen component-hybrid contract."
            )
        benchmark = _read_json(benchmark_path)
        benchmark_system_ids = {
            str(case.get("scoreSystemId") or "")
            for case in benchmark.get("cases") or []
        } - {""}
        exposure = _discovery_human_exposure_inventory(review_root)
        exposed_input_ids = set(exposure["inputIds"])
        exposed_system_ids = set(exposure["scoreSystemIds"])
        shadow_root = benchmark_root / "future-discovery-shadow"
        candidate_dir = shadow_root / "candidates"
        candidate_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(shadow_root, 0o700)
        os.chmod(candidate_dir, 0o700)
        existing_by_system: dict[str, dict[str, Any]] = {}
        for candidate_path in sorted(candidate_dir.glob("*.json")):
            candidate = _read_json(candidate_path)
            candidate_digest = str(candidate.get("candidateDigest") or "")
            if candidate_digest != _sha256_json(
                {
                    key: value
                    for key, value in candidate.items()
                    if key != "candidateDigest"
                }
            ):
                raise ExtractionWorkflowError(
                    "A future discovery shadow candidate digest changed."
                )
            if (
                str(candidate.get("batchId") or "") != batch_id
                or str(candidate.get("projectionContractDigest") or "")
                != projection_contract_digest
                or str(candidate.get("projectionSelectionDigest") or "")
                != projection_selection_digest
                or str(candidate.get("hybridContractDigest") or "")
                != hybrid_contract_digest
                or str(candidate.get("hybridSelectionDigest") or "")
                != hybrid_selection_digest
            ):
                raise ExtractionWorkflowError(
                    "A future discovery shadow candidate has incompatible lineage."
                )
            system_id = str(candidate.get("scoreSystemId") or "")
            if system_id in existing_by_system:
                raise ExtractionWorkflowError(
                    "A score system has duplicate future discovery shadow candidates."
                )
            existing_by_system[system_id] = candidate

        allowed_input_ids = {str(item.get("inputId") or "") for item in work}
        skipped: Counter[str] = Counter()
        captured: list[dict[str, Any]] = []
        pages_dir = output_root / "pages"
        for page_path in sorted(pages_dir.glob("*.json")):
            page = _read_json(page_path)
            input_id = str(page.get("inputId") or "")
            if input_id not in allowed_input_ids:
                skipped["not_in_discovery_work_queue"] += 1
                continue
            page_systems = list(page.get("scoreSystems") or [])
            if not page_systems:
                skipped["page_has_no_score_system"] += 1
                continue
            if (
                input_id in exposed_input_ids
                or bool(page.get("humanApprovalComplete"))
                or str(page.get("reviewState") or "").startswith("human_")
            ):
                skipped["page_already_human_exposed"] += len(page_systems)
                continue
            for score_system in sorted(
                page_systems, key=lambda item: int(item.get("systemIndex") or 0)
            ):
                system_id = str(score_system.get("scoreSystemId") or "")
                if not system_id:
                    skipped["missing_score_system_id"] += 1
                    continue
                if system_id in existing_by_system:
                    skipped["already_captured"] += 1
                    continue
                if system_id in exposed_system_ids:
                    skipped["system_already_human_exposed"] += 1
                    continue
                if system_id in benchmark_system_ids:
                    skipped["opened_regression_benchmark_member"] += 1
                    continue
                if str(score_system.get("reviewState") or "").startswith("human_"):
                    skipped["system_already_human_approved"] += 1
                    continue
                if len(captured) >= limit:
                    skipped["capture_limit_reached"] += 1
                    continue
                crop = score_system.get("omrPreparedDerivative") or {}
                crop_relative_path = str(crop.get("relativePath") or "")
                crop_sha256 = str(crop.get("sha256") or "")
                crop_path = output_root / crop_relative_path
                if (
                    not crop_relative_path
                    or not crop_sha256
                    or not crop_path.exists()
                    or _sha256_bytes(crop_path.read_bytes()) != crop_sha256
                ):
                    skipped["missing_or_changed_score_crop"] += 1
                    continue
                music_xml = (
                    score_system.get("musicXml")
                    or score_system.get("recognizedMusicXml")
                    or {}
                )
                music_xml_relative_path = str(music_xml.get("relativePath") or "")
                music_xml_sha256 = str(music_xml.get("sha256") or "")
                music_xml_path = output_root / music_xml_relative_path
                omr_path = (
                    output_root / Path(music_xml_relative_path).with_suffix(".omr")
                    if music_xml_relative_path
                    else None
                )
                if (
                    not music_xml_relative_path
                    or not music_xml_sha256
                    or not music_xml_path.exists()
                    or _sha256_bytes(music_xml_path.read_bytes()) != music_xml_sha256
                    or omr_path is None
                    or not omr_path.exists()
                ):
                    skipped["missing_or_changed_omr_lineage"] += 1
                    continue
                try:
                    notehead_prediction = _audiveris_notehead_columns(omr_path)
                    hybrid = _score_projection_component_hybrid(
                        crop_path, notehead_prediction
                    )
                except ExtractionWorkflowError:
                    skipped["source_only_prediction_failed"] += 1
                    continue
                page_digest = _sha256_json(page)
                omr_sha256 = _sha256_bytes(omr_path.read_bytes())
                candidate_id = _stable_id(
                    "source-score-hybrid-future-shadow",
                    batch_id,
                    input_id,
                    system_id,
                    page_digest,
                    crop_sha256,
                    omr_sha256,
                    projection_contract_digest,
                    projection_selection_digest,
                    hybrid_contract_digest,
                    hybrid_selection_digest,
                )
                candidate_core = {
                    "schemaVersion": SOURCE_SCORE_PROJECTION_SHADOW_SCHEMA_VERSION,
                    "candidateId": candidate_id,
                    "batchId": batch_id,
                    "partition": "discovery",
                    "inputId": input_id,
                    "scoreSystemId": system_id,
                    "systemIndex": int(score_system.get("systemIndex") or 0),
                    "pageRecordPath": str(page_path.relative_to(output_root)),
                    "pageRecordDigestAtCapture": page_digest,
                    "assetSha256": str(page.get("assetSha256") or ""),
                    "scoreCropRelativePath": crop_relative_path,
                    "scoreCropSha256": crop_sha256,
                    "musicXmlRelativePath": music_xml_relative_path,
                    "musicXmlSha256": music_xml_sha256,
                    "omrRelativePath": str(omr_path.relative_to(output_root)),
                    "omrSha256": omr_sha256,
                    "sourceCopedentId": manifest.get("sourceCopedentId"),
                    "sourceCopedentRevision": manifest.get("sourceCopedentRevision"),
                    "projectionContractDigest": projection_contract_digest,
                    "projectionSelectionDigest": projection_selection_digest,
                    "hybridContractDigest": hybrid_contract_digest,
                    "hybridSelectionDigest": hybrid_selection_digest,
                    "baselineAttackCount": int(notehead_prediction["columnCount"]),
                    "projectionAttackCount": int(hybrid["projectionAttackCount"]),
                    "componentAttackCount": int(hybrid["componentAttackCount"]),
                    "challengerAttackCount": int(hybrid["fusedAttackCount"]),
                    "selectedDetector": str(hybrid["selectedDetector"]),
                    "projection": dict(hybrid["projection"]),
                    "component": dict(hybrid["component"]),
                    "hybrid": hybrid,
                    "humanExposureInventoryDigestAtCapture": exposure[
                        "inventoryDigest"
                    ],
                    "humanExposureArtifactCountAtCapture": exposure[
                        "artifactCount"
                    ],
                    "humanExposureAtCapture": False,
                    "reviewTruthAvailableAtCapture": False,
                    "reviewPacketCreated": False,
                    "currentPageRecordModified": False,
                    "validationAccessed": False,
                    "sealedTestAccessed": False,
                    "capturedAt": _utc_now(),
                }
                candidate = {
                    **candidate_core,
                    "candidateDigest": _sha256_json(candidate_core),
                }
                candidate_path = candidate_dir / f"{candidate_id}.json"
                if candidate_path.exists():
                    if _read_json(candidate_path) != candidate:
                        raise ExtractionWorkflowError(
                            "A future discovery shadow candidate cannot be overwritten."
                        )
                else:
                    _write_json(candidate_path, candidate)
                captured.append(candidate)

        return {
            "schemaVersion": SOURCE_SCORE_PROJECTION_SHADOW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "projectionSelectionDigest": projection_selection_digest,
            "projectionContractDigest": projection_contract_digest,
            "hybridSelectionDigest": hybrid_selection_digest,
            "hybridContractDigest": hybrid_contract_digest,
            "existingCandidateCount": len(existing_by_system),
            "capturedCandidateCount": len(captured),
            "capturedCandidateIds": [item["candidateId"] for item in captured],
            "humanExposureArtifactCount": exposure["artifactCount"],
            "humanExposureInventoryDigest": exposure["inventoryDigest"],
            "skippedReasonCounts": dict(sorted(skipped.items())),
            "captureOrdering": "before_human_facing_review_artifacts",
            "reviewPacketCreated": False,
            "currentPageRecordsModified": False,
            "trainingStarted": False,
            "promotionEligible": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def score_source_score_projection_shadow(
        self,
        batch_id: str,
        *,
        minimum_cases: int = 5,
    ) -> dict[str, Any]:
        """Score pre-review predictions after independent discovery truth arrives."""

        if not 1 <= minimum_cases <= 100:
            raise ExtractionWorkflowError(
                "Future discovery shadow minimum cases must be between 1 and 100."
            )
        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        projection_selection_path = benchmark_root / "selected-projection-contract.json"
        hybrid_selection_path = (
            benchmark_root / "selected-component-hybrid-contract.json"
        )
        candidate_dir = benchmark_root / "future-discovery-shadow" / "candidates"
        if not projection_selection_path.exists() or not hybrid_selection_path.exists():
            raise ExtractionWorkflowError(
                "The frozen projection or component-hybrid selection is missing."
            )
        projection_selection = _read_json(projection_selection_path)
        projection_selection_digest = str(
            projection_selection.get("selectionDigest") or ""
        )
        if projection_selection_digest != _sha256_json(
            {
                key: value
                for key, value in projection_selection.items()
                if key != "selectionDigest"
            }
        ):
            raise ExtractionWorkflowError("The frozen projection selection digest changed.")
        hybrid_selection = _read_json(hybrid_selection_path)
        hybrid_selection_digest = str(hybrid_selection.get("selectionDigest") or "")
        if hybrid_selection_digest != _sha256_json(
            {
                key: value
                for key, value in hybrid_selection.items()
                if key != "selectionDigest"
            }
        ):
            raise ExtractionWorkflowError("The frozen component-hybrid selection digest changed.")
        projection_contract_digest = str(
            projection_selection.get("contractDigest") or ""
        )
        hybrid_contract_digest = str(hybrid_selection.get("contractDigest") or "")
        approved_index_path = (
            output_root
            / "review"
            / "combined-score-tab-audit"
            / "application"
            / "approved-line-index.jsonl"
        )
        latest_truth_by_system: dict[str, dict[str, Any]] = {}
        if approved_index_path.exists():
            for row in _read_jsonl(approved_index_path):
                system_id = str(row.get("scoreSystemId") or "")
                if system_id:
                    latest_truth_by_system[system_id] = row
        candidates = []
        for candidate_path in sorted(candidate_dir.glob("*.json")) if candidate_dir.exists() else []:
            candidate = _read_json(candidate_path)
            candidate_digest = str(candidate.get("candidateDigest") or "")
            if candidate_digest != _sha256_json(
                {
                    key: value
                    for key, value in candidate.items()
                    if key != "candidateDigest"
                }
            ):
                raise ExtractionWorkflowError(
                    "A future discovery shadow candidate digest changed."
                )
            if (
                str(candidate.get("batchId") or "") != batch_id
                or str(candidate.get("partition") or "") != "discovery"
                or str(candidate.get("projectionSelectionDigest") or "")
                != projection_selection_digest
                or str(candidate.get("projectionContractDigest") or "")
                != projection_contract_digest
                or str(candidate.get("hybridSelectionDigest") or "")
                != hybrid_selection_digest
                or str(candidate.get("hybridContractDigest") or "")
                != hybrid_contract_digest
                or candidate.get("humanExposureAtCapture") is not False
                or candidate.get("reviewTruthAvailableAtCapture") is not False
            ):
                raise ExtractionWorkflowError(
                    "A future discovery shadow candidate lacks clean frozen lineage."
                )
            for relative_key, digest_key in (
                ("scoreCropRelativePath", "scoreCropSha256"),
                ("musicXmlRelativePath", "musicXmlSha256"),
                ("omrRelativePath", "omrSha256"),
            ):
                artifact_path = output_root / str(candidate.get(relative_key) or "")
                if (
                    not artifact_path.exists()
                    or _sha256_bytes(artifact_path.read_bytes())
                    != str(candidate.get(digest_key) or "")
                ):
                    raise ExtractionWorkflowError(
                        "A future discovery shadow source artifact changed."
                    )
            candidates.append(candidate)

        pending_count = 0
        results: list[dict[str, Any]] = []
        for candidate in candidates:
            truth = latest_truth_by_system.get(str(candidate["scoreSystemId"]))
            if (
                truth is None
                or str(truth.get("status") or "") != "human_approved_pitch_only"
                or int(truth.get("scoreAttackCount") or 0) < 1
            ):
                pending_count += 1
                continue
            source_attack_count = int(truth["scoreAttackCount"])
            baseline = int(candidate["baselineAttackCount"])
            challenger = int(candidate["challengerAttackCount"])
            results.append(
                {
                    "candidateId": candidate["candidateId"],
                    "candidateDigest": candidate["candidateDigest"],
                    "inputId": candidate["inputId"],
                    "scoreSystemId": candidate["scoreSystemId"],
                    "reviewDecisionId": str(truth.get("decisionId") or ""),
                    "reviewedRecordDigest": str(
                        truth.get("reviewedRecordDigest") or ""
                    ),
                    "sourceAttackCount": source_attack_count,
                    "baselineAttackCount": baseline,
                    "challengerAttackCount": challenger,
                    "baselineExact": baseline == source_attack_count,
                    "challengerExact": challenger == source_attack_count,
                    "baselineAbsoluteError": abs(baseline - source_attack_count),
                    "challengerAbsoluteError": abs(
                        challenger - source_attack_count
                    ),
                    "fusionApplied": bool(
                        (candidate.get("hybrid") or {}).get("fusionApplied")
                    ),
                }
            )
        metrics = _source_score_projection_shadow_metrics(results)
        gates = {
            "minimumFreshCaseCountMet": metrics["caseCount"] >= minimum_cases,
            "minimumSourcePageCountMet": metrics["sourcePageCount"] >= 3,
            "exactCountImproved": metrics["challengerExactCount"]
            > metrics["baselineExactCount"],
            "absoluteErrorImproved": metrics["challengerAbsoluteError"]
            < metrics["baselineAbsoluteError"],
        }
        gate_passed = all(gates.values())
        report_path: Path | None = None
        report_digest: str | None = None
        if results:
            report_core = {
                "schemaVersion": SOURCE_SCORE_PROJECTION_SHADOW_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": "discovery",
                "evaluationClass": "fresh_unseen_discovery_shadow",
                "projectionSelectionDigest": projection_selection_digest,
                "projectionContractDigest": projection_contract_digest,
                "hybridSelectionDigest": hybrid_selection_digest,
                "hybridContractDigest": hybrid_contract_digest,
                "minimumCases": minimum_cases,
                "candidateCount": len(candidates),
                "pendingTruthCount": pending_count,
                "metrics": metrics,
                "gates": gates,
                "gatePassed": gate_passed,
                "promotionEligible": False,
                "results": results,
                "reviewPacketCreated": False,
                "currentPageRecordsModified": False,
                "trainingStarted": False,
                "validationAccessed": False,
                "sealedTestAccessed": False,
            }
            report_digest = _sha256_json(report_core)
            report = {**report_core, "reportDigest": report_digest}
            report_path = (
                benchmark_root
                / "future-discovery-shadow"
                / f"score-report-{report_digest[:12]}.json"
            )
            if report_path.exists():
                if _read_json(report_path) != report:
                    raise ExtractionWorkflowError(
                        "A future discovery shadow score report cannot be overwritten."
                    )
            else:
                _write_json(report_path, report)
        return {
            "schemaVersion": SOURCE_SCORE_PROJECTION_SHADOW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "fresh_unseen_discovery_shadow",
            "projectionSelectionDigest": projection_selection_digest,
            "projectionContractDigest": projection_contract_digest,
            "hybridSelectionDigest": hybrid_selection_digest,
            "hybridContractDigest": hybrid_contract_digest,
            "candidateCount": len(candidates),
            "scoredCaseCount": len(results),
            "pendingTruthCount": pending_count,
            "minimumCases": minimum_cases,
            "metrics": metrics,
            "gates": gates,
            "gatePassed": gate_passed,
            "promotionEligible": False,
            "reportDigest": report_digest,
            "reportPath": (
                str(report_path.relative_to(output_root)) if report_path else None
            ),
            "reviewPacketCreated": False,
            "currentPageRecordsModified": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def build_discovery_score_sequence_dataset(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Freeze reviewed discovery lines as private sequence-model labels.

        The dataset contains digest-pinned conventional-score crops and ordered
        human-approved pitch groups.  It deliberately excludes tablature,
        timing, horizontal boxes, validation, and sealed-test material.
        """

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root / "review" / "automation" / "source-score-notehead-challenger"
        )
        benchmark_path = benchmark_root / "benchmark-manifest.json"
        if not benchmark_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the discovery score benchmark before sequence labeling."
            )
        benchmark = _read_json(benchmark_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The score benchmark digest changed.")

        cases: list[dict[str, Any]] = []
        for raw_case in benchmark.get("cases") or []:
            case = dict(raw_case)
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            if not record_path.exists():
                raise ExtractionWorkflowError(
                    "A reviewed score sequence record is missing."
                )
            record = _read_json(record_path)
            reviewed_record_digest = str(case.get("reviewedRecordDigest") or "")
            if _sha256_json(record) != reviewed_record_digest:
                raise ExtractionWorkflowError(
                    "A reviewed score sequence record changed."
                )
            rights = record.get("rightsAndAccess") or {}
            if (
                str(rights.get("reviewStatus") or "") != "approved"
                or not bool((rights.get("allowedUses") or {}).get("modelTraining"))
            ):
                raise ExtractionWorkflowError(
                    "Score sequence labels require approved model-training use."
                )
            score_system_id = str(case.get("scoreSystemId") or "")
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "") == score_system_id
                ),
                None,
            )
            if score_system is None:
                raise ExtractionWorkflowError(
                    "A reviewed score sequence system is missing."
                )

            image_path: Path | None = None
            image_metadata: dict[str, Any] | None = None
            for candidate in (
                score_system.get("omrPreparedDerivative") or {},
                score_system.get("scoreRepairSourceCrop") or {},
            ):
                relative_path = str(candidate.get("relativePath") or "")
                expected_sha = str(candidate.get("sha256") or "")
                path = output_root / relative_path
                if (
                    relative_path
                    and expected_sha
                    and path.exists()
                    and _sha256_bytes(path.read_bytes()) == expected_sha
                ):
                    image_path = path
                    image_metadata = copy.deepcopy(dict(candidate))
                    break
            if image_path is None or image_metadata is None:
                raise ExtractionWorkflowError(
                    "A digest-pinned conventional-score crop is unavailable."
                )
            with Image.open(image_path) as opened:
                width, height = opened.size

            target = _reviewed_score_sequence_target(score_system)
            target_digest = _sha256_json(target)
            cases.append(
                {
                    "caseId": str(case.get("caseId") or ""),
                    "inputId": str(case.get("inputId") or ""),
                    "scoreSystemId": score_system_id,
                    "contentUnitId": str(record.get("contentUnitId") or ""),
                    "subset": str(case.get("subset") or ""),
                    "reviewDecisionId": str(case.get("reviewDecisionId") or ""),
                    "reviewedRecordPath": str(case.get("reviewedRecordPath") or ""),
                    "reviewedRecordDigest": reviewed_record_digest,
                    "image": {
                        "relativePath": str(image_path.relative_to(output_root)),
                        "sha256": _sha256_bytes(image_path.read_bytes()),
                        "width": width,
                        "height": height,
                        "role": "conventional_score_line",
                        "rawImageCopied": False,
                    },
                    "target": target,
                    "targetDigest": target_digest,
                    "targetContract": {
                        "order": "human_approved",
                        "chordMembership": "human_approved",
                        "pitch": "human_approved",
                        "durationIncluded": False,
                        "rhythmicPositionIncluded": False,
                        "tieIncluded": False,
                        "horizontalLocalizationIncluded": False,
                    },
                    "rightsAuthorizationRecordDigest": str(
                        rights.get("authorizationRecordDigest") or ""
                    ),
                    "modelTrainingAllowed": True,
                }
            )

        def metrics(values: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
            return {
                "caseCount": len(values),
                "sourcePageCount": len(
                    {str(value.get("inputId") or "") for value in values}
                ),
                "contentUnitCount": len(
                    {str(value.get("contentUnitId") or "") for value in values}
                ),
                "attackGroupCount": sum(
                    len(value.get("target") or []) for value in values
                ),
                "noteheadLabelCount": sum(
                    len(group.get("notes") or [])
                    for value in values
                    for group in value.get("target") or []
                ),
            }

        by_subset = {
            subset: metrics(
                [value for value in cases if value.get("subset") == subset]
            )
            for subset in ("development", "shadow")
        }
        manifest_core = {
            "schemaVersion": DISCOVERY_SCORE_SEQUENCE_DATASET_SCHEMA_VERSION,
            "datasetVersion": DISCOVERY_SCORE_SEQUENCE_DATASET_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_supervised_sequence_training",
            "benchmarkManifestDigest": benchmark_digest,
            "splitContract": "page_grouped_inherited_from_frozen_benchmark",
            "aggregate": metrics(cases),
            "bySubset": by_subset,
            "cases": cases,
            "sourceTextIncluded": False,
            "tablatureIncluded": False,
            "rawImagesCopied": False,
            "reviewPacketCreated": False,
            "currentPageRecordsModified": False,
            "trainingStarted": False,
            "promotionEligible": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        manifest_digest = _sha256_json(manifest_core)
        manifest = {**manifest_core, "manifestDigest": manifest_digest}
        dataset_root = (
            output_root
            / "review"
            / "automation"
            / DISCOVERY_SCORE_SEQUENCE_DATASET_VERSION
        )
        dataset_root.mkdir(parents=True, exist_ok=True)
        os.chmod(dataset_root, 0o700)
        manifest_path = dataset_root / f"manifest-{manifest_digest[:12]}.json"
        if manifest_path.exists():
            if _read_json(manifest_path) != manifest:
                raise ExtractionWorkflowError(
                    "An immutable score sequence manifest cannot be overwritten."
                )
        else:
            _write_json(manifest_path, manifest)
        return {
            "schemaVersion": manifest["schemaVersion"],
            "datasetVersion": manifest["datasetVersion"],
            "batchId": batch_id,
            "partition": "discovery",
            "aggregate": manifest["aggregate"],
            "bySubset": manifest["bySubset"],
            "manifestDigest": manifest_digest,
            "manifestPath": str(manifest_path.relative_to(output_root)),
            "reviewPacketCreated": False,
            "currentPageRecordsModified": False,
            "trainingStarted": False,
            "promotionEligible": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def train_discovery_score_sequence_challenger(
        self,
        batch_id: str,
        *,
        dependency_root: Path,
        seed: int = 1729,
        maximum_epochs: int = 80,
    ) -> dict[str, Any]:
        """Train a private full-line CTC reader and score opened shadow once."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        from pocketsteel.amazing_tablature_score_sequence import (
            ScoreSequenceTrainingError,
            train_discovery_score_sequence_challenger,
        )

        try:
            return train_discovery_score_sequence_challenger(
                output_root=output_root,
                dependency_root=dependency_root,
                seed=seed,
                maximum_epochs=maximum_epochs,
            )
        except ScoreSequenceTrainingError as exc:
            raise ExtractionWorkflowError(str(exc)) from exc

    def evaluate_discovery_source_score_semantic_repair(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Replay the source-only semantic repair on opened discovery truth.

        Prediction is completed before reviewed counts or pitches are joined.
        This command creates no review packet, training evidence, or promotion
        claim and cannot open validation or sealed-test partitions.
        """

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root / "review" / "automation" / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before semantic repair."
            )
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")

        results: list[dict[str, Any]] = []
        for raw_case in benchmark.get("cases") or []:
            case = dict(raw_case)
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            if not record_path.exists():
                raise ExtractionWorkflowError(
                    "A semantic-repair discovery record is missing."
                )
            record = _read_json(record_path)
            if _sha256_json(record) != str(case.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError(
                    "A semantic-repair discovery record changed."
                )
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "")
                    == str(case.get("scoreSystemId") or "")
                ),
                None,
            )
            if score_system is None:
                raise ExtractionWorkflowError(
                    "A semantic-repair score system is missing."
                )
            crop_path: Path | None = None
            crop_sha256 = ""
            for crop in (
                score_system.get("omrPreparedDerivative") or {},
                score_system.get("scoreRepairSourceCrop") or {},
            ):
                relative_path = str(crop.get("relativePath") or "")
                expected_sha = str(crop.get("sha256") or "")
                candidate_path = output_root / relative_path
                if (
                    relative_path
                    and candidate_path.exists()
                    and _sha256_bytes(candidate_path.read_bytes()) == expected_sha
                ):
                    crop_path = candidate_path
                    crop_sha256 = expected_sha
                    break
            if crop_path is None:
                raise ExtractionWorkflowError(
                    "A digest-pinned score crop is unavailable for semantic repair."
                )
            omr_path = output_root / str(case.get("omrRelativePath") or "")
            if (
                not omr_path.exists()
                or _sha256_bytes(omr_path.read_bytes())
                != str(case.get("omrSha256") or "")
            ):
                raise ExtractionWorkflowError(
                    "A semantic-repair OMR artifact changed."
                )

            # Source-only inference ends here.  Reviewed truth is joined below.
            prediction = _source_score_semantic_repair(
                image_path=crop_path,
                omr_path=omr_path,
                system_id=str(case.get("scoreSystemId") or ""),
            )
            truth_count = int(case.get("sourceAttackCount") or 0)
            truth_groups = _score_event_groups_by_printed_position(
                score_system.get("scoreEvents") or []
            )
            predicted_groups = _score_event_groups_by_printed_position(
                prediction.get("scoreEvents") or []
            )
            natural_groups = _score_event_groups_by_printed_position(
                prediction.get("naturalScoreEvents") or []
            )

            def exact_pitch_groups(
                predicted: Sequence[Sequence[Mapping[str, Any]]],
            ) -> int:
                if len(predicted) != len(truth_groups):
                    return 0
                return sum(
                    {
                        int(event["pitchValue"])
                        for event in predicted_group
                        if event.get("pitchValue") is not None
                    }
                    == {
                        int(event["pitchValue"])
                        for event in truth_group
                        if event.get("pitchValue") is not None
                    }
                    for predicted_group, truth_group in zip(
                        predicted, truth_groups, strict=True
                    )
                )

            semantic_count = int(prediction.get("semanticAttackCount") or 0)
            baseline_count = int(prediction.get("baselineAttackCount") or 0)
            hybrid_count = int(
                prediction.get("hybridAttackCountBeforeTieRepair") or 0
            )
            natural_exact = exact_pitch_groups(natural_groups)
            adjusted_exact = exact_pitch_groups(predicted_groups)
            results.append(
                {
                    "caseId": case.get("caseId"),
                    "inputId": case.get("inputId"),
                    "scoreSystemId": case.get("scoreSystemId"),
                    "subset": case.get("subset"),
                    "cropSha256": crop_sha256,
                    "sourceAttackCount": truth_count,
                    "baselineAttackCount": baseline_count,
                    "hybridAttackCount": hybrid_count,
                    "semanticAttackCount": semantic_count,
                    "baselineExact": baseline_count == truth_count,
                    "hybridExact": hybrid_count == truth_count,
                    "semanticExact": semantic_count == truth_count,
                    "baselineAbsoluteError": abs(baseline_count - truth_count),
                    "hybridAbsoluteError": abs(hybrid_count - truth_count),
                    "semanticAbsoluteError": abs(semantic_count - truth_count),
                    "countPublishable": bool(prediction.get("countPublishable")),
                    "pitchesPublishable": bool(prediction.get("pitchesPublishable")),
                    "tieRepairApplied": bool(prediction.get("tieRepairApplied")),
                    "keySignatureCaptured": prediction.get("keySignature") is not None,
                    "truthEventCount": len(truth_groups),
                    "naturalPitchExactEventCount": natural_exact,
                    "adjustedPitchExactEventCount": adjusted_exact,
                    "adjustedPitchExactLine": bool(
                        truth_groups and adjusted_exact == len(truth_groups)
                    ),
                    "prediction": prediction,
                }
            )

        def metrics(items: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
            publishable = [item for item in items if item.get("countPublishable")]
            pitch_comparable = [
                item
                for item in items
                if int(item.get("truthEventCount") or 0)
                == len(
                    _score_event_groups_by_printed_position(
                        (item.get("prediction") or {}).get("scoreEvents") or []
                    )
                )
            ]
            return {
                "caseCount": len(items),
                "baselineExactCount": sum(bool(item["baselineExact"]) for item in items),
                "hybridExactCount": sum(bool(item["hybridExact"]) for item in items),
                "semanticExactCount": sum(bool(item["semanticExact"]) for item in items),
                "baselineAbsoluteError": sum(
                    int(item["baselineAbsoluteError"]) for item in items
                ),
                "hybridAbsoluteError": sum(
                    int(item["hybridAbsoluteError"]) for item in items
                ),
                "semanticAbsoluteError": sum(
                    int(item["semanticAbsoluteError"]) for item in items
                ),
                "publishableCount": len(publishable),
                "publishableExactCount": sum(
                    bool(item["semanticExact"]) for item in publishable
                ),
                "publishableCountAccuracy": round(
                    sum(bool(item["semanticExact"]) for item in publishable)
                    / len(publishable),
                    6,
                )
                if publishable
                else None,
                "withheldCount": len(items) - len(publishable),
                "tieRepairCount": sum(bool(item["tieRepairApplied"]) for item in items),
                "keySignatureCaptureCount": sum(
                    bool(item["keySignatureCaptured"]) for item in items
                ),
                "pitchComparableLineCount": len(pitch_comparable),
                "naturalPitchExactEventCount": sum(
                    int(item["naturalPitchExactEventCount"])
                    for item in pitch_comparable
                ),
                "adjustedPitchExactEventCount": sum(
                    int(item["adjustedPitchExactEventCount"])
                    for item in pitch_comparable
                ),
                "pitchComparableEventCount": sum(
                    int(item["truthEventCount"]) for item in pitch_comparable
                ),
                "adjustedPitchExactLineCount": sum(
                    bool(item["adjustedPitchExactLine"])
                    for item in pitch_comparable
                ),
            }

        aggregate = metrics(results)
        by_subset = {
            subset: metrics(
                [item for item in results if str(item.get("subset") or "") == subset]
            )
            for subset in ("development", "shadow")
        }
        report_core = {
            "schemaVersion": SOURCE_SCORE_SEMANTIC_REPAIR_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_regression_fit_only",
            "benchmarkManifestDigest": benchmark_digest,
            "repairVersion": SOURCE_SCORE_SEMANTIC_REPAIR_VERSION,
            "aggregate": aggregate,
            "byOpenedSubset": by_subset,
            "results": results,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = benchmark_root / f"semantic-repair-{report_digest[:12]}.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": report["schemaVersion"],
            "batchId": batch_id,
            "partition": "discovery",
            "repairVersion": SOURCE_SCORE_SEMANTIC_REPAIR_VERSION,
            "aggregate": aggregate,
            "byOpenedSubset": by_subset,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def evaluate_discovery_machine_score_tab_timeline(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Test the unified machine timeline on already-opened discovery cases.

        Source-score inference and archived pre-correction machine tablature are
        frozen before reviewed score/tab truth is read for scoring.  The command
        creates neither review packets nor training evidence and cannot access
        validation or sealed-test partitions.
        """

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_root = output_root / "review"
        benchmark_root = (
            review_root / "automation" / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before timeline evaluation."
            )
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")

        def tab_signature(event: Mapping[str, Any]) -> dict[str, Any]:
            return {
                "executionType": str(event.get("executionType") or "attack"),
                "controlChanges": sorted(str(value) for value in event.get("controlChanges") or []),
                "actions": [
                    {
                        "string": int(action.get("string") or 0),
                        "fret": int(action.get("fret") or 0),
                        "controls": sorted(
                            str(value).upper() for value in action.get("controls") or []
                        ),
                        "attack": bool(action.get("attack", True)),
                        "sustain": bool(action.get("sustain")),
                    }
                    for action in sorted(
                        event.get("steelActions") or [],
                        key=lambda value: int(value.get("string") or 0),
                    )
                ],
            }

        results: list[dict[str, Any]] = []
        blocker_counts: Counter[str] = Counter()
        for raw_case in benchmark.get("cases") or []:
            case = dict(raw_case)
            input_id = str(case.get("inputId") or "")
            score_system_id = str(case.get("scoreSystemId") or "")
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            if not record_path.exists():
                raise ExtractionWorkflowError(
                    "A timeline discovery record is missing."
                )
            reviewed_record = _read_json(record_path)
            if _sha256_json(reviewed_record) != str(
                case.get("reviewedRecordDigest") or ""
            ):
                raise ExtractionWorkflowError(
                    "A timeline discovery record changed."
                )
            reviewed_score_system = next(
                (
                    system
                    for system in reviewed_record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "") == score_system_id
                ),
                None,
            )
            if reviewed_score_system is None:
                raise ExtractionWorkflowError(
                    "A timeline discovery score system is missing."
                )

            crop_path: Path | None = None
            crop_sha256 = ""
            for crop in (
                reviewed_score_system.get("omrPreparedDerivative") or {},
                reviewed_score_system.get("scoreRepairSourceCrop") or {},
            ):
                relative_path = str(crop.get("relativePath") or "")
                expected_sha = str(crop.get("sha256") or "")
                candidate_path = output_root / relative_path
                if (
                    relative_path
                    and candidate_path.exists()
                    and _sha256_bytes(candidate_path.read_bytes()) == expected_sha
                ):
                    crop_path = candidate_path
                    crop_sha256 = expected_sha
                    break
            if crop_path is None:
                raise ExtractionWorkflowError(
                    "A digest-pinned score crop is unavailable for timeline evaluation."
                )
            omr_path = output_root / str(case.get("omrRelativePath") or "")
            if (
                not omr_path.exists()
                or _sha256_bytes(omr_path.read_bytes())
                != str(case.get("omrSha256") or "")
            ):
                raise ExtractionWorkflowError(
                    "A timeline OMR artifact changed."
                )

            prior_digest = str(
                (reviewed_record.get("machineCorrection") or {}).get(
                    "priorMachineRecordDigest"
                )
                or ""
            )
            machine_record: dict[str, Any] | None = None
            if prior_digest:
                revision_dir = review_root / "machine-record-revisions" / input_id
                for candidate_path in sorted(revision_dir.glob("*.json")):
                    candidate = _read_json(candidate_path)
                    if _sha256_json(candidate) == prior_digest:
                        machine_record = candidate
                        break

            page_key_signature: dict[str, Any] | None = None
            page_key_crop_sha256: str | None = None
            page_key_omr_sha256: str | None = None
            if machine_record is not None:
                machine_score_systems = sorted(
                    machine_record.get("scoreSystems") or [],
                    key=lambda value: int(value.get("systemIndex") or 0),
                )
                first_score_system = (
                    machine_score_systems[0] if machine_score_systems else None
                )
                if first_score_system is not None:
                    first_index = int(first_score_system.get("systemIndex") or 0)
                    first_crop_path = (
                        output_root
                        / "score-crops"
                        / input_id
                        / f"score-system-{first_index:02d}.png"
                    )
                    first_omr_path = (
                        output_root
                        / "omr"
                        / input_id
                        / f"system-{first_index:02d}"
                        / f"score-system-{first_index:02d}.omr"
                    )
                    expected_crop_sha = str(
                        first_score_system.get("cropSha256") or ""
                    )
                    if (
                        first_index == 1
                        and first_crop_path.exists()
                        and expected_crop_sha
                        and _sha256_bytes(first_crop_path.read_bytes())
                        == expected_crop_sha
                        and first_omr_path.exists()
                    ):
                        page_key_crop_sha256 = expected_crop_sha
                        page_key_omr_sha256 = _sha256_bytes(
                            first_omr_path.read_bytes()
                        )
                        try:
                            page_key_signature = _source_first_system_key_signature(
                                first_omr_path,
                                system_id=str(
                                    first_score_system.get("scoreSystemId")
                                    or f"{input_id}-first-system"
                                ),
                            )
                        except ExtractionWorkflowError:
                            page_key_signature = None

            # Machine inference ends before any reviewed score/tab facts below
            # are grouped or compared.  Only immutable IDs, source derivatives,
            # and the archived pre-correction machine snapshot are inputs.
            prediction = _source_score_semantic_repair(
                image_path=crop_path,
                omr_path=omr_path,
                system_id=score_system_id,
            )
            page_key_applied = bool(
                prediction.get("keySignature") is None
                and page_key_signature is not None
            )
            if page_key_applied:
                prediction = copy.deepcopy(prediction)
                prediction["keySignature"] = copy.deepcopy(page_key_signature)
                prediction["scoreEvents"] = _apply_key_signature_to_score_events(
                    prediction.get("naturalScoreEvents") or [],
                    int(page_key_signature["fifths"]),
                )
                prediction["pageKeySignatureApplied"] = True
            inference_blockers: list[dict[str, Any]] = []
            machine_tab_events: list[dict[str, Any]] = []
            if machine_record is None:
                inference_blockers.append({"kind": "archived_machine_snapshot_missing"})
            else:
                machine_score_system = next(
                    (
                        system
                        for system in machine_record.get("scoreSystems") or []
                        if str(system.get("scoreSystemId") or "") == score_system_id
                    ),
                    None,
                )
                machine_tab_system = None
                if machine_score_system is not None:
                    paired_tab_id = str(
                        machine_score_system.get("pairedTabSystemId") or ""
                    )
                    machine_tab_system = next(
                        (
                            system
                            for system in machine_record.get("tabSystems") or []
                            if str(system.get("tabSystemId") or "") == paired_tab_id
                        ),
                        None,
                    )
                if machine_tab_system is None:
                    inference_blockers.append(
                        {"kind": "archived_machine_tab_system_missing"}
                    )
                else:
                    machine_tab_events = sorted(
                        copy.deepcopy(machine_tab_system.get("tabEvents") or []),
                        key=lambda value: int(value.get("eventIndex") or 0),
                    )

            semantic_count = int(prediction.get("semanticAttackCount") or 0)
            source_attack_groups = _score_attack_groups(
                prediction.get("scoreEvents") or []
            )
            timeline_pitch_candidate_complete = bool(
                prediction.get("countPublishable")
                and prediction.get("scoreEvents")
                and len(source_attack_groups) == semantic_count
                and prediction.get("keySignature") is not None
            )
            machine_tab_states = _ordered_tab_states(
                {"tabEvents": machine_tab_events}
            )
            machine_tab_attack_count = sum(
                bool(state.get("isAttack")) for state in machine_tab_states
            )
            if not bool(prediction.get("countPublishable")):
                inference_blockers.append({"kind": "source_score_count_not_publishable"})
            if not timeline_pitch_candidate_complete:
                inference_blockers.append({"kind": "source_score_pitch_candidate_incomplete"})
            if len(source_attack_groups) != semantic_count:
                inference_blockers.append(
                    {
                        "kind": "source_score_event_count_mismatch",
                        "expected": semantic_count,
                        "actual": len(source_attack_groups),
                    }
                )
            timeline = _machine_unified_score_tab_timeline(
                prediction.get("scoreEvents") or [],
                machine_tab_events,
                expected_attack_count=semantic_count,
            )
            inference_blockers.extend(copy.deepcopy(timeline.get("blockers") or []))
            machine_reviewable = bool(
                not inference_blockers and timeline.get("reviewable")
            )
            for blocker in inference_blockers:
                blocker_counts[str(blocker.get("kind") or "unknown")] += 1

            inference = {
                "repairVersion": SOURCE_SCORE_SEMANTIC_REPAIR_VERSION,
                "timelineVersion": DISCOVERY_MACHINE_TIMELINE_VERSION,
                "cropSha256": crop_sha256,
                "omrSha256": str(case.get("omrSha256") or ""),
                "pageKeyCropSha256": page_key_crop_sha256,
                "pageKeyOmrSha256": page_key_omr_sha256,
                "pageKeySignature": copy.deepcopy(page_key_signature),
                "pageKeySignatureApplied": page_key_applied,
                "archivedMachineRecordDigest": prior_digest or None,
                "semanticAttackCount": semantic_count,
                "sourceScoreAttackCount": len(source_attack_groups),
                "machineTabAttackCount": machine_tab_attack_count,
                "machineTabStateCount": len(machine_tab_states),
                "countPublishable": bool(prediction.get("countPublishable")),
                "pitchCandidateComplete": timeline_pitch_candidate_complete,
                "timeline": timeline,
                "blockers": inference_blockers,
                "machineReviewable": machine_reviewable,
                "reviewedTruthUsedDuringInference": False,
            }
            inference_digest = _sha256_json(inference)

            # Post-inference scoring starts here.  These reviewed values never
            # influence the prediction, its blockers, or its digest.
            reviewed_tab_system = next(
                (
                    system
                    for system in reviewed_record.get("tabSystems") or []
                    if str(system.get("tabSystemId") or "")
                    == str(reviewed_score_system.get("pairedTabSystemId") or "")
                ),
                None,
            )
            truth_score_groups = _score_attack_groups(
                reviewed_score_system.get("scoreEvents") or []
            )
            truth_tab_events = sorted(
                copy.deepcopy((reviewed_tab_system or {}).get("tabEvents") or []),
                key=lambda value: int(value.get("eventIndex") or 0),
            )
            predicted_score_groups = _score_attack_groups(
                prediction.get("scoreEvents") or []
            )
            score_pitch_exact = bool(
                len(predicted_score_groups) == len(truth_score_groups)
                and all(
                    {
                        int(event["pitchValue"])
                        for event in predicted_group
                        if event.get("pitchValue") is not None
                    }
                    == {
                        int(event["pitchValue"])
                        for event in truth_group
                        if event.get("pitchValue") is not None
                    }
                    for predicted_group, truth_group in zip(
                        predicted_score_groups, truth_score_groups, strict=True
                    )
                )
            )
            tab_exact = bool(
                len(machine_tab_events) == len(truth_tab_events)
                and all(
                    tab_signature(predicted) == tab_signature(truth)
                    for predicted, truth in zip(
                        machine_tab_events, truth_tab_events, strict=True
                    )
                )
            )
            results.append(
                {
                    "caseId": case.get("caseId"),
                    "inputId": input_id,
                    "scoreSystemId": score_system_id,
                    "subset": case.get("subset"),
                    "inferenceDigest": inference_digest,
                    "inference": inference,
                    "truthScoreAttackCount": len(truth_score_groups),
                    "truthTabStateCount": len(truth_tab_events),
                    "scoreCountExact": semantic_count == len(truth_score_groups),
                    "machineTabCountExact": len(machine_tab_events)
                    == len(truth_tab_events),
                    "scorePitchExact": score_pitch_exact,
                    "machineTabExact": tab_exact,
                    "machineReviewable": machine_reviewable,
                    "reviewableTruthExact": bool(
                        machine_reviewable and score_pitch_exact and tab_exact
                    ),
                    "truthJoinedAfterInference": True,
                }
            )

        reviewable = [item for item in results if item.get("machineReviewable")]
        aggregate = {
            "caseCount": len(results),
            "archivedMachineSnapshotCount": sum(
                bool((item.get("inference") or {}).get("archivedMachineRecordDigest"))
                for item in results
            ),
            "sourceCountPublishableCount": sum(
                bool((item.get("inference") or {}).get("countPublishable"))
                for item in results
            ),
            "sourcePitchCandidateCompleteCount": sum(
                bool((item.get("inference") or {}).get("pitchCandidateComplete"))
                for item in results
            ),
            "sourceMachineEventCountAgreementCount": sum(
                int((item.get("inference") or {}).get("semanticAttackCount") or 0)
                > 0
                and int((item.get("inference") or {}).get("semanticAttackCount") or 0)
                == int((item.get("inference") or {}).get("sourceScoreAttackCount") or 0)
                == int((item.get("inference") or {}).get("machineTabStateCount") or 0)
                for item in results
            ),
            "structurallyCompleteTimelineCount": sum(
                bool(
                    ((item.get("inference") or {}).get("timeline") or {}).get(
                        "structurallyComplete"
                    )
                )
                for item in results
            ),
            "mechanicallyValidTimelineCount": sum(
                bool(
                    ((item.get("inference") or {}).get("timeline") or {}).get(
                        "mechanicallyValid"
                    )
                )
                for item in results
            ),
            "pitchContainedTimelineCount": sum(
                bool(
                    ((item.get("inference") or {}).get("timeline") or {}).get(
                        "pitchContained"
                    )
                )
                for item in results
            ),
            "noBlankTimelineCount": sum(
                bool(
                    ((item.get("inference") or {}).get("timeline") or {}).get(
                        "noBlankTimelineRows"
                    )
                )
                for item in results
            ),
            "sourceCountExactCount": sum(
                bool(item.get("scoreCountExact")) for item in results
            ),
            "machineTabCountExactCount": sum(
                bool(item.get("machineTabCountExact")) for item in results
            ),
            "scorePitchExactCount": sum(
                bool(item.get("scorePitchExact")) for item in results
            ),
            "machineTabExactCount": sum(
                bool(item.get("machineTabExact")) for item in results
            ),
            "machineReviewableCount": len(reviewable),
            "reviewableTruthExactCount": sum(
                bool(item.get("reviewableTruthExact")) for item in reviewable
            ),
            "reviewablePrecision": (
                round(
                    sum(bool(item.get("reviewableTruthExact")) for item in reviewable)
                    / len(reviewable),
                    6,
                )
                if reviewable
                else None
            ),
            "withheldFromReviewCount": len(results) - len(reviewable),
            "blockerCounts": dict(sorted(blocker_counts.items())),
        }
        report_core = {
            "schemaVersion": DISCOVERY_MACHINE_TIMELINE_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_machine_timeline_regression",
            "benchmarkManifestDigest": benchmark_digest,
            "repairVersion": SOURCE_SCORE_SEMANTIC_REPAIR_VERSION,
            "timelineVersion": DISCOVERY_MACHINE_TIMELINE_VERSION,
            "lineageContract": {
                "sourceScoreInputs": "digest_pinned_source_crop_and_omr_only",
                "tabInputs": "digest_pinned_archived_pre_correction_machine_record_only",
                "reviewedTruthJoin": "after_inference_digest",
                "reviewedTruthUsedDuringInference": False,
            },
            "aggregate": aggregate,
            "results": results,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanRereviewRequested": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_dir = review_root / "automation" / DISCOVERY_MACHINE_TIMELINE_VERSION
        report_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(report_dir, 0o700)
        report_path = report_dir / f"report-{report_digest[:12]}.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": DISCOVERY_MACHINE_TIMELINE_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "aggregate": aggregate,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanRereviewRequested": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def evaluate_discovery_tab_row_geometry_challenger(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Evaluate a narrow source-geometry grip merge on opened discovery."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_root = output_root / "review"
        benchmark_path = (
            review_root
            / "automation"
            / "source-score-notehead-challenger"
            / "benchmark-manifest.json"
        )
        if not benchmark_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before tab-row evaluation."
            )
        benchmark = _read_json(benchmark_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")

        results: list[dict[str, Any]] = []
        blocker_counts: Counter[str] = Counter()
        for raw_case in benchmark.get("cases") or []:
            case = dict(raw_case)
            input_id = str(case.get("inputId") or "")
            score_system_id = str(case.get("scoreSystemId") or "")
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            reviewed_record = _read_json(record_path)
            if _sha256_json(reviewed_record) != str(
                case.get("reviewedRecordDigest") or ""
            ):
                raise ExtractionWorkflowError(
                    "A tab-row discovery record changed."
                )
            prior_digest = str(
                (reviewed_record.get("machineCorrection") or {}).get(
                    "priorMachineRecordDigest"
                )
                or ""
            )
            machine_record: dict[str, Any] | None = None
            if prior_digest:
                revision_dir = review_root / "machine-record-revisions" / input_id
                for candidate_path in sorted(revision_dir.glob("*.json")):
                    candidate = _read_json(candidate_path)
                    if _sha256_json(candidate) == prior_digest:
                        machine_record = candidate
                        break
            if machine_record is None:
                blocker_counts["archived_machine_snapshot_missing"] += 1
                results.append(
                    {
                        "caseId": case.get("caseId"),
                        "inputId": input_id,
                        "scoreSystemId": score_system_id,
                        "subset": case.get("subset"),
                        "status": "blocked",
                        "blocker": "archived_machine_snapshot_missing",
                    }
                )
                continue

            machine_score_system = next(
                (
                    system
                    for system in machine_record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "") == score_system_id
                ),
                None,
            )
            reviewed_score_system = next(
                (
                    system
                    for system in reviewed_record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "") == score_system_id
                ),
                None,
            )
            machine_tab_system = next(
                (
                    system
                    for system in machine_record.get("tabSystems") or []
                    if machine_score_system is not None
                    and str(system.get("tabSystemId") or "")
                    == str(machine_score_system.get("pairedTabSystemId") or "")
                ),
                None,
            )
            reviewed_tab_system = next(
                (
                    system
                    for system in reviewed_record.get("tabSystems") or []
                    if reviewed_score_system is not None
                    and str(system.get("tabSystemId") or "")
                    == str(reviewed_score_system.get("pairedTabSystemId") or "")
                ),
                None,
            )
            if (
                machine_score_system is None
                or machine_tab_system is None
                or reviewed_tab_system is None
            ):
                blocker_counts["paired_tab_system_missing"] += 1
                continue

            derivative = machine_record.get("derivative") or {}
            derivative_path = output_root / str(derivative.get("relativePath") or "")
            derivative_sha = str(derivative.get("sha256") or "")
            if (
                not derivative_path.exists()
                or _sha256_bytes(derivative_path.read_bytes()) != derivative_sha
            ):
                raise ExtractionWorkflowError(
                    "A tab-row source derivative changed."
                )
            gray = np.asarray(Image.open(derivative_path).convert("L"))
            grids = detect_tab_grids(gray)
            system_index = int(machine_score_system.get("systemIndex") or 0)
            if not 1 <= system_index <= len(grids):
                blocker_counts["tab_grid_missing"] += 1
                continue
            grid = grids[system_index - 1]
            baseline_candidates = _tab_event_candidates(gray, grid)
            challenger_candidates = _merge_split_grip_event_candidates(
                baseline_candidates,
                image_width=max(1, grid.x1 - grid.x0),
            )
            machine_events = sorted(
                copy.deepcopy(machine_tab_system.get("tabEvents") or []),
                key=lambda value: int(value.get("eventIndex") or 0),
            )
            anchors = [
                float(event.get("horizontalPosition") or 0.0)
                for event in machine_events
            ]
            row_proposals: list[dict[str, Any]] = []
            if anchors and all(anchor > 0 for anchor in anchors):
                grid_width = max(1, grid.x1 - grid.x0)
                for event_index, (event, anchor) in enumerate(
                    zip(machine_events, anchors, strict=True),
                    start=1,
                ):
                    baseline_rows = {
                        int(action.get("string") or 0)
                        for action in event.get("steelActions") or []
                        if int(action.get("string") or 0)
                    }
                    visual_rows: set[int] = set()
                    for candidate in challenger_candidates:
                        normalized_x = float(candidate.get("x") or 0) / grid_width
                        nearest = min(
                            range(len(anchors)),
                            key=lambda value: abs(normalized_x - anchors[value]),
                        )
                        if (
                            nearest == event_index - 1
                            and abs(normalized_x - anchor) <= 0.045
                        ):
                            visual_rows.update(
                                int(value)
                                for value in candidate.get("candidateStrings") or []
                            )
                    if len(baseline_rows) != 2:
                        continue
                    low, high = sorted(baseline_rows)
                    middle = low + 1
                    if high - low == 2 and visual_rows == baseline_rows | {middle}:
                        row_proposals.append(
                            {
                                "eventIndex": event_index,
                                "baselineStrings": sorted(baseline_rows),
                                "proposedMissingString": middle,
                                "visualStrings": sorted(visual_rows),
                            }
                        )

            inference = {
                "geometryVersion": DISCOVERY_TAB_ROW_GEOMETRY_VERSION,
                "derivativeSha256": derivative_sha,
                "archivedMachineRecordDigest": prior_digest,
                "systemIndex": system_index,
                "baselineCandidates": baseline_candidates,
                "challengerCandidates": challenger_candidates,
                "rowProposals": row_proposals,
                "reviewedTruthUsedDuringInference": False,
            }
            inference_digest = _sha256_json(inference)

            truth_events = sorted(
                copy.deepcopy(reviewed_tab_system.get("tabEvents") or []),
                key=lambda value: int(value.get("eventIndex") or 0),
            )
            proposal_results: list[dict[str, Any]] = []
            for proposal in row_proposals:
                event_index = int(proposal["eventIndex"])
                truth_rows = (
                    {
                        int(action.get("string") or 0)
                        for action in truth_events[event_index - 1].get("steelActions")
                        or []
                    }
                    if event_index <= len(truth_events)
                    else set()
                )
                proposed_rows = set(proposal["baselineStrings"]) | {
                    int(proposal["proposedMissingString"])
                }
                proposal_results.append(
                    {
                        "eventIndex": event_index,
                        "exactAfterTruthJoin": proposed_rows == truth_rows,
                    }
                )
            baseline_count_exact = len(baseline_candidates) == len(truth_events)
            challenger_count_exact = len(challenger_candidates) == len(truth_events)
            results.append(
                {
                    "caseId": case.get("caseId"),
                    "inputId": input_id,
                    "scoreSystemId": score_system_id,
                    "subset": case.get("subset"),
                    "status": "evaluated",
                    "inferenceDigest": inference_digest,
                    "inference": inference,
                    "truthEventCount": len(truth_events),
                    "baselineCountExact": baseline_count_exact,
                    "challengerCountExact": challenger_count_exact,
                    "countImproved": challenger_count_exact
                    and not baseline_count_exact,
                    "countRegressed": baseline_count_exact
                    and not challenger_count_exact,
                    "proposalResults": proposal_results,
                    "truthJoinedAfterInference": True,
                }
            )

        def subset_metrics(subset: str) -> dict[str, Any]:
            items = [
                item
                for item in results
                if item.get("subset") == subset and item.get("status") == "evaluated"
            ]
            proposals = [
                proposal
                for item in items
                for proposal in item.get("proposalResults") or []
            ]
            return {
                "evaluatedCaseCount": len(items),
                "baselineExactCount": sum(
                    bool(item.get("baselineCountExact")) for item in items
                ),
                "challengerExactCount": sum(
                    bool(item.get("challengerCountExact")) for item in items
                ),
                "improvedCount": sum(bool(item.get("countImproved")) for item in items),
                "regressedCount": sum(bool(item.get("countRegressed")) for item in items),
                "rowProposalCount": len(proposals),
                "exactRowProposalCount": sum(
                    bool(item.get("exactAfterTruthJoin")) for item in proposals
                ),
                "falseRowProposalCount": sum(
                    not bool(item.get("exactAfterTruthJoin")) for item in proposals
                ),
            }

        by_subset = {
            subset: subset_metrics(subset) for subset in ("development", "shadow")
        }
        development = by_subset["development"]
        shadow = by_subset["shadow"]
        gate_passed = bool(
            development["improvedCount"] >= 1
            and development["regressedCount"] == 0
            and development["rowProposalCount"] >= 1
            and development["falseRowProposalCount"] == 0
            and shadow["regressedCount"] == 0
            and shadow["rowProposalCount"] >= 1
            and shadow["falseRowProposalCount"] == 0
        )
        report_core = {
            "schemaVersion": DISCOVERY_TAB_ROW_GEOMETRY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_tab_row_geometry_regression",
            "benchmarkManifestDigest": benchmark_digest,
            "geometryVersion": DISCOVERY_TAB_ROW_GEOMETRY_VERSION,
            "lineageContract": {
                "geometryInputs": "digest_pinned_source_derivative_only",
                "anchorInputs": "digest_pinned_archived_pre_correction_machine_record_only",
                "reviewedTruthJoin": "after_inference_digest",
                "reviewedTruthUsedDuringInference": False,
            },
            "byOpenedSubset": by_subset,
            "blockerCounts": dict(sorted(blocker_counts.items())),
            "results": results,
            "openedDiscoveryGatePassed": gate_passed,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanRereviewRequested": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_dir = review_root / "automation" / DISCOVERY_TAB_ROW_GEOMETRY_VERSION
        report_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(report_dir, 0o700)
        report_path = report_dir / f"report-{report_digest[:12]}.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": DISCOVERY_TAB_ROW_GEOMETRY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "byOpenedSubset": by_subset,
            "blockerCounts": dict(sorted(blocker_counts.items())),
            "openedDiscoveryGatePassed": gate_passed,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanRereviewRequested": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def freeze_discovery_tab_row_geometry_contract(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Freeze the one regression-passed geometry contract for later replay."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        geometry_root = (
            output_root
            / "review"
            / "automation"
            / DISCOVERY_TAB_ROW_GEOMETRY_VERSION
        )
        matching: list[tuple[Path, dict[str, Any]]] = []
        for report_path in sorted(geometry_root.glob("report-*.json")):
            report = _read_json(report_path)
            report_digest = str(report.get("reportDigest") or "")
            if report_digest != _sha256_json(
                {key: value for key, value in report.items() if key != "reportDigest"}
            ):
                raise ExtractionWorkflowError(
                    "A tab-row geometry report digest changed."
                )
            if (
                report.get("schemaVersion")
                == DISCOVERY_TAB_ROW_GEOMETRY_SCHEMA_VERSION
                and report.get("geometryVersion")
                == DISCOVERY_TAB_ROW_GEOMETRY_VERSION
                and report.get("openedDiscoveryGatePassed") is True
            ):
                matching.append((report_path, report))
        if len(matching) != 1:
            raise ExtractionWorkflowError(
                "Freeze exactly one regression-passed tab-row geometry report."
            )
        report_path, report = matching[0]
        contract = {
            "geometryVersion": DISCOVERY_TAB_ROW_GEOMETRY_VERSION,
            "maximumSplitCandidateDeltaRatio": 0.02,
            "maximumArchivedAnchorDeltaRatio": 0.045,
            "pattern": "adjacent_exact_middle_string_between_two_outer_strings",
            "rowPolicy": "add_missing_middle_only_never_replace_existing_rows",
            "tokenPolicy": (
                "complete_independent_cell_token_single_action_confidence_gte_0_95"
            ),
            "mechanicalPolicy": "exact_source_copedent_validation_required",
        }
        selection_core = {
            "schemaVersion": DISCOVERY_TAB_ROW_GEOMETRY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "contract": contract,
            "contractDigest": _sha256_json(contract),
            "fitReportDigest": report.get("reportDigest"),
            "fitReportPath": str(report_path.relative_to(output_root)),
            "selectionClass": "frozen_opened_discovery_action_replay_only",
            "freshDiscoveryAvailable": False,
            "promotionEligible": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "frozenAt": _utc_now(),
        }
        selection = {
            **selection_core,
            "selectionDigest": _sha256_json(selection_core),
        }
        selection_path = geometry_root / "selected-contract.json"
        if selection_path.exists():
            existing = _read_json(selection_path)
            if str(existing.get("selectionDigest") or "") != _sha256_json(
                {
                    key: value
                    for key, value in existing.items()
                    if key != "selectionDigest"
                }
            ):
                raise ExtractionWorkflowError(
                    "The frozen tab-row geometry selection changed."
                )
            comparable_existing = {
                key: value
                for key, value in existing.items()
                if key not in {"frozenAt", "selectionDigest"}
            }
            comparable_selection = {
                key: value
                for key, value in selection.items()
                if key not in {"frozenAt", "selectionDigest"}
            }
            if comparable_existing != comparable_selection:
                raise ExtractionWorkflowError(
                    "A different tab-row geometry contract is already frozen."
                )
            selection = existing
        else:
            _write_json(selection_path, selection)
        return {
            "schemaVersion": DISCOVERY_TAB_ROW_GEOMETRY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "contractDigest": selection["contractDigest"],
            "fitReportDigest": selection["fitReportDigest"],
            "selectionDigest": selection["selectionDigest"],
            "selectionPath": str(selection_path.relative_to(output_root)),
            "selectionClass": selection["selectionClass"],
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def evaluate_discovery_tab_action_recovery_challenger(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Read complete actions for frozen geometry proposals before truth join."""

        batch_dir, manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_root = output_root / "review"
        geometry_root = (
            review_root / "automation" / DISCOVERY_TAB_ROW_GEOMETRY_VERSION
        )
        selection_path = geometry_root / "selected-contract.json"
        if not selection_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the tab-row geometry contract before action recovery."
            )
        selection = _read_json(selection_path)
        selection_digest = str(selection.get("selectionDigest") or "")
        if selection_digest != _sha256_json(
            {key: value for key, value in selection.items() if key != "selectionDigest"}
        ):
            raise ExtractionWorkflowError(
                "The frozen tab-row geometry selection changed."
            )
        contract = selection.get("contract") or {}
        if (
            contract.get("geometryVersion") != DISCOVERY_TAB_ROW_GEOMETRY_VERSION
            or float(contract.get("maximumSplitCandidateDeltaRatio") or 0.0)
            != 0.02
            or float(contract.get("maximumArchivedAnchorDeltaRatio") or 0.0)
            != 0.045
        ):
            raise ExtractionWorkflowError(
                "Action recovery requires the exact frozen geometry contract."
            )
        fit_report_path = output_root / str(selection.get("fitReportPath") or "")
        fit_report = _read_json(fit_report_path)
        if str(fit_report.get("reportDigest") or "") != str(
            selection.get("fitReportDigest") or ""
        ):
            raise ExtractionWorkflowError(
                "The selected tab-row geometry report changed."
            )
        benchmark_path = (
            review_root
            / "automation"
            / "source-score-notehead-challenger"
            / "benchmark-manifest.json"
        )
        benchmark = _read_json(benchmark_path)
        benchmark_by_case = {
            str(case.get("caseId") or ""): dict(case)
            for case in benchmark.get("cases") or []
        }
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        reader_contract_method = getattr(self.tab_vision, "contract", None)
        reader_contract = (
            reader_contract_method()
            if callable(reader_contract_method)
            else {"reader": str(getattr(self.tab_vision, "model", "unknown"))}
        )
        reader_contract_digest = _sha256_json(reader_contract)
        action_root = geometry_root / DISCOVERY_TAB_ACTION_RECOVERY_VERSION
        cell_root = action_root / "cell-captures"
        cell_root.mkdir(parents=True, exist_ok=True)
        os.chmod(action_root, 0o700)
        os.chmod(cell_root, 0o700)

        def action_signature(action: Mapping[str, Any]) -> dict[str, Any]:
            return {
                "string": int(action.get("string") or 0),
                "fret": int(action.get("fret") or 0),
                "controls": sorted(
                    str(value).upper() for value in action.get("controls") or []
                ),
                "halfStop": bool(action.get("halfStop")),
                "attack": bool(action.get("attack", True)),
            }

        results: list[dict[str, Any]] = []
        for geometry_result in fit_report.get("results") or []:
            inference = geometry_result.get("inference") or {}
            row_proposals = list(inference.get("rowProposals") or [])
            if not row_proposals or geometry_result.get("status") != "evaluated":
                continue
            case_id = str(geometry_result.get("caseId") or "")
            case = benchmark_by_case.get(case_id)
            if case is None:
                raise ExtractionWorkflowError(
                    "A geometry action case is absent from the benchmark."
                )
            input_id = str(case.get("inputId") or "")
            score_system_id = str(case.get("scoreSystemId") or "")
            reviewed_path = output_root / str(case.get("reviewedRecordPath") or "")
            reviewed_record = _read_json(reviewed_path)
            if _sha256_json(reviewed_record) != str(
                case.get("reviewedRecordDigest") or ""
            ):
                raise ExtractionWorkflowError(
                    "A geometry action reviewed record changed."
                )
            prior_digest = str(inference.get("archivedMachineRecordDigest") or "")
            machine_record: dict[str, Any] | None = None
            revision_dir = review_root / "machine-record-revisions" / input_id
            for candidate_path in sorted(revision_dir.glob("*.json")):
                candidate = _read_json(candidate_path)
                if _sha256_json(candidate) == prior_digest:
                    machine_record = candidate
                    break
            if machine_record is None:
                raise ExtractionWorkflowError(
                    "A geometry action archived machine record is missing."
                )
            machine_score = next(
                system
                for system in machine_record.get("scoreSystems") or []
                if str(system.get("scoreSystemId") or "") == score_system_id
            )
            machine_tab = next(
                system
                for system in machine_record.get("tabSystems") or []
                if str(system.get("tabSystemId") or "")
                == str(machine_score.get("pairedTabSystemId") or "")
            )
            machine_events = sorted(
                copy.deepcopy(machine_tab.get("tabEvents") or []),
                key=lambda value: int(value.get("eventIndex") or 0),
            )
            anchors = [
                float(event.get("horizontalPosition") or 0.0)
                for event in machine_events
            ]
            derivative = machine_record.get("derivative") or {}
            derivative_path = output_root / str(derivative.get("relativePath") or "")
            if _sha256_bytes(derivative_path.read_bytes()) != str(
                derivative.get("sha256") or ""
            ):
                raise ExtractionWorkflowError(
                    "A geometry action derivative changed."
                )
            image = Image.open(derivative_path).convert("RGB")
            gray = np.asarray(image.convert("L"))
            grids = detect_tab_grids(gray)
            system_index = int(machine_score.get("systemIndex") or 0)
            if not 1 <= system_index <= len(grids):
                raise ExtractionWorkflowError(
                    "A geometry action tab grid is missing."
                )
            grid = grids[system_index - 1]
            challenger_candidates = [
                copy.deepcopy(dict(candidate))
                for candidate in inference.get("challengerCandidates") or []
            ]
            sheets = _contact_sheets(
                image,
                grid,
                challenger_candidates,
                cell_root / case_id,
                system_index,
            )
            cells: dict[str, dict[str, Any]] = {}
            for sheet in sheets:
                cells.update(self._read_tab_cells(sheet))
            grid_width = max(1, grid.x1 - grid.x0)
            proposal_inferences: list[dict[str, Any]] = []
            for proposal in row_proposals:
                event_index = int(proposal["eventIndex"])
                string = int(proposal["proposedMissingString"])
                anchor = anchors[event_index - 1]
                matching_candidates = [
                    candidate
                    for candidate in challenger_candidates
                    if string in {
                        int(value)
                        for value in candidate.get("candidateStrings") or []
                    }
                    and abs(
                        float(candidate.get("x") or 0) / grid_width - anchor
                    )
                    <= float(contract["maximumArchivedAnchorDeltaRatio"])
                ]
                matching_candidates.sort(
                    key=lambda candidate: abs(
                        float(candidate.get("x") or 0) / grid_width - anchor
                    )
                )
                candidate = matching_candidates[0] if matching_candidates else None
                cell = (
                    cells.get(f"e{candidate['eventIndex']}s{string}", {})
                    if candidate is not None
                    else {}
                )
                confidence = float(cell.get("confidence") or 0.0)
                uncertain = bool(cell.get("uncertain"))
                actions, issue = _tab_action_sequence_from_cell(
                    cell,
                    string=string,
                    profile=profile,
                    region_id=_stable_id(
                        "geometry-action-region", case_id, event_index, string
                    ),
                )
                complete = bool(
                    candidate is not None
                    and confidence >= 0.95
                    and not uncertain
                    and len(actions) == 1
                    and issue is None
                )
                mechanically_valid = bool(
                    complete
                    and (actions[0].get("mechanicalValidation") or {}).get("valid")
                )
                proposal_inferences.append(
                    {
                        "eventIndex": event_index,
                        "string": string,
                        "candidateEventIndex": (
                            int(candidate["eventIndex"])
                            if candidate is not None
                            else None
                        ),
                        "cell": copy.deepcopy(cell),
                        "action": (
                            action_signature(actions[0]) if complete else None
                        ),
                        "completeIndependentToken": complete,
                        "mechanicallyValid": mechanically_valid,
                        "issueKind": str((issue or {}).get("kind") or "") or None,
                    }
                )
            action_inference = {
                "actionRecoveryVersion": DISCOVERY_TAB_ACTION_RECOVERY_VERSION,
                "geometrySelectionDigest": selection_digest,
                "geometryInferenceDigest": geometry_result.get("inferenceDigest"),
                "readerContract": reader_contract,
                "readerContractDigest": reader_contract_digest,
                "sourceCopedentId": profile.id,
                "sourceCopedentRevision": profile.revision,
                "sourceCopedentDigest": _profile_digest(profile),
                "proposals": proposal_inferences,
                "reviewedTruthUsedDuringInference": False,
            }
            action_inference_digest = _sha256_json(action_inference)

            reviewed_score = next(
                system
                for system in reviewed_record.get("scoreSystems") or []
                if str(system.get("scoreSystemId") or "") == score_system_id
            )
            reviewed_tab = next(
                system
                for system in reviewed_record.get("tabSystems") or []
                if str(system.get("tabSystemId") or "")
                == str(reviewed_score.get("pairedTabSystemId") or "")
            )
            truth_events = sorted(
                reviewed_tab.get("tabEvents") or [],
                key=lambda value: int(value.get("eventIndex") or 0),
            )
            scored_proposals: list[dict[str, Any]] = []
            for proposal in proposal_inferences:
                truth_action = next(
                    (
                        action
                        for action in truth_events[int(proposal["eventIndex"]) - 1].get(
                            "steelActions"
                        )
                        or []
                        if int(action.get("string") or 0) == int(proposal["string"])
                    ),
                    None,
                )
                scored_proposals.append(
                    {
                        "eventIndex": proposal["eventIndex"],
                        "string": proposal["string"],
                        "actionExactAfterTruthJoin": bool(
                            proposal.get("action") is not None
                            and truth_action is not None
                            and proposal["action"] == action_signature(truth_action)
                        ),
                    }
                )
            results.append(
                {
                    "caseId": case_id,
                    "inputId": input_id,
                    "scoreSystemId": score_system_id,
                    "subset": case.get("subset"),
                    "actionInferenceDigest": action_inference_digest,
                    "actionInference": action_inference,
                    "scoredProposals": scored_proposals,
                    "truthJoinedAfterInference": True,
                }
            )

        by_subset = {
            subset: _tab_action_recovery_metrics(results, subset)
            for subset in ("development", "shadow")
        }
        gate_passed = _tab_action_recovery_gate(by_subset)
        report_core = {
            "schemaVersion": DISCOVERY_TAB_ACTION_RECOVERY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_tab_action_regression",
            "geometrySelectionDigest": selection_digest,
            "readerContractDigest": reader_contract_digest,
            "byOpenedSubset": by_subset,
            "results": results,
            "openedDiscoveryActionGatePassed": gate_passed,
            "freshDiscoveryAvailable": False,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanRereviewRequested": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = action_root / f"report-{report_digest[:12]}.json"
        _write_json(report_path, report)
        return {
            "schemaVersion": DISCOVERY_TAB_ACTION_RECOVERY_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "geometrySelectionDigest": selection_digest,
            "readerContractDigest": reader_contract_digest,
            "byOpenedSubset": by_subset,
            "openedDiscoveryActionGatePassed": gate_passed,
            "freshDiscoveryAvailable": False,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanRereviewRequested": False,
            "trainingEvidenceCreated": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def evaluate_discovery_guided_capture_regression(
        self,
        batch_id: str,
        *,
        limit: int = 8,
    ) -> dict[str, Any]:
        """Replay corrected discovery lines as supervised glyph-recognition cases.

        Reviewed event positions and string rows are supplied as geometry only.
        Predicted fret/control tokens and score pitches are compared with truth
        only after inference.  This is an opened discovery regression, never a
        holdout, promotion result, or new training record.
        """

        if not 1 <= limit <= 25:
            raise ExtractionWorkflowError("Guided discovery regression limit must be 1-25.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        benchmark_root = (
            output_root / "review" / "automation" / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before guided regression."
            )
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")
        regression_dir = (
            output_root
            / "review"
            / "automation"
            / "guided-score-tab-capture-regression-v1"
        )
        regression_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(regression_dir, 0o700)
        contract = {
            "schemaVersion": "guided-score-tab-capture-regression-v1",
            "evaluationClass": "opened_discovery_supervised_geometry_regression",
            "model": self.tab_system_vision.model,
            "modelContract": self.tab_system_vision.contract(),
            "tabPromptVersion": TAB_SYSTEM_LOCALIZATION_PROMPT_VERSION,
            "scorePromptVersion": SCORE_PITCH_LOCALIZATION_PROMPT_VERSION,
            "reviewedEventCountProvided": True,
            "reviewedEventPositionsProvided": True,
            "reviewedStringRowsProvided": True,
            "reviewedKeySignatureProvided": True,
            "reviewedFretControlTruthProvidedDuringInference": False,
            "reviewedScorePitchTruthProvidedDuringInference": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        contract_digest = _sha256_json(contract)
        results: list[dict[str, Any]] = []
        eligible_count = 0
        for case in sorted(
            (dict(value) for value in benchmark.get("cases") or []),
            key=lambda value: str(value.get("caseId") or ""),
        ):
            if eligible_count >= limit:
                break
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            if not record_path.exists():
                continue
            record = _read_json(record_path)
            if _sha256_json(record) != str(case.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError("A reviewed discovery regression record changed.")
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "")
                    == str(case.get("scoreSystemId") or "")
                ),
                None,
            )
            if score_system is None:
                continue
            tab_system = next(
                (
                    system
                    for system in record.get("tabSystems") or []
                    if str(system.get("tabSystemId") or "")
                    == str(score_system.get("pairedTabSystemId") or "")
                ),
                None,
            )
            if tab_system is None:
                continue
            truth_tab_events = sorted(
                list(tab_system.get("tabEvents") or []),
                key=lambda value: int(value.get("eventIndex") or 0),
            )
            truth_score_groups = _score_event_groups_by_printed_position(
                score_system.get("scoreEvents") or []
            )
            if (
                not truth_tab_events
                or len(truth_tab_events) != len(truth_score_groups)
                or len(truth_tab_events) > 32
            ):
                continue
            eligible_count += 1
            case_id = str(case.get("caseId") or "")
            result: dict[str, Any] = {
                "caseId": case_id,
                "inputId": case.get("inputId"),
                "scoreSystemId": case.get("scoreSystemId"),
                "eventCount": len(truth_tab_events),
                "tabExact": False,
                "scoreExact": False,
                "status": "withheld",
            }
            try:
                head_graph = _parse_audiveris_head_graph(
                    output_root / str(case.get("omrRelativePath") or ""),
                    str(score_system.get("scoreSystemId") or case_id),
                )
                natural_head_groups = _score_event_groups_by_printed_position(
                    head_graph.get("scoreEvents") or []
                )
                result["headGraphNaturalAttackCount"] = len(natural_head_groups)
                if len(natural_head_groups) == len(truth_score_groups):
                    natural_exact_count = sum(
                        {
                            int(event["pitchValue"])
                            for event in predicted
                            if event.get("pitchValue") is not None
                        }
                        == {
                            int(event["pitchValue"])
                            for event in truth
                            if event.get("pitchValue") is not None
                        }
                        for predicted, truth in zip(
                            natural_head_groups, truth_score_groups, strict=True
                        )
                    )
                    result["headGraphNaturalExactEventCount"] = natural_exact_count
                    result["headGraphNaturalExact"] = natural_exact_count == len(
                        truth_score_groups
                    )
                else:
                    result["headGraphNaturalExactEventCount"] = 0
                    result["headGraphNaturalExact"] = False
                key_fifths = score_system.get("keyFifths")
                if key_fifths is None:
                    key_fifths = score_system.get("keySignatureFifths")
                if key_fifths is not None:
                    head_events = _apply_key_signature_to_score_events(
                        head_graph.get("scoreEvents") or [], int(key_fifths)
                    )
                    head_groups = _score_event_groups_by_printed_position(head_events)
                    result["headGraphAttackCount"] = len(head_groups)
                    if len(head_groups) == len(truth_score_groups):
                        head_exact_count = sum(
                            {
                                int(event["pitchValue"])
                                for event in predicted
                                if event.get("pitchValue") is not None
                            }
                            == {
                                int(event["pitchValue"])
                                for event in truth
                                if event.get("pitchValue") is not None
                            }
                            for predicted, truth in zip(
                                head_groups, truth_score_groups, strict=True
                            )
                        )
                        result["headGraphExactEventCount"] = head_exact_count
                        result["headGraphExact"] = head_exact_count == len(
                            truth_score_groups
                        )
                    else:
                        result["headGraphExactEventCount"] = 0
                        result["headGraphExact"] = False
                else:
                    result["headGraphKeyAdjustedUnavailable"] = True
            except ExtractionWorkflowError as exc:
                result["headGraphFailure"] = type(exc).__name__
            try:
                guided_tab_system = copy.deepcopy(tab_system)
                guided_tab_system["tabEventCandidates"] = [
                    {
                        "sourceCandidateEventIndex": ordinal,
                        "horizontalPosition": float(event.get("horizontalPosition") or 0.0),
                        "candidateStrings": sorted(
                            int(action["string"])
                            for action in event.get("steelActions") or []
                        ),
                    }
                    for ordinal, event in enumerate(truth_tab_events, start=1)
                ]
                tab_crop = _prepare_event_localization_tab_crop(
                    output_root=output_root,
                    localization_dir=regression_dir,
                    input_id=str(case.get("inputId") or case_id),
                    record=record,
                    tab_system=tab_system,
                )
                guided_tab_crop = _prepare_guided_tab_state_crop(
                    localization_dir=regression_dir,
                    input_id=str(case.get("inputId") or case_id),
                    tab_system=guided_tab_system,
                    tab_crop=tab_crop,
                )
                localization = self.tab_system_vision.localize_events(
                    Path(guided_tab_crop["path"]),
                    expected_event_count=len(truth_tab_events),
                    constraint_source="human_reviewed_discovery_feedback",
                    guided=True,
                    expected_cell_counts=[
                        len(candidate.get("candidateStrings") or [])
                        for candidate in guided_tab_system["tabEventCandidates"]
                    ],
                    control_string_map=_profile_control_string_map(profile),
                )
                localization = copy.deepcopy(localization)
                for raw_event, guide, candidate in zip(
                    localization.get("events") or [],
                    guided_tab_crop["guides"],
                    guided_tab_system["tabEventCandidates"],
                    strict=True,
                ):
                    raw_cells = sorted(
                        list(raw_event.get("cells") or []),
                        key=lambda cell: int(cell.get("string") or 0),
                    )
                    strings = list(candidate["candidateStrings"])
                    if len(raw_cells) != len(strings):
                        raise ExtractionWorkflowError(
                            "Guided discovery reader did not return one token per reviewed row."
                        )
                    for raw_cell, string in zip(raw_cells, strings, strict=True):
                        raw_cell["string"] = string
                    raw_event["cells"] = raw_cells
                    raw_event["x"] = round(
                        (
                            float(tab_crop["contentX0"])
                            + float(guide["horizontalPosition"])
                            * (
                                float(tab_crop["contentX1"])
                                - float(tab_crop["contentX0"])
                            )
                        )
                        / float(tab_crop["width"]),
                        7,
                    )
                predicted_tab_events = _machine_localized_tab_events(
                    input_id=str(case.get("inputId") or case_id),
                    tab_system=guided_tab_system,
                    localization=localization,
                    crop_metadata=tab_crop,
                    expected_count=len(truth_tab_events),
                    profile=profile,
                )

                def tab_signature(event: Mapping[str, Any]) -> list[tuple[int, int, tuple[str, ...]]]:
                    return sorted(
                        (
                            int(action["string"]),
                            int(action["fret"]),
                            tuple(sorted(str(value) for value in action.get("controls") or [])),
                        )
                        for action in event.get("steelActions") or []
                    )

                tab_exact_count = sum(
                    tab_signature(predicted) == tab_signature(truth)
                    for predicted, truth in zip(
                        predicted_tab_events, truth_tab_events, strict=True
                    )
                )
                result["tabExactEventCount"] = tab_exact_count
                result["tabExact"] = tab_exact_count == len(truth_tab_events)

                predicted_tab_system = copy.deepcopy(tab_system)
                predicted_tab_system["tabEvents"] = predicted_tab_events
                guided_score_crop = _prepare_guided_score_pitch_crop(
                    output_root=output_root,
                    audit_dir=regression_dir,
                    input_id=str(case.get("inputId") or case_id),
                    score_system=score_system,
                    tab_system=predicted_tab_system,
                )
                recognition = self.tab_system_vision.read_score_pitch_events(
                    Path(guided_score_crop["path"]),
                    expected_event_count=len(truth_tab_events),
                    guided=True,
                    constraint_source="human_reviewed_discovery_feedback",
                )
                predicted_score_events = _machine_localized_score_events(
                    input_id=str(case.get("inputId") or case_id),
                    score_system=score_system,
                    recognition=recognition,
                    tab_events=predicted_tab_events,
                )
                predicted_score_groups = _score_event_groups_by_printed_position(
                    predicted_score_events
                )
                score_exact_count = sum(
                    {
                        int(event["pitchValue"])
                        for event in predicted
                        if event.get("pitchValue") is not None
                    }
                    == {
                        int(event["pitchValue"])
                        for event in truth
                        if event.get("pitchValue") is not None
                    }
                    for predicted, truth in zip(
                        predicted_score_groups, truth_score_groups, strict=True
                    )
                )
                result["scoreExactEventCount"] = score_exact_count
                result["scoreExact"] = score_exact_count == len(truth_score_groups)
                result["status"] = "measured"
            except ExtractionWorkflowError as exc:
                result["failure"] = str(exc)[:500]
            results.append(result)

        measured = [item for item in results if item["status"] == "measured"]
        total_events = sum(int(item["eventCount"]) for item in results)
        report_core = {
            "schemaVersion": "guided-score-tab-capture-regression-v1",
            "batchId": batch_id,
            "partition": "discovery",
            "benchmarkManifestDigest": benchmark_digest,
            "contract": contract,
            "contractDigest": contract_digest,
            "caseCount": len(results),
            "measuredCaseCount": len(measured),
            "withheldCaseCount": len(results) - len(measured),
            "eventCount": total_events,
            "tabExactEventCount": sum(
                int(item.get("tabExactEventCount") or 0) for item in measured
            ),
            "scoreExactEventCount": sum(
                int(item.get("scoreExactEventCount") or 0) for item in measured
            ),
            "headGraphExactEventCount": sum(
                int(item.get("headGraphExactEventCount") or 0) for item in results
            ),
            "headGraphNaturalExactEventCount": sum(
                int(item.get("headGraphNaturalExactEventCount") or 0)
                for item in results
            ),
            "tabExactLineCount": sum(bool(item.get("tabExact")) for item in measured),
            "scoreExactLineCount": sum(bool(item.get("scoreExact")) for item in measured),
            "headGraphExactLineCount": sum(
                bool(item.get("headGraphExact")) for item in results
            ),
            "headGraphNaturalExactLineCount": sum(
                bool(item.get("headGraphNaturalExact")) for item in results
            ),
            "results": results,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "trainingEvidenceCreated": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = regression_dir / f"report-{report_digest}.json"
        _write_json(report_path, report)
        return {
            key: report[key]
            for key in (
                "schemaVersion",
                "batchId",
                "partition",
                "caseCount",
                "measuredCaseCount",
                "withheldCaseCount",
                "eventCount",
                "tabExactEventCount",
                "scoreExactEventCount",
                "headGraphExactEventCount",
                "headGraphNaturalExactEventCount",
                "tabExactLineCount",
                "scoreExactLineCount",
                "headGraphExactLineCount",
                "headGraphNaturalExactLineCount",
                "promotionEligible",
                "reviewPacketCreated",
                "trainingEvidenceCreated",
                "validationAccessed",
                "sealedTestAccessed",
            )
        } | {
            "contractDigest": contract_digest,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def evaluate_source_score_vision_regression(
        self,
        batch_id: str,
        *,
        workers: int = 2,
        limit: int = 39,
        resume: bool = True,
    ) -> dict[str, Any]:
        """Measure an unconstrained score-only vision reader on discovery regressions.

        All benchmark cases have already been exposed through prior discovery work,
        so this method deliberately makes no holdout, promotion, or training claim.
        The reader sees only a digest-pinned printed-score derivative. Reviewer truth
        and tablature are joined only after inference for aggregate diagnostics.
        """

        if not 1 <= workers <= 4:
            raise ExtractionWorkflowError("Source-score vision workers must be between 1 and 4.")
        if not 1 <= limit <= 100:
            raise ExtractionWorkflowError("Source-score vision limit must be between 1 and 100.")
        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        manifest_path = benchmark_root / "benchmark-manifest.json"
        if not manifest_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score notehead benchmark before vision regression."
            )
        benchmark = _read_json(manifest_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        if benchmark_digest != _sha256_json(
            {key: value for key, value in benchmark.items() if key != "manifestDigest"}
        ):
            raise ExtractionWorkflowError("The source-score benchmark digest changed.")
        contract = {
            "reader": "local_score_only_vision",
            "model": self.tab_system_vision.model,
            "promptVersion": SOURCE_SCORE_VISION_PROMPT_VERSION,
            "seed": self.tab_system_vision.seed,
            "numCtx": self.tab_system_vision.num_ctx,
            "numPredict": 1024,
            "expectedCountProvided": False,
            "tablatureProvided": False,
            "reviewerTruthProvidedDuringInference": False,
        }
        contract_digest = _sha256_json(contract)
        all_cases = sorted(
            (dict(case) for case in benchmark.get("cases") or []),
            key=lambda item: str(item.get("caseId") or ""),
        )
        cases = all_cases[:limit]
        if not cases:
            raise ExtractionWorkflowError("The source-score vision regression is empty.")
        candidate_root = benchmark_root / "vision-candidates"
        candidate_root.mkdir(parents=True, exist_ok=True)
        os.chmod(candidate_root, 0o700)

        prepared: list[dict[str, Any]] = []
        for case in cases:
            record_path = output_root / str(case.get("reviewedRecordPath") or "")
            if not record_path.exists():
                raise ExtractionWorkflowError("A reviewed source-score regression record is missing.")
            record = _read_json(record_path)
            if _sha256_json(record) != str(case.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError("A reviewed source-score regression record changed.")
            score_system = next(
                (
                    system
                    for system in record.get("scoreSystems") or []
                    if str(system.get("scoreSystemId") or "")
                    == str(case.get("scoreSystemId") or "")
                ),
                None,
            )
            crop_source: str | None = None
            crop_relative_path = ""
            crop_sha256 = ""
            crop_path = output_root
            for source_name, candidate_crop in (
                (
                    "omr_prepared_derivative",
                    (score_system or {}).get("omrPreparedDerivative") or {},
                ),
                (
                    "score_repair_source_crop",
                    (score_system or {}).get("scoreRepairSourceCrop") or {},
                ),
            ):
                candidate_relative_path = str(candidate_crop.get("relativePath") or "")
                candidate_sha256 = str(candidate_crop.get("sha256") or "")
                candidate_path = output_root / candidate_relative_path
                if (
                    candidate_relative_path
                    and candidate_path.exists()
                    and _sha256_bytes(candidate_path.read_bytes()) == candidate_sha256
                ):
                    crop_source = source_name
                    crop_relative_path = candidate_relative_path
                    crop_sha256 = candidate_sha256
                    crop_path = candidate_path
                    break
            if score_system is None or crop_source is None:
                raise ExtractionWorkflowError(
                    "A digest-pinned score-only derivative is unavailable or changed."
                )
            prepared.append(
                {
                    "case": case,
                    "cropPath": crop_path,
                    "cropRelativePath": crop_relative_path,
                    "cropSha256": crop_sha256,
                    "cropSource": crop_source,
                }
            )

        def infer_one(item: Mapping[str, Any]) -> dict[str, Any]:
            case = item["case"]
            case_id = str(case.get("caseId") or "")
            cache_path = candidate_root / f"{case_id}-{contract_digest[:12]}.json"
            if resume and cache_path.exists():
                cached = _read_json(cache_path)
                if (
                    cached.get("contractDigest") == contract_digest
                    and cached.get("cropSha256") == item.get("cropSha256")
                    and cached.get("caseId") == case_id
                ):
                    return cached
            candidate_core = {
                "schemaVersion": SOURCE_SCORE_VISION_REGRESSION_SCHEMA_VERSION,
                "caseId": case_id,
                "cropRelativePath": item.get("cropRelativePath"),
                "cropSha256": item.get("cropSha256"),
                "cropSource": item.get("cropSource"),
                "contract": contract,
                "contractDigest": contract_digest,
                "prediction": self.tab_system_vision.read_unconstrained_score_columns(
                    Path(item["cropPath"])
                ),
            }
            candidate = {
                **candidate_core,
                "candidateDigest": _sha256_json(candidate_core),
            }
            _write_json(cache_path, candidate)
            return candidate

        candidates_by_case: dict[str, dict[str, Any]] = {}
        failures_by_case: dict[str, str] = {}
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {
                executor.submit(infer_one, item): str(item["case"].get("caseId") or "")
                for item in prepared
            }
            for future in concurrent.futures.as_completed(futures):
                case_id = futures[future]
                try:
                    candidates_by_case[case_id] = future.result()
                except Exception as exc:
                    failures_by_case[case_id] = type(exc).__name__

        results: list[dict[str, Any]] = []
        for item in prepared:
            case = item["case"]
            case_id = str(case.get("caseId") or "")
            truth = int(case.get("sourceAttackCount") or 0)
            omr_path = output_root / str(case.get("omrRelativePath") or "")
            if (
                not omr_path.exists()
                or _sha256_bytes(omr_path.read_bytes()) != str(case.get("omrSha256") or "")
            ):
                raise ExtractionWorkflowError("A source-score regression OMR artifact changed.")
            notehead_prediction: dict[str, Any] | None = None
            notehead_failure: str | None = None
            try:
                notehead_prediction = _audiveris_notehead_columns(omr_path)
            except ExtractionWorkflowError as exc:
                notehead_failure = type(exc).__name__
            candidate = candidates_by_case.get(case_id)
            vision_prediction = (candidate or {}).get("prediction") or None
            vision_count = (
                int(vision_prediction["attackCount"])
                if vision_prediction is not None
                else None
            )
            notehead_count = (
                int(notehead_prediction["columnCount"])
                if notehead_prediction is not None
                else None
            )
            results.append(
                {
                    "caseId": case_id,
                    "inputId": case.get("inputId"),
                    "scoreSystemId": case.get("scoreSystemId"),
                    "sourceAttackCount": truth,
                    "noteheadAttackCount": notehead_count,
                    "noteheadFailure": notehead_failure,
                    "visionAttackCount": vision_count,
                    "visionVisibleColumnCount": (
                        int(vision_prediction["visibleColumnCount"])
                        if vision_prediction is not None
                        else None
                    ),
                    "visionContinuationOnlyCount": (
                        int(vision_prediction["continuationOnlyCount"])
                        if vision_prediction is not None
                        else None
                    ),
                    "visionFailure": failures_by_case.get(case_id),
                    "noteheadExact": notehead_count == truth,
                    "visionExact": vision_count == truth,
                    "noteheadAbsoluteError": (
                        abs(notehead_count - truth) if notehead_count is not None else truth
                    ),
                    "visionAbsoluteError": (
                        abs(vision_count - truth) if vision_count is not None else truth
                    ),
                    "countConsensus": (
                        notehead_count is not None
                        and vision_count is not None
                        and notehead_count == vision_count
                    ),
                    "candidateDigest": (candidate or {}).get("candidateDigest"),
                }
            )

        def metrics(prefix: str) -> dict[str, int]:
            count_key = f"{prefix}AttackCount"
            return {
                "exactCount": sum(bool(item[f"{prefix}Exact"]) for item in results),
                "absoluteErrorIncludingFailuresAsZero": sum(
                    int(item[f"{prefix}AbsoluteError"]) for item in results
                ),
                "failureCount": sum(item.get(count_key) is None for item in results),
            }

        consensus = [item for item in results if item.get("countConsensus") is True]
        notehead_metrics = metrics("notehead")
        vision_metrics = metrics("vision")
        report_core = {
            "schemaVersion": SOURCE_SCORE_VISION_REGRESSION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "evaluationClass": "opened_discovery_regression_only",
            "benchmarkManifestDigest": benchmark_digest,
            "contract": contract,
            "contractDigest": contract_digest,
            "caseCount": len(results),
            "noteheadDetector": notehead_metrics,
            "visionReader": vision_metrics,
            "consensus": {
                "caseCount": len(consensus),
                "exactCount": sum(bool(item["visionExact"]) for item in consensus),
                "absoluteError": sum(int(item["visionAbsoluteError"]) for item in consensus),
            },
            "diagnosticGates": {
                "exactCountImproved": vision_metrics["exactCount"]
                > notehead_metrics["exactCount"],
                "absoluteErrorImproved": vision_metrics[
                    "absoluteErrorIncludingFailuresAsZero"
                ]
                < notehead_metrics["absoluteErrorIncludingFailuresAsZero"],
                "failureCountNotWorse": vision_metrics["failureCount"]
                <= notehead_metrics["failureCount"],
            },
            "results": results,
            "promotionEligible": False,
            "reviewPacketCreated": False,
            "humanApprovalCreated": False,
            "trainingStarted": False,
            "currentPageRecordsModified": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        report_path = benchmark_root / f"vision-regression-{report_digest[:12]}.json"
        _write_json(report_path, report)
        return {
            key: report[key]
            for key in (
                "schemaVersion",
                "batchId",
                "partition",
                "evaluationClass",
                "caseCount",
                "noteheadDetector",
                "visionReader",
                "consensus",
                "diagnosticGates",
                "promotionEligible",
                "reviewPacketCreated",
                "humanApprovalCreated",
                "trainingStarted",
                "currentPageRecordsModified",
                "validationAccessed",
                "sealedTestAccessed",
            )
        } | {
            "contractDigest": contract_digest,
            "reportDigest": report_digest,
            "reportPath": str(report_path.relative_to(output_root)),
        }

    def freeze_source_score_notehead_challenger_contract(
        self,
        batch_id: str,
    ) -> dict[str, Any]:
        """Freeze the exact development-passed detector before one shadow run."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        benchmark_root = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
        )
        benchmark_path = benchmark_root / "benchmark-manifest.json"
        if not benchmark_path.exists():
            raise ExtractionWorkflowError(
                "Freeze the source-score benchmark before selecting a challenger."
            )
        benchmark = _read_json(benchmark_path)
        benchmark_digest = str(benchmark.get("manifestDigest") or "")
        contract = {
            "detectorVersion": SOURCE_SCORE_NOTEHEAD_DETECTOR_VERSION,
            "mergeWidthFactor": SOURCE_SCORE_NOTEHEAD_MERGE_WIDTH_FACTOR,
            "source": "audiveris_internal_notehead_bounds",
            "clefRequired": False,
            "pitchesEmitted": False,
            "tablatureCountProvided": False,
            "tablaturePitchesProvided": False,
        }
        contract_digest = _sha256_json(contract)
        development_report_path = (
            benchmark_root / f"development-report-{contract_digest[:12]}.json"
        )
        if not development_report_path.exists():
            raise ExtractionWorkflowError(
                "Evaluate the current challenger on development before selecting it."
            )
        development_report = _read_json(development_report_path)
        if (
            development_report.get("benchmarkManifestDigest") != benchmark_digest
            or development_report.get("challengerContractDigest") != contract_digest
            or development_report.get("gatePassed") is not True
        ):
            raise ExtractionWorkflowError(
                "Only the exact development-passed challenger may be selected."
            )
        selected_contract_path = benchmark_root / "selected-contract.json"
        if selected_contract_path.exists():
            selection = _read_json(selected_contract_path)
            if (
                selection.get("benchmarkManifestDigest") != benchmark_digest
                or selection.get("challengerContractDigest") != contract_digest
                or selection.get("developmentReportDigest")
                != development_report.get("reportDigest")
            ):
                raise ExtractionWorkflowError(
                    "The source-score challenger contract is already frozen."
                )
        else:
            selection_core = {
                "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": "discovery",
                "benchmarkManifestDigest": benchmark_digest,
                "challengerContract": contract,
                "challengerContractDigest": contract_digest,
                "developmentReportDigest": development_report.get("reportDigest"),
                "selectedAt": _utc_now(),
                "validationAccessed": False,
                "sealedTestAccessed": False,
            }
            selection = {
                **selection_core,
                "selectionDigest": _sha256_json(selection_core),
            }
            _write_json(selected_contract_path, selection)
        return {
            "schemaVersion": SOURCE_SCORE_NOTEHEAD_BENCHMARK_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "benchmarkManifestDigest": benchmark_digest,
            "challengerContractDigest": contract_digest,
            "developmentReportDigest": development_report.get("reportDigest"),
            "selectionDigest": selection["selectionDigest"],
            "selectedContractPath": str(
                selected_contract_path.relative_to(output_root)
            ),
            "shadowAccessed": False,
            "reviewPacketCreated": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def prepare_review(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        limit: int = 25,
        prior_feedback_only: bool = False,
        never_reviewed_only: bool = False,
        current_extractor_only: bool = False,
        tab_pages_only: bool = False,
        passing_refresh_gate_only: bool = False,
    ) -> dict[str, Any]:
        if limit < 1 or limit > 100:
            raise ExtractionWorkflowError("Review packet limit must be between 1 and 100 pages.")
        batch_dir, _manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        summary_path = output_root / "summary.json"
        if not summary_path.exists():
            raise ExtractionWorkflowError("Extraction must finish before its human-review packet is prepared.")
        extraction_summary = _read_json(summary_path)
        current_rights_path = batch_dir / "rights-and-access.json"
        current_rights = _normalized_rights_and_access(
            _read_json(current_rights_path) if current_rights_path.exists() else None
        )
        extraction_version = str(extraction_summary.get("extractorVersion") or "")
        page_review_compatibility = _page_review_compatibility_version(extraction_version)
        if (
            page_review_compatibility is None
            or extraction_summary.get("decisionDerivationVersion") != DECISION_DERIVATION_VERSION
            or int(extraction_summary.get("processedCount") or 0) != len(work)
            or int(extraction_summary.get("failedPageCount") or 0) != 0
            or extraction_summary.get("rightsAuthorizationDigest")
            != current_rights.get("authorizationRecordDigest")
        ):
            raise ExtractionWorkflowError(
                "Human review requires one complete, failure-free, current-version extraction pinned to the current authorization."
            )
        projection_shadow_capture: dict[str, Any] | None = None
        projection_selection_path = (
            review_dir
            / "automation"
            / "source-score-notehead-challenger"
            / "selected-projection-contract.json"
        )
        hybrid_selection_path = (
            review_dir
            / "automation"
            / "source-score-notehead-challenger"
            / "selected-component-hybrid-contract.json"
        )
        if partition == "discovery" and (
            projection_selection_path.exists() or hybrid_selection_path.exists()
        ):
            # This must run before page-review-packet.jsonl or any per-page packet
            # is written. Prepared-but-unsubmitted packets count as exposure,
            # and capture refuses to fall back when either frozen selection is
            # missing.
            projection_shadow_capture = self.capture_source_score_projection_shadow(
                batch_id,
                limit=limit,
            )
        existing_index_path = review_dir / "approved-record-index.jsonl"
        existing_index = _read_jsonl(existing_index_path) if existing_index_path.exists() else []
        reviewed_input_ids = {str(item.get("inputId")) for item in existing_index if item.get("inputId")}
        feedback_log_path = review_dir / "human-review-feedback.jsonl"
        existing_feedback = _read_jsonl(feedback_log_path) if feedback_log_path.exists() else []
        feedback_by_input: dict[str, list[dict[str, Any]]] = {}
        for submission in existing_feedback:
            feedback_by_input.setdefault(str(submission.get("inputId") or ""), []).append(submission)

        def in_review_scope(input_id: str) -> bool:
            if input_id in reviewed_input_ids:
                return False
            if prior_feedback_only and input_id not in feedback_by_input:
                return False
            if never_reviewed_only and input_id in feedback_by_input:
                return False
            if current_extractor_only:
                page_path = pages_dir / f"{input_id}.json"
                if not page_path.exists():
                    return False
                current_record = _read_json(page_path)
                if str(current_record.get("extractorVersion") or "") != EXTRACTOR_VERSION:
                    return False
                if (
                    current_record.get("runDigest") != extraction_summary.get("runDigest")
                    and (current_record.get("unreviewedRefresh") or {}).get("schemaVersion")
                    != UNREVIEWED_REFRESH_SCHEMA_VERSION
                ):
                    return False
            if tab_pages_only:
                page_path = pages_dir / f"{input_id}.json"
                if not page_path.exists() or not _read_json(page_path).get("tabSystems"):
                    return False
            if passing_refresh_gate_only:
                page_path = pages_dir / f"{input_id}.json"
                if not page_path.exists():
                    return False
                current_record = _read_json(page_path)
                archive_dir = review_dir / "unreviewed-refresh-revisions" / input_id
                prior_record = next(
                    (
                        candidate
                        for candidate_path in sorted(archive_dir.glob("*.json"))
                        for candidate in [_read_json(candidate_path)]
                        if str(candidate.get("extractorVersion") or "")
                        != EXTRACTOR_VERSION
                    ),
                    None,
                )
                if prior_record is None or not _unreviewed_refresh_regression_gate(
                    prior_record, current_record
                )["passed"]:
                    return False
            return True

        packets: list[dict[str, Any]] = []
        total_remaining = len(work) - len(reviewed_input_ids)
        scope_remaining = sum(
            1
            for item in work
            if in_review_scope(str(item["inputId"]))
        )
        pending_feedback_page_count = 0
        for item in work:
            input_id = str(item["inputId"])
            if not in_review_scope(input_id):
                continue
            page_path = pages_dir / f"{input_id}.json"
            if not page_path.exists():
                raise ExtractionWorkflowError(f"Extraction record is missing for {input_id}.")
            record = _read_json(page_path)
            if (
                (
                    record.get("runDigest") != extraction_summary.get("runDigest")
                    and not (
                        current_extractor_only
                        and (record.get("unreviewedRefresh") or {}).get("schemaVersion")
                        == UNREVIEWED_REFRESH_SCHEMA_VERSION
                    )
                )
                or _page_review_compatibility_version(record.get("extractorVersion"))
                != page_review_compatibility
            ):
                raise ExtractionWorkflowError(f"Extraction record is stale or mixed-version for {input_id}.")
            record_digest = _sha256_json(record)
            if any(
                str(submission.get("machineRecordDigest") or "") == record_digest
                for submission in feedback_by_input.get(input_id, [])
            ):
                pending_feedback_page_count += 1
                continue
            unresolved = list(record.get("unresolved") or [])
            packets.append(
                {
                    "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "pageObjectId": record["objectId"],
                    "machineRevision": record["revision"],
                    "machineRecordDigest": record_digest,
                    "assetSha256": record["assetSha256"],
                    "extractionVersion": extraction_version,
                    "pageReviewCompatibilityVersion": page_review_compatibility,
                    "machineRecordPath": str(page_path.relative_to(output_root)),
                    "sourceImageRelativePath": record["provenance"]["imageFilename"],
                    "sourceLabel": Path(str(record["provenance"]["imageFilename"])).name,
                    "derivativeRelativePath": record["derivative"]["relativePath"],
                    "sourceCopedent": copy.deepcopy(record["sourceCopedent"]),
                    "coreCounts": _core_counts(record),
                    "hardBlockers": _hard_review_blockers(record),
                    "unresolvedItems": unresolved,
                    "unresolvedItemsExcludedFromTrainingUnlessCorrected": True,
                    "machineRecord": copy.deepcopy(record),
                    "priorFeedback": copy.deepcopy(feedback_by_input.get(input_id, [])),
                    "requiredApprovalSections": list(
                        CORE_APPROVAL_SECTIONS
                        if _score_tab_attack_counts_complete(record)
                        else TAB_ONLY_APPROVAL_SECTIONS
                    ),
                    "approvalScope": (
                        "complete_page"
                        if _score_tab_attack_counts_complete(record)
                        else "tab_only_score_audit_required"
                    ),
                    "scoreAuditRequired": not _score_tab_attack_counts_complete(record),
                    "decisionTemplate": {
                        "inputId": input_id,
                        "expectedMachineRecordDigest": record_digest,
                        "action": "accept | feedback | exclude",
                        "reviewerReference": None,
                        "approvedSections": [],
                        "eventFeedback": [],
                        "notes": None,
                    },
                }
            )
            if len(packets) == limit:
                break
        packet_path = review_dir / "page-review-packet.jsonl"
        _write_jsonl(packet_path, packets)
        packet_digest = _sha256_json(packets)
        packet_dir = review_dir / "packets"
        packet_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(packet_dir, 0o700)
        packet_index: list[dict[str, Any]] = []
        for packet in packets:
            packet_file = packet_dir / f"{packet['inputId']}.json"
            _write_json(packet_file, packet)
            packet_index.append(
                {
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": packet["inputId"],
                    "machineRecordDigest": packet["machineRecordDigest"],
                    "sourceLabel": packet["sourceLabel"],
                    "packetUrl": f"./packets/{packet['inputId']}.json",
                    "coreCounts": packet["coreCounts"],
                    "hardBlockerCount": len(packet["hardBlockers"]),
                    "unresolvedCount": len(packet["unresolvedItems"]),
                }
            )
        console_path = review_dir / "page-review-console.html"
        _write_private_text(
            console_path,
            _review_console_html(packet_index, packet_digest=packet_digest),
        )
        summary = {
            "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "reviewScope": "feedback_corrections" if prior_feedback_only else "all_available",
            "neverReviewedOnly": never_reviewed_only,
            "currentExtractorOnly": current_extractor_only,
            "tabPagesOnly": tab_pages_only,
            "passingRefreshGateOnly": passing_refresh_gate_only,
            "extractionVersion": extraction_version,
            "pageReviewCompatibilityVersion": page_review_compatibility,
            "totalPageCount": len(work),
            "alreadyReviewedPageCount": len(reviewed_input_ids),
            "remainingPageCount": total_remaining,
            "scopeRemainingPageCount": scope_remaining,
            "pendingFeedbackCorrectionPageCount": pending_feedback_page_count,
            "availableForReviewPageCount": scope_remaining - pending_feedback_page_count,
            "pageCount": len(packets),
            "deferredPageCount": max(0, scope_remaining - pending_feedback_page_count - len(packets)),
            "packetLimit": limit,
            "pageWithHardBlockerCount": sum(bool(packet["hardBlockers"]) for packet in packets),
            "unresolvedItemCount": sum(len(packet["unresolvedItems"]) for packet in packets),
            "packetDigest": packet_digest,
            "packetIndexDigest": _sha256_json(packet_index),
            "packetPath": str(packet_path.relative_to(batch_dir)),
            "packetDirectory": str(packet_dir.relative_to(batch_dir)),
            "reviewConsolePath": str(console_path.relative_to(batch_dir)),
            "reviewConsoleSha256": _sha256_bytes(console_path.read_bytes()),
            "projectionShadowCapture": projection_shadow_capture,
            "humanApprovalComplete": False,
            "sealedTestAccessed": False,
        }
        _write_json(review_dir / "page-review-packet-summary.json", summary)
        return summary

    def _complete_score_payload_from_measure_slices(
        self,
        *,
        prepared_path: Path,
        repair_root: Path,
        input_id: str,
        system_index: int,
        system_id: str,
        grid: GridDetection,
        tab_system: Mapping[str, Any],
        score_payload: dict[str, Any],
        base_reviewed_record_digest: str,
    ) -> list[dict[str, Any]]:
        """Retry only mismatched measures with a clef-bearing, enlarged OMR strip."""

        attack_events = [
            event
            for event in tab_system.get("tabEvents") or []
            if any(bool(action.get("attack", True)) for action in event.get("steelActions") or [])
        ]
        score_events = [event for event in score_payload.get("scoreEvents") or [] if not event.get("rest")]
        score_measures = sorted({int(event.get("measure") or 0) for event in score_events})
        tab_measures = sorted({int(event.get("measure") or 0) for event in attack_events})
        if not tab_measures:
            return []
        rebuild_all_measures = not score_measures or len(score_measures) != len(tab_measures)
        score_group_counts = Counter(
            int(measure)
            for measure, _beat in {
                (int(event.get("measure") or 0), round(float(event.get("beat") or 0.0), 6))
                for event in score_events
            }
        )
        tab_event_counts = Counter(int(event.get("measure") or 0) for event in attack_events)
        score_measure_targets = (
            list(range(1, len(tab_measures) + 1)) if rebuild_all_measures else score_measures
        )
        mismatched: list[tuple[int, int]] = []
        for score_measure, tab_measure in zip(score_measure_targets, tab_measures, strict=True):
            measure_score_events = [
                event
                for event in score_events
                if int(event.get("measure") or 0) == score_measure
            ]
            measure_tab_events = [
                event
                for event in attack_events
                if int(event.get("measure") or 0) == tab_measure
            ]
            measure_alignments = _align_events(measure_score_events, measure_tab_events)
            pitch_valid = len(measure_alignments) == len(measure_tab_events) and all(
                bool(alignment.get("notationAdjustedPitchAgreement"))
                for alignment in measure_alignments
            )
            if rebuild_all_measures or (
                score_group_counts[score_measure] != tab_event_counts[tab_measure]
                or not pitch_valid
            ):
                mismatched.append((score_measure, tab_measure))
        if not mismatched:
            return []
        tab_measure_geometry = {
            int(measure.get("measure") or 0): measure
            for measure in tab_system.get("measures") or []
        }
        first_tab_measure = tab_measures[0]
        first_geometry = tab_measure_geometry.get(first_tab_measure)
        if first_geometry is None:
            return []
        header_end = int(
            round(
                grid.x0
                + float(first_geometry.get("horizontalStart") or 0.0)
                * max(1, grid.x1 - grid.x0)
            )
        )
        first_attack_x = min(
            grid.x0
            + float(event.get("horizontalPosition") or 0.0) * max(1, grid.x1 - grid.x0)
            for event in attack_events
        )
        header_end = max(
            header_end,
            int(round(first_attack_x - grid.cell_height * 2.0)),
        )
        repairs: list[dict[str, Any]] = []
        successful_slices: dict[int, dict[str, Any]] = {}
        with Image.open(prepared_path) as opened:
            source_image = opened.convert("RGB")
        header_end = max(1, min(header_end, source_image.width - 1))
        for score_measure, tab_measure in mismatched:
            geometry = tab_measure_geometry.get(tab_measure)
            expected_events = [
                event for event in attack_events if int(event.get("measure") or 0) == tab_measure
            ]
            if geometry is None or not expected_events:
                continue
            measure_left = int(
                round(
                    grid.x0
                    + float(geometry.get("horizontalStart") or 0.0)
                    * max(1, grid.x1 - grid.x0)
                )
            )
            measure_right = int(
                round(
                    grid.x0
                    + float(geometry.get("horizontalEnd") or 1.0)
                    * max(1, grid.x1 - grid.x0)
                )
            )
            measure_row = next(
                (
                    measure
                    for measure in score_payload.get("measures") or []
                    if int(measure.get("measure") or 0) == score_measure
                ),
                None,
            )
            measure_position = score_measure_targets.index(score_measure)
            variant_specs = (
                ("wide", 2.0, False),
                ("tight", 0.35, False),
                ("tight-contrast", 0.35, True),
                ("medium-contrast", 0.85, True),
            )
            attempts: list[dict[str, Any]] = []
            accepted_slice: dict[str, Any] | None = None
            for variant_name, padding_scale, increase_contrast in variant_specs:
                boundary_padding = max(4, int(round(grid.cell_height * padding_scale)))
                variant_left = max(0, min(measure_left - boundary_padding, source_image.width - 1))
                variant_right = max(
                    variant_left + 1,
                    min(measure_right + boundary_padding, source_image.width),
                )
                if tab_measure == first_tab_measure:
                    first_left = max(0, variant_left - boundary_padding)
                    strip = source_image.crop((first_left, 0, variant_right, source_image.height))
                else:
                    strip = Image.new(
                        "RGB",
                        (header_end + variant_right - variant_left, source_image.height),
                        "white",
                    )
                    strip.paste(source_image.crop((0, 0, header_end, source_image.height)), (0, 0))
                    strip.paste(
                        source_image.crop((variant_left, 0, variant_right, source_image.height)),
                        (header_end, 0),
                    )
                strip = strip.resize(
                    (strip.width * 2, strip.height * 2),
                    Image.Resampling.LANCZOS,
                )
                if increase_contrast:
                    strip = ImageOps.autocontrast(strip.convert("L"), cutoff=1).convert("RGB")
                suffix = "" if variant_name == "wide" else f"-{variant_name}"
                strip_path = (
                    repair_root
                    / "measure-strips"
                    / input_id
                    / f"system-{system_index:02d}"
                    / (
                        f"measure-{tab_measure:03d}-{base_reviewed_record_digest[:16]}"
                        f"{suffix}.png"
                    )
                )
                strip_path.parent.mkdir(parents=True, exist_ok=True)
                os.chmod(strip_path.parent, 0o700)
                strip.save(strip_path, format="PNG")
                os.chmod(strip_path, 0o600)
                strip_digest = _sha256_bytes(strip_path.read_bytes())
                strip_output = (
                    repair_root
                    / "measure-omr-output"
                    / input_id
                    / f"system-{system_index:02d}"
                    / f"measure-{tab_measure:03d}-{strip_digest[:16]}"
                )
                try:
                    slice_payload = self.omr.read(
                        strip_path,
                        strip_output,
                        _stable_id("score-measure-repair", system_id, score_measure, strip_digest),
                    )
                except ExtractionWorkflowError as exc:
                    attempts.append(
                        {
                            "variant": variant_name,
                            "status": "slice_omr_failed",
                            "stripSha256": strip_digest,
                            "message": str(exc),
                        }
                    )
                    continue
                clef_normalization = _normalize_score_payload_clef(
                    slice_payload,
                    score_payload.get("clef"),
                )
                raw_music_xml_path = slice_payload.pop("_musicXmlPath", None)
                slice_events = list(slice_payload.get("scoreEvents") or [])
                playable_groups = {
                    (int(event.get("measure") or 0), round(float(event.get("beat") or 0.0), 6))
                    for event in slice_events
                    if not event.get("rest")
                }
                if len(playable_groups) != len(expected_events):
                    attempts.append(
                        {
                            "variant": variant_name,
                            "status": "slice_group_count_mismatch",
                            "stripSha256": strip_digest,
                            "recognizedAttackCount": len(playable_groups),
                            "clefNormalization": clef_normalization,
                        }
                    )
                    continue
                slice_measure_row = next(iter(slice_payload.get("measures") or []), {})
                measure_duration = float(
                    (measure_row or {}).get("durationBeats")
                    or slice_measure_row.get("durationBeats")
                    or 4.0
                )
                rhythmic_start = float(
                    (measure_row or {}).get("rhythmicStart")
                    if measure_row is not None
                    else measure_position * measure_duration
                )
                remapped_events: list[dict[str, Any]] = []
                for event_index, event in enumerate(slice_events, start=1):
                    remapped = copy.deepcopy(event)
                    remapped["measure"] = score_measure
                    remapped["rhythmicPosition"] = round(
                        rhythmic_start + max(0.0, float(remapped.get("beat") or 1.0) - 1.0),
                        6,
                    )
                    remapped["scoreEventId"] = _stable_id(
                        "score-event",
                        system_id,
                        score_measure,
                        remapped.get("beat"),
                        event_index,
                        remapped.get("pitch"),
                        bool(remapped.get("rest")),
                    )
                    remapped_events.append(remapped)
                proposed_events = (
                    remapped_events
                    if rebuild_all_measures
                    else [
                        event
                        for event in score_payload.get("scoreEvents") or []
                        if int(event.get("measure") or 0) != score_measure
                    ]
                    + remapped_events
                )
                ordered_events = sorted(
                    proposed_events,
                    key=lambda event: (
                        int(event.get("measure") or 0),
                        float(event.get("beat") or 0.0),
                        int(event.get("voice") or 1),
                        str(event.get("pitch") or ""),
                    ),
                )
                measure_events = [
                    event
                    for event in ordered_events
                    if int(event.get("measure") or 0) == score_measure and not event.get("rest")
                ]
                proposed_alignments = _align_events(measure_events, expected_events)
                if len(proposed_alignments) != len(expected_events) or not all(
                    bool(alignment.get("notationAdjustedPitchAgreement"))
                    for alignment in proposed_alignments
                ):
                    attempts.append(
                        {
                            "variant": variant_name,
                            "status": "slice_pitch_validation_failed",
                            "stripSha256": strip_digest,
                            "recognizedAttackCount": len(playable_groups),
                            "clefNormalization": clef_normalization,
                        }
                    )
                    continue
                attempts.append(
                    {
                        "variant": variant_name,
                        "status": "slice_validation_passed",
                        "stripSha256": strip_digest,
                        "recognizedAttackCount": len(playable_groups),
                        "clefNormalization": clef_normalization,
                    }
                )
                accepted_slice = {
                    "slicePayload": slice_payload,
                    "rawMusicXmlPath": raw_music_xml_path,
                    "sliceMeasureRow": slice_measure_row,
                    "measureDuration": measure_duration,
                    "rhythmicStart": rhythmic_start,
                    "remappedEvents": remapped_events,
                    "orderedEvents": ordered_events,
                    "playableGroupCount": len(playable_groups),
                    "stripSha256": strip_digest,
                    "variant": variant_name,
                    "clefNormalization": clef_normalization,
                }
                break
            if accepted_slice is None:
                repeated_glyph_repair = (
                    _repair_repeated_score_glyph(
                        score_payload=score_payload,
                        score_measure=score_measure,
                        tab_events=expected_events,
                        source_image=source_image,
                        staff_lines=_detect_score_staff_lines(
                            np.asarray(source_image.convert("L"))
                        ),
                        grid=grid,
                        system_id=system_id,
                    )
                    if not rebuild_all_measures
                    else None
                )
                if repeated_glyph_repair is not None:
                    repairs.append(
                        {
                            "scoreMeasure": score_measure,
                            "tabMeasure": tab_measure,
                            "status": "repeated_source_glyph_repair_applied",
                            "expectedAttackCount": len(expected_events),
                            "attempts": attempts,
                            "repeatedSourceGlyphRepair": repeated_glyph_repair,
                        }
                    )
                    continue
                last_attempt = attempts[-1] if attempts else {"status": "slice_omr_failed"}
                repairs.append(
                    {
                        "scoreMeasure": score_measure,
                        "tabMeasure": tab_measure,
                        "status": last_attempt["status"],
                        "expectedAttackCount": len(expected_events),
                        "recognizedAttackCount": last_attempt.get("recognizedAttackCount"),
                        "stripSha256": last_attempt.get("stripSha256"),
                        "attempts": attempts,
                    }
                )
                continue
            slice_payload = accepted_slice["slicePayload"]
            raw_music_xml_path = accepted_slice["rawMusicXmlPath"]
            slice_measure_row = accepted_slice["sliceMeasureRow"]
            measure_duration = float(accepted_slice["measureDuration"])
            rhythmic_start = float(accepted_slice["rhythmicStart"])
            remapped_events = accepted_slice["remappedEvents"]
            ordered_events = accepted_slice["orderedEvents"]
            playable_group_count = int(accepted_slice["playableGroupCount"])
            strip_digest = str(accepted_slice["stripSha256"])
            if rebuild_all_measures:
                successful_slices[score_measure] = {
                    "payload": copy.deepcopy(slice_payload),
                    "events": remapped_events,
                    "rhythmicStart": rhythmic_start,
                    "durationBeats": measure_duration,
                }
            else:
                score_payload["scoreEvents"] = ordered_events
                replacement_measure = copy.deepcopy(dict(slice_measure_row))
                replacement_measure.update(
                    {
                        "measureId": _stable_id("measure", system_id, 1, score_measure),
                        "measure": score_measure,
                        "printedMeasureNumber": str(score_measure),
                        "rhythmicStart": rhythmic_start,
                        "durationBeats": measure_duration,
                    }
                )
                score_payload["measures"] = sorted(
                    [
                        item
                        for item in score_payload.get("measures") or []
                        if int(item.get("measure") or 0) != score_measure
                    ]
                    + [replacement_measure],
                    key=lambda item: int(item.get("measure") or 0),
                )
            repairs.append(
                {
                    "scoreMeasure": score_measure,
                    "tabMeasure": tab_measure,
                    "status": "slice_repair_applied",
                    "expectedAttackCount": len(expected_events),
                    "recognizedAttackCount": playable_group_count,
                    "stripSha256": strip_digest,
                    "selectedVariant": accepted_slice["variant"],
                    "clefNormalization": accepted_slice["clefNormalization"],
                    "attempts": attempts,
                    "musicXmlSha256": (
                        _sha256_bytes(Path(str(raw_music_xml_path)).read_bytes())
                        if raw_music_xml_path
                        else None
                    ),
                }
            )
        if rebuild_all_measures and len(successful_slices) == len(score_measure_targets):
            rebuilt_events: list[dict[str, Any]] = []
            rebuilt_measures: list[dict[str, Any]] = []
            rebuilt_chords: list[dict[str, Any]] = []
            rebuilt_tempos: list[dict[str, Any]] = []
            rebuilt_repeats: list[dict[str, Any]] = []
            rhythmic_start = 0.0
            for score_measure in score_measure_targets:
                item = successful_slices[score_measure]
                slice_payload = item["payload"]
                duration_beats = float(item["durationBeats"])
                slice_measure = copy.deepcopy(dict(next(iter(slice_payload.get("measures") or []), {})))
                slice_measure.update(
                    {
                        "measureId": _stable_id("measure", system_id, 1, score_measure),
                        "measure": score_measure,
                        "printedMeasureNumber": str(score_measure),
                        "rhythmicStart": rhythmic_start,
                        "durationBeats": duration_beats,
                    }
                )
                rebuilt_measures.append(slice_measure)
                for event in item["events"]:
                    rebuilt = copy.deepcopy(event)
                    rebuilt["rhythmicPosition"] = round(
                        rhythmic_start + max(0.0, float(rebuilt.get("beat") or 1.0) - 1.0),
                        6,
                    )
                    rebuilt_events.append(rebuilt)
                for key, target in (
                    ("chordContexts", rebuilt_chords),
                    ("tempoMarkings", rebuilt_tempos),
                    ("repeatStructures", rebuilt_repeats),
                ):
                    for source_item in slice_payload.get(key) or []:
                        remapped_item = copy.deepcopy(source_item)
                        remapped_item["measure"] = score_measure
                        target.append(remapped_item)
                rhythmic_start += duration_beats
            score_payload["scoreEvents"] = sorted(
                rebuilt_events,
                key=lambda event: (
                    int(event.get("measure") or 0),
                    float(event.get("beat") or 0.0),
                    int(event.get("voice") or 1),
                    str(event.get("pitch") or ""),
                ),
            )
            score_payload["measures"] = rebuilt_measures
            score_payload["chordContexts"] = rebuilt_chords
            score_payload["tempoMarkings"] = rebuilt_tempos
            score_payload["repeatStructures"] = rebuilt_repeats
            first_payload = successful_slices[score_measure_targets[0]]["payload"]
            score_payload["keyFifths"] = first_payload.get(
                "keyFifths", score_payload.get("keyFifths")
            )
            score_payload["timeSignature"] = first_payload.get(
                "timeSignature", score_payload.get("timeSignature")
            )
            repairs.append(
                {
                    "status": "full_system_rebuilt_from_validated_measure_slices",
                    "measureCount": len(rebuilt_measures),
                    "scoreMeasures": score_measure_targets,
                    "tabMeasures": tab_measures,
                }
            )
        elif rebuild_all_measures:
            repairs.append(
                {
                    "status": "full_system_rebuild_incomplete",
                    "expectedMeasureCount": len(score_measure_targets),
                    "validatedMeasureCount": len(successful_slices),
                }
            )
        return repairs

    def _build_score_repair_candidate(
        self,
        *,
        output_root: Path,
        input_id: str,
        base_record: Mapping[str, Any],
        base_reviewed_record_digest: str,
        prior_review_decision_id: str | None,
    ) -> dict[str, Any]:
        candidate = copy.deepcopy(dict(base_record))
        reviewed_tab_facts_digest = _reviewed_tab_facts_digest(base_record)
        tab_by_id = {
            str(system.get("tabSystemId") or ""): system
            for system in candidate.get("tabSystems") or []
        }
        repair_root = output_root / "review" / "score-audit" / "repair"
        repaired_systems: list[dict[str, Any]] = []
        for system in candidate.get("scoreSystems") or []:
            repaired = copy.deepcopy(dict(system))
            system_index = int(repaired.get("systemIndex") or 0)
            paired_tab_id = str(repaired.get("pairedTabSystemId") or "")
            paired_tab = tab_by_id.get(paired_tab_id)
            if paired_tab is None:
                raise ExtractionWorkflowError(
                    f"Score repair found no reviewed paired tab system for {input_id} system {system_index}."
                )
            score_crop_path = (
                output_root / "score-crops" / input_id / f"score-system-{system_index:02d}.png"
            )
            if not score_crop_path.exists():
                raise ExtractionWorkflowError(
                    f"The immutable score crop is missing for {input_id} system {system_index}."
                )
            source_crop_digest = _sha256_bytes(score_crop_path.read_bytes())
            recorded_crop_digest = str(repaired.get("cropSha256") or "")
            repair_source_crop: dict[str, Any] = {
                "relativePath": str(score_crop_path.relative_to(output_root)),
                "sha256": source_crop_digest,
                "recordedCropSha256": recorded_crop_digest or None,
                "reconstructedFromReviewedRegion": False,
            }
            if source_crop_digest != recorded_crop_digest:
                derivative_relative_path = str(
                    (candidate.get("derivative") or {}).get("relativePath") or ""
                )
                derivative_path = (output_root / derivative_relative_path).resolve()
                if (
                    not derivative_relative_path
                    or output_root.resolve() not in derivative_path.parents
                    or not derivative_path.exists()
                ):
                    raise ExtractionWorkflowError(
                        f"The approved derivative needed to rebuild the score crop is missing for {input_id}."
                    )
                region = repaired.get("pageRegion") or {}
                with Image.open(derivative_path) as opened:
                    derivative_image = opened.convert("RGB")
                left = int(round(float(region.get("x") or 0.0) * derivative_image.width))
                top = int(round(float(region.get("y") or 0.0) * derivative_image.height))
                right = int(
                    round(
                        (float(region.get("x") or 0.0) + float(region.get("width") or 0.0))
                        * derivative_image.width
                    )
                )
                bottom = int(
                    round(
                        (float(region.get("y") or 0.0) + float(region.get("height") or 0.0))
                        * derivative_image.height
                    )
                )
                left = max(0, min(left, derivative_image.width - 1))
                top = max(0, min(top, derivative_image.height - 1))
                right = max(left + 1, min(right, derivative_image.width))
                bottom = max(top + 1, min(bottom, derivative_image.height))
                rebuilt_crop = derivative_image.crop((left, top, right, bottom))
                rebuilt_path = (
                    repair_root
                    / "source-crops"
                    / input_id
                    / f"system-{system_index:02d}"
                    / f"{base_reviewed_record_digest[:16]}.png"
                )
                rebuilt_path.parent.mkdir(parents=True, exist_ok=True)
                os.chmod(rebuilt_path.parent, 0o700)
                rebuilt_crop.save(rebuilt_path, format="PNG")
                os.chmod(rebuilt_path, 0o600)
                score_crop_path = rebuilt_path
                source_crop_digest = _sha256_bytes(score_crop_path.read_bytes())
                repair_source_crop = {
                    "relativePath": str(score_crop_path.relative_to(output_root)),
                    "sha256": source_crop_digest,
                    "recordedCropSha256": recorded_crop_digest or None,
                    "supersededDerivedCropSha256": repair_source_crop["sha256"],
                    "derivativeSha256": _sha256_bytes(derivative_path.read_bytes()),
                    "reviewedPageRegion": copy.deepcopy(region),
                    "reconstructedFromReviewedRegion": True,
                }
            repaired["cropSha256"] = source_crop_digest
            repaired["scoreRepairSourceCrop"] = repair_source_crop
            grid = _grid_from_reviewed_tab_system(candidate, paired_tab)
            prepared_path = (
                repair_root
                / "omr-prepared"
                / input_id
                / f"system-{system_index:02d}"
                / f"{base_reviewed_record_digest[:16]}.png"
            )
            prepared = _prepare_score_omr_crop(
                score_crop_path,
                prepared_path,
                grid=grid,
                tab_events=paired_tab.get("tabEvents") or [],
            )
            prepared["relativePath"] = str(prepared_path.relative_to(output_root))
            omr_output = (
                repair_root
                / "omr-output"
                / input_id
                / f"system-{system_index:02d}"
                / str(prepared["sha256"])[:16]
            )
            payload = self.omr.read(
                prepared_path,
                omr_output,
                str(repaired.get("scoreSystemId") or ""),
            )
            raw_music_xml_path = payload.pop("_musicXmlPath", None)
            raw_omr_path = payload.pop("_omrPath", None)
            if not raw_music_xml_path:
                raise ExtractionWorkflowError(
                    f"Score repair produced no MusicXML path for {input_id} system {system_index}."
                )
            music_xml_path = Path(str(raw_music_xml_path)).resolve()
            if output_root.resolve() not in music_xml_path.parents:
                raise ExtractionWorkflowError("A repaired MusicXML path escaped the private extraction root.")
            head_graph_recovery: dict[str, Any] | None = None
            if raw_omr_path:
                omr_path = Path(str(raw_omr_path)).resolve()
                if output_root.resolve() not in omr_path.parents:
                    raise ExtractionWorkflowError(
                        "A repaired Audiveris graph path escaped the private extraction root."
                    )
                try:
                    graph_payload = _parse_audiveris_head_graph(
                        omr_path,
                        str(repaired.get("scoreSystemId") or ""),
                    )
                except (ExtractionWorkflowError, zipfile.BadZipFile, ET.ParseError):
                    graph_payload = None
                attack_tab_events = [
                    event
                    for event in paired_tab.get("tabEvents") or []
                    if any(
                        action.get("attack", True) is not False
                        for action in event.get("steelActions") or []
                    )
                ]
                graph_groups = (
                    _score_attack_groups(graph_payload.get("scoreEvents") or [])
                    if graph_payload is not None
                    else []
                )
                exported_groups = _score_attack_groups(payload.get("scoreEvents") or [])

                def pitch_sets(
                    groups: Sequence[Sequence[Mapping[str, Any]]],
                ) -> list[set[int]]:
                    return [
                        {
                            int(event["pitchValue"])
                            for event in group
                            if event.get("pitchValue") is not None
                        }
                        for group in groups
                    ]

                graph_pitch_sets = pitch_sets(graph_groups)
                exported_pitch_sets = pitch_sets(exported_groups)
                exported_prefix_agrees = bool(exported_pitch_sets) and (
                    exported_pitch_sets
                    == graph_pitch_sets[: len(exported_pitch_sets)]
                )
                graph_positions = [
                    sum(float(event["defaultX"]) for event in group) / len(group)
                    for group in graph_groups
                    if group and all(event.get("defaultX") is not None for event in group)
                ]
                tab_positions = [
                    float(event.get("horizontalPosition") or 0.0)
                    for event in attack_tab_events
                ]

                def normalize(values: Sequence[float]) -> list[float]:
                    if not values:
                        return []
                    low, high = min(values), max(values)
                    if high <= low:
                        return [0.0 for _value in values]
                    return [(value - low) / (high - low) for value in values]

                normalized_graph = normalize(graph_positions)
                normalized_tab = normalize(tab_positions)
                position_errors = [
                    abs(left - right)
                    for left, right in zip(normalized_graph, normalized_tab, strict=True)
                ] if len(normalized_graph) == len(normalized_tab) else []
                geometry_agrees = bool(position_errors) and (
                    float(np.mean(position_errors)) <= 0.08
                    and max(position_errors) <= 0.16
                )
                if (
                    graph_payload is not None
                    and len(graph_groups) == len(attack_tab_events)
                    and len(graph_positions) == len(graph_groups)
                    and exported_prefix_agrees
                    and geometry_agrees
                ):
                    recovery_mode = "cross_check_complete_export"
                    if len(exported_groups) < len(graph_groups):
                        recovery_mode = "recover_omitted_exported_attacks"
                        graph_events = copy.deepcopy(graph_payload.get("scoreEvents") or [])
                        graph_event_groups = _score_attack_groups(graph_events)
                        for graph_group, tab_event in zip(
                            graph_event_groups,
                            attack_tab_events,
                            strict=True,
                        ):
                            for graph_event in graph_group:
                                graph_event["measure"] = int(tab_event.get("measure") or 1)
                                graph_event["beat"] = float(tab_event.get("beat") or 1.0)
                                graph_event["rhythmicPosition"] = float(
                                    tab_event.get("rhythmicPosition")
                                    if tab_event.get("rhythmicPosition") is not None
                                    else graph_event.get("rhythmicPosition") or 0.0
                                )
                                graph_event["measureAlignmentEvidenceClass"] = (
                                    "deterministic_derivation"
                                )
                                graph_event["measureInheritedFromReviewedTabGeometry"] = True
                        payload["scoreEvents"] = graph_events
                        occupied_measures = sorted(
                            {
                                int(event.get("measure") or 1)
                                for event in graph_events
                            }
                        )
                        payload["measures"] = [
                            {
                                "measureId": _stable_id(
                                    "measure-head-graph",
                                    str(repaired.get("scoreSystemId") or ""),
                                    measure,
                                ),
                                "measure": measure,
                                "printedMeasureNumber": None,
                                "partIndex": 1,
                                "rhythmicStart": 0.0,
                                "durationBeats": float(
                                    max(
                                        (
                                            event.get("beat") or 1.0
                                            for event in graph_events
                                            if int(event.get("measure") or 1) == measure
                                        ),
                                        default=1.0,
                                    )
                                ),
                                "durationEvidenceClass": "unknown_or_unresolved",
                                "rhythmPlaceholder": True,
                                "keyFifths": payload.get("keyFifths"),
                                "timeSignature": copy.deepcopy(payload.get("timeSignature")),
                                "repeatDirections": [],
                                "endings": [],
                                "measureAlignmentEvidenceClass": "deterministic_derivation",
                                "measureInheritedFromReviewedTabGeometry": True,
                                "evidenceClass": "direct_visual_observation",
                                "confidence": min(
                                    float(event.get("confidence") or 0.0)
                                    for event in graph_events
                                ),
                                "reviewState": "needs_human_review",
                            }
                            for measure in occupied_measures
                        ]
                        for key in (
                            "chordContexts",
                            "tempoMarkings",
                            "repeatStructures",
                        ):
                            payload[key] = copy.deepcopy(graph_payload.get(key) or [])
                        payload["clef"] = copy.deepcopy(
                            graph_payload.get("clef") or payload.get("clef")
                        )
                    head_graph_recovery = {
                        **copy.deepcopy(graph_payload.get("headGraph") or {}),
                        "mode": recovery_mode,
                        "omrSha256": _sha256_bytes(omr_path.read_bytes()),
                        "exportedAttackCount": len(exported_groups),
                        "recoveredAttackCount": len(graph_groups),
                        "expectedTabAttackCount": len(attack_tab_events),
                        "exportedPrefixAgreement": True,
                        "meanNormalizedPositionError": round(
                            float(np.mean(position_errors)), 6
                        ),
                        "maxNormalizedPositionError": round(max(position_errors), 6),
                        "sourceOnly": True,
                        "tablaturePitchesProvided": False,
                    }
            measure_slice_repairs = self._complete_score_payload_from_measure_slices(
                prepared_path=prepared_path,
                repair_root=repair_root,
                input_id=input_id,
                system_index=system_index,
                system_id=str(repaired.get("scoreSystemId") or ""),
                grid=grid,
                tab_system=paired_tab,
                score_payload=payload,
                base_reviewed_record_digest=base_reviewed_record_digest,
            )
            normalized_score_digest = _sha256_json(
                {
                    key: payload.get(key)
                    for key in (
                        "measures",
                        "scoreEvents",
                        "chordContexts",
                        "tempoMarkings",
                        "repeatStructures",
                        "keyFifths",
                        "timeSignature",
                        "clef",
                    )
                }
            )
            normalized_music_xml_path = (
                repair_root
                / "normalized-musicxml"
                / input_id
                / f"system-{system_index:02d}"
                / f"{normalized_score_digest}.musicxml"
            )
            normalized_music_xml = _write_normalized_score_musicxml(
                payload,
                normalized_music_xml_path,
            )
            normalized_music_xml["relativePath"] = str(
                normalized_music_xml_path.relative_to(output_root)
            )
            for key in (
                "measures",
                "scoreEvents",
                "chordContexts",
                "tempoMarkings",
                "repeatStructures",
                "keyFifths",
                "timeSignature",
                "clef",
            ):
                repaired[key] = copy.deepcopy(payload.get(key))
            repaired["omrPreparedDerivative"] = prepared
            repaired["omrPreparedDerivative"]["measureSliceRepairs"] = measure_slice_repairs
            if head_graph_recovery is not None:
                repaired["omrPreparedDerivative"]["headGraphRecovery"] = head_graph_recovery
            repaired["recognizedMusicXml"] = {
                "relativePath": str(music_xml_path.relative_to(output_root.resolve())),
                "sha256": _sha256_bytes(music_xml_path.read_bytes()),
                "format": music_xml_path.suffix.lower().lstrip("."),
                "reader": "audiveris-musicxml-v1",
                "repairVersion": SCORE_REPAIR_VERSION,
            }
            repaired["musicXml"] = {
                **normalized_music_xml,
                "repairVersion": SCORE_REPAIR_VERSION,
                "normalizedScoreFactsDigest": normalized_score_digest,
                "recognizedMusicXmlSha256": repaired["recognizedMusicXml"]["sha256"],
            }
            repaired["omrStatus"] = "score_repair_candidate"
            repaired["reviewState"] = "needs_human_review"
            for measure in repaired.get("measures") or []:
                measure["reviewState"] = "needs_human_review"
            for event in repaired.get("scoreEvents") or []:
                event["reviewState"] = "needs_human_review"
            for chord in repaired.get("chordContexts") or []:
                chord["reviewState"] = "needs_human_review"
            for tempo in repaired.get("tempoMarkings") or []:
                tempo["reviewState"] = "needs_human_review"
            for repeat in repaired.get("repeatStructures") or []:
                repeat["reviewState"] = "needs_human_review"
            repaired_systems.append(repaired)
        candidate["scoreSystems"] = repaired_systems

        alignment_candidates: list[dict[str, Any]] = []
        for score_system in repaired_systems:
            paired_tab = tab_by_id[str(score_system.get("pairedTabSystemId") or "")]
            alignment_candidates.extend(
                _align_events(
                    score_system.get("scoreEvents") or [],
                    paired_tab.get("tabEvents") or [],
                )
            )
        alignments, alignment_unresolved = _separate_verified_alignments(alignment_candidates)
        candidate["eventAlignments"] = alignments
        remaining_unresolved = [
            copy.deepcopy(item)
            for item in candidate.get("unresolved") or []
            if item.get("kind")
            not in {
                "score_omr_failure",
                "unverified_score_tab_alignment",
            }
        ]
        candidate["unresolved"] = remaining_unresolved + [
            {**copy.deepcopy(item), "inputId": item.get("inputId") or input_id}
            for item in alignment_unresolved
        ]
        actions = [
            action
            for system in candidate.get("tabSystems") or []
            for event in system.get("tabEvents") or []
            for action in event.get("steelActions") or []
        ]
        candidate["validationSummary"] = {
            **copy.deepcopy(candidate.get("validationSummary") or {}),
            "steelActionCount": len(actions),
            "mechanicallyValidCount": sum(
                bool(action.get("mechanicalValidation", {}).get("valid")) for action in actions
            ),
            "soundingPitchAgreementCount": sum(
                bool(alignment.get("soundingPitchAgreement")) for alignment in alignments
            ),
            "notationAdjustedPitchAgreementCount": sum(
                bool(alignment.get("notationAdjustedPitchAgreement")) for alignment in alignments
            ),
            "alignmentCount": len(alignments),
            "provenanceComplete": True,
            "rightsAndAccessComplete": True,
        }
        candidate["revision"] = int(base_record.get("revision") or 1) + 1
        candidate["reviewState"] = "needs_human_review"
        candidate["humanApprovalComplete"] = False
        candidate["scoreRepair"] = {
            "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
            "repairVersion": SCORE_REPAIR_VERSION,
            "baseReviewedRecordDigest": base_reviewed_record_digest,
            "priorReviewDecisionId": prior_review_decision_id,
            "reviewedTabFactsDigest": reviewed_tab_facts_digest,
            "repairedAt": _utc_now(),
            "scoreSystemCount": len(repaired_systems),
            "priorTabApprovalPreserved": True,
            "humanScoreAuditRequired": True,
        }
        if _reviewed_tab_facts_digest(candidate) != reviewed_tab_facts_digest:
            raise ExtractionWorkflowError(f"Score repair changed reviewed tab facts for {input_id}.")
        diagnostics = _score_audit_diagnostics(candidate)
        gates = _score_audit_equivalence_gates(candidate, diagnostics)
        candidate_digest = _sha256_json(candidate)
        candidate_path = (
            repair_root / "candidate-records" / input_id / f"{candidate_digest}.json"
        )
        if candidate_path.exists():
            if _sha256_json(_read_json(candidate_path)) != candidate_digest:
                raise ExtractionWorkflowError(f"An existing score-repair candidate changed for {input_id}.")
        else:
            _write_json(candidate_path, candidate)
        return {
            "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
            "repairVersion": SCORE_REPAIR_VERSION,
            "batchId": candidate.get("batchId"),
            "partition": candidate.get("datasetPartition"),
            "inputId": input_id,
            "status": "candidate_ready",
            "baseReviewedRecordDigest": base_reviewed_record_digest,
            "priorReviewDecisionId": prior_review_decision_id,
            "reviewedTabFactsDigest": reviewed_tab_facts_digest,
            "candidateRecordPath": str(candidate_path.relative_to(output_root)),
            "candidateRecordDigest": candidate_digest,
            "scoreSystemCount": len(repaired_systems),
            "allGatesPassed": bool(gates) and all(
                bool(gate.get("readyForHumanReview")) for gate in gates.values()
            ),
            "scoreAuditGatesBySystem": gates,
            "priorTabApprovalPreserved": True,
            "sealedTestAccessed": False,
        }

    def repair_score_audit(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        workers: int = 1,
        limit: int = 100,
        input_ids: Sequence[str] | None = None,
    ) -> dict[str, Any]:
        """Build score-only candidates for the current internal repair queue."""

        if workers < 1 or workers > 4:
            raise ExtractionWorkflowError("Score-repair workers must be between 1 and 4.")
        if limit < 1 or limit > 100:
            raise ExtractionWorkflowError("Score-repair page limit must be between 1 and 100.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        audit_dir = review_dir / "score-audit"
        queue_path = audit_dir / "score-audit-repair-queue.jsonl"
        if not queue_path.exists():
            raise ExtractionWorkflowError("Prepare the score-audit repair queue before running score repair.")
        queued_by_input = {
            str(item.get("inputId") or ""): item
            for item in _read_jsonl(queue_path)
            if item.get("inputId")
        }
        prior_packet_path = audit_dir / "score-audit-packet.jsonl"
        if prior_packet_path.exists():
            for item in _read_jsonl(prior_packet_path):
                input_id = str(item.get("inputId") or "")
                if input_id and input_id not in queued_by_input:
                    queued_by_input[input_id] = {
                        "inputId": input_id,
                        "repairState": "refresh_prior_gate_passed_candidate",
                    }
        requested_input_ids = {str(value).strip() for value in input_ids or [] if str(value).strip()}
        missing_input_ids = sorted(requested_input_ids - set(queued_by_input))
        if missing_input_ids:
            raise ExtractionWorkflowError(
                "The requested score-repair input is not in the current queue: "
                + ", ".join(missing_input_ids)
            )
        queued_keys = sorted(requested_input_ids or queued_by_input)
        queued = [queued_by_input[key] for key in queued_keys][:limit]
        if not queued:
            raise ExtractionWorkflowError("The current score-audit repair queue is empty.")
        approved_entries = {
            str(item.get("inputId") or ""): item
            for item in _read_jsonl(review_dir / "approved-record-index.jsonl")
            if item.get("status") == "human_approved"
        }
        repair_root = audit_dir / "repair"
        index_path = repair_root / "score-repair-index.jsonl"
        existing_index = _read_jsonl(index_path) if index_path.exists() else []

        def repair_one(queue_item: Mapping[str, Any]) -> dict[str, Any]:
            input_id = str(queue_item.get("inputId") or "")
            approved = approved_entries.get(input_id)
            if approved is None:
                raise ExtractionWorkflowError(f"The score-repair queue references unapproved {input_id!r}.")
            relative_path = str(approved.get("reviewedRecordPath") or "")
            reviewed_path = output_root / relative_path
            if not relative_path or not reviewed_path.exists():
                raise ExtractionWorkflowError(f"The approved record is missing for {input_id}.")
            base_record = _read_json(reviewed_path)
            base_digest = _sha256_json(base_record)
            if base_digest != str(approved.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError(f"The approved record digest changed for {input_id}.")
            current = _score_repair_candidate(
                output_root,
                input_id=input_id,
                base_reviewed_record_digest=base_digest,
            )
            if current is not None:
                return {**copy.deepcopy(current[2]), "reused": True}
            return self._build_score_repair_candidate(
                output_root=output_root,
                input_id=input_id,
                base_record=base_record,
                base_reviewed_record_digest=base_digest,
                prior_review_decision_id=str(approved.get("reviewDecisionId") or "") or None,
            )

        results_by_input: dict[str, dict[str, Any]] = {}
        failures: list[dict[str, Any]] = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {
                executor.submit(repair_one, item): str(item.get("inputId") or "")
                for item in queued
            }
            for future in concurrent.futures.as_completed(futures):
                input_id = futures[future]
                try:
                    results_by_input[input_id] = future.result()
                except Exception as exc:
                    failures.append(
                        {
                            "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
                            "repairVersion": SCORE_REPAIR_VERSION,
                            "batchId": batch_id,
                            "partition": partition,
                            "inputId": input_id,
                            "status": "repair_failed",
                            "message": str(exc),
                            "priorTabApprovalPreserved": True,
                            "sealedTestAccessed": False,
                        }
                    )
        new_entries = [results_by_input[key] for key in sorted(results_by_input)] + sorted(
            failures,
            key=lambda item: str(item.get("inputId") or ""),
        )
        existing_keys = {
            (
                str(item.get("inputId") or ""),
                str(item.get("baseReviewedRecordDigest") or ""),
                str(item.get("candidateRecordDigest") or ""),
                str(item.get("status") or ""),
            )
            for item in existing_index
        }
        combined_index = existing_index + [
            item
            for item in new_entries
            if (
                str(item.get("inputId") or ""),
                str(item.get("baseReviewedRecordDigest") or ""),
                str(item.get("candidateRecordDigest") or ""),
                str(item.get("status") or ""),
            )
            not in existing_keys
        ]
        _write_jsonl(index_path, combined_index)
        candidates = [item for item in new_entries if item.get("status") == "candidate_ready"]
        summary = {
            "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
            "repairVersion": SCORE_REPAIR_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "queuedPageCount": len(queued),
            "candidateReadyPageCount": len(candidates),
            "gatePassedPageCount": sum(bool(item.get("allGatesPassed")) for item in candidates),
            "stillBlockedPageCount": sum(not bool(item.get("allGatesPassed")) for item in candidates),
            "repairFailedPageCount": len(failures),
            "scoreSystemCount": sum(int(item.get("scoreSystemCount") or 0) for item in candidates),
            "indexPath": str(index_path.relative_to(batch_dir)),
            "indexDigest": _sha256_json(combined_index),
            "priorTabApprovalsPreserved": all(
                bool(item.get("priorTabApprovalPreserved", True))
                for item in new_entries
            ),
            "targetedTabCorrectionPageCount": sum(
                not bool(item.get("priorTabApprovalPreserved", True))
                for item in candidates
            ),
            "trainingStarted": False,
            "sealedTestAccessed": False,
        }
        _write_json(repair_root / "score-repair-summary.json", summary)
        return summary

    def prepare_combined_score_tab_review(
        self,
        batch_id: str,
        *,
        input_ids: Sequence[str],
        score_system_ids: Sequence[str] | None = None,
        key_signature_overrides: Mapping[str, int] | None = None,
        partition: str = "discovery",
        activate: bool = True,
        provisional_joint_review: bool = False,
    ) -> dict[str, Any]:
        """Prepare one immutable combined score/tab audit from approved discovery records."""

        if partition != "discovery":
            raise ExtractionWorkflowError("Combined score/tab review is discovery-only.")
        requested = [str(value).strip() for value in input_ids if str(value).strip()]
        if not requested or len(requested) > 10 or len(set(requested)) != len(requested):
            raise ExtractionWorkflowError(
                "Combined score/tab review needs 1-10 unique discovery input IDs."
            )
        requested_system_ids = {
            str(value).strip()
            for value in score_system_ids or []
            if str(value).strip()
        }
        if score_system_ids and len(requested_system_ids) != len(score_system_ids):
            raise ExtractionWorkflowError(
                "Combined score/tab line filters must be unique non-empty score-system IDs."
            )
        key_overrides = {
            str(system_id): int(fifths)
            for system_id, fifths in (key_signature_overrides or {}).items()
        }
        if any(not system_id or not -7 <= fifths <= 7 for system_id, fifths in key_overrides.items()):
            raise ExtractionWorkflowError("Combined-review key-signature overrides are invalid.")
        if requested_system_ids and not set(key_overrides).issubset(requested_system_ids):
            raise ExtractionWorkflowError(
                "A key-signature override must target a requested score-system ID."
            )
        batch_dir, manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        review_root = output_root / "review"
        regression = self.replay_combined_score_tab_regressions(
            batch_id,
            partition=partition,
        )
        if not bool(regression.get("gatePassed")):
            raise ExtractionWorkflowError(
                "Known combined score/tab regressions must pass before preparing another review."
            )
        review_dir = review_root / "combined-score-tab-audit"
        review_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(review_dir, 0o700)
        prior_current_snapshot = _snapshot_current_combined_score_tab_review(review_dir)
        work_ids = {str(item.get("inputId") or "") for item in work}
        missing = sorted(set(requested) - work_ids)
        if missing:
            raise ExtractionWorkflowError(
                "Combined score/tab review references non-discovery inputs: " + ", ".join(missing)
            )
        confirmation_path = review_root / "feedback-correction-confirmation-decisions.jsonl"
        confirmations = _read_jsonl(confirmation_path) if confirmation_path.exists() else []
        approved_record_path = review_root / "approved-record-index.jsonl"
        approved_record_entries = (
            _read_jsonl(approved_record_path) if approved_record_path.exists() else []
        )
        reviewed_base_meta_by_input: dict[str, dict[str, str]] = {
            str(item.get("inputId") or ""): {
                "reviewedRecordPath": str(item.get("reviewedRecordPath") or ""),
                "reviewedRecordDigest": str(item.get("reviewedRecordDigest") or ""),
                "decisionId": str(item.get("reviewDecisionId") or ""),
                "origin": "page_review",
            }
            for item in approved_record_entries
            if item.get("status") == "human_approved"
            and item.get("reviewedRecordPath")
            and item.get("reviewedRecordDigest")
        }
        approved_line_path = review_dir / "application" / "approved-line-index.jsonl"
        approved_line_entries = (
            _read_jsonl(approved_line_path) if approved_line_path.exists() else []
        )
        for item in approved_line_entries:
            input_id = str(item.get("inputId") or "")
            if (
                input_id in reviewed_base_meta_by_input
                and item.get("status") == "human_approved_pitch_only"
                and item.get("reviewedRecordPath")
                and item.get("reviewedRecordDigest")
            ):
                reviewed_base_meta_by_input[input_id] = {
                    "reviewedRecordPath": str(item.get("reviewedRecordPath") or ""),
                    "reviewedRecordDigest": str(item.get("reviewedRecordDigest") or ""),
                    "decisionId": str(item.get("decisionId") or ""),
                    "origin": "combined_line_review",
                }
        input_names = {
            str(item.get("inputId") or ""): Path(str(item.get("relativePath") or "")).name
            for item in manifest.get("inputs") or []
        }
        pages: list[dict[str, Any]] = []
        withheld: list[dict[str, Any]] = []
        candidate_index: list[dict[str, Any]] = []
        found_system_ids: set[str] = set()
        for input_id in requested:
            machine_path = pages_dir / f"{input_id}.json"
            if not machine_path.exists():
                raise ExtractionWorkflowError(f"Current machine record is missing for {input_id}.")
            machine_record = _read_json(machine_path)
            machine_digest = _sha256_json(machine_record)
            base_record = machine_record
            base_digest = machine_digest
            base_origin = "machine_page"
            reviewed_meta = reviewed_base_meta_by_input.get(input_id)
            confirmation: Mapping[str, Any] | None = None
            if reviewed_meta is not None:
                reviewed_path = output_root / reviewed_meta["reviewedRecordPath"]
                if not reviewed_path.exists():
                    raise ExtractionWorkflowError(
                        f"The reviewed combined-review base is missing for {input_id}."
                    )
                reviewed_record = _read_json(reviewed_path)
                if _sha256_json(reviewed_record) != reviewed_meta["reviewedRecordDigest"]:
                    raise ExtractionWorkflowError(
                        f"The reviewed combined-review base digest changed for {input_id}."
                    )
                base_record = reviewed_record
                base_digest = reviewed_meta["reviewedRecordDigest"]
                base_origin = reviewed_meta["origin"]
                confirmation = {
                    "decisionId": reviewed_meta["decisionId"] or None,
                    "status": "human_approved_reviewed_record",
                    "machineRecordDigest": base_digest,
                }
            else:
                confirmation = next(
                    (
                        item
                        for item in reversed(confirmations)
                        if str(item.get("inputId") or "") == input_id
                        and str(item.get("machineRecordDigest") or "") == machine_digest
                        and str(item.get("status") or "") == "confirm"
                    ),
                    None,
                )
            if confirmation is None and not provisional_joint_review:
                raise ExtractionWorkflowError(
                    f"Combined score/tab review requires a current confirmed tab correction for {input_id}."
                )
            if confirmation is None:
                confirmation = {
                    "decisionId": None,
                    "status": "provisional_joint_review",
                    "machineRecordDigest": base_digest,
                }
            candidate_record: dict[str, Any] | None = None
            candidate_result: dict[str, Any] | None = None
            indexed_candidate = _score_repair_candidate(
                output_root,
                input_id=input_id,
                base_reviewed_record_digest=base_digest,
            )
            if indexed_candidate is not None:
                candidate_record, relative_path, indexed_entry = indexed_candidate
                candidate_result = {
                    "candidateRecordPath": relative_path,
                    "candidateRecordDigest": _sha256_json(candidate_record),
                    "reused": True,
                    "scoreRepairIndexEntry": copy.deepcopy(indexed_entry),
                }
            candidate_root = review_root / "score-audit" / "repair" / "candidate-records" / input_id
            for candidate_path in (
                []
                if candidate_record is not None
                else sorted(candidate_root.glob("*.json"), reverse=True)
            ):
                candidate = _read_json(candidate_path)
                repair = candidate.get("scoreRepair") or {}
                if (
                    str(repair.get("repairVersion") or "") == SCORE_REPAIR_VERSION
                    and str(repair.get("baseReviewedRecordDigest") or "") == base_digest
                    and _reviewed_tab_facts_digest(candidate)
                    == str(repair.get("reviewedTabFactsDigest") or "")
                ):
                    candidate_record = candidate
                    candidate_result = {
                        "candidateRecordPath": str(candidate_path.relative_to(output_root)),
                        "candidateRecordDigest": _sha256_json(candidate),
                        "reused": True,
                    }
                    break
            if candidate_record is None:
                candidate_result = _rebase_score_repair_candidate_after_tab_correction(
                    output_root,
                    input_id=input_id,
                    base_record=base_record,
                    base_reviewed_record_digest=base_digest,
                    prior_review_decision_id=(
                        str(confirmation.get("decisionId") or "") or None
                    ),
                )
                if candidate_result is not None:
                    candidate_path = output_root / str(
                        candidate_result["candidateRecordPath"]
                    )
                    candidate_record = _read_json(candidate_path)
            if candidate_record is None:
                candidate_result = self._build_score_repair_candidate(
                    output_root=output_root,
                    input_id=input_id,
                    base_record=base_record,
                    base_reviewed_record_digest=base_digest,
                    prior_review_decision_id=(
                        str(confirmation.get("decisionId") or "") or None
                    ),
                )
                candidate_path = output_root / str(candidate_result["candidateRecordPath"])
                candidate_record = _read_json(candidate_path)
            assert candidate_result is not None
            candidate_digest = str(candidate_result["candidateRecordDigest"])
            if _sha256_json(candidate_record) != candidate_digest:
                raise ExtractionWorkflowError(f"Combined score candidate changed for {input_id}.")
            candidate_index.append(
                {
                    "inputId": input_id,
                    "machineRecordDigest": base_digest,
                    "baseRecordOrigin": base_origin,
                    "confirmationDecisionId": confirmation.get("decisionId"),
                    "candidateRecordPath": candidate_result["candidateRecordPath"],
                    "candidateRecordDigest": candidate_digest,
                    "reused": bool(candidate_result.get("reused")),
                }
            )
            tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in candidate_record.get("tabSystems") or []
            }
            systems: list[dict[str, Any]] = []
            for score_system in candidate_record.get("scoreSystems") or []:
                score_system_id = str(score_system.get("scoreSystemId") or "")
                if requested_system_ids and score_system_id not in requested_system_ids:
                    continue
                found_system_ids.add(score_system_id)
                key_signature = score_system.get("keySignature") or {}
                captured_key_fifths = (
                    score_system.get("keySignatureFifths")
                    if score_system.get("keySignatureFifths") is not None
                    else (
                        key_signature.get("fifths")
                        if isinstance(key_signature, Mapping)
                        and key_signature.get("fifths") is not None
                        else score_system.get("keyFifths")
                    )
                )
                display_key_fifths = int(
                    key_overrides.get(
                        score_system_id,
                        captured_key_fifths if captured_key_fifths is not None else 0,
                    )
                )
                key_signature_known = (
                    score_system_id in key_overrides or captured_key_fifths is not None
                )
                tab_system_id = str(score_system.get("pairedTabSystemId") or "")
                tab_system = tab_by_id.get(tab_system_id)
                if tab_system is None:
                    withheld.append(
                        {
                            "inputId": input_id,
                            "scoreSystemId": score_system_id,
                            "reason": "paired_tablature_missing",
                        }
                    )
                    continue
                comparison = _combined_score_tab_columns(score_system, tab_system)
                if not comparison["mechanicallyValid"] or not comparison["scoreAttacks"]:
                    withheld.append(
                        {
                            "inputId": input_id,
                            "scoreSystemId": score_system_id,
                            "reason": (
                                "mechanical_preflight_failed"
                                if not comparison["mechanicallyValid"]
                                else "score_reader_returned_no_attacks"
                            ),
                        }
                    )
                    continue
                if comparison.get("monophonicScoreTextureConflict"):
                    withheld.append(
                        {
                            "inputId": input_id,
                            "scoreSystemId": score_system_id,
                            "reason": (
                                "monophonic_line_contains_isolated_score_chord;"
                                "internal_score_recapture_required"
                            ),
                        }
                    )
                    continue
                provisional_blockers = (
                    _provisional_joint_review_blockers(
                        comparison,
                        key_signature_known=key_signature_known,
                    )
                    if provisional_joint_review
                    else []
                )
                if provisional_blockers:
                    withheld.append(
                        {
                            "inputId": input_id,
                            "scoreSystemId": score_system_id,
                            "reason": "provisional_not_review_ready:"
                            + ",".join(provisional_blockers),
                        }
                    )
                    continue
                crop = _prepare_score_tab_source_crop(
                    output_root=output_root,
                    audit_dir=review_dir,
                    input_id=input_id,
                    record=candidate_record,
                    score_system=score_system,
                    tab_system=tab_system,
                )
                systems.append(
                    {
                        "inputId": input_id,
                        "sourceLabel": input_names.get(input_id) or input_id,
                        "systemIndex": int(score_system.get("systemIndex") or len(systems) + 1),
                        "scoreSystemId": score_system_id,
                        "tabSystemId": tab_system_id,
                        "machineRecordDigest": base_digest,
                        "baseRecordOrigin": base_origin,
                        "scoreCandidateDigest": candidate_digest,
                        "keySignatureFifths": display_key_fifths,
                        "keySignatureKnown": key_signature_known,
                        "keySignatureEvidence": (
                            "direct_visual_observation_pending_human_review"
                            if score_system_id in key_overrides
                            else (
                                "captured_candidate"
                                if key_signature_known
                                else "unknown_unresolved"
                            )
                        ),
                        "sourcePairUrl": Path(
                            os.path.relpath(
                                output_root / str(crop["relativePath"]), review_dir
                            )
                        ).as_posix(),
                        "sourcePairSha256": crop["sha256"],
                        "comparison": comparison,
                        "evidenceGates": {
                            "source": "passed",
                            "tablature": (
                                "machine_candidate_needs_human_review"
                                if provisional_joint_review
                                else "correction_approved"
                            ),
                            "score": "source_only_candidate_needs_human_review",
                            "alignment": (
                                "candidate_exact" if comparison["countsAgree"] else "needs_human_review"
                            ),
                            "pitch": (
                                "candidate_exact"
                                if comparison["automaticPitchGatePassed"]
                                else "needs_human_review"
                            ),
                            "mechanics": "passed",
                            "humanReview": "pending",
                        },
                        "trainingEligible": False,
                    }
                )
            if systems:
                pages.append(
                    {
                        "inputId": input_id,
                        "sourceLabel": input_names.get(input_id) or input_id,
                        "machineRecordDigest": base_digest,
                        "baseRecordOrigin": base_origin,
                        "confirmationDecisionId": confirmation.get("decisionId"),
                        "systems": systems,
                    }
                )
        if withheld:
            raise ExtractionWorkflowError(
                "Combined score/tab preflight withheld one or more lines: "
                + ", ".join(
                    f"{item['inputId']}:{item['scoreSystemId']} ({item['reason']})"
                    for item in withheld
                )
            )
        missing_system_ids = sorted(requested_system_ids - found_system_ids)
        if missing_system_ids:
            raise ExtractionWorkflowError(
                "Combined score/tab line filters were not found in the requested pages: "
                + ", ".join(missing_system_ids)
            )
        packet_core = {
            "schemaVersion": COMBINED_SCORE_TAB_REVIEW_SCHEMA_VERSION,
            "gateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
            "rendererVersion": COMBINED_SCORE_TAB_RENDERER_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "requestedScoreSystemIds": sorted(requested_system_ids),
            "pages": pages,
            "scoreReaderIndependentOfTabPitches": True,
            "tabPitchHypothesisIsNotSourceTruthWithoutHumanApproval": True,
            "falseHarmonyInferenceAllowed": False,
            "trainingEligibleBeforeReview": False,
            "jointTabReviewRequired": provisional_joint_review,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_filename = f"packet-{packet_digest}.json"
        console_filename = (
            f"combined-score-tab-audit-console-{packet_digest[:12]}.html"
        )
        candidate_index_filename = f"score-candidate-index-{packet_digest}.jsonl"
        packet_path = review_dir / packet_filename
        console_path = review_dir / console_filename
        candidate_index_path = review_dir / candidate_index_filename
        _write_json(packet_path, packet)
        _write_jsonl(candidate_index_path, candidate_index)
        _write_private_text(
            console_path,
            _combined_score_tab_console_html(
                packet_digest=packet_digest,
                packet_filename=packet_filename,
            ),
        )
        if activate:
            _write_json(review_dir / "packet.json", packet)
            _write_jsonl(review_dir / "score-candidate-index.jsonl", candidate_index)
            _write_private_text(
                review_dir / "combined-score-tab-audit-console.html",
                _combined_score_tab_console_html(packet_digest=packet_digest),
            )
        summary = {
            "schemaVersion": COMBINED_SCORE_TAB_REVIEW_SCHEMA_VERSION,
            "gateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "pageCount": len(pages),
            "systemCount": sum(len(page["systems"]) for page in pages),
            "automaticExactSystemCount": sum(
                bool(system["comparison"]["automaticPitchGatePassed"])
                for page in pages
                for system in page["systems"]
            ),
            "humanResolutionSystemCount": sum(
                not bool(system["comparison"]["automaticPitchGatePassed"])
                for page in pages
                for system in page["systems"]
            ),
            "packetDigest": packet_digest,
            "packetPath": str(packet_path.relative_to(batch_dir)),
            "consolePath": str(console_path.relative_to(batch_dir)),
            "candidateIndexPath": str(candidate_index_path.relative_to(batch_dir)),
            "relativeUrl": (
                f"/{batch_id}/extraction/{partition}/review/combined-score-tab-audit/"
                f"{console_filename}"
            ),
            "activatedAsCurrentPacket": activate,
            "immutablePacketVersion": True,
            "priorCurrentPacketSnapshotDigest": (
                prior_current_snapshot.get("packetDigest")
                if prior_current_snapshot
                else None
            ),
            "confirmationApprovalsPreserved": True,
            "jointTabReviewRequired": provisional_joint_review,
            "scoreApprovalGranted": False,
            "alignmentApprovalGranted": False,
            "lineFilterApplied": bool(requested_system_ids),
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        _write_json(review_dir / f"packet-summary-{packet_digest}.json", summary)
        if activate:
            _write_json(review_dir / "packet-summary.json", summary)
        return summary

    def remediate_validation_machine_capture(
        self,
        batch_id: str,
        *,
        input_ids: Sequence[str] = (),
        limit: int = 8,
        resume: bool = True,
        apply: bool = False,
    ) -> dict[str, Any]:
        """Recapture validation lines from machine consensus without human truth."""

        if not 1 <= limit <= 100:
            raise ExtractionWorkflowError("Validation machine recapture limit must be 1-100.")
        batch_dir, manifest, work = self._batch_paths(batch_id, "validation")
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        output_root = batch_dir / "extraction" / "validation"
        pages_dir = output_root / "pages"
        summary_path = output_root / "summary.json"
        if not summary_path.exists():
            raise ExtractionWorkflowError("Validation extraction is required before recapture.")
        extraction_summary = _read_json(summary_path)
        validation_model = copy.deepcopy(extraction_summary.get("validationModel") or {})
        if not validation_model.get("modelId"):
            raise ExtractionWorkflowError("Validation recapture requires pinned model lineage.")
        remediation_dir = (
            output_root
            / "review"
            / "automation"
            / VALIDATION_MACHINE_RECAPTURE_VERSION
        )
        candidate_dir = remediation_dir / "candidates"
        revision_dir = remediation_dir / "machine-record-revisions"
        for directory in (remediation_dir, candidate_dir, revision_dir):
            directory.mkdir(parents=True, exist_ok=True)
            os.chmod(directory, 0o700)
        contract = {
            "schemaVersion": VALIDATION_MACHINE_RECAPTURE_VERSION,
            "countReader": self.tab_system_vision.contract(),
            "tabLocalizationPromptVersion": TAB_SYSTEM_LOCALIZATION_PROMPT_VERSION,
            "scorePitchSource": "existing_independent_audiveris_musicxml",
            "scorePitchCountMayBeConstrainedByTab": False,
            "countConstraintSource": "machine_visual_candidate_geometry",
            "minimumConfidence": 0.85,
            "requiresVisualCandidateAgreement": True,
            "eventAndStringGeometrySource": "deterministic_visual_candidate_geometry",
            "stateTokenSource": "guided_full_state_vision_with_pinned_cell_crosscheck",
            "independentCellReaderPromptVersion": TAB_VISION_PROMPT_VERSION,
            "requiresOneTokenPerVisualCandidateCell": True,
            "minimumStringOriginConsensus": 0.75,
            "mechanicalChecksumMayResolveMinorityRow": False,
            "deterministicGeometryRowsRemainAuthoritative": True,
            "countOnlyVisionReaderIsDiagnostic": True,
            "requiresMechanicalValidity": True,
            "requiresScorePitchContainmentInTab": True,
            "sourceCopedentId": profile.id,
            "sourceCopedentRevision": profile.revision,
            "validationModel": validation_model,
            "validationMayTrain": False,
            "sealedTestAccessed": False,
        }
        contract_digest = _sha256_json(contract)
        requested_ids = {str(value) for value in input_ids if str(value)}
        work_ids = {str(item.get("inputId") or "") for item in work}
        if requested_ids - work_ids:
            raise ExtractionWorkflowError("Validation recapture requested an unknown input ID.")

        results: list[dict[str, Any]] = []
        selected_count = 0
        applied_count = 0
        for work_item in work:
            input_id = str(work_item.get("inputId") or "")
            if requested_ids and input_id not in requested_ids:
                continue
            page_path = pages_dir / f"{input_id}.json"
            if not page_path.exists():
                raise ExtractionWorkflowError(f"Validation page record is missing for {input_id}.")
            record = _read_json(page_path)
            tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in record.get("tabSystems") or []
            }
            for score_system in list(record.get("scoreSystems") or []):
                if selected_count >= limit:
                    break
                score_system_id = str(score_system.get("scoreSystemId") or "")
                tab_system_id = str(score_system.get("pairedTabSystemId") or "")
                tab_system = tab_by_id.get(tab_system_id)
                if not score_system_id or tab_system is None:
                    continue
                existing_comparison = _combined_score_tab_columns(
                    score_system, tab_system
                )
                existing_issues = [
                    item
                    for item in record.get("unresolved") or []
                    if str(item.get("scoreSystemId") or "") == score_system_id
                    or str(item.get("tabSystemId") or "") == tab_system_id
                ]
                key_known = (
                    score_system.get("keySignatureFifths") is not None
                    or score_system.get("keyFifths") is not None
                    or (score_system.get("keySignature") or {}).get("fifths")
                    is not None
                )
                existing_blockers = _validation_line_preflight_blockers(
                    existing_comparison,
                    key_signature_known=key_known,
                    blocking_issue_count=_validation_capture_issue_count(existing_issues),
                )
                if not existing_blockers:
                    continue
                selected_count += 1
                result_core: dict[str, Any] = {
                    "inputId": input_id,
                    "scoreSystemId": score_system_id,
                    "tabSystemId": tab_system_id,
                    "systemIndex": int(score_system.get("systemIndex") or 0),
                    "priorBlockers": existing_blockers,
                    "applied": False,
                }
                try:
                    source_crop = _prepare_score_tab_source_crop(
                        output_root=output_root,
                        audit_dir=remediation_dir,
                        input_id=input_id,
                        record=record,
                        score_system=score_system,
                        tab_system=tab_system,
                    )
                    source_pair_path = output_root / str(source_crop["relativePath"])
                    tab_crop = _prepare_event_localization_tab_crop(
                        output_root=output_root,
                        localization_dir=remediation_dir,
                        input_id=input_id,
                        record=record,
                        tab_system=tab_system,
                    )
                    guided_tab_crop = _prepare_guided_tab_state_crop(
                        localization_dir=remediation_dir,
                        input_id=input_id,
                        tab_system=tab_system,
                        tab_crop=tab_crop,
                    )
                    independent_cells, independent_cell_cache_digests = (
                        _validation_independent_contact_cells(
                            output_root=output_root,
                            tab_system=tab_system,
                            model=self.tab_system_vision.model,
                        )
                    )
                    cache_path = candidate_dir / f"{input_id}-{score_system_id}.json"
                    machine_record_digest = _sha256_json(record)
                    cached: dict[str, Any] = {}
                    if resume and cache_path.exists():
                        candidate_cache = _read_json(cache_path)
                        if (
                            candidate_cache.get("contractDigest") == contract_digest
                            and candidate_cache.get("machineRecordDigest")
                            == machine_record_digest
                            and candidate_cache.get("sourcePairSha256")
                            == _sha256_bytes(source_pair_path.read_bytes())
                        ):
                            cached = candidate_cache
                    tab_count_prediction = copy.deepcopy(
                        cached.get("tabCountPrediction")
                    ) if isinstance(cached.get("tabCountPrediction"), Mapping) else None
                    if tab_count_prediction is None:
                        tab_count_prediction = self.tab_system_vision.read_event_count(
                            source_pair_path
                        )
                    expected_count = len(tab_system.get("tabEventCandidates") or [])
                    if not 1 <= expected_count <= 64:
                        raise ExtractionWorkflowError(
                            "Deterministic visual candidate geometry produced an invalid count."
                        )
                    independent_count, count_blockers = _validation_machine_count_consensus(
                        tab_system, tab_count_prediction
                    )
                    count_reader_agrees = independent_count == expected_count
                    localization = copy.deepcopy(
                        cached.get("tabLocalization")
                    ) if (
                        int(cached.get("expectedEventCount") or 0) == expected_count
                        and isinstance(cached.get("tabLocalization"), Mapping)
                    ) else None
                    if localization is None:
                        localization = self.tab_system_vision.localize_events(
                            Path(guided_tab_crop["path"]),
                            expected_event_count=expected_count,
                            constraint_source="machine_visual_candidate_geometry",
                            guided=True,
                            expected_cell_counts=[
                                len(candidate.get("candidateStrings") or [])
                                for candidate in tab_system.get("tabEventCandidates") or []
                            ],
                            control_string_map=_profile_control_string_map(profile),
                        )
                    original_localization = copy.deepcopy(localization)
                    score_events, score_recognition = (
                        _validation_machine_score_from_existing_omr(
                            score_system,
                            expected_event_counts={
                                expected_count,
                                sum(
                                    str(event.get("execution") or "")
                                    != "movement_only"
                                    for event in localization.get("events") or []
                                ),
                            },
                        )
                    )
                    localization, tab_events, hypothesis_diagnostics = (
                        _validation_contact_tab_hypothesis(
                            input_id=input_id,
                            tab_system=tab_system,
                            localization=localization,
                            independent_cells=independent_cells,
                            guided_tab_crop=guided_tab_crop,
                            tab_crop=tab_crop,
                            score_events=score_events,
                            profile=profile,
                            expected_count=expected_count,
                        )
                    )
                    string_origin_offset = int(
                        hypothesis_diagnostics["selectedStringOriginOffset"]
                    )
                    string_origin_consensus = 1.0
                    geometry_row_reassignments = 0
                    independent_cell_token_overrides = 0
                    for original_event, selected_event in zip(
                        original_localization.get("events") or [],
                        localization.get("events") or [],
                        strict=True,
                    ):
                        original_cells = sorted(
                            original_event.get("cells") or [],
                            key=lambda cell: int(cell.get("string") or 0),
                        )
                        selected_cells = sorted(
                            selected_event.get("cells") or [],
                            key=lambda cell: int(cell.get("string") or 0),
                        )
                        for original_cell, selected_cell in zip(
                            original_cells, selected_cells, strict=True
                        ):
                            geometry_row_reassignments += int(
                                original_cell.get("string") or 0
                            ) != int(selected_cell.get("string") or 0)
                            independent_cell_token_overrides += (
                                str(original_cell.get("token") or "").strip().upper()
                                != str(selected_cell.get("token") or "").strip().upper()
                            )
                    visual_candidates = list(tab_system.get("tabEventCandidates") or [])
                    if len(visual_candidates) != expected_count:
                        raise ExtractionWorkflowError(
                            "Machine tab localization lost visual candidate agreement."
                        )
                    maximum_position_delta = max(
                        (
                            abs(
                                float(event.get("horizontalPosition") or 0.0)
                                - float(candidate.get("horizontalPosition") or 0.0)
                            )
                            for event, candidate in zip(
                                tab_events, visual_candidates, strict=True
                            )
                        ),
                        default=1.0,
                    )
                    if maximum_position_delta > 0.065:
                        raise ExtractionWorkflowError(
                            "Machine tab localization failed independent checks: "
                            f"maximum_position_delta={maximum_position_delta:.6f}."
                        )
                    score_tab_diagnostics = _machine_score_tab_containment_diagnostics(
                        score_events, tab_events
                    )
                    if not _machine_score_is_contained_in_tab(score_events, tab_events):
                        raise ExtractionWorkflowError(
                            "Machine score pitches are not contained in the machine-captured tab states: "
                            + json.dumps(score_tab_diagnostics, sort_keys=True)
                        )
                    cache_core = {
                        "schemaVersion": VALIDATION_MACHINE_RECAPTURE_VERSION,
                        "batchId": batch_id,
                        "partition": "validation",
                        "inputId": input_id,
                        "scoreSystemId": score_system_id,
                        "tabSystemId": tab_system_id,
                        "machineRecordDigest": machine_record_digest,
                        "contractDigest": contract_digest,
                        "sourcePairSha256": _sha256_bytes(source_pair_path.read_bytes()),
                        "tabCropSha256": _sha256_bytes(Path(tab_crop["path"]).read_bytes()),
                        "guidedTabCropSha256": str(guided_tab_crop["sha256"]),
                        "guidedScoreCropSha256": None,
                        "expectedEventCount": expected_count,
                        "tabCountPrediction": tab_count_prediction,
                        "countOnlyReaderAgrees": count_reader_agrees,
                        "countOnlyReaderBlockers": count_blockers,
                        "tabLocalization": localization,
                        "scoreRecognition": score_recognition,
                        "scoreTabContainmentDiagnostics": score_tab_diagnostics,
                        "tabHypothesisDiagnostics": hypothesis_diagnostics,
                        "geometryRowReassignmentCount": geometry_row_reassignments,
                        "mechanicalRowOverrideCount": 0,
                        "independentCellTokenOverrideCount": independent_cell_token_overrides,
                        "independentCellCacheDigests": independent_cell_cache_digests,
                        "stringOriginOffset": string_origin_offset,
                        "stringOriginConsensus": round(string_origin_consensus, 6),
                        "humanTruthUsed": False,
                        "validationMayTrain": False,
                        "sealedTestAccessed": False,
                    }
                    _write_json(cache_path, cache_core)

                    candidate_record = copy.deepcopy(record)
                    candidate_score = next(
                        system
                        for system in candidate_record.get("scoreSystems") or []
                        if str(system.get("scoreSystemId") or "") == score_system_id
                    )
                    candidate_tab = next(
                        system
                        for system in candidate_record.get("tabSystems") or []
                        if str(system.get("tabSystemId") or "") == tab_system_id
                    )
                    candidate_score["scoreEvents"] = score_events
                    candidate_score["scoreAttackCount"] = int(
                        score_recognition["eventCount"]
                    )
                    candidate_score["keyFifths"] = int(
                        score_recognition["keySignatureFifths"]
                    )
                    candidate_score["keySignatureFifths"] = int(
                        score_recognition["keySignatureFifths"]
                    )
                    candidate_score["omrStatus"] = "machine_verified_existing_omr"
                    candidate_score["machineRecapture"] = {
                        "schemaVersion": VALIDATION_MACHINE_RECAPTURE_VERSION,
                        "contractDigest": contract_digest,
                        "expectedEventCount": expected_count,
                        "scorePitchSource": score_recognition["captureSource"],
                        "humanTruthUsed": False,
                    }
                    candidate_tab["tabEvents"] = tab_events
                    for candidate, resolved_event in zip(
                        candidate_tab.get("tabEventCandidates") or [],
                        tab_events,
                        strict=True,
                    ):
                        original_strings = [
                            int(value) for value in candidate.get("candidateStrings") or []
                        ]
                        candidate["candidateStrings"] = sorted(
                            int(action["string"])
                            for action in resolved_event.get("steelActions") or []
                        )
                        candidate["stringOriginCalibration"] = {
                            "schemaVersion": VALIDATION_MACHINE_RECAPTURE_VERSION,
                            "originalCandidateStrings": original_strings,
                            "offset": string_origin_offset,
                            "consensus": round(string_origin_consensus, 6),
                        }
                    candidate_tab["eventCounts"] = {
                        **copy.deepcopy(candidate_tab.get("eventCounts") or {}),
                        "printedCandidateColumns": expected_count,
                        "recognizedSoundingStates": expected_count,
                        "pickedStates": sum(
                            event.get("executionType") != "movement_only"
                            for event in tab_events
                        ),
                        "movementOnlyStates": sum(
                            event.get("executionType") == "movement_only"
                            for event in tab_events
                        ),
                        "unresolvedCandidateColumns": 0,
                    }
                    candidate_record["unresolved"] = [
                        item
                        for item in candidate_record.get("unresolved") or []
                        if str(item.get("scoreSystemId") or "") != score_system_id
                        and str(item.get("tabSystemId") or "") != tab_system_id
                    ]
                    _revalidate_corrected_record(
                        candidate_record,
                        profile,
                        include_movement_only_tab_system_ids={tab_system_id},
                    )
                    recaptured_score = next(
                        system
                        for system in candidate_record.get("scoreSystems") or []
                        if str(system.get("scoreSystemId") or "") == score_system_id
                    )
                    recaptured_tab = next(
                        system
                        for system in candidate_record.get("tabSystems") or []
                        if str(system.get("tabSystemId") or "") == tab_system_id
                    )
                    recaptured_issues = [
                        item
                        for item in candidate_record.get("unresolved") or []
                        if str(item.get("scoreSystemId") or "") == score_system_id
                        or str(item.get("tabSystemId") or "") == tab_system_id
                    ]
                    final_comparison = _combined_score_tab_columns(
                        recaptured_score, recaptured_tab
                    )
                    final_blockers = _validation_line_preflight_blockers(
                        final_comparison,
                        key_signature_known=True,
                        blocking_issue_count=_validation_capture_issue_count(
                            recaptured_issues
                        ),
                    )
                    if final_blockers:
                        raise ExtractionWorkflowError(
                            "Recaptured line failed structural preflight: "
                            + ", ".join(final_blockers)
                        )
                    candidate_record["revision"] = int(record.get("revision") or 1) + 1
                    candidate_record.setdefault("validationMachineRecaptures", []).append(
                        {
                            "schemaVersion": VALIDATION_MACHINE_RECAPTURE_VERSION,
                            "scoreSystemId": score_system_id,
                            "tabSystemId": tab_system_id,
                            "contractDigest": contract_digest,
                            "expectedEventCount": expected_count,
                            "countOnlyReaderAgrees": count_reader_agrees,
                            "humanTruthUsed": False,
                            "validationMayTrain": False,
                        }
                    )
                    if apply:
                        prior_digest = _sha256_json(record)
                        archive_path = (
                            revision_dir / input_id / f"{prior_digest}.json"
                        )
                        if not archive_path.exists():
                            _write_json(archive_path, record)
                        _write_json(page_path, candidate_record)
                        record = candidate_record
                        tab_by_id[tab_system_id] = recaptured_tab
                        applied_count += 1
                    results.append(
                        {
                            **result_core,
                            "status": "passed_machine_preflight",
                            "expectedEventCount": expected_count,
                            "maximumPositionDelta": round(maximum_position_delta, 6),
                            "geometryRowReassignmentCount": geometry_row_reassignments,
                            "mechanicalRowOverrideCount": 0,
                            "independentCellTokenOverrideCount": (
                                independent_cell_token_overrides
                            ),
                            "stringOriginOffset": string_origin_offset,
                            "stringOriginConsensus": round(string_origin_consensus, 6),
                            "countOnlyReaderAgrees": count_reader_agrees,
                            "countOnlyReaderBlockers": count_blockers,
                            "scorePitchContainmentPassed": True,
                            "applied": apply,
                        }
                    )
                except ExtractionWorkflowError as exc:
                    results.append(
                        {
                            **result_core,
                            "status": "withheld",
                            "failure": str(exc)[:500],
                        }
                    )
            if selected_count >= limit:
                break
        status_counts = Counter(str(item["status"]) for item in results)
        report_core = {
            "schemaVersion": VALIDATION_MACHINE_RECAPTURE_VERSION,
            "batchId": batch_id,
            "partition": "validation",
            "contract": contract,
            "contractDigest": contract_digest,
            "selectedLineCount": selected_count,
            "passedLineCount": int(status_counts["passed_machine_preflight"]),
            "withheldLineCount": int(status_counts["withheld"]),
            "appliedLineCount": applied_count,
            "applyRequested": apply,
            "results": results,
            "humanTruthUsed": False,
            "validationMayTrain": False,
            "validationAccessed": True,
            "sealedTestAccessed": False,
        }
        report_digest = _sha256_json(report_core)
        report = {**report_core, "reportDigest": report_digest}
        _write_json(remediation_dir / f"report-{report_digest}.json", report)
        _write_json(remediation_dir / "report.json", report)
        return report

    def prepare_validation_line_audit(
        self,
        batch_id: str,
        *,
        activate: bool = True,
    ) -> dict[str, Any]:
        """Prepare a complete, compact validation audit without creating training data."""

        batch_dir, manifest, work = self._batch_paths(batch_id, "validation")
        output_root = batch_dir / "extraction" / "validation"
        pages_dir = output_root / "pages"
        summary_path = output_root / "summary.json"
        if not summary_path.exists():
            raise ExtractionWorkflowError(
                "A complete validation extraction is required before its line audit."
            )
        extraction_summary = _read_json(summary_path)
        if (
            extraction_summary.get("partition") != "validation"
            or extraction_summary.get("extractorVersion") != EXTRACTOR_VERSION
            or extraction_summary.get("failedPageCount") != 0
            or extraction_summary.get("sealedTestAccessed") is not False
        ):
            raise ExtractionWorkflowError(
                "Validation line audit requires a complete current-extractor run with sealed test closed."
            )
        validation_model = extraction_summary.get("validationModel") or {}
        if not validation_model.get("modelId") or not validation_model.get(
            "artifactSha256"
        ):
            raise ExtractionWorkflowError(
                "Validation line audit requires an exact pinned challenger lineage."
            )
        audit_dir = output_root / "review" / "validation-line-audit"
        audit_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(audit_dir, 0o700)
        input_names = {
            str(item.get("inputId") or ""): Path(
                str(item.get("relativePath") or "")
            ).name
            for item in manifest.get("inputs") or []
        }
        pages: list[dict[str, Any]] = []
        no_line_pages: list[dict[str, Any]] = []
        expected_run_digest = str(extraction_summary.get("runDigest") or "")
        work_ids = [str(item.get("inputId") or "") for item in work]
        issue_kind_labels = {
            "unresolved_tab_event_candidate": "unresolved movement columns",
            "uncertain_tab_symbol": "uncertain tablature symbols",
            "tab_modifier_symbol": "unresolved pedal/lever marks",
            "low_confidence_tab_symbol": "low-confidence tablature symbols",
            "repeated_tab_symbol_ambiguity": "repeat-mark ambiguities",
            "score_omr_failure": "score-reader failures",
            "tab_cell_vision_failure": "tablature-reader failures",
        }
        for input_id in work_ids:
            page_path = pages_dir / f"{input_id}.json"
            if not page_path.exists():
                raise ExtractionWorkflowError(
                    f"Validation page record is missing for {input_id}."
                )
            record = _read_json(page_path)
            if (
                record.get("datasetPartition") != "validation"
                or record.get("extractorVersion") != EXTRACTOR_VERSION
                or str(record.get("runDigest") or "") != expected_run_digest
            ):
                raise ExtractionWorkflowError(
                    f"Validation page lineage is stale for {input_id}."
                )
            machine_digest = _sha256_json(record)
            tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in record.get("tabSystems") or []
            }
            blocking_items = [
                item
                for item in record.get("unresolved") or []
                if item.get("blocking") is not False
            ]
            systems: list[dict[str, Any]] = []
            for score_system in record.get("scoreSystems") or []:
                score_system_id = str(score_system.get("scoreSystemId") or "")
                tab_system_id = str(score_system.get("pairedTabSystemId") or "")
                tab_system = tab_by_id.get(tab_system_id)
                if not score_system_id or tab_system is None:
                    raise ExtractionWorkflowError(
                        f"Validation score/tab system pairing is incomplete for {input_id}."
                    )
                line_issues = [
                    item
                    for item in blocking_items
                    if (
                        str(item.get("scoreSystemId") or "") == score_system_id
                        or str(item.get("tabSystemId") or "") == tab_system_id
                        or (
                            not item.get("scoreSystemId")
                            and not item.get("tabSystemId")
                        )
                    )
                ]
                kind_counts = Counter(
                    str(item.get("kind") or "unclassified_validation_issue")
                    for item in line_issues
                )
                issue_phrases = [
                    f"{count} {issue_kind_labels.get(kind, kind.replace('_', ' '))}"
                    for kind, count in sorted(kind_counts.items())
                ]
                issue_core = {
                    "blockingCount": len(line_issues),
                    "kindCounts": dict(sorted(kind_counts.items())),
                    "plainLanguage": "; ".join(issue_phrases),
                }
                key_signature = score_system.get("keySignature") or {}
                captured_key_fifths = (
                    score_system.get("keySignatureFifths")
                    if score_system.get("keySignatureFifths") is not None
                    else (
                        key_signature.get("fifths")
                        if isinstance(key_signature, Mapping)
                        and key_signature.get("fifths") is not None
                        else score_system.get("keyFifths")
                    )
                )
                comparison = _combined_score_tab_columns(score_system, tab_system)
                capture_preflight_blockers = _validation_line_preflight_blockers(
                    comparison,
                    key_signature_known=captured_key_fifths is not None,
                    blocking_issue_count=_validation_capture_issue_count(line_issues),
                )
                line_gate_passed = bool(
                    comparison.get("automaticPitchGatePassed")
                    and comparison.get("mechanicallyValid")
                    and not line_issues
                )
                systems.append(
                    {
                        "inputId": input_id,
                        "sourceLabel": input_names.get(input_id) or input_id,
                        "systemIndex": int(
                            score_system.get("systemIndex") or len(systems) + 1
                        ),
                        "scoreSystemId": score_system_id,
                        "tabSystemId": tab_system_id,
                        "machineRecordDigest": machine_digest,
                        "keySignatureFifths": int(captured_key_fifths or 0),
                        "keySignatureKnown": captured_key_fifths is not None,
                        "comparison": comparison,
                        "validationIssueSummary": {
                            **issue_core,
                            "digest": _sha256_json(issue_core),
                        },
                        "capturePreflightVersion": VALIDATION_LINE_PREFLIGHT_VERSION,
                        "capturePreflightPassed": not capture_preflight_blockers,
                        "capturePreflightBlockers": capture_preflight_blockers,
                        "lineGatePassed": line_gate_passed,
                        "trainingEligible": False,
                    }
                )
            if systems:
                pages.append(
                    {
                        "inputId": input_id,
                        "sourceLabel": input_names.get(input_id) or input_id,
                        "machineRecordDigest": machine_digest,
                        "systems": systems,
                    }
                )
            else:
                no_line_pages.append(
                    {
                        "inputId": input_id,
                        "sourceLabel": input_names.get(input_id) or input_id,
                        "machineRecordDigest": machine_digest,
                        "reason": "no_paired_score_tab_line_detected",
                        "automaticValidationFailure": True,
                    }
                )
        line_count = sum(len(page["systems"]) for page in pages)
        if line_count < 1:
            no_line_pages.extend(
                {
                    "inputId": input_id,
                    "sourceLabel": input_names.get(input_id) or input_id,
                    "reason": "no_paired_score_tab_line_detected",
                    "automaticValidationFailure": True,
                }
                for input_id in work_ids
                if input_id not in {str(item.get("inputId") or "") for item in no_line_pages}
            )
        preflight_failures = [
            {
                "inputId": str(system.get("inputId") or ""),
                "scoreSystemId": str(system.get("scoreSystemId") or ""),
                "blockers": list(system.get("capturePreflightBlockers") or []),
            }
            for page in pages
            for system in page["systems"]
            if not bool(system.get("capturePreflightPassed"))
        ]
        if preflight_failures or no_line_pages:
            blocker_counts = Counter(
                blocker
                for failure in preflight_failures
                for blocker in failure["blockers"]
            )
            if no_line_pages:
                blocker_counts["page_has_no_complete_score_tab_line"] += len(
                    no_line_pages
                )
            readiness_core = {
                "schemaVersion": VALIDATION_LINE_AUDIT_SCHEMA_VERSION,
                "status": "blocked_before_human_review",
                "preflightVersion": VALIDATION_LINE_PREFLIGHT_VERSION,
                "batchId": batch_id,
                "partition": "validation",
                "extractorVersion": EXTRACTOR_VERSION,
                "validationRunDigest": expected_run_digest,
                "validationModel": copy.deepcopy(validation_model),
                "validationPageCount": len(work_ids),
                "lineCount": line_count,
                "blockedLineCount": len(preflight_failures),
                "readyLineCount": line_count - len(preflight_failures),
                "noLinePageCount": len(no_line_pages),
                "blockerCounts": dict(sorted(blocker_counts.items())),
                "failures": preflight_failures,
                "noLinePages": no_line_pages,
                "auditPublished": False,
                "trainingEligible": False,
                "validationGroundTruthMayTrain": False,
                "validationAccessed": True,
                "sealedTestAccessed": False,
            }
            readiness_digest = _sha256_json(readiness_core)
            readiness = {
                **readiness_core,
                "readinessDigest": readiness_digest,
                "relativeUrl": (
                    f"/{batch_id}/extraction/validation/review/validation-line-audit/"
                    f"validation-line-audit-console.html?v={readiness_digest[:8]}"
                ),
                "activatedAsCurrentStatus": activate,
            }
            _write_json(
                audit_dir / f"readiness-{readiness_digest}.json", readiness
            )
            _write_private_text(
                audit_dir / f"validation-line-audit-not-ready-{readiness_digest[:12]}.html",
                _validation_audit_not_ready_html(readiness),
            )
            if activate:
                _write_json(audit_dir / "packet-summary.json", readiness)
                _write_private_text(
                    audit_dir / "validation-line-audit-console.html",
                    _validation_audit_not_ready_html(readiness),
                )
            return readiness

        for page in pages:
            input_id = str(page.get("inputId") or "")
            record = _read_json(pages_dir / f"{input_id}.json")
            score_by_id = {
                str(system.get("scoreSystemId") or ""): system
                for system in record.get("scoreSystems") or []
            }
            tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in record.get("tabSystems") or []
            }
            for system in page["systems"]:
                score_system = score_by_id[str(system["scoreSystemId"])]
                tab_system = tab_by_id[str(system["tabSystemId"])]
                crop = _prepare_score_tab_source_crop(
                    output_root=output_root,
                    audit_dir=audit_dir,
                    input_id=input_id,
                    record=record,
                    score_system=score_system,
                    tab_system=tab_system,
                )
                system["sourcePairUrl"] = Path(
                    os.path.relpath(
                        output_root / str(crop["relativePath"]), audit_dir
                    )
                ).as_posix()
                system["sourcePairSha256"] = crop["sha256"]
        packet_core = {
            "schemaVersion": VALIDATION_LINE_AUDIT_SCHEMA_VERSION,
            "reviewType": "validation_line_audit",
            "gateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
            "rendererVersion": COMBINED_SCORE_TAB_RENDERER_VERSION,
            "preflightVersion": VALIDATION_LINE_PREFLIGHT_VERSION,
            "batchId": batch_id,
            "partition": "validation",
            "extractorVersion": EXTRACTOR_VERSION,
            "validationRunDigest": expected_run_digest,
            "validationModel": copy.deepcopy(validation_model),
            "pages": pages,
            "validationPageCount": len(work_ids),
            "reviewablePageCount": len(pages),
            "noLinePages": no_line_pages,
            "noLinePageCount": len(no_line_pages),
            "lineCount": line_count,
            "jointTabReviewRequired": True,
            "trainingEligible": False,
            "trainingEligibleBeforeReview": False,
            "validationGroundTruthMayTrain": False,
            "validationAccessed": True,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_filename = f"packet-{packet_digest}.json"
        console_filename = (
            f"validation-line-audit-console-{packet_digest[:12]}.html"
        )
        packet_path = audit_dir / packet_filename
        console_path = audit_dir / console_filename
        _write_json(packet_path, packet)
        _write_private_text(
            console_path,
            _combined_score_tab_console_html(
                packet_digest=packet_digest,
                packet_filename=packet_filename,
                review_type="validation_line_audit",
            ),
        )
        if activate:
            _write_json(audit_dir / "packet.json", packet)
            _write_private_text(
                audit_dir / "validation-line-audit-console.html",
                _combined_score_tab_console_html(
                    packet_digest=packet_digest,
                    review_type="validation_line_audit",
                ),
            )
        result = {
            "schemaVersion": VALIDATION_LINE_AUDIT_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "validation",
            "validationPageCount": len(work_ids),
            "reviewablePageCount": len(pages),
            "noLinePageCount": len(no_line_pages),
            "noLinePageDigest": _sha256_json(no_line_pages),
            "lineCount": line_count,
            "machinePassingLineCount": sum(
                bool(system["lineGatePassed"])
                for page in pages
                for system in page["systems"]
            ),
            "humanReviewLineCount": sum(
                not bool(system["lineGatePassed"])
                for page in pages
                for system in page["systems"]
            ),
            "blockingIssueCount": sum(
                int(system["validationIssueSummary"]["blockingCount"])
                for page in pages
                for system in page["systems"]
            ),
            "validationModel": copy.deepcopy(validation_model),
            "validationRunDigest": expected_run_digest,
            "packetDigest": packet_digest,
            "packetPath": str(packet_path.relative_to(batch_dir)),
            "consolePath": str(console_path.relative_to(batch_dir)),
            "relativeUrl": (
                f"/{batch_id}/extraction/validation/review/validation-line-audit/"
                f"{console_filename}?v={packet_digest[:8]}"
            ),
            "activatedAsCurrentPacket": activate,
            "eligibleForTraining": False,
            "validationGroundTruthMayTrain": False,
            "validationAccessed": True,
            "sealedTestAccessed": False,
        }
        _write_json(audit_dir / f"packet-summary-{packet_digest}.json", result)
        if activate:
            _write_json(audit_dir / "packet-summary.json", result)
        return result

    def prepare_challenger_comparison_review(
        self,
        batch_id: str,
        *,
        model_id: str,
        report_digest: str,
        input_ids: Sequence[str],
        score_system_ids: Sequence[str] | None = None,
        max_decisions: int | None = None,
    ) -> dict[str, Any]:
        """Prepare a small concrete-tab review from score-gated shadow disagreements."""

        requested_inputs = {str(value).strip() for value in input_ids if str(value).strip()}
        requested_systems = {
            str(value).strip() for value in score_system_ids or [] if str(value).strip()
        }
        if not requested_inputs or len(requested_inputs) > 3:
            raise ExtractionWorkflowError("Challenger review needs 1-3 discovery pages.")
        if max_decisions is not None and not 1 <= max_decisions <= 12:
            raise ExtractionWorkflowError("Challenger review cap must be 1-12 decisions.")
        shadow_dir = self.private_root / "discovery-shadows" / model_id
        report_path = shadow_dir / f"report-{report_digest}.json"
        if not report_path.exists():
            raise ExtractionWorkflowError("Challenger review references a missing shadow report.")
        report = _read_json(report_path)
        computed_report_digest = _sha256_json(
            {
                key: value
                for key, value in report.items()
                if key not in {"reportDigest", "createdAt"}
            }
        )
        if (
            str(report.get("modelId") or "") != model_id
            or str(report.get("reportDigest") or "") != report_digest
            or computed_report_digest != report_digest
        ):
            raise ExtractionWorkflowError("Challenger shadow report belongs to another model.")
        selected_lineage = (
            (report.get("evidenceArtifacts") or {}).get("selectedLines") or {}
        )
        if selected_lineage:
            selected_path = self.private_root / str(
                selected_lineage.get("relativePath") or ""
            )
        else:
            selected_path = shadow_dir / f"selected-lines-{report_digest}.jsonl"
        if not selected_path.exists():
            raise ExtractionWorkflowError("Challenger review references missing shadow evidence.")
        selected_records = _read_jsonl(selected_path)
        if selected_lineage and (
            _sha256_bytes(selected_path.read_bytes())
            != str(selected_lineage.get("fileSha256") or "")
            or _sha256_json(selected_records)
            != str(selected_lineage.get("canonicalDigest") or "")
            or len(selected_records)
            != int(selected_lineage.get("recordCount") or 0)
        ):
            raise ExtractionWorkflowError("Challenger shadow evidence digest changed.")
        selected = [
            item
            for item in selected_records
            if str(item.get("batchId") or "") == batch_id
            and str(item.get("inputId") or "") in requested_inputs
            and (
                not requested_systems
                or str(item.get("scoreSystemId") or "") in requested_systems
            )
        ]
        found_inputs = {str(item.get("inputId") or "") for item in selected}
        if found_inputs != requested_inputs:
            raise ExtractionWorkflowError("Requested challenger pages are not in this shadow selection.")
        if requested_systems != {
            str(item.get("scoreSystemId") or "") for item in selected
        } and requested_systems:
            raise ExtractionWorkflowError("Requested challenger lines are not in this shadow selection.")

        batch_dir, manifest, _work = self._batch_paths(batch_id, "discovery")
        output_root = batch_dir / "extraction" / "discovery"
        review_root = output_root / "review"
        review_dir = review_root / "challenger-comparison"
        review_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(review_dir, 0o700)
        approved = {
            str(item.get("inputId") or ""): item
            for item in _read_jsonl(review_root / "approved-record-index.jsonl")
            if item.get("status") == "human_approved"
        }
        input_names = {
            str(item.get("inputId") or ""): Path(str(item.get("relativePath") or "")).name
            for item in manifest.get("inputs") or []
        }
        systems: list[dict[str, Any]] = []
        remaining_decisions = max_decisions
        for item in selected:
            if remaining_decisions == 0:
                break
            if not bool(item.get("automaticScoreAuditPassed")):
                raise ExtractionWorkflowError("Challenger line failed the score-completeness gate.")
            input_id = str(item.get("inputId") or "")
            meta = approved.get(input_id)
            if meta is None:
                raise ExtractionWorkflowError("Challenger line lacks an approved source record.")
            record_path = output_root / str(meta.get("reviewedRecordPath") or "")
            record = _read_json(record_path)
            if _sha256_json(record) != str(meta.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError("Approved challenger source record changed.")
            score_system_id = str(item.get("scoreSystemId") or "")
            tab_system_id = str(item.get("tabSystemId") or "")
            score_system = next(
                (x for x in record.get("scoreSystems") or [] if str(x.get("scoreSystemId") or "") == score_system_id),
                None,
            )
            tab_system = next(
                (x for x in record.get("tabSystems") or [] if str(x.get("tabSystemId") or "") == tab_system_id),
                None,
            )
            if score_system is None or tab_system is None:
                raise ExtractionWorkflowError("Challenger source line is missing from its approved record.")
            comparison = _combined_score_tab_columns(score_system, tab_system)
            if not bool(comparison.get("automaticPitchGatePassed")):
                raise ExtractionWorkflowError("Challenger source line no longer has exact score/tab pitches.")
            crop = _prepare_score_tab_source_crop(
                output_root=output_root,
                audit_dir=review_dir,
                input_id=input_id,
                record=record,
                score_system=score_system,
                tab_system=tab_system,
            )
            event_ordinals = {
                str(state.get("tabEventId") or ""): index
                for index, state in enumerate(comparison.get("tabStates") or [], start=1)
            }
            disagreements: list[dict[str, Any]] = []
            for disagreement in item.get("challengerDisagreements") or []:
                if remaining_decisions == 0:
                    break
                source_actions = list(
                    (disagreement.get("sourceCandidate") or {}).get("mechanicalActions") or []
                )
                challenger_actions = list(
                    (disagreement.get("challengerCandidate") or {}).get("mechanicalActions") or []
                )
                if not source_actions or not challenger_actions:
                    raise ExtractionWorkflowError(
                        "A challenger difference lacks concrete tablature actions."
                    )
                source_tab_event_id = str(disagreement.get("sourceTabEventId") or "")
                disagreements.append(
                    {
                        "decisionId": str(disagreement.get("decisionId") or ""),
                        "inputId": input_id,
                        "scoreSystemId": score_system_id,
                        "sourceTabEventId": source_tab_event_id,
                        "eventIndex": event_ordinals.get(source_tab_event_id),
                        "melodyPitch": str(disagreement.get("melodyPitch") or ""),
                        "sourceActions": source_actions,
                        "challengerActions": challenger_actions,
                        "predictionMargin": disagreement.get("predictionMargin"),
                    }
                )
                if remaining_decisions is not None:
                    remaining_decisions -= 1
            if not disagreements:
                continue
            systems.append(
                {
                    "inputId": input_id,
                    "sourceLabel": input_names.get(input_id) or input_id,
                    "systemIndex": int(score_system.get("systemIndex") or 0),
                    "scoreSystemId": score_system_id,
                    "tabSystemId": tab_system_id,
                    "sourcePairUrl": Path(
                        os.path.relpath(output_root / str(crop["relativePath"]), review_dir)
                    ).as_posix(),
                    "scoreAttackCount": int(comparison.get("scoreAttackCount") or 0),
                    "tabAttackCount": int(comparison.get("tabAttackCount") or 0),
                    "automaticPitchGatePassed": True,
                    "disagreements": disagreements,
                }
            )
        if not systems:
            raise ExtractionWorkflowError("The requested shadow lines contain no challenger differences.")
        packet_core = {
            "schemaVersion": CHALLENGER_COMPARISON_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": "discovery",
            "modelId": model_id,
            "shadowReportDigest": report_digest,
            "systems": systems,
            "scoreCompletenessGatePassed": True,
            "sourceTabMechanicsPassed": True,
            "trainingEligibleBeforeReview": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        packet_digest = _sha256_json(packet_core)
        packet = {**packet_core, "packetDigest": packet_digest}
        packet_path = review_dir / f"packet-{packet_digest}.json"
        console_path = review_dir / f"challenger-comparison-console-{packet_digest[:12]}.html"
        _write_json(packet_path, packet)
        _write_private_text(
            console_path,
            _challenger_comparison_console_html(packet_digest=packet_digest),
        )
        _write_json(review_dir / "packet.json", packet)
        _write_private_text(
            review_dir / "challenger-comparison-console.html",
            _challenger_comparison_console_html(packet_digest=packet_digest),
        )
        return {
            "schemaVersion": CHALLENGER_COMPARISON_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "modelId": model_id,
            "packetDigest": packet_digest,
            "systemCount": len(systems),
            "disagreementCount": sum(len(item["disagreements"]) for item in systems),
            "relativeUrl": (
                f"/{batch_id}/extraction/discovery/review/challenger-comparison/"
                f"challenger-comparison-console-{packet_digest[:12]}.html"
            ),
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def replay_combined_score_tab_regressions(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Re-evaluate current reviewed lines and prove exclusions remain fail closed."""

        if partition != "discovery":
            raise ExtractionWorkflowError(
                "Combined score/tab regression replay is discovery-only."
            )
        batch_dir, _manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        application_dir = (
            output_root / "review" / "combined-score-tab-audit" / "application"
        )
        index_path = application_dir / "approved-line-index.jsonl"
        raw_entries = _read_jsonl(index_path) if index_path.exists() else []
        entries = _current_combined_line_entries(raw_entries)
        feedback_path = application_dir / "feedback-queue.jsonl"
        feedback_ids = {
            str(item.get("feedbackId") or "")
            for item in (_read_jsonl(feedback_path) if feedback_path.exists() else [])
        }
        cases: list[dict[str, Any]] = []
        for entry in entries:
            input_id = str(entry.get("inputId") or "")
            score_system_id = str(entry.get("scoreSystemId") or "")
            tab_system_id = str(entry.get("tabSystemId") or "")
            decision_id = str(entry.get("decisionId") or "")
            status = str(entry.get("status") or "")
            failures: list[str] = []
            comparison: dict[str, Any] | None = None
            recomputed_scope: dict[str, Any] | None = None

            if status in {
                "unresolved_requires_structured_correction",
                "contract_revalidation_required",
            }:
                if any(
                    entry.get(field) is not False
                    for field in (
                        "scorePitchTrainingEligible",
                        "pitchToTabTrainingEligible",
                        "trainingEligible",
                    )
                ):
                    failures.append("unresolved_line_not_fail_closed")
                if (
                    status == "unresolved_requires_structured_correction"
                    and str(entry.get("feedbackId") or "") not in feedback_ids
                ):
                    failures.append("unresolved_line_missing_feedback_provenance")
                if (
                    status == "contract_revalidation_required"
                    and not str(entry.get("supersedesDecisionId") or "")
                ):
                    failures.append("contract_revalidation_missing_superseded_decision")
            elif status == "human_approved_pitch_only":
                relative_path = str(entry.get("reviewedRecordPath") or "")
                expected_digest = str(entry.get("reviewedRecordDigest") or "")
                record_path = output_root / relative_path
                if not relative_path or not record_path.exists():
                    failures.append("reviewed_record_missing")
                else:
                    record = _read_json(record_path)
                    if _sha256_json(record) != expected_digest:
                        failures.append("reviewed_record_digest_changed")
                    score_by_id = {
                        str(item.get("scoreSystemId") or ""): item
                        for item in record.get("scoreSystems") or []
                    }
                    tab_by_id = {
                        str(item.get("tabSystemId") or ""): item
                        for item in record.get("tabSystems") or []
                    }
                    score_system = score_by_id.get(score_system_id)
                    tab_system = tab_by_id.get(tab_system_id)
                    if score_system is None or tab_system is None:
                        failures.append("reviewed_system_missing")
                    else:
                        grouping_contract = str(
                            entry.get("gateVersion")
                            or LEGACY_COMBINED_SCORE_TAB_GATE_VERSION
                        )
                        if str(score_system.get("pairedTabSystemId") or "") != tab_system_id:
                            failures.append("score_tab_pairing_changed")
                        if str(score_system.get("combinedScoreTabDecisionId") or "") != decision_id:
                            failures.append("score_decision_provenance_changed")
                        comparison = _combined_score_tab_columns(
                            score_system,
                            tab_system,
                            grouping_contract=grouping_contract,
                        )
                        _alignments, recomputed_scope = _combined_review_alignments(
                            score_system,
                            tab_system,
                            decision_id=decision_id,
                            grouping_contract=grouping_contract,
                        )
                        if int(entry.get("scoreAttackCount") or 0) != int(
                            comparison["scoreAttackCount"]
                        ):
                            failures.append("score_attack_count_changed")
                        if int(entry.get("tabMovementCount") or 0) != int(
                            comparison["tabMovementCount"]
                        ):
                            failures.append("tab_movement_count_changed")
                        if entry.get("tabAttackCount") is not None and int(
                            entry.get("tabAttackCount") or 0
                        ) != int(comparison["tabAttackCount"]):
                            failures.append("tab_attack_count_changed")
                        if int(entry.get("exactColumnCount") or 0) != int(
                            comparison["exactColumnCount"]
                        ):
                            failures.append("exact_pitch_column_count_changed")
                        if not bool(comparison.get("mechanicallyValid")):
                            failures.append("mechanical_validation_failed")
                        expected_eligible = bool(entry.get("pitchToTabTrainingEligible"))
                        if expected_eligible != bool(
                            recomputed_scope.get("pitchToTabTrainingEligible")
                        ):
                            failures.append("correspondence_eligibility_changed")
                        if str(entry.get("alignmentMode") or "") != str(
                            recomputed_scope.get("mode") or ""
                        ):
                            failures.append("alignment_mode_changed")
                        if entry.get("scorePitchTrainingEligible") is not True:
                            failures.append("approved_score_pitch_scope_missing")
                        if entry.get("trainingEligible") is not expected_eligible:
                            failures.append("training_eligibility_inconsistent")
                        if entry.get("scoreRhythmTrainingEligible") is not False:
                            failures.append("score_rhythm_scope_leaked")
                        if any(
                            (event.get("fieldReviewStates") or {}).get("pitch")
                            != "human_approved"
                            or (event.get("fieldReviewStates") or {}).get("duration")
                            != "not_reviewed_excluded"
                            for event in score_system.get("scoreEvents") or []
                            if not event.get("rest")
                        ):
                            failures.append("score_field_review_scope_changed")
            else:
                failures.append("unsupported_line_status")

            cases.append(
                {
                    "inputId": input_id,
                    "scoreSystemId": score_system_id,
                    "tabSystemId": tab_system_id,
                    "decisionId": decision_id,
                    "status": status,
                    "scorePitchTrainingEligible": bool(
                        entry.get("scorePitchTrainingEligible")
                    ),
                    "pitchToTabTrainingEligible": bool(
                        entry.get("pitchToTabTrainingEligible")
                    ),
                    "scoreRhythmTrainingEligible": False,
                    "scoreAttackCount": (
                        int(comparison["scoreAttackCount"]) if comparison else None
                    ),
                    "tabMovementCount": (
                        int(comparison["tabMovementCount"]) if comparison else None
                    ),
                    "tabAttackCount": (
                        int(comparison["tabAttackCount"]) if comparison else None
                    ),
                    "alignmentMode": (
                        str(recomputed_scope.get("mode") or "")
                        if recomputed_scope
                        else None
                    ),
                    "failures": failures,
                    "passed": not failures,
                }
            )

        report_core = {
            "schemaVersion": COMBINED_SCORE_TAB_REGRESSION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "appendOnlyLineEntryCount": len(raw_entries),
            "currentLineCount": len(entries),
            "supersededLineEntryCount": len(raw_entries) - len(entries),
            "scorePitchApprovedLineCount": sum(
                bool(item.get("scorePitchTrainingEligible")) for item in cases
            ),
            "pitchToTabTrainingEligibleLineCount": sum(
                bool(item.get("pitchToTabTrainingEligible")) for item in cases
            ),
            "unresolvedFailClosedLineCount": sum(
                item.get("status")
                in {
                    "unresolved_requires_structured_correction",
                    "contract_revalidation_required",
                }
                and bool(item.get("passed"))
                for item in cases
            ),
            "failureCount": sum(len(item.get("failures") or []) for item in cases),
            "gatePassed": all(bool(item.get("passed")) for item in cases),
            "scoreRhythmTrainingEligibleLineCount": 0,
            "cases": cases,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report = {**report_core, "reportDigest": _sha256_json(report_core)}
        report_dir = (
            output_root
            / "review"
            / "analysis"
            / COMBINED_SCORE_TAB_REGRESSION_SCHEMA_VERSION
        )
        _write_json(report_dir / "combined-line-regression-report.json", report)
        return report

    def quarantine_combined_score_tab_contract_regressions(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Supersede stale line eligibility after a stricter alignment contract change."""

        if partition != "discovery":
            raise ExtractionWorkflowError(
                "Combined score/tab contract quarantine is discovery-only."
            )
        report = self.replay_combined_score_tab_regressions(
            batch_id,
            partition=partition,
        )
        batch_dir, _manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        application_dir = (
            output_root / "review" / "combined-score-tab-audit" / "application"
        )
        index_path = application_dir / "approved-line-index.jsonl"
        raw_entries = _read_jsonl(index_path) if index_path.exists() else []
        current = _current_combined_line_entries(raw_entries)
        current_by_key = {
            (str(item.get("inputId") or ""), str(item.get("scoreSystemId") or "")): item
            for item in current
        }
        replacements: list[dict[str, Any]] = []
        for case in report.get("cases") or []:
            failures = list(case.get("failures") or [])
            if not failures:
                continue
            key = (
                str(case.get("inputId") or ""),
                str(case.get("scoreSystemId") or ""),
            )
            prior = current_by_key.get(key)
            if prior is None:
                raise ExtractionWorkflowError(
                    "A failed combined regression lost its current line entry."
                )
            if prior.get("status") == "contract_revalidation_required":
                continue
            replacement = {
                **copy.deepcopy(prior),
                "decisionId": _stable_id(
                    "combined-score-tab-contract-quarantine",
                    str(prior.get("decisionId") or ""),
                    COMBINED_SCORE_TAB_GATE_VERSION,
                    *sorted(str(value) for value in failures),
                ),
                "status": "contract_revalidation_required",
                "supersedesDecisionId": str(prior.get("decisionId") or ""),
                "scorePitchTrainingEligible": False,
                "pitchToTabTrainingEligible": False,
                "trainingEligible": False,
                "scoreRhythmTrainingEligible": False,
                "contractRevalidationReasons": failures,
                "contractRevalidationGateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
                "quarantinedAt": _utc_now(),
            }
            if case.get("scoreAttackCount") is not None:
                replacement["scoreAttackCount"] = int(case["scoreAttackCount"])
            if case.get("tabAttackCount") is not None:
                replacement["tabAttackCount"] = int(case["tabAttackCount"])
            if case.get("tabMovementCount") is not None:
                replacement["tabMovementCount"] = int(case["tabMovementCount"])
            replacements.append(replacement)
        if replacements:
            _write_jsonl(index_path, raw_entries + replacements)
        replay = self.replay_combined_score_tab_regressions(
            batch_id,
            partition=partition,
        )
        return {
            "schemaVersion": COMBINED_SCORE_TAB_REGRESSION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "quarantinedLineCount": len(replacements),
            "supersededDecisionIds": [
                str(item.get("supersedesDecisionId") or "") for item in replacements
            ],
            "currentPitchToTabTrainingEligibleLineCount": replay[
                "pitchToTabTrainingEligibleLineCount"
            ],
            "gatePassed": replay["gatePassed"],
            "reportDigest": replay["reportDigest"],
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }

    def revalidate_combined_score_tab_normalized_positions(
        self,
        batch_id: str,
        *,
        input_id: str,
        score_system_id: str,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Migrate one reviewed v4 line whose normalized X positions were collapsed.

        This is deliberately narrower than a general approval migration.  It
        preserves an existing human score-pitch decision, changes no score or
        tablature facts, and only rebuilds the line's deterministic grouping
        and alignments under the scale-aware v5 contract.
        """

        if partition != "discovery":
            raise ExtractionWorkflowError(
                "Combined score/tab contract revalidation is discovery-only."
            )
        batch_dir, _manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        application_dir = (
            output_root / "review" / "combined-score-tab-audit" / "application"
        )
        index_path = application_dir / "approved-line-index.jsonl"
        raw_entries = _read_jsonl(index_path) if index_path.exists() else []
        current = _current_combined_line_entries(raw_entries)
        matches = [
            item
            for item in current
            if str(item.get("inputId") or "") == input_id
            and str(item.get("scoreSystemId") or "") == score_system_id
        ]
        if len(matches) != 1:
            raise ExtractionWorkflowError(
                "Normalized-position revalidation requires one current reviewed line."
            )
        prior = matches[0]
        if (
            prior.get("status") != "human_approved_pitch_only"
            or prior.get("scorePitchTrainingEligible") is not True
            or prior.get("scoreRhythmTrainingEligible") is not False
            or str(prior.get("gateVersion") or "")
            != FIXED_PRINTED_X_COMBINED_SCORE_TAB_GATE_VERSION
            or str(prior.get("selectedScoreCandidate") or "")
            != "human_confirmed_tab_pitch_hypothesis"
        ):
            raise ExtractionWorkflowError(
                "Only a human-confirmed v4 tab-pitch score replacement may use this migration."
            )
        relative_path = str(prior.get("reviewedRecordPath") or "")
        prior_digest = str(prior.get("reviewedRecordDigest") or "")
        record_path = output_root / relative_path
        if not relative_path or not record_path.exists():
            raise ExtractionWorkflowError("The reviewed record to revalidate is missing.")
        record = _read_json(record_path)
        if _sha256_json(record) != prior_digest:
            raise ExtractionWorkflowError("The reviewed record digest changed.")
        revised = copy.deepcopy(record)
        score_by_id = {
            str(item.get("scoreSystemId") or ""): item
            for item in revised.get("scoreSystems") or []
        }
        tab_by_id = {
            str(item.get("tabSystemId") or ""): item
            for item in revised.get("tabSystems") or []
        }
        score_system = score_by_id.get(score_system_id)
        tab_system_id = str(prior.get("tabSystemId") or "")
        tab_system = tab_by_id.get(tab_system_id)
        if score_system is None or tab_system is None:
            raise ExtractionWorkflowError("The reviewed score/tab system pair is missing.")
        if str(score_system.get("pairedTabSystemId") or "") != tab_system_id:
            raise ExtractionWorkflowError("The reviewed score/tab system pairing changed.")
        old_decision_id = str(prior.get("decisionId") or "")
        if str(score_system.get("combinedScoreTabDecisionId") or "") != old_decision_id:
            raise ExtractionWorkflowError("The reviewed score decision provenance changed.")
        score_events = [
            event
            for event in score_system.get("scoreEvents") or []
            if not event.get("rest")
        ]
        printed_x = [
            float(event["defaultX"])
            for event in score_events
            if event.get("defaultX") is not None
        ]
        if not printed_x or max(abs(value) for value in printed_x) > 2.0:
            raise ExtractionWorkflowError(
                "The reviewed score line does not use normalized horizontal positions."
            )
        if any(
            (event.get("fieldReviewStates") or {}).get("pitch") != "human_approved"
            or (event.get("fieldReviewStates") or {}).get("duration")
            != "not_reviewed_excluded"
            for event in score_events
        ):
            raise ExtractionWorkflowError(
                "The reviewed score line lacks the required pitch-only human scope."
            )

        comparison = _combined_score_tab_columns(score_system, tab_system)
        new_decision_id = _stable_id(
            "combined-score-tab-normalized-position-revalidation",
            old_decision_id,
            COMBINED_SCORE_TAB_GATE_VERSION,
        )
        new_alignments, alignment_scope = _combined_review_alignments(
            score_system,
            tab_system,
            decision_id=new_decision_id,
        )
        if not bool(alignment_scope.get("pitchToTabTrainingEligible")) or not new_alignments:
            raise ExtractionWorkflowError(
                "Scale-aware regrouping did not produce complete eligible correspondence."
            )
        if int(comparison.get("scoreAttackCount") or 0) <= int(
            prior.get("scoreAttackCount") or 0
        ):
            raise ExtractionWorkflowError(
                "Scale-aware regrouping did not recover additional score attacks."
            )
        prior_tab_digest = _reviewed_tab_facts_digest(revised)
        score_event_ids = {
            str(event.get("scoreEventId") or "") for event in score_events
        }
        tab_event_ids = {
            str(event.get("tabEventId") or "")
            for event in tab_system.get("tabEvents") or []
        }
        revised["eventAlignments"] = [
            alignment
            for alignment in revised.get("eventAlignments") or []
            if not (
                set(str(value) for value in alignment.get("scoreEventIds") or [])
                & score_event_ids
                or set(str(value) for value in alignment.get("tabEventIds") or [])
                & tab_event_ids
            )
        ] + new_alignments
        score_system["combinedScoreTabDecisionId"] = new_decision_id
        score_system["scoreAuditApprovalScope"] = {
            **copy.deepcopy(score_system.get("scoreAuditApprovalScope") or {}),
            "scoreToTabCorrespondence": "human_approved",
            "noteDuration": "not_reviewed_excluded",
            "rhythmicPosition": "not_reviewed_excluded",
        }
        for event in score_events:
            event["combinedScoreTabDecisionId"] = new_decision_id
        revised["revision"] = int(revised.get("revision") or 1) + 1
        revised["combinedScoreTabContractRevalidation"] = {
            "fromGateVersion": FIXED_PRINTED_X_COMBINED_SCORE_TAB_GATE_VERSION,
            "toGateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
            "reason": "normalized_horizontal_positions_require_scale_aware_grouping",
            "supersedesDecisionId": old_decision_id,
            "decisionId": new_decision_id,
            "revalidatedAt": _utc_now(),
            "scoreFactsChanged": False,
            "tabFactsChanged": False,
            "scoreRhythmTrainingEligible": False,
        }
        if _reviewed_tab_facts_digest(revised) != prior_tab_digest:
            raise ExtractionWorkflowError(
                "Contract revalidation changed human-approved tablature facts."
            )
        revised_digest = _sha256_json(revised)
        target = application_dir / "applied-records" / input_id / f"{revised_digest}.json"
        _write_json(target, revised)
        revised_relative_path = str(target.relative_to(output_root))
        replacement = {
            **copy.deepcopy(prior),
            "gateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
            "decisionId": new_decision_id,
            "supersedesDecisionId": old_decision_id,
            "reviewedRecordPath": revised_relative_path,
            "reviewedRecordDigest": revised_digest,
            "scorePitchTrainingEligible": True,
            "pitchToTabTrainingEligible": True,
            "trainingEligible": True,
            "scoreRhythmTrainingEligible": False,
            "alignmentMode": str(alignment_scope.get("mode") or ""),
            "alignmentExclusionReason": None,
            "scoreAttackCount": int(comparison["scoreAttackCount"]),
            "tabAttackCount": int(comparison["tabAttackCount"]),
            "tabMovementCount": int(comparison["tabMovementCount"]),
            "movementOnlyCount": int(comparison["movementOnlyCount"]),
            "exactColumnCount": int(comparison["exactColumnCount"]),
            "contractRevalidationReason": (
                "normalized_horizontal_positions_require_scale_aware_grouping"
            ),
            "contractRevalidatedAt": _utc_now(),
        }
        _write_jsonl(index_path, raw_entries + [replacement])
        replay = self.replay_combined_score_tab_regressions(
            batch_id,
            partition=partition,
        )
        if not bool(replay.get("gatePassed")):
            raise ExtractionWorkflowError(
                "Combined score/tab replay failed after normalized-position revalidation."
            )
        report_core = {
            "schemaVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "inputId": input_id,
            "scoreSystemId": score_system_id,
            "tabSystemId": tab_system_id,
            "fromGateVersion": FIXED_PRINTED_X_COMBINED_SCORE_TAB_GATE_VERSION,
            "toGateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
            "supersededDecisionId": old_decision_id,
            "decisionId": new_decision_id,
            "priorScoreAttackCount": int(prior.get("scoreAttackCount") or 0),
            "scoreAttackCount": int(comparison["scoreAttackCount"]),
            "tabAttackCount": int(comparison["tabAttackCount"]),
            "pitchToTabTrainingEligible": True,
            "scoreRhythmTrainingEligible": False,
            "reviewedRecordDigest": revised_digest,
            "regressionReportDigest": str(replay.get("reportDigest") or ""),
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        report = {**report_core, "reportDigest": _sha256_json(report_core)}
        report_path = (
            application_dir
            / "contract-revalidations"
            / f"normalized-positions-{report['reportDigest']}.json"
        )
        _write_json(report_path, report)
        return report

    def apply_combined_score_tab_review(
        self,
        batch_id: str,
        source: Path | str,
        *,
        partition: str = "discovery",
        dry_run: bool = False,
    ) -> dict[str, Any]:
        """Apply a digest-pinned combined review without granting page-wide approval."""

        if partition != "discovery":
            raise ExtractionWorkflowError("Combined score/tab review is discovery-only.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review" / "combined-score-tab-audit"
        source_path = Path(source).expanduser().resolve()
        submissions_dir = (review_dir / "submissions").resolve()
        if (
            source_path.parent != submissions_dir
            or not source_path.name.startswith("combined-score-tab-submission-")
            or source_path.suffix != ".jsonl"
        ):
            raise ExtractionWorkflowError(
                "Combined review application requires a received private submission."
            )
        receipt_path = source_path.with_suffix(".json")
        if receipt_path.exists():
            receipt = _read_json(receipt_path)
            packet_digest = str(receipt.get("packetDigest") or "")
        else:
            current_packet_path = review_dir / "packet.json"
            if not current_packet_path.exists():
                raise ExtractionWorkflowError("The combined score/tab packet is missing.")
            packet_digest = str(_read_json(current_packet_path).get("packetDigest") or "")
        packet, packet_path = _load_combined_score_tab_packet(review_dir, packet_digest)
        if (
            str(packet.get("batchId") or "") != batch_id
            or str(packet.get("partition") or "") != partition
        ):
            raise ExtractionWorkflowError("The combined score/tab packet has another identity.")
        reviews = _read_jsonl(source_path)
        submission_digest = _sha256_json(
            {
                "reviewType": "combined_score_tab",
                "batchId": batch_id,
                "partition": partition,
                "packetDigest": packet_digest,
                "reviews": reviews,
            }
        )
        expected_name = f"combined-score-tab-submission-{submission_digest[:20]}.jsonl"
        if source_path.name != expected_name:
            raise ExtractionWorkflowError(
                "The combined score/tab submission filename does not match its contents."
            )
        packet_systems = [
            system
            for page in packet.get("pages") or []
            for system in page.get("systems") or []
        ]
        if packet.get("jointTabReviewRequired"):
            stale_burden_failures = [
                {
                    "inputId": str(system.get("inputId") or ""),
                    "scoreSystemId": str(system.get("scoreSystemId") or ""),
                    "blockers": _provisional_joint_review_blockers(
                        system.get("comparison") or {},
                        key_signature_known=system.get("keySignatureKnown") is True,
                    ),
                }
                for system in packet_systems
            ]
            stale_burden_failures = [
                item for item in stale_burden_failures if item["blockers"]
            ]
            if stale_burden_failures:
                raise ExtractionWorkflowError(
                    "The provisional combined-review packet fails the current "
                    "reviewer-burden gate and cannot be applied."
                )
        packet_by_key = {
            (str(item.get("inputId") or ""), str(item.get("scoreSystemId") or "")): item
            for item in packet_systems
        }
        review_by_key = {
            (str(item.get("inputId") or ""), str(item.get("scoreSystemId") or "")): item
            for item in reviews
        }
        if len(review_by_key) != len(reviews) or set(review_by_key) != set(packet_by_key):
            raise ExtractionWorkflowError(
                "The combined score/tab submission is incomplete or duplicated."
            )
        valid_statuses = {
            "both_match",
            "tab_pitch_hypothesis_matches",
            "score_reader_matches",
            "feedback",
        }
        if any(str(item.get("status") or "") not in valid_statuses for item in reviews):
            raise ExtractionWorkflowError("The combined review contains an unsupported status.")
        if packet.get("jointTabReviewRequired") and any(
            str(item.get("status") or "") != "feedback" and item.get("tabConfirmed") is not True
            for item in reviews
        ):
            raise ExtractionWorkflowError(
                "Joint score/tab review lacks explicit tablature confirmation."
            )
        for key, review in review_by_key.items():
            expected = packet_by_key[key]
            if (
                str(review.get("tabSystemId") or "")
                != str(expected.get("tabSystemId") or "")
                or str(review.get("expectedMachineRecordDigest") or "")
                != str(expected.get("machineRecordDigest") or "")
                or str(review.get("expectedScoreCandidateDigest") or "")
                != str(expected.get("scoreCandidateDigest") or "")
            ):
                raise ExtractionWorkflowError("A combined review target changed after display.")
            if str(review.get("status") or "") == "feedback" and not str(
                review.get("comment") or ""
            ).strip():
                raise ExtractionWorkflowError("Combined review feedback needs a comment.")

        application_digest = _sha256_json(
            {
                "schemaVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
                "packetDigest": packet_digest,
                "submissionDigest": submission_digest,
            }
        )
        application_dir = review_dir / "application"
        versioned_summary = application_dir / "summaries" / f"{application_digest}.json"
        if versioned_summary.exists():
            return {**_read_json(versioned_summary), "deduplicated": True, "dryRun": dry_run}

        versioned_candidate_index = (
            review_dir / f"score-candidate-index-{packet_digest}.jsonl"
        )
        candidate_index_path = (
            versioned_candidate_index
            if versioned_candidate_index.exists()
            else review_dir / "score-candidate-index.jsonl"
        )
        candidate_entries = _read_jsonl(candidate_index_path)
        candidate_by_input = {str(item.get("inputId") or ""): item for item in candidate_entries}
        source_copedent_id = str(manifest.get("sourceCopedentId") or "")
        source_copedent = get_e9_copedent_profile(source_copedent_id)
        source_copedent_digest = e9_copedent_profile_digest(source_copedent)
        revised_records: dict[str, dict[str, Any]] = {}
        record_lineage: dict[str, dict[str, Any]] = {}
        line_index: list[dict[str, Any]] = []
        feedback_queue: list[dict[str, Any]] = []

        for input_id in sorted({key[0] for key in packet_by_key}):
            entry = candidate_by_input.get(input_id)
            if entry is None:
                raise ExtractionWorkflowError(f"Combined score candidate is missing for {input_id}.")
            candidate_path = output_root / str(entry.get("candidateRecordPath") or "")
            candidate = _read_json(candidate_path)
            candidate_digest = _sha256_json(candidate)
            expected_candidate_digests = {
                str(system.get("scoreCandidateDigest") or "")
                for system in packet_systems
                if str(system.get("inputId") or "") == input_id
            }
            if expected_candidate_digests != {candidate_digest}:
                raise ExtractionWorkflowError(f"Combined score candidate changed for {input_id}.")
            prior_tab_digest = _reviewed_tab_facts_digest(candidate)
            revised = copy.deepcopy(candidate)
            score_by_id = {
                str(item.get("scoreSystemId") or ""): item
                for item in revised.get("scoreSystems") or []
            }
            tab_by_id = {
                str(item.get("tabSystemId") or ""): item
                for item in revised.get("tabSystems") or []
            }
            accepted_count = 0
            for key, packet_system in sorted(packet_by_key.items()):
                if key[0] != input_id:
                    continue
                review = review_by_key[key]
                status = str(review.get("status") or "")
                score_system_id = key[1]
                tab_system_id = str(packet_system.get("tabSystemId") or "")
                decision_id = _stable_id(
                    "combined-score-tab-decision",
                    application_digest,
                    input_id,
                    score_system_id,
                )
                base_line = {
                    "schemaVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "scoreSystemId": score_system_id,
                    "tabSystemId": tab_system_id,
                    "decisionId": decision_id,
                    "reviewStatus": status,
                    "packetDigest": packet_digest,
                    "submissionDigest": submission_digest,
                    "sourceCopedentId": source_copedent_id,
                    "sourceCopedentDigest": source_copedent_digest,
                    "scoreRhythmTrainingEligible": False,
                    "tabFactsHumanApproved": bool(review.get("tabConfirmed")) or not bool(
                        packet.get("jointTabReviewRequired")
                    ),
                }
                if status == "feedback":
                    feedback_id = _stable_id("combined-score-tab-feedback", decision_id)
                    feedback_queue.append(
                        {
                            **base_line,
                            "feedbackId": feedback_id,
                            "comment": str(review.get("comment") or "").strip(),
                            "status": "unresolved_requires_structured_correction",
                            "evidenceClass": "unknown_or_unresolved",
                            "trainingEligible": False,
                        }
                    )
                    line_index.append(
                        {
                            **base_line,
                            "status": "unresolved_requires_structured_correction",
                            "scorePitchTrainingEligible": False,
                            "pitchToTabTrainingEligible": False,
                            "trainingEligible": False,
                            "feedbackId": feedback_id,
                        }
                    )
                    continue
                score_system = score_by_id.get(score_system_id)
                tab_system = tab_by_id.get(tab_system_id)
                if score_system is None or tab_system is None:
                    raise ExtractionWorkflowError("A combined review line no longer exists.")
                if str(score_system.get("pairedTabSystemId") or "") != tab_system_id:
                    raise ExtractionWorkflowError("A combined score/tab pairing changed.")
                selected_candidate = "independent_score_reader"
                if status == "tab_pitch_hypothesis_matches":
                    selected_candidate = "human_confirmed_tab_pitch_hypothesis"
                    existing_score_attacks = _ordered_score_attacks(score_system)
                    all_tab_states = _ordered_tab_states(tab_system)
                    tab_attack_states = [
                        state for state in all_tab_states if state.get("isAttack")
                    ]
                    # Prefer every sounding tablature state when the written
                    # line has the same number of musical changes.  This keeps
                    # a pedal/lever release on ringing strings paired with the
                    # written change it realizes instead of deleting that
                    # score event from the reviewed line.
                    tab_states = (
                        all_tab_states
                        if len(existing_score_attacks) == len(all_tab_states)
                        else tab_attack_states
                    )
                    if not tab_states or any(not state.get("pitches") for state in tab_states):
                        raise ExtractionWorkflowError(
                            "A selected tab-pitch hypothesis contains an empty pitch state."
                        )
                    beats = int((score_system.get("timeSignature") or {}).get("beats") or 4)
                    used_positions: set[tuple[int, float]] = set()
                    attacks: list[dict[str, Any]] = []
                    tab_events = {
                        str(item.get("tabEventId") or ""): item
                        for item in tab_system.get("tabEvents") or []
                    }
                    for ordinal, state in enumerate(tab_states):
                        tab_event = tab_events[str(state.get("tabEventId") or "")]
                        if len(existing_score_attacks) == len(tab_states):
                            score_position = existing_score_attacks[ordinal]
                            measure = int(score_position.get("measure") or 1)
                            beat = float(score_position.get("beat") or ordinal + 1)
                        else:
                            measure = int(tab_event.get("measure") or 1)
                            beat = round(
                                1.0
                                + float(tab_event.get("measureHorizontalPosition") or 0.0)
                                * max(1, beats - 1),
                                6,
                            )
                        while (measure, beat) in used_positions:
                            beat = round(beat + 0.000001, 6)
                        used_positions.add((measure, beat))
                        attacks.append(
                            {
                                "measure": measure,
                                "beat": beat,
                                "pitches": list(state.get("pitches") or []),
                                "defaultX": float(state.get("horizontalPosition") or ordinal),
                                "durationBeats": 1.0,
                            }
                        )
                    projection = [
                        {
                            "measure": item["measure"],
                            "beat": item["beat"],
                            "pitches": sorted(item["pitches"]),
                        }
                        for item in _ordered_score_attacks(score_system)
                    ]
                    _replace_score_system_attacks_from_review(
                        score_system,
                        {
                            "operationId": _stable_id(
                                "combined-tab-pitch-score-replacement", decision_id
                            ),
                            "expectedScoreAttackDigest": _sha256_json(projection),
                            "replacementAttacks": attacks,
                        },
                    )
                comparison = _combined_score_tab_columns(score_system, tab_system)
                new_alignments, alignment_scope = _combined_review_alignments(
                    score_system, tab_system, decision_id=decision_id
                )
                score_ids = {
                    str(item.get("scoreEventId") or "")
                    for item in score_system.get("scoreEvents") or []
                }
                tab_ids = {
                    str(item.get("tabEventId") or "")
                    for item in tab_system.get("tabEvents") or []
                }
                revised["eventAlignments"] = [
                    item
                    for item in revised.get("eventAlignments") or []
                    if not (
                        set(str(value) for value in item.get("scoreEventIds") or []) & score_ids
                        or set(str(value) for value in item.get("tabEventIds") or []) & tab_ids
                    )
                ] + new_alignments
                score_system["reviewState"] = "human_approved"
                score_system["combinedScoreTabDecisionId"] = decision_id
                score_system["scoreAuditApprovalScope"] = {
                    "pitchAndChordMembership": "human_approved",
                    "eventOrderAndMeasureMembership": "human_approved",
                    "scoreToTabCorrespondence": (
                        "human_approved"
                        if alignment_scope["pitchToTabTrainingEligible"]
                        else "not_approved_unresolved"
                    ),
                    "noteDuration": "not_reviewed_excluded",
                    "rhythmicPosition": "not_reviewed_excluded",
                }
                for event in score_system.get("scoreEvents") or []:
                    event["reviewState"] = "human_approved"
                    event["evidenceClass"] = "direct_visual_observation"
                    event["combinedScoreTabDecisionId"] = decision_id
                    event["fieldReviewStates"] = {
                        **copy.deepcopy(event.get("fieldReviewStates") or {}),
                        "pitch": "human_approved",
                        "chordMembership": "human_approved",
                        "eventOrder": "human_approved",
                        "duration": "not_reviewed_excluded",
                        "rhythmicPosition": "not_reviewed_excluded",
                        "tie": "not_reviewed_excluded",
                    }
                accepted_count += 1
                line_index.append(
                    {
                        **base_line,
                        "gateVersion": COMBINED_SCORE_TAB_GATE_VERSION,
                        "status": "human_approved_pitch_only",
                        "selectedScoreCandidate": selected_candidate,
                        "scorePitchTrainingEligible": True,
                        "pitchToTabTrainingEligible": bool(
                            alignment_scope["pitchToTabTrainingEligible"]
                        ),
                        "trainingEligible": bool(
                            alignment_scope["pitchToTabTrainingEligible"]
                        ),
                        "alignmentMode": alignment_scope["mode"],
                        "alignmentExclusionReason": alignment_scope["reason"],
                        "scoreAttackCount": comparison["scoreAttackCount"],
                        "tabAttackCount": comparison["tabAttackCount"],
                        "tabMovementCount": comparison["tabMovementCount"],
                        "movementOnlyCount": comparison["movementOnlyCount"],
                        "exactColumnCount": comparison["exactColumnCount"],
                    }
                )
            if accepted_count:
                if _reviewed_tab_facts_digest(revised) != prior_tab_digest:
                    raise ExtractionWorkflowError(
                        f"Combined score review changed confirmed tab facts for {input_id}."
                    )
                revised["revision"] = int(candidate.get("revision") or 1) + 1
                revised["reviewState"] = "partially_human_approved"
                revised["humanApprovalComplete"] = False
                revised["combinedScoreTabReview"] = {
                    "schemaVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
                    "applicationDigest": application_digest,
                    "packetDigest": packet_digest,
                    "submissionDigest": submission_digest,
                    "approvedLineCount": accepted_count,
                    "scoreRhythmTrainingEligible": False,
                    "reviewedAt": _utc_now(),
                }
                revised_records[input_id] = revised
                record_lineage[input_id] = {
                    "priorRecordPath": str(candidate_path.relative_to(output_root)),
                    "priorRecordDigest": candidate_digest,
                    "baseReviewedRecordDigest": str(entry.get("machineRecordDigest") or ""),
                    "confirmationDecisionId": entry.get("confirmationDecisionId"),
                    "reviewedTabFactsDigest": prior_tab_digest,
                }

        summary = {
            "schemaVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "applicationDigest": application_digest,
            "packetDigest": packet_digest,
            "submissionDigest": submission_digest,
            "reviewedLineCount": len(reviews),
            "scorePitchApprovedLineCount": sum(
                bool(item.get("scorePitchTrainingEligible")) for item in line_index
            ),
            "pitchToTabTrainingEligibleLineCount": sum(
                bool(item.get("pitchToTabTrainingEligible")) for item in line_index
            ),
            "unresolvedLineCount": sum(
                item.get("status") == "unresolved_requires_structured_correction"
                for item in line_index
            ),
            "scoreRhythmTrainingEligibleLineCount": 0,
            "reviewedPageCount": len(revised_records),
            "sourceCopedentId": source_copedent_id,
            "sourceCopedentDigest": source_copedent_digest,
            "dryRun": dry_run,
            "deduplicated": False,
            "trainingStarted": False,
            "validationAccessed": False,
            "sealedTestAccessed": False,
        }
        if dry_run:
            return summary

        applied_dir = application_dir / "applied-records"
        repair_index_path = (
            output_root / "review" / "score-audit" / "repair" / "score-repair-index.jsonl"
        )
        repair_index = _read_jsonl(repair_index_path)
        for input_id, revised in revised_records.items():
            revised_digest = _sha256_json(revised)
            target = applied_dir / input_id / f"{revised_digest}.json"
            _write_json(target, revised)
            relative_path = str(target.relative_to(output_root))
            for item in line_index:
                if item.get("inputId") == input_id and item.get("scorePitchTrainingEligible"):
                    item["reviewedRecordPath"] = relative_path
                    item["reviewedRecordDigest"] = revised_digest
            lineage = record_lineage[input_id]
            repair_index.append(
                {
                    "schemaVersion": SCORE_REPAIR_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "baseReviewedRecordDigest": lineage["baseReviewedRecordDigest"],
                    "priorReviewDecisionId": lineage["confirmationDecisionId"],
                    "candidateRecordPath": relative_path,
                    "candidateRecordDigest": revised_digest,
                    "reviewedTabFactsDigest": lineage["reviewedTabFactsDigest"],
                    "repairVersion": COMBINED_SCORE_TAB_APPLICATION_SCHEMA_VERSION,
                    "combinedScoreTabApplicationDigest": application_digest,
                    "priorTabApprovalPreserved": True,
                    "status": "candidate_ready_partial_line_approval",
                    "sealedTestAccessed": False,
                }
            )
        application_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(application_dir, 0o700)
        approved_line_index_path = application_dir / "approved-line-index.jsonl"
        existing_lines = (
            _read_jsonl(approved_line_index_path)
            if approved_line_index_path.exists()
            else []
        )
        known_decisions = {str(item.get("decisionId") or "") for item in existing_lines}
        _write_jsonl(
            approved_line_index_path,
            existing_lines
            + [item for item in line_index if str(item.get("decisionId") or "") not in known_decisions],
        )
        shadow_candidate_dir = (
            output_root
            / "review"
            / "automation"
            / "source-score-notehead-challenger"
            / "future-discovery-shadow"
            / "candidates"
        )
        if shadow_candidate_dir.exists() and any(shadow_candidate_dir.glob("*.json")):
            shadow_score = self.score_source_score_projection_shadow(batch_id)
            summary["hybridShadowScore"] = {
                "candidateCount": shadow_score["candidateCount"],
                "scoredCaseCount": shadow_score["scoredCaseCount"],
                "pendingTruthCount": shadow_score["pendingTruthCount"],
                "metrics": shadow_score["metrics"],
                "gates": shadow_score["gates"],
                "gatePassed": shadow_score["gatePassed"],
                "promotionEligible": False,
                "reportDigest": shadow_score["reportDigest"],
                "reportPath": shadow_score["reportPath"],
            }
        feedback_queue_path = application_dir / "feedback-queue.jsonl"
        existing_feedback = (
            _read_jsonl(feedback_queue_path) if feedback_queue_path.exists() else []
        )
        known_feedback = {str(item.get("feedbackId") or "") for item in existing_feedback}
        _write_jsonl(
            feedback_queue_path,
            existing_feedback
            + [
                item
                for item in feedback_queue
                if str(item.get("feedbackId") or "") not in known_feedback
            ],
        )
        _write_jsonl(repair_index_path, repair_index)
        versioned_summary.parent.mkdir(parents=True, exist_ok=True)
        os.chmod(versioned_summary.parent, 0o700)
        _write_json(versioned_summary, summary)
        _write_json(application_dir / "summary.json", summary)
        if receipt_path.exists():
            receipt = _read_json(receipt_path)
            if str(receipt.get("submissionDigest") or "") != submission_digest:
                raise ExtractionWorkflowError("Combined review receipt digest does not match.")
            receipt["status"] = "applied"
            receipt["appliedAt"] = _utc_now()
            receipt["applicationDigest"] = application_digest
            _write_json(receipt_path, receipt)
        return summary

    def prepare_score_audit_review(
        self,
        batch_id: str,
        *,
        partition: str = "discovery",
        limit: int = 25,
    ) -> dict[str, Any]:
        """Prepare a score-only audit without disturbing prior tablature approvals."""

        if limit < 1 or limit > 100:
            raise ExtractionWorkflowError("Score-audit packet limit must be between 1 and 100 pages.")
        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        approved_index_path = review_dir / "approved-record-index.jsonl"
        if not approved_index_path.exists():
            raise ExtractionWorkflowError("Score audit requires existing page-level review approvals.")
        approved_entries = [
            item for item in _read_jsonl(approved_index_path) if item.get("status") == "human_approved"
        ]
        audit_dir = review_dir / "score-audit"
        audit_index_path = audit_dir / "approved-score-index.jsonl"
        audit_index = _read_jsonl(audit_index_path) if audit_index_path.exists() else []
        audited_pairs = {
            (str(item.get("inputId") or ""), str(item.get("reviewedRecordDigest") or ""))
            for item in audit_index
            if item.get("status") == "human_approved"
        }
        audited_input_ids = {
            str(item.get("inputId") or "")
            for item in audit_index
            if item.get("status") == "human_approved"
        }
        feedback_path = audit_dir / "score-audit-feedback.jsonl"
        feedback = _read_jsonl(feedback_path) if feedback_path.exists() else []
        feedback_by_id = {
            str(item.get("scoreAuditFeedbackId") or ""): item
            for item in feedback
            if item.get("scoreAuditFeedbackId")
        }
        feedback_pairs = {
            (str(item.get("inputId") or ""), str(item.get("reviewedRecordDigest") or ""))
            for item in feedback
        }
        packets: list[dict[str, Any]] = []
        repair_queue: list[dict[str, Any]] = []
        eligible_pages = 0
        audited_pages = 0
        pending_feedback_pages = 0
        for entry in sorted(approved_entries, key=lambda item: str(item.get("inputId") or "")):
            input_id = str(entry.get("inputId") or "")
            relative_path = str(entry.get("reviewedRecordPath") or "")
            reviewed_path = output_root / relative_path
            if not relative_path or not reviewed_path.exists():
                raise ExtractionWorkflowError(f"Approved reviewed record is missing for {input_id}.")
            record = _read_json(reviewed_path)
            base_reviewed_digest = _sha256_json(record)
            if base_reviewed_digest != str(entry.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError(f"Approved reviewed record digest changed for {input_id}.")
            if (record.get("scoreSystems") or []) and input_id in audited_input_ids:
                eligible_pages += 1
                audited_pages += 1
                continue
            repair_candidate = _score_repair_candidate(
                output_root,
                input_id=input_id,
                base_reviewed_record_digest=base_reviewed_digest,
            )
            repair_entry: dict[str, Any] | None = None
            if repair_candidate is not None:
                record, relative_path, repair_entry = repair_candidate
            reviewed_digest = _sha256_json(record)
            targeted_tab_corrections = list(record.get("sourceTabCorrections") or [])
            prior_tab_approval_preserved = not bool(targeted_tab_corrections)
            score_systems = record.get("scoreSystems") or []
            if not score_systems:
                continue
            tab_systems_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in record.get("tabSystems") or []
            }
            eligible_pages += 1
            pair = (input_id, reviewed_digest)
            if pair in audited_pairs:
                audited_pages += 1
                continue
            if pair in feedback_pairs:
                pending_feedback_pages += 1
                continue
            source_filename = str(record.get("provenance", {}).get("imageFilename") or input_id)
            offsets_by_system: dict[str, list[int]] = {}
            score_system_by_event = {
                str(event.get("scoreEventId") or ""): str(system.get("scoreSystemId") or "")
                for system in score_systems
                for event in system.get("scoreEvents") or []
            }
            for alignment in record.get("eventAlignments") or []:
                for event_id in alignment.get("scoreEventIds") or []:
                    system_id = score_system_by_event.get(str(event_id))
                    if system_id:
                        offsets_by_system.setdefault(system_id, []).append(
                            int(alignment.get("scoreNotationTranspositionSemitones") or 0)
                        )
            score_audit_diagnostics = _score_audit_diagnostics(record)
            score_audit_gates = _score_audit_equivalence_gates(record, score_audit_diagnostics)
            notation_renderings: dict[str, dict[str, Any]] = {}
            for system in score_systems:
                system_id = str(system.get("scoreSystemId") or "")
                gate = score_audit_gates[system_id]
                music_xml_path = _score_system_musicxml_path(output_root, input_id, system)
                if music_xml_path is None:
                    gate["blockingReasons"].append(
                        {
                            "code": "recognized_musicxml_missing",
                            "message": "The recognized MusicXML needed for a faithful notation rendering is missing.",
                        }
                    )
                    gate["readyForHumanReview"] = False
                    gate["status"] = "blocked_internal_repair"
                    gate["reviewEffect"] = "withheld_for_internal_repair"
                    continue
                target_path = (
                    audit_dir
                    / "notation"
                    / input_id
                    / f"score-system-{int(system.get('systemIndex') or 0):02d}.svg"
                )
                try:
                    rendering = _render_musicxml_notation(music_xml_path, target_path)
                except ExtractionWorkflowError as exc:
                    gate["blockingReasons"].append(
                        {"code": "faithful_notation_rendering_failed", "message": str(exc)}
                    )
                    gate["readyForHumanReview"] = False
                    gate["status"] = "blocked_internal_repair"
                    gate["reviewEffect"] = "withheld_for_internal_repair"
                    continue
                rendering["relativePath"] = str(target_path.relative_to(output_root))
                rendering["relativeUrl"] = (
                    f"./notation/{input_id}/score-system-{int(system.get('systemIndex') or 0):02d}.svg"
                )
                notation_renderings[system_id] = rendering
            blocked_systems = [
                gate for gate in score_audit_gates.values() if not bool(gate.get("readyForHumanReview"))
            ]
            ready_systems = [
                gate for gate in score_audit_gates.values() if bool(gate.get("readyForHumanReview"))
            ]
            blocked_system_ids = {
                str(gate.get("scoreSystemId") or "") for gate in blocked_systems
            }
            carried_forward_feedback: list[dict[str, str]] = []
            for feedback_id in (
                record.get("scoreAuditCorrection") or {}
            ).get("scoreAuditFeedbackIds") or []:
                prior_feedback = feedback_by_id.get(str(feedback_id)) or {}
                for system_decision in prior_feedback.get("systemDecisions") or []:
                    system_id = str(system_decision.get("scoreSystemId") or "")
                    comment = str(system_decision.get("comment") or "").strip()
                    if (
                        system_id in blocked_system_ids
                        and system_decision.get("status") == "feedback"
                        and comment
                    ):
                        carried_forward_feedback.append(
                            {"scoreSystemId": system_id, "comment": comment}
                        )
            if blocked_systems:
                repair_queue.append(
                    {
                        "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
                        "gateVersion": SCORE_AUDIT_GATE_VERSION,
                        "batchId": batch_id,
                        "partition": partition,
                        "inputId": input_id,
                        "reviewedRecordDigest": reviewed_digest,
                        "baseReviewedRecordDigest": base_reviewed_digest,
                        "priorReviewDecisionId": entry.get("reviewDecisionId"),
                        "blockedSystemCount": len(blocked_systems),
                        "scoreAuditGatesBySystem": score_audit_gates,
                        "repairState": "internal_repair_required",
                        "humanReviewRequested": bool(ready_systems),
                        "humanReviewScope": (
                            "passing_systems_and_blocked_feedback_only"
                            if ready_systems
                            else "none"
                        ),
                        "priorTabApprovalPreserved": prior_tab_approval_preserved,
                        "targetedTabCorrectionCount": len(targeted_tab_corrections),
                        "scoreRepairVersion": (
                            repair_entry.get("repairVersion") if repair_entry is not None else None
                        ),
                    }
                )
            if not ready_systems:
                continue
            score_tab_source_crops: dict[str, dict[str, Any]] = {}
            for system in score_systems:
                system_id = str(system.get("scoreSystemId") or "")
                paired_tab_id = str(system.get("pairedTabSystemId") or "")
                paired_tab_system = tab_systems_by_id.get(paired_tab_id)
                if paired_tab_system is None:
                    raise ExtractionWorkflowError(
                        f"Score audit found no paired tab source system for {input_id}."
                    )
                score_tab_source_crops[system_id] = _prepare_score_tab_source_crop(
                    output_root=output_root,
                    audit_dir=audit_dir,
                    input_id=input_id,
                    record=record,
                    score_system=system,
                    tab_system=paired_tab_system,
                )
            packets.append(
                {
                    "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
                    "auditUiRevision": "score-audit-ui-v13",
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "sourceLabel": Path(source_filename).name,
                    "assetSha256": record.get("assetSha256"),
                    "priorReviewDecisionId": entry.get("reviewDecisionId"),
                    "reviewedRecordPath": relative_path,
                    "reviewedRecordDigest": reviewed_digest,
                    "baseReviewedRecordDigest": base_reviewed_digest,
                    "derivativeRelativePath": record.get("derivative", {}).get("relativePath"),
                    "scoreSystemCount": len(score_systems),
                    "gatePassedScoreSystemCount": len(ready_systems),
                    "blockedFeedbackOnlyScoreSystemCount": len(blocked_systems),
                    "scoreEventCount": sum(len(system.get("scoreEvents") or []) for system in score_systems),
                    "eventAlignmentCount": len(record.get("eventAlignments") or []),
                    "detectedNotationOffsetsBySystem": {
                        system_id: sorted(set(offsets))
                        for system_id, offsets in sorted(offsets_by_system.items())
                    },
                    "scoreAuditDiagnosticsBySystem": score_audit_diagnostics,
                    "scoreAuditGatesBySystem": score_audit_gates,
                    "notationRenderingsBySystem": notation_renderings,
                    "scoreTabSourceCropsBySystem": score_tab_source_crops,
                    "scoreSourceCropsBySystem": {
                        str(system.get("scoreSystemId") or ""): "../../"
                        + str(
                            (system.get("scoreRepairSourceCrop") or {}).get("relativePath")
                            or (
                                Path("score-crops")
                                / input_id
                                / f"score-system-{int(system.get('systemIndex') or 0):02d}.png"
                            )
                        )
                        for system in score_systems
                    },
                    "preapprovedScoreSystemIds": sorted(
                        str(value)
                        for value in (record.get("scoreAuditCorrection") or {}).get(
                            "acceptedUnchangedScoreSystemIds"
                        )
                        or []
                    ),
                    "carriedForwardSystemFeedback": sorted(
                        {
                            item["scoreSystemId"]: item
                            for item in carried_forward_feedback
                        }.values(),
                        key=lambda item: item["scoreSystemId"],
                    ),
                    "targetedTabCorrections": copy.deepcopy(targeted_tab_corrections),
                    "targetedTabCorrectionSystemIds": sorted(
                        {
                            str(item.get("scoreSystemId") or "")
                            for item in targeted_tab_corrections
                            if item.get("scoreSystemId")
                        }
                    ),
                    "priorTabApprovalPreserved": prior_tab_approval_preserved,
                    "scoreRepairVersion": (
                        repair_entry.get("repairVersion") if repair_entry is not None else None
                    ),
                    "reviewedRecord": copy.deepcopy(record),
                    "decisionTemplate": {
                        "inputId": input_id,
                        "expectedReviewedRecordDigest": reviewed_digest,
                        "action": "accept | feedback",
                        "reviewerReference": None,
                        "systemDecisions": [
                            {
                                "scoreSystemId": system.get("scoreSystemId"),
                                "status": "accept | feedback | not_applicable",
                                "comment": None,
                            }
                            for system in score_systems
                        ],
                        "eventFeedback": [],
                        "notes": None,
                    },
                }
            )
            if len(packets) == limit:
                break

        packet_path = audit_dir / "score-audit-packet.jsonl"
        _write_jsonl(packet_path, packets)
        repair_queue_path = audit_dir / "score-audit-repair-queue.jsonl"
        _write_jsonl(repair_queue_path, repair_queue)
        packet_digest = _sha256_json(packets)
        packet_dir = audit_dir / "packets"
        packet_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(packet_dir, 0o700)
        packet_index: list[dict[str, Any]] = []
        for packet in packets:
            packet_file = packet_dir / f"{packet['inputId']}.json"
            _write_json(packet_file, packet)
            packet_index.append(
                {
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": packet["inputId"],
                    "sourceLabel": packet["sourceLabel"],
                    "reviewedRecordDigest": packet["reviewedRecordDigest"],
                    "scoreSystemCount": packet["scoreSystemCount"],
                    "packetUrl": f"./packets/{packet['inputId']}.json",
                }
            )
        console_path = audit_dir / "score-audit-console.html"
        _write_private_text(
            console_path,
            _score_audit_console_html(
                packet_index,
                packet_digest=packet_digest,
                blocked_repair_page_count=len(repair_queue),
                blocked_repair_system_count=sum(item["blockedSystemCount"] for item in repair_queue),
            ),
        )
        summary = {
            "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "eligibleApprovedPageCount": eligible_pages,
            "alreadyAuditedPageCount": audited_pages,
            "pendingFeedbackCorrectionPageCount": pending_feedback_pages,
            "blockedInternalRepairPageCount": len(repair_queue),
            "blockedInternalRepairSystemCount": sum(
                item["blockedSystemCount"] for item in repair_queue
            ),
            "remainingPageCount": eligible_pages - audited_pages,
            "pageCount": len(packets),
            "deferredPageCount": max(
                0, eligible_pages - audited_pages - pending_feedback_pages - len(packets)
            ),
            "scoreSystemCount": sum(packet["scoreSystemCount"] for packet in packets),
            "scoreEventCount": sum(packet["scoreEventCount"] for packet in packets),
            "eventAlignmentCount": sum(packet["eventAlignmentCount"] for packet in packets),
            "diagnosticAttentionCount": sum(
                int(system.get("attentionCount") or 0)
                for packet in packets
                for system in packet["scoreAuditDiagnosticsBySystem"].values()
            ),
            "diagnosticCautionCount": sum(
                int(system.get("cautionCount") or 0)
                for packet in packets
                for system in packet["scoreAuditDiagnosticsBySystem"].values()
            ),
            "packetLimit": limit,
            "packetDigest": packet_digest,
            "packetIndexDigest": _sha256_json(packet_index),
            "packetPath": str(packet_path.relative_to(batch_dir)),
            "repairQueuePath": str(repair_queue_path.relative_to(batch_dir)),
            "repairQueueDigest": _sha256_json(repair_queue),
            "packetDirectory": str(packet_dir.relative_to(batch_dir)),
            "reviewConsolePath": str(console_path.relative_to(batch_dir)),
            "reviewConsoleSha256": _sha256_bytes(console_path.read_bytes()),
            "scoreAuditComplete": eligible_pages == audited_pages,
            "priorTabApprovalsPreserved": all(
                bool(packet.get("priorTabApprovalPreserved", True))
                for packet in packets
            ) and all(
                bool(item.get("priorTabApprovalPreserved", True))
                for item in repair_queue
            ),
            "targetedTabCorrectionPageCount": sum(
                not bool(packet.get("priorTabApprovalPreserved", True))
                for packet in packets
            ),
            "sealedTestAccessed": False,
        }
        _write_json(audit_dir / "score-audit-packet-summary.json", summary)
        return summary

    def apply_score_audit_review(
        self,
        batch_id: str,
        source: Path | str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Apply an explicit per-system score audit to already reviewed pages."""

        batch_dir, _manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        audit_dir = review_dir / "score-audit"
        source_path = Path(source).expanduser().resolve()
        decisions = _read_jsonl(source_path)
        if not decisions:
            raise ExtractionWorkflowError("The score-audit review file contains no decisions.")
        all_page_index_rows = _read_jsonl(review_dir / "approved-record-index.jsonl")
        approved_page_index = {
            str(item.get("inputId") or ""): item
            for item in all_page_index_rows
            if item.get("status") == "human_approved"
        }
        decision_log_path = audit_dir / "score-audit-decisions.jsonl"
        feedback_log_path = audit_dir / "score-audit-feedback.jsonl"
        audit_index_path = audit_dir / "approved-score-index.jsonl"
        existing_decisions = _read_jsonl(decision_log_path) if decision_log_path.exists() else []
        existing_feedback = _read_jsonl(feedback_log_path) if feedback_log_path.exists() else []
        existing_index = _read_jsonl(audit_index_path) if audit_index_path.exists() else []
        index_by_input = {str(item.get("inputId") or ""): item for item in existing_index}
        finalized_pairs = {
            (
                str(item.get("inputId") or ""),
                str(
                    item.get("auditedCandidateDigest")
                    or item.get("reviewedRecordDigest")
                    or ""
                ),
            )
            for item in existing_index
        }
        new_decisions: list[dict[str, Any]] = []
        new_feedback: list[dict[str, Any]] = []
        seen_inputs: set[str] = set()
        for raw_decision in decisions:
            input_id = str(raw_decision.get("inputId") or "")
            page_entry = approved_page_index.get(input_id)
            if page_entry is None or input_id in seen_inputs:
                raise ExtractionWorkflowError(f"Score audit references an unknown or repeated input {input_id!r}.")
            seen_inputs.add(input_id)
            submitted_candidate_digest = str(
                raw_decision.get("expectedReviewedRecordDigest") or ""
            )
            if any(
                str(item.get("inputId") or "") == input_id
                and str(item.get("auditedCandidateDigest") or "")
                == submitted_candidate_digest
                and str(item.get("action") or "")
                == str(raw_decision.get("action") or "")
                and str(item.get("reviewerReference") or "")
                == str(raw_decision.get("reviewerReference") or "").strip()
                for item in existing_decisions
            ):
                continue
            base_relative_path = str(page_entry.get("reviewedRecordPath") or "")
            reviewed_path = output_root / base_relative_path
            if not base_relative_path or not reviewed_path.exists():
                raise ExtractionWorkflowError(f"The approved record is missing for {input_id}.")
            base_reviewed_record = _read_json(reviewed_path)
            base_reviewed_digest = _sha256_json(base_reviewed_record)
            if base_reviewed_digest != str(page_entry.get("reviewedRecordDigest") or ""):
                raise ExtractionWorkflowError(f"The approved record digest changed for {input_id}.")
            repair_candidate = _score_repair_candidate(
                output_root,
                input_id=input_id,
                base_reviewed_record_digest=base_reviewed_digest,
            )
            repair_entry: dict[str, Any] | None = None
            reviewed_record = base_reviewed_record
            if repair_candidate is not None:
                reviewed_record, _candidate_path, repair_entry = repair_candidate
            reviewed_digest = _sha256_json(reviewed_record)
            targeted_tab_corrections = list(reviewed_record.get("sourceTabCorrections") or [])
            prior_tab_approval_preserved = not bool(targeted_tab_corrections)
            score_audit_diagnostics = _score_audit_diagnostics(reviewed_record)
            packet = {
                "inputId": input_id,
                "reviewedRecordDigest": reviewed_digest,
                "reviewedRecord": reviewed_record,
                "scoreAuditGatesBySystem": _score_audit_equivalence_gates(
                    reviewed_record,
                    score_audit_diagnostics,
                ),
            }
            decision = _normalize_score_audit_review(raw_decision, packet)
            pair = (input_id, reviewed_digest)
            replayed_decision = next(
                (
                    item
                    for item in existing_decisions
                    if str(item.get("inputId") or "") == input_id
                    and str(item.get("auditedCandidateDigest") or "") == reviewed_digest
                    and str(item.get("action") or "") == decision["action"]
                    and str(item.get("reviewerReference") or "")
                    == decision["reviewerReference"]
                    and (item.get("systemDecisions") or []) == decision["systemDecisions"]
                    and (item.get("eventFeedback") or []) == decision["eventFeedback"]
                    and (item.get("notes") or None) == (decision.get("notes") or None)
                ),
                None,
            )
            if replayed_decision is not None:
                continue
            if pair in finalized_pairs:
                raise ExtractionWorkflowError(f"The score audit for {input_id} is already immutable and final.")
            reviewed_at = _utc_now()
            audit_decision_id = str(
                decision.get("scoreAuditDecisionId")
                or _stable_id(
                    "score-audit-review",
                    batch_id,
                    partition,
                    input_id,
                    reviewed_digest,
                    decision["action"],
                    decision["reviewerReference"],
                )
            )
            log_entry = {
                "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
                "scoreAuditDecisionId": audit_decision_id,
                "batchId": batch_id,
                "partition": partition,
                "inputId": input_id,
                "auditedCandidateDigest": reviewed_digest,
                "reviewedRecordDigest": reviewed_digest,
                "baseReviewedRecordDigest": base_reviewed_digest,
                "scoreRepairVersion": (
                    repair_entry.get("repairVersion") if repair_entry is not None else None
                ),
                "priorReviewDecisionId": page_entry.get("reviewDecisionId"),
                "action": decision["action"],
                "reviewerReference": decision["reviewerReference"],
                "systemDecisions": decision["systemDecisions"],
                "eventFeedback": decision["eventFeedback"],
                "notes": decision.get("notes"),
                "reviewedAt": reviewed_at,
                "targetedTabCorrectionIds": sorted(
                    str(item.get("targetedTabCorrectionId") or "")
                    for item in targeted_tab_corrections
                ),
                "priorTabApprovalPreserved": prior_tab_approval_preserved,
                "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                    targeted_tab_corrections
                ),
            }
            new_decisions.append(log_entry)
            if decision["action"] == "feedback":
                feedback_id = _stable_id("score-audit-feedback", audit_decision_id, decision)
                new_feedback.append({**log_entry, "scoreAuditFeedbackId": feedback_id})
                continue

            event_to_system = {
                str(event.get("scoreEventId") or ""): str(system.get("scoreSystemId") or "")
                for system in reviewed_record.get("scoreSystems") or []
                for event in system.get("scoreEvents") or []
            }
            offsets_by_system: dict[str, set[int]] = {}
            for alignment in reviewed_record.get("eventAlignments") or []:
                for event_id in alignment.get("scoreEventIds") or []:
                    system_id = event_to_system.get(str(event_id))
                    if system_id:
                        offsets_by_system.setdefault(system_id, set()).add(
                            int(alignment.get("scoreNotationTranspositionSemitones") or 0)
                        )
            accepted_systems = [
                item["scoreSystemId"] for item in decision["systemDecisions"] if item["status"] == "accept"
            ]
            not_applicable_systems = [
                item["scoreSystemId"]
                for item in decision["systemDecisions"]
                if item["status"] == "not_applicable"
            ]
            final_reviewed_digest = reviewed_digest
            final_reviewed_path = str(page_entry.get("reviewedRecordPath") or "")
            approval_scope: dict[str, Any] | None = None
            if accepted_systems:
                approved_score_record = copy.deepcopy(reviewed_record)
                before_tab_digest = _reviewed_tab_facts_digest(approved_score_record)
                _mark_score_audited_objects(
                    approved_score_record,
                    set(accepted_systems),
                )
                approved_targeted_tab_correction_ids = _approve_targeted_tab_corrections(
                    approved_score_record,
                    set(accepted_systems),
                    reviewer_reference=decision["reviewerReference"],
                    reviewed_at=reviewed_at,
                )
                approval_scope = _apply_pitch_only_score_audit_scope(
                    approved_score_record,
                    set(accepted_systems),
                    reviewer_reference=decision["reviewerReference"],
                )
                approved_score_record["revision"] = max(
                    int(base_reviewed_record.get("revision") or 1),
                    int(reviewed_record.get("revision") or 1),
                ) + 1
                approved_score_record["reviewState"] = "human_approved"
                approved_score_record["humanApprovalComplete"] = True
                approved_score_record["scoreAudit"] = {
                    "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
                    "scoreAuditDecisionId": audit_decision_id,
                    "reviewerReference": decision["reviewerReference"],
                    "reviewedAt": reviewed_at,
                    "auditedCandidateDigest": reviewed_digest,
                    "baseReviewedRecordDigest": base_reviewed_digest,
                    "approvedScoreSystemIds": sorted(accepted_systems),
                    "notApplicableScoreSystemIds": sorted(not_applicable_systems),
                    "targetedTabCorrectionIds": approved_targeted_tab_correction_ids,
                    "priorTabApprovalPreserved": prior_tab_approval_preserved,
                    "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                        targeted_tab_corrections
                    ),
                    "approvalScope": copy.deepcopy(approval_scope),
                }
                after_tab_digest = _reviewed_tab_facts_digest(approved_score_record)
                if not targeted_tab_corrections and after_tab_digest != before_tab_digest:
                    raise ExtractionWorkflowError(
                        f"Score audit promotion changed reviewed tab facts for {input_id}."
                    )
                if targeted_tab_corrections and after_tab_digest == before_tab_digest:
                    raise ExtractionWorkflowError(
                        f"Targeted tab approval did not promote the corrected event for {input_id}."
                    )
                approved_dir = review_dir / "approved-records"
                approved_path = (
                    approved_dir
                    / f"{input_id}-r{approved_score_record['revision']}-score-audited.json"
                )
                _write_json(approved_path, approved_score_record)
                final_reviewed_path = str(approved_path.relative_to(output_root))
                final_reviewed_digest = _sha256_json(approved_score_record)
                page_entry.update(
                    {
                        "action": (
                            "score_repair_approved"
                            if repair_entry is not None
                            else "score_audit_approved"
                        ),
                        "recordRevision": approved_score_record["revision"],
                        "reviewedRecordPath": final_reviewed_path,
                        "reviewedRecordDigest": final_reviewed_digest,
                        "baseReviewedRecordDigest": base_reviewed_digest,
                        "scoreAuditDecisionId": audit_decision_id,
                        "scoreAuditApprovalScope": copy.deepcopy(approval_scope),
                        "targetedTabCorrectionIds": approved_targeted_tab_correction_ids,
                        "priorTabApprovalPreserved": prior_tab_approval_preserved,
                        "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                            targeted_tab_corrections
                        ),
                    }
                )
                if repair_entry is not None:
                    page_entry["scoreRepairCandidateDigest"] = reviewed_digest
            index_by_input[input_id] = {
                "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
                "inputId": input_id,
                "status": "human_approved",
                "scoreAuditDecisionId": audit_decision_id,
                "priorReviewDecisionId": page_entry.get("reviewDecisionId"),
                "reviewedRecordDigest": final_reviewed_digest,
                "reviewedRecordPath": final_reviewed_path,
                "auditedCandidateDigest": reviewed_digest,
                "baseReviewedRecordDigest": base_reviewed_digest,
                "scoreRepairVersion": (
                    repair_entry.get("repairVersion") if repair_entry is not None else None
                ),
                "approvedScoreSystemIds": sorted(accepted_systems),
                "notApplicableScoreSystemIds": sorted(not_applicable_systems),
                "explicitlyApprovedNotationOffsetsBySystem": {
                    key: sorted(value) for key, value in sorted(offsets_by_system.items())
                },
                "scoreEvidenceEligible": bool(accepted_systems),
                "pitchToTabTrainingEligible": bool(accepted_systems),
                "scoreRhythmTrainingEligible": False,
                "scoreAuditApprovalScope": copy.deepcopy(approval_scope),
                "reviewerReference": decision["reviewerReference"],
                "reviewedAt": reviewed_at,
                "targetedTabCorrectionIds": sorted(
                    str(item.get("targetedTabCorrectionId") or "")
                    for item in targeted_tab_corrections
                ),
                "priorTabApprovalPreserved": prior_tab_approval_preserved,
                "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                    targeted_tab_corrections
                ),
            }
            log_entry["reviewedRecordDigest"] = final_reviewed_digest
            log_entry["reviewedRecordPath"] = final_reviewed_path
            finalized_pairs.add(pair)

        all_decisions = existing_decisions + new_decisions
        all_feedback = existing_feedback + new_feedback
        index = [index_by_input[key] for key in sorted(index_by_input)]
        _write_jsonl(decision_log_path, all_decisions)
        _write_jsonl(feedback_log_path, all_feedback)
        _write_jsonl(audit_index_path, index)
        approved_page_index_rows = sorted(
            [
                approved_page_index.get(str(item.get("inputId") or ""), item)
                for item in all_page_index_rows
            ],
            key=lambda item: str(item.get("inputId") or ""),
        )
        _write_jsonl(review_dir / "approved-record-index.jsonl", approved_page_index_rows)
        human_review_summary_path = review_dir / "human-review-summary.json"
        if human_review_summary_path.exists():
            human_review_summary = _read_json(human_review_summary_path)
            human_review_summary["approvedIndexDigest"] = _sha256_json(
                approved_page_index_rows
            )
            human_review_summary["scoreRepairPromotionCount"] = sum(
                bool(item.get("scoreRepairCandidateDigest"))
                for item in approved_page_index_rows
            )
            human_review_summary["priorTabApprovalsPreserved"] = all(
                bool(item.get("priorTabApprovalPreserved", True))
                for item in approved_page_index_rows
            )
            _write_json(human_review_summary_path, human_review_summary)
        eligible_count = 0
        for entry in approved_page_index.values():
            record_path = output_root / str(entry.get("reviewedRecordPath") or "")
            if (_read_json(record_path).get("scoreSystems") or []):
                eligible_count += 1
        audited_count = len(index)
        summary = {
            "schemaVersion": SCORE_AUDIT_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "eligibleApprovedPageCount": eligible_count,
            "auditedPageCount": audited_count,
            "feedbackPageCount": len(
                {str(item.get("inputId") or "") for item in all_feedback}
            ),
            "remainingPageCount": eligible_count - audited_count,
            "scoreAuditComplete": eligible_count == audited_count,
            "decisionLogDigest": _sha256_json(all_decisions),
            "feedbackLogDigest": _sha256_json(all_feedback),
            "approvedIndexDigest": _sha256_json(index),
            "priorTabApprovalsPreserved": all(
                bool(item.get("priorTabApprovalPreserved", True)) for item in index
            ),
            "targetedTabCorrectionApprovedPageCount": sum(
                bool(item.get("targetedTabCorrectionIds")) for item in index
            ),
            "sealedTestAccessed": False,
        }
        _write_json(audit_dir / "score-audit-summary.json", summary)
        _mark_score_audit_submission_applied(source_path, summary)
        return summary

    def qualify_score_audit_scope(
        self,
        batch_id: str,
        *,
        input_id: str,
        expected_score_audit_decision_id: str,
        reviewer_reference: str,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        """Append a pitch-only approval scope to an already approved score audit."""

        _batch_dir, _manifest, _work = self._batch_paths(batch_id, partition)
        output_root = _batch_dir / "extraction" / partition
        review_dir = output_root / "review"
        audit_dir = review_dir / "score-audit"
        page_index_path = review_dir / "approved-record-index.jsonl"
        audit_index_path = audit_dir / "approved-score-index.jsonl"
        page_index = _read_jsonl(page_index_path)
        audit_index = _read_jsonl(audit_index_path)
        page_entry = next(
            (
                item
                for item in page_index
                if str(item.get("inputId") or "") == input_id
                and item.get("status") == "human_approved"
            ),
            None,
        )
        audit_entry = next(
            (
                item
                for item in audit_index
                if str(item.get("inputId") or "") == input_id
                and item.get("status") == "human_approved"
            ),
            None,
        )
        if page_entry is None or audit_entry is None:
            raise ExtractionWorkflowError(
                f"{input_id} lacks a current approved extraction and score audit."
            )
        if str(audit_entry.get("scoreAuditDecisionId") or "") != expected_score_audit_decision_id:
            raise ExtractionWorkflowError(
                f"The approved score-audit decision changed for {input_id}."
            )
        reviewed_path_value = str(page_entry.get("reviewedRecordPath") or "")
        reviewed_digest = str(page_entry.get("reviewedRecordDigest") or "")
        reviewed_path = output_root / reviewed_path_value
        if not reviewed_path_value or not reviewed_path.exists():
            raise ExtractionWorkflowError(f"The approved record is missing for {input_id}.")
        reviewed_record = _read_json(reviewed_path)
        if _sha256_json(reviewed_record) != reviewed_digest:
            raise ExtractionWorkflowError(f"The approved record digest changed for {input_id}.")
        if str(audit_entry.get("reviewedRecordDigest") or "") != reviewed_digest:
            raise ExtractionWorkflowError(
                f"The score-audit index is not pinned to the current record for {input_id}."
            )
        approved_system_ids = {
            str(value) for value in audit_entry.get("approvedScoreSystemIds") or []
        }
        if not approved_system_ids:
            raise ExtractionWorkflowError(
                f"{input_id} has no approved score systems to qualify."
            )

        amendment_id = _stable_id(
            "score-audit-scope-amendment",
            batch_id,
            partition,
            input_id,
            expected_score_audit_decision_id,
            SCORE_AUDIT_SCOPE_SCHEMA_VERSION,
        )
        amendment_log_path = audit_dir / "score-audit-scope-amendments.jsonl"
        amendment_log = (
            _read_jsonl(amendment_log_path) if amendment_log_path.exists() else []
        )
        existing_amendment = next(
            (
                item
                for item in amendment_log
                if str(item.get("scoreAuditScopeAmendmentId") or "") == amendment_id
            ),
            None,
        )
        if existing_amendment is not None:
            current_scope = reviewed_record.get("scoreAuditApprovalScope") or {}
            if (
                current_scope.get("schemaVersion") != SCORE_AUDIT_SCOPE_SCHEMA_VERSION
                or current_scope.get("scoreRhythmTrainingEligible") is not False
            ):
                raise ExtractionWorkflowError(
                    f"The logged score-audit scope amendment is not current for {input_id}."
                )
            return {
                **copy.deepcopy(existing_amendment),
                "deduplicated": True,
                "sealedTestAccessed": False,
            }

        amended_at = _utc_now()
        amended_record = copy.deepcopy(reviewed_record)
        before_tab_digest = _reviewed_tab_facts_digest(amended_record)
        scope = _apply_pitch_only_score_audit_scope(
            amended_record,
            approved_system_ids,
            reviewer_reference=reviewer_reference,
        )
        amended_record["revision"] = int(reviewed_record.get("revision") or 1) + 1
        amended_record["scoreAuditScopeAmendment"] = {
            "schemaVersion": SCORE_AUDIT_SCOPE_SCHEMA_VERSION,
            "scoreAuditScopeAmendmentId": amendment_id,
            "scoreAuditDecisionId": expected_score_audit_decision_id,
            "reviewerReference": reviewer_reference,
            "amendedAt": amended_at,
            "priorReviewedRecordDigest": reviewed_digest,
            "priorTabApprovalPreserved": True,
        }
        if amended_record.get("scoreAudit"):
            amended_record["scoreAudit"]["approvalScope"] = copy.deepcopy(scope)
        if _reviewed_tab_facts_digest(amended_record) != before_tab_digest:
            raise ExtractionWorkflowError(
                f"The score-audit scope amendment changed reviewed tab facts for {input_id}."
            )
        approved_path = (
            review_dir
            / "approved-records"
            / f"{input_id}-r{amended_record['revision']}-score-scope-amended.json"
        )
        amended_digest = _sha256_json(amended_record)
        amendment = {
            "schemaVersion": SCORE_AUDIT_SCOPE_SCHEMA_VERSION,
            "scoreAuditScopeAmendmentId": amendment_id,
            "batchId": batch_id,
            "partition": partition,
            "inputId": input_id,
            "scoreAuditDecisionId": expected_score_audit_decision_id,
            "reviewerReference": reviewer_reference,
            "priorReviewedRecordDigest": reviewed_digest,
            "amendedReviewedRecordDigest": amended_digest,
            "approvedScoreSystemCount": len(approved_system_ids),
            "scoreEventCount": scope["scoreEventCount"],
            "eventAlignmentCount": scope["eventAlignmentCount"],
            "pitchToTabTrainingEligible": True,
            "scoreRhythmTrainingEligible": False,
            "priorTabApprovalPreserved": True,
            "amendedAt": amended_at,
            "deduplicated": False,
            "sealedTestAccessed": False,
        }

        _write_json(approved_path, amended_record)
        relative_path = str(approved_path.relative_to(output_root))
        page_entry.update(
            {
                "action": "score_audit_scope_amended",
                "recordRevision": amended_record["revision"],
                "reviewedRecordPath": relative_path,
                "reviewedRecordDigest": amended_digest,
                "priorReviewedRecordDigest": reviewed_digest,
                "scoreAuditApprovalScope": copy.deepcopy(scope),
                "pitchToTabTrainingEligible": True,
                "scoreRhythmTrainingEligible": False,
                "priorTabApprovalPreserved": True,
            }
        )
        audit_entry.update(
            {
                "reviewedRecordPath": relative_path,
                "reviewedRecordDigest": amended_digest,
                "priorReviewedRecordDigest": reviewed_digest,
                "scoreAuditApprovalScope": copy.deepcopy(scope),
                "pitchToTabTrainingEligible": True,
                "scoreRhythmTrainingEligible": False,
                "priorTabApprovalPreserved": True,
            }
        )
        page_index = sorted(page_index, key=lambda item: str(item.get("inputId") or ""))
        audit_index = sorted(audit_index, key=lambda item: str(item.get("inputId") or ""))
        _write_jsonl(page_index_path, page_index)
        _write_jsonl(audit_index_path, audit_index)
        _write_jsonl(amendment_log_path, amendment_log + [amendment])

        human_summary_path = review_dir / "human-review-summary.json"
        if human_summary_path.exists():
            human_summary = _read_json(human_summary_path)
            human_summary["approvedIndexDigest"] = _sha256_json(page_index)
            _write_json(human_summary_path, human_summary)
        score_summary_path = audit_dir / "score-audit-summary.json"
        if score_summary_path.exists():
            score_summary = _read_json(score_summary_path)
            score_summary["approvedIndexDigest"] = _sha256_json(audit_index)
            score_summary["pitchToTabTrainingEligible"] = True
            score_summary["scoreRhythmTrainingEligible"] = False
            _write_json(score_summary_path, score_summary)
        return amendment

    def apply_score_audit_corrections(
        self,
        batch_id: str,
        source: Path | str,
        *,
        partition: str = "discovery",
        dry_run: bool = False,
    ) -> dict[str, Any]:
        """Apply digest-pinned score corrections without granting score approval."""

        batch_dir, manifest, _work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        audit_dir = output_root / "review" / "score-audit"
        repair_root = audit_dir / "repair"
        source_path = Path(source).expanduser().resolve()
        plans = _read_jsonl(source_path)
        if not plans:
            raise ExtractionWorkflowError("The score-audit correction plan contains no corrections.")
        plan_digest = _sha256_json(plans)
        correction_log_path = audit_dir / "score-audit-correction-log.jsonl"
        existing_log = _read_jsonl(correction_log_path) if correction_log_path.exists() else []
        existing_for_plan = [
            item
            for item in existing_log
            if str(item.get("correctionPlanDigest") or "") == plan_digest
        ]
        if existing_for_plan:
            return {
                "schemaVersion": SCORE_AUDIT_CORRECTION_PLAN_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": partition,
                "correctionPlanDigest": plan_digest,
                "deduplicated": True,
                "dryRun": dry_run,
                "humanApprovalGranted": False,
                "priorTabApprovalsPreserved": all(
                    bool(item.get("priorTabApprovalPreserved", True))
                    for item in existing_for_plan
                ),
                "sealedTestAccessed": False,
            }
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))

        feedback_path = audit_dir / "score-audit-feedback.jsonl"
        feedback_rows = _read_jsonl(feedback_path) if feedback_path.exists() else []
        feedback_by_id = {
            str(item.get("scoreAuditFeedbackId") or ""): item
            for item in feedback_rows
            if item.get("scoreAuditFeedbackId")
        }
        for feedback_id, feedback in _combined_feedback_score_audit_bridge(
            output_root / "review"
        ).items():
            feedback_by_id.setdefault(feedback_id, feedback)
        approved_entries = {
            str(item.get("inputId") or ""): item
            for item in _read_jsonl(output_root / "review" / "approved-record-index.jsonl")
            if item.get("status") == "human_approved"
        }
        confirmation_path = (
            output_root / "review" / "feedback-correction-confirmation-decisions.jsonl"
        )
        confirmed_tab_entries: dict[str, dict[str, Any]] = {}
        if confirmation_path.exists():
            for item in _read_jsonl(confirmation_path):
                if item.get("status") != "confirm":
                    continue
                confirmed_tab_entries[str(item.get("inputId") or "")] = item
        index_path = repair_root / "score-repair-index.jsonl"
        existing_index = _read_jsonl(index_path) if index_path.exists() else []
        candidate_rows: list[dict[str, Any]] = []
        log_rows: list[dict[str, Any]] = []
        seen_inputs: set[str] = set()
        total_operations = 0

        for plan in plans:
            if plan.get("schemaVersion") != SCORE_AUDIT_CORRECTION_PLAN_SCHEMA_VERSION:
                raise ExtractionWorkflowError("Unsupported score-audit correction plan schema.")
            input_id = str(plan.get("inputId") or "")
            if not input_id or input_id in seen_inputs:
                raise ExtractionWorkflowError("Score-audit correction inputs must be unique.")
            seen_inputs.add(input_id)
            approved = approved_entries.get(input_id)
            if approved is None:
                confirmation = confirmed_tab_entries.get(input_id)
                machine_path = output_root / "pages" / f"{input_id}.json"
                machine_digest = (
                    _sha256_json(_read_json(machine_path)) if machine_path.exists() else ""
                )
                if (
                    confirmation is None
                    or str(confirmation.get("machineRecordDigest") or "") != machine_digest
                ):
                    raise ExtractionWorkflowError(
                        f"Score correction references unapproved {input_id!r}."
                    )
                base_digest = machine_digest
            else:
                base_digest = str(approved.get("reviewedRecordDigest") or "")
            current = _score_repair_candidate(
                output_root,
                input_id=input_id,
                base_reviewed_record_digest=base_digest,
            )
            if current is None:
                combined_dir = (
                    output_root / "review" / "combined-score-tab-audit"
                )
                expected_candidate_digest = str(
                    plan.get("expectedCandidateDigest") or ""
                )
                candidate_index_paths = sorted(
                    combined_dir.glob("score-candidate-index-*.jsonl"),
                    reverse=True,
                )
                canonical_index = combined_dir / "score-candidate-index.jsonl"
                if canonical_index.exists():
                    candidate_index_paths.append(canonical_index)
                for combined_index_path in candidate_index_paths:
                    entry = next(
                        (
                            item
                            for item in _read_jsonl(combined_index_path)
                            if str(item.get("inputId") or "") == input_id
                            and str(item.get("machineRecordDigest") or "") == base_digest
                            and str(item.get("candidateRecordDigest") or "")
                            == expected_candidate_digest
                        ),
                        None,
                    )
                    if entry is None:
                        continue
                    candidate_path = output_root / str(
                        entry.get("candidateRecordPath") or ""
                    )
                    if not candidate_path.exists():
                        continue
                    candidate = _read_json(candidate_path)
                    if _sha256_json(candidate) != expected_candidate_digest:
                        raise ExtractionWorkflowError(
                            f"Combined score candidate digest mismatch for {input_id}."
                        )
                    reviewed_tab_digest = str(
                        (candidate.get("scoreRepair") or {}).get(
                            "reviewedTabFactsDigest"
                        )
                        or _reviewed_tab_facts_digest(candidate)
                    )
                    current = (
                        candidate,
                        str(candidate_path.relative_to(output_root)),
                        {
                            **copy.deepcopy(entry),
                            "baseReviewedRecordDigest": base_digest,
                            "repairVersion": SCORE_REPAIR_VERSION,
                            "status": "candidate_ready",
                            "reviewedTabFactsDigest": reviewed_tab_digest,
                        },
                    )
                    break
            if current is None:
                raise ExtractionWorkflowError(f"Score correction has no current candidate for {input_id}.")
            current_candidate, _relative_path, current_entry = current
            current_digest = _sha256_json(current_candidate)
            if current_digest != str(plan.get("expectedCandidateDigest") or ""):
                raise ExtractionWorkflowError(
                    f"The score-repair candidate changed before correcting {input_id}."
                )
            feedback_ids = [str(value) for value in plan.get("scoreAuditFeedbackIds") or []]
            if not feedback_ids or len(set(feedback_ids)) != len(feedback_ids):
                raise ExtractionWorkflowError("Score correction feedback IDs must be unique and nonempty.")
            selected_feedback = []
            for feedback_id in feedback_ids:
                feedback = feedback_by_id.get(feedback_id)
                if feedback is None or str(feedback.get("inputId") or "") != input_id:
                    raise ExtractionWorkflowError(
                        f"Score correction references unknown feedback {feedback_id!r}."
                    )
                if str(feedback.get("auditedCandidateDigest") or "") != current_digest:
                    prior_feedback_ids = {
                        str(value)
                        for value in (
                            current_candidate.get("scoreAuditCorrection") or {}
                        ).get("scoreAuditFeedbackIds")
                        or []
                    }
                    if (
                        feedback_id not in prior_feedback_ids
                        or bool(current_candidate.get("humanApprovalComplete"))
                    ):
                        raise ExtractionWorkflowError(
                            "Score correction feedback does not pin the current candidate."
                        )
                    feedback = {
                        **copy.deepcopy(feedback),
                        "auditedCandidateDigest": current_digest,
                        "iterativeCorrectionOfCandidateDigest": str(
                            feedback.get("auditedCandidateDigest") or ""
                        ),
                    }
                selected_feedback.append(feedback)
            expected_feedback_pairs = {
                (str(item["scoreAuditFeedbackId"]), str(system.get("scoreSystemId") or ""))
                for item in selected_feedback
                for system in item.get("systemDecisions") or []
                if system.get("status") == "feedback"
            }
            expected_event_feedback_targets = {
                (str(item["scoreAuditFeedbackId"]), str(feedback_item.get("targetId") or ""))
                for item in selected_feedback
                for feedback_item in item.get("eventFeedback") or []
            }
            expected_accepted_system_ids = {
                str(system.get("scoreSystemId") or "")
                for item in selected_feedback
                for system in item.get("systemDecisions") or []
                if system.get("status") == "accept"
            }
            accepted_unchanged_system_ids = {
                str(value) for value in plan.get("acceptedUnchangedScoreSystemIds") or []
            }
            if accepted_unchanged_system_ids != expected_accepted_system_ids:
                raise ExtractionWorkflowError(
                    "The correction plan must preserve every accepted unchanged score system."
                )
            operations = plan.get("operations") or []
            if not isinstance(operations, list) or not operations:
                raise ExtractionWorkflowError("A score correction plan needs operations.")
            operation_pairs = {
                (str(item.get("scoreAuditFeedbackId") or ""), str(item.get("scoreSystemId") or ""))
                for item in operations
            }
            if operation_pairs != expected_feedback_pairs:
                raise ExtractionWorkflowError(
                    "Score correction operations must cover every feedback system."
                )
            if expected_event_feedback_targets:
                operation_targets = {
                    (
                        str(item.get("scoreAuditFeedbackId") or ""),
                        str(item.get("feedbackTargetId") or ""),
                    )
                    for item in operations
                }
                if operation_targets != expected_event_feedback_targets or len(operation_targets) != len(
                    operations
                ):
                    raise ExtractionWorkflowError(
                        "Score correction operations must cover every selected feedback item exactly once."
                    )

            candidate = copy.deepcopy(current_candidate)
            systems_by_id = {
                str(system.get("scoreSystemId") or ""): system
                for system in candidate.get("scoreSystems") or []
            }
            accepted_system_digests = {
                system_id: _sha256_json(systems_by_id[system_id])
                for system_id in accepted_unchanged_system_ids
                if system_id in systems_by_id
            }
            if set(accepted_system_digests) != accepted_unchanged_system_ids:
                raise ExtractionWorkflowError("An accepted unchanged score system is missing.")
            applied_operations: list[dict[str, Any]] = []
            corrected_system_ids: set[str] = set()
            targeted_tab_correction_system_ids: set[str] = set()
            targeted_tab_corrections: list[dict[str, Any]] = []
            for operation in operations:
                operation_type = str(operation.get("type") or "")
                operation_id = str(operation.get("operationId") or "")
                if not operation_id:
                    raise ExtractionWorkflowError(
                        "Every score correction operation needs an operationId."
                    )
                system_id = str(operation.get("scoreSystemId") or "")
                if system_id in accepted_unchanged_system_ids:
                    raise ExtractionWorkflowError("A score correction cannot alter an accepted score system.")
                system = systems_by_id.get(system_id)
                if system is None:
                    raise ExtractionWorkflowError(
                        f"Score correction references unknown system {system_id!r}."
                    )
                if operation_type == "replace_score_attack":
                    result = _replace_score_attack_from_review(system, operation)
                    result["feedbackTargetId"] = str(operation.get("feedbackTargetId") or "")
                    result["scoreAuditFeedbackId"] = str(
                        operation.get("scoreAuditFeedbackId") or ""
                    )
                    applied_operations.append(result)
                    corrected_system_ids.add(system_id)
                elif operation_type == "replace_score_system_attacks":
                    result = _replace_score_system_attacks_from_review(system, operation)
                    result["feedbackTargetId"] = str(operation.get("feedbackTargetId") or "")
                    result["scoreAuditFeedbackId"] = str(
                        operation.get("scoreAuditFeedbackId") or ""
                    )
                    applied_operations.append(result)
                    corrected_system_ids.add(system_id)
                elif operation_type in {
                    "acknowledge_excluded_score_duration",
                    "confirm_score_system_correction",
                }:
                    applied_operations.append(
                        {
                            "operationId": str(operation.get("operationId") or ""),
                            "type": operation_type,
                            "scoreSystemId": system_id,
                            "feedbackTargetId": str(operation.get("feedbackTargetId") or ""),
                            "evidenceClass": "explicit_text",
                            "reviewState": "recorded_no_score_fact_change",
                            "durationReviewState": (
                                "not_reviewed_excluded"
                                if operation_type == "acknowledge_excluded_score_duration"
                                else None
                            ),
                        }
                    )
                elif operation_type == "confirm_source_score_tab_discrepancy":
                    applied_operations.append(
                        {
                            "operationId": str(operation.get("operationId") or ""),
                            "type": operation_type,
                            "scoreSystemId": system_id,
                            "feedbackTargetId": str(operation.get("feedbackTargetId") or ""),
                            "expectedScorePitches": sorted(
                                {str(value) for value in operation.get("expectedScorePitches") or []}
                            ),
                            "expectedTabPitches": sorted(
                                {str(value) for value in operation.get("expectedTabPitches") or []}
                            ),
                            "expertTargetPitches": sorted(
                                {str(value) for value in operation.get("expertTargetPitches") or []}
                            ),
                            "reasonCode": str(
                                operation.get("reasonCode")
                                or "printed_score_tab_pitch_mismatch"
                            ),
                            "evidenceClass": "explicit_text",
                            "reviewState": "needs_human_review",
                            "eligibleForTransformationTraining": False,
                        }
                    )
                elif operation_type == "replace_tab_event_with_expert_solution":
                    feedback_id = str(operation.get("scoreAuditFeedbackId") or "")
                    applied, provenance = _replace_tab_event_from_score_audit(
                        candidate,
                        operation,
                        feedback_id=feedback_id,
                    )
                    applied_operations.append(applied)
                    targeted_tab_corrections.append(provenance)
                    targeted_tab_correction_system_ids.add(system_id)
                elif operation_type == "defer_cross_scope_conflict":
                    conflict = {
                        "kind": "score_audit_cross_scope_conflict",
                        "scoreSystemId": system_id,
                        "scoreAuditFeedbackId": str(
                            operation.get("scoreAuditFeedbackId") or ""
                        ),
                        "feedbackTargetId": str(operation.get("feedbackTargetId") or ""),
                        "targetDomain": str(operation.get("targetDomain") or "score_tab_alignment"),
                        "reasonCode": str(operation.get("reasonCode") or "requires_targeted_review"),
                        "evidenceClass": "explicit_text",
                        "reviewState": "unresolved",
                    }
                    candidate.setdefault("unresolved", []).append(conflict)
                    applied_operations.append(
                        {
                            "operationId": str(operation.get("operationId") or ""),
                            "type": operation_type,
                            "scoreSystemId": system_id,
                            "feedbackTargetId": conflict["feedbackTargetId"],
                            "targetDomain": conflict["targetDomain"],
                            "reasonCode": conflict["reasonCode"],
                            "evidenceClass": "explicit_text",
                            "reviewState": "unresolved",
                        }
                    )
                else:
                    raise ExtractionWorkflowError(
                        "Unsupported score-audit correction operation."
                    )

            if any(
                _sha256_json(systems_by_id[system_id]) != digest
                for system_id, digest in accepted_system_digests.items()
            ):
                raise ExtractionWorkflowError("An accepted unchanged score system was modified.")

            for system_id in corrected_system_ids:
                system = systems_by_id[system_id]
                normalized_score_digest = _sha256_json(
                    {
                        key: system.get(key)
                        for key in (
                            "measures",
                            "scoreEvents",
                            "chordContexts",
                            "tempoMarkings",
                            "repeatStructures",
                            "keyFifths",
                            "timeSignature",
                            "clef",
                        )
                    }
                )
                system_index = int(system.get("systemIndex") or 0)
                normalized_path = (
                    repair_root
                    / "normalized-musicxml"
                    / input_id
                    / f"system-{system_index:02d}"
                    / f"{normalized_score_digest}.musicxml"
                )
                metadata = _write_normalized_score_musicxml(system, normalized_path)
                metadata["relativePath"] = str(normalized_path.relative_to(output_root))
                system["musicXml"] = {
                    **metadata,
                    "repairVersion": SCORE_REPAIR_VERSION,
                    "normalizedScoreFactsDigest": normalized_score_digest,
                    "scoreAuditCorrectionPlanDigest": plan_digest,
                }
                system["reviewState"] = "needs_human_review"

            if targeted_tab_corrections:
                _revalidate_corrected_record(candidate, profile)
                correction_ids = {
                    str(item.get("targetedTabCorrectionId") or "")
                    for item in targeted_tab_corrections
                }
                corrected_event_ids = {
                    str(item.get("tabEventId") or "") for item in targeted_tab_corrections
                }
                for tab_system in candidate.get("tabSystems") or []:
                    for tab_event in tab_system.get("tabEvents") or []:
                        if str(tab_event.get("tabEventId") or "") not in corrected_event_ids:
                            continue
                        tab_event["evidenceClass"] = "explicit_text"
                        tab_event["reviewState"] = "needs_human_review"
                        tab_event["eligibleForTransformationTraining"] = False
                        for action in tab_event.get("steelActions") or []:
                            action["evidenceClass"] = "explicit_text"
                            action["reviewState"] = "needs_human_review"
                existing_corrections = [
                    copy.deepcopy(item)
                    for item in candidate.get("sourceTabCorrections") or []
                    if str(item.get("targetedTabCorrectionId") or "") not in correction_ids
                ]
                candidate["sourceTabCorrections"] = existing_corrections + targeted_tab_corrections
                for discrepancy in candidate.get("sourceScoreTabDiscrepancies") or []:
                    matching = next(
                        (
                            item
                            for item in targeted_tab_corrections
                            if str(item.get("tabEventId") or "")
                            in {str(value) for value in discrepancy.get("tabEventIds") or []}
                        ),
                        None,
                    )
                    if matching is not None:
                        discrepancy["resolutionState"] = (
                            "expert_corrected_normalized_tab_pending_review"
                        )
                        discrepancy["targetedTabCorrectionId"] = matching[
                            "targetedTabCorrectionId"
                        ]

            tab_by_id = {
                str(system.get("tabSystemId") or ""): system
                for system in candidate.get("tabSystems") or []
            }
            alignment_candidates: list[dict[str, Any]] = []
            for score_system in candidate.get("scoreSystems") or []:
                paired_tab = tab_by_id.get(str(score_system.get("pairedTabSystemId") or ""))
                if paired_tab is None:
                    raise ExtractionWorkflowError("A corrected score system lost its paired tab system.")
                alignment_candidates.extend(
                    _align_events(
                        score_system.get("scoreEvents") or [],
                        paired_tab.get("tabEvents") or [],
                    )
                )
            alignments, unresolved = _separate_verified_alignments(alignment_candidates)
            confirmed_discrepancies: list[dict[str, Any]] = []
            for operation in applied_operations:
                if operation.get("type") != "confirm_source_score_tab_discrepancy":
                    continue
                promoted, discrepancy = _promote_confirmed_source_discrepancy(
                    candidate,
                    unresolved,
                    operation,
                )
                alignments.append(promoted)
                confirmed_discrepancies.append(discrepancy)
            candidate["eventAlignments"] = alignments
            candidate["unresolved"] = [
                copy.deepcopy(item)
                for item in candidate.get("unresolved") or []
                if item.get("kind") != "unverified_score_tab_alignment"
                and not (
                    item.get("kind") == "score_audit_cross_scope_conflict"
                    and any(
                        str(item.get("scoreSystemId") or "")
                        == str(operation.get("scoreSystemId") or "")
                        and str(item.get("feedbackTargetId") or "")
                        == str(operation.get("feedbackTargetId") or "")
                        for operation in applied_operations
                        if operation.get("type") != "defer_cross_scope_conflict"
                    )
                )
            ] + [
                {**copy.deepcopy(item), "inputId": item.get("inputId") or input_id}
                for item in unresolved
            ]
            if confirmed_discrepancies:
                candidate["sourceScoreTabDiscrepancies"] = _merge_current_source_discrepancies(
                    candidate.get("sourceScoreTabDiscrepancies") or [],
                    confirmed_discrepancies,
                )
            candidate["validationSummary"] = {
                **copy.deepcopy(candidate.get("validationSummary") or {}),
                "soundingPitchAgreementCount": sum(
                    bool(alignment.get("soundingPitchAgreement")) for alignment in alignments
                ),
                "notationAdjustedPitchAgreementCount": sum(
                    bool(alignment.get("notationAdjustedPitchAgreement"))
                    for alignment in alignments
                ),
                "alignmentCount": len(alignments),
                "provenanceComplete": True,
                "rightsAndAccessComplete": True,
            }
            candidate["revision"] = int(current_candidate.get("revision") or 1) + 1
            candidate["reviewState"] = "needs_human_review"
            candidate["humanApprovalComplete"] = False
            all_targeted_tab_corrections = list(
                candidate.get("sourceTabCorrections") or []
            )
            all_targeted_tab_correction_ids = sorted(
                {
                    str(item.get("targetedTabCorrectionId") or "")
                    for item in all_targeted_tab_corrections
                    if item.get("targetedTabCorrectionId")
                }
            )
            all_targeted_tab_correction_system_ids = sorted(
                {
                    str(item.get("scoreSystemId") or "")
                    for item in all_targeted_tab_corrections
                    if item.get("scoreSystemId")
                }
            )
            candidate["scoreAuditCorrection"] = {
                "schemaVersion": SCORE_AUDIT_CORRECTION_PLAN_SCHEMA_VERSION,
                "correctionPlanDigest": plan_digest,
                "sourceCandidateDigest": current_digest,
                "scoreAuditFeedbackIds": feedback_ids,
                "acceptedUnchangedScoreSystemIds": sorted(accepted_unchanged_system_ids),
                "acceptedUnchangedScoreSystemDigests": accepted_system_digests,
                "operations": applied_operations,
                "correctedAt": _utc_now(),
                "humanScoreAuditRequired": True,
                "humanApprovalGranted": False,
                "targetedTabCorrectionSystemIds": all_targeted_tab_correction_system_ids,
                "targetedTabCorrectionIds": all_targeted_tab_correction_ids,
                "priorTabApprovalPreserved": not bool(all_targeted_tab_corrections),
                "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                    all_targeted_tab_corrections
                ),
            }
            reviewed_tab_digest = str(current_entry.get("reviewedTabFactsDigest") or "")
            corrected_tab_digest = _reviewed_tab_facts_digest(candidate)
            if targeted_tab_corrections:
                candidate.setdefault("scoreRepair", {})[
                    "priorReviewedTabFactsDigest"
                ] = reviewed_tab_digest
                candidate["scoreRepair"]["reviewedTabFactsDigest"] = corrected_tab_digest
                candidate["scoreRepair"]["priorTabApprovalPreserved"] = False
                candidate["scoreRepair"]["priorTabApprovalSupersededOnlyForTargetedEvents"] = True
            elif corrected_tab_digest != reviewed_tab_digest:
                raise ExtractionWorkflowError(f"Score correction changed reviewed tab facts for {input_id}.")
            diagnostics = _score_audit_diagnostics(candidate)
            gates = _score_audit_equivalence_gates(candidate, diagnostics)
            candidate_digest = _sha256_json(candidate)
            candidate_path = repair_root / "candidate-records" / input_id / f"{candidate_digest}.json"
            candidate_entry = {
                **copy.deepcopy(current_entry),
                "candidateRecordPath": str(candidate_path.relative_to(output_root)),
                "candidateRecordDigest": candidate_digest,
                "allGatesPassed": bool(gates)
                and all(bool(gate.get("readyForHumanReview")) for gate in gates.values()),
                "scoreAuditGatesBySystem": gates,
                "scoreAuditCorrectionPlanDigest": plan_digest,
                "status": "candidate_ready",
                "priorReviewedTabFactsDigest": (
                    reviewed_tab_digest
                    if targeted_tab_corrections
                    else current_entry.get("priorReviewedTabFactsDigest")
                ),
                "reviewedTabFactsDigest": corrected_tab_digest,
                "targetedTabCorrectionSystemIds": all_targeted_tab_correction_system_ids,
                "targetedTabCorrectionIds": all_targeted_tab_correction_ids,
                "priorTabApprovalPreserved": not bool(all_targeted_tab_corrections),
                "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                    all_targeted_tab_corrections
                ),
                "sealedTestAccessed": False,
            }
            candidate_rows.append(candidate_entry)
            log_rows.append(
                {
                    "schemaVersion": SCORE_AUDIT_CORRECTION_PLAN_SCHEMA_VERSION,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "correctionPlanDigest": plan_digest,
                    "sourceCandidateDigest": current_digest,
                    "correctedCandidateDigest": candidate_digest,
                    "scoreAuditFeedbackIds": feedback_ids,
                    "operationCount": len(applied_operations),
                    "allGatesPassed": candidate_entry["allGatesPassed"],
                    "humanApprovalGranted": False,
                    "targetedTabCorrectionCount": len(
                        all_targeted_tab_corrections
                    ),
                    "priorTabApprovalPreserved": not bool(
                        all_targeted_tab_corrections
                    ),
                    "priorTabApprovalSupersededOnlyForTargetedEvents": bool(
                        all_targeted_tab_corrections
                    ),
                    "sealedTestAccessed": False,
                    "appliedAt": _utc_now(),
                }
            )
            total_operations += len(applied_operations)
            if not dry_run and not candidate_path.exists():
                _write_json(candidate_path, candidate)

        if not dry_run:
            _write_jsonl(index_path, existing_index + candidate_rows)
            _write_jsonl(correction_log_path, existing_log + log_rows)
        return {
            "schemaVersion": SCORE_AUDIT_CORRECTION_PLAN_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "correctionPlanDigest": plan_digest,
            "correctedPageCount": len(candidate_rows),
            "operationCount": total_operations,
            "gatePassedPageCount": sum(bool(item.get("allGatesPassed")) for item in candidate_rows),
            "dryRun": dry_run,
            "deduplicated": False,
            "humanApprovalGranted": False,
            "priorTabApprovalsPreserved": all(
                bool(item.get("priorTabApprovalPreserved", True))
                for item in candidate_rows
            ),
            "targetedTabCorrectionPageCount": sum(
                not bool(item.get("priorTabApprovalPreserved", True))
                for item in candidate_rows
            ),
            "sealedTestAccessed": False,
        }

    def apply_review(
        self,
        batch_id: str,
        source: Path | str,
        *,
        partition: str = "discovery",
    ) -> dict[str, Any]:
        batch_dir, manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        source_path = Path(source).expanduser().resolve()
        decisions = _read_jsonl(source_path)
        if not decisions:
            raise ExtractionWorkflowError("The extraction review file contains no decisions.")
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        decision_log_path = review_dir / "human-review-decisions.jsonl"
        existing_decisions = _read_jsonl(decision_log_path) if decision_log_path.exists() else []
        feedback_log_path = review_dir / "human-review-feedback.jsonl"
        existing_feedback = _read_jsonl(feedback_log_path) if feedback_log_path.exists() else []
        existing_index_path = review_dir / "approved-record-index.jsonl"
        existing_index = _read_jsonl(existing_index_path) if existing_index_path.exists() else []
        index_by_input = {str(item["inputId"]): item for item in existing_index}
        logged_ids = {str(item["reviewDecisionId"]) for item in existing_decisions}
        logged_feedback_ids = {
            str(item["feedbackSubmissionId"])
            for item in existing_feedback
            if item.get("feedbackSubmissionId")
        }
        reviewed_machine_records = {
            (str(item["inputId"]), str(item["machineRecordDigest"])) for item in existing_decisions
        }
        work_by_input = {str(item["inputId"]): item for item in work}
        new_log_entries: list[dict[str, Any]] = []
        new_feedback_entries: list[dict[str, Any]] = []
        seen_inputs: set[str] = set()
        for decision in decisions:
            input_id = str(decision.get("inputId") or "")
            if input_id not in work_by_input:
                raise ExtractionWorkflowError(f"Review decision references unknown {partition} input {input_id!r}.")
            if input_id in seen_inputs:
                raise ExtractionWorkflowError(f"The review file contains multiple decisions for {input_id}.")
            seen_inputs.add(input_id)
            page_path = pages_dir / f"{input_id}.json"
            if not page_path.exists():
                raise ExtractionWorkflowError(f"Extraction record is missing for {input_id}.")
            machine_record = _read_json(page_path)
            machine_digest = _sha256_json(machine_record)
            expected_digest = str(decision.get("expectedMachineRecordDigest") or "")
            if expected_digest != machine_digest:
                raise ExtractionWorkflowError(f"The review decision for {input_id} targets a stale machine record.")
            action = str(decision.get("action") or "")
            if action not in {"accept", "feedback", "correct", "exclude"}:
                raise ExtractionWorkflowError(f"Unsupported extraction review action {action!r}.")
            reviewer_reference = str(decision.get("reviewerReference") or "").strip()
            if not reviewer_reference:
                raise ExtractionWorkflowError("Every extraction review decision requires a reviewerReference.")
            approved_sections = [str(value) for value in decision.get("approvedSections") or []]
            score_capture_complete = _score_tab_attack_counts_complete(machine_record)
            expected_approval_sections = (
                CORE_APPROVAL_SECTIONS if score_capture_complete else TAB_ONLY_APPROVAL_SECTIONS
            )
            if action in {"accept", "correct"} and set(approved_sections) != set(expected_approval_sections):
                raise ExtractionWorkflowError(
                    f"The review for {input_id} must explicitly approve its displayed review scope."
                )
            if action in {"feedback", "exclude"} and approved_sections:
                raise ExtractionWorkflowError(f"The {action} action cannot approve deterministic core sections.")
            reviewed_at = _utc_now()

            if action == "feedback":
                if input_id in index_by_input:
                    raise ExtractionWorkflowError(f"The page {input_id} already has a final review decision.")
                normalized_feedback = _normalized_event_feedback(
                    machine_record,
                    decision.get("eventFeedback"),
                    input_id=input_id,
                    machine_digest=machine_digest,
                )
                notes = str(decision.get("notes") or "").strip() or None
                if not normalized_feedback and notes is None:
                    raise ExtractionWorkflowError(
                        f"Feedback for {input_id} requires at least one targeted comment or a whole-page note."
                    )
                feedback_submission_id = str(
                    decision.get("feedbackSubmissionId")
                    or _stable_id(
                        "extraction-feedback-submission",
                        batch_id,
                        partition,
                        input_id,
                        machine_digest,
                        reviewer_reference,
                        normalized_feedback,
                        notes,
                    )
                )
                if feedback_submission_id in logged_feedback_ids:
                    raise ExtractionWorkflowError(f"Duplicate feedbackSubmissionId {feedback_submission_id}.")
                new_feedback_entries.append(
                    {
                        "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
                        "feedbackSubmissionId": feedback_submission_id,
                        "batchId": batch_id,
                        "partition": partition,
                        "inputId": input_id,
                        "machineRecordDigest": machine_digest,
                        "action": "feedback",
                        "reviewerReference": reviewer_reference,
                        "approvedSections": [],
                        "eventFeedback": normalized_feedback,
                        "notes": notes,
                        "submittedAt": reviewed_at,
                        "approvalEffect": "none",
                    }
                )
                logged_feedback_ids.add(feedback_submission_id)
                continue

            if (input_id, machine_digest) in reviewed_machine_records:
                raise ExtractionWorkflowError(
                    f"The machine record for {input_id} already has an immutable review decision."
                )
            if action == "accept" and any(
                str(item.get("inputId")) == input_id
                and str(item.get("machineRecordDigest")) == machine_digest
                for item in existing_feedback + new_feedback_entries
            ):
                raise ExtractionWorkflowError(
                    f"The current extraction for {input_id} has unresolved reviewer feedback and cannot be accepted as shown."
                )
            review_decision_id = str(
                decision.get("reviewDecisionId")
                or _stable_id(
                    "extraction-review", batch_id, partition, input_id, machine_digest, action, reviewer_reference
                )
            )
            if review_decision_id in logged_ids:
                raise ExtractionWorkflowError(f"Duplicate reviewDecisionId {review_decision_id}.")
            reviewed_record: dict[str, Any] | None = None
            if action == "correct":
                supplied = decision.get("correctedRecord")
                if not isinstance(supplied, Mapping):
                    raise ExtractionWorkflowError("A correct decision requires a full correctedRecord object.")
                reviewed_record = copy.deepcopy(dict(supplied))
                immutable_fields = (
                    "objectId",
                    "batchId",
                    "inputId",
                    "datasetPartition",
                    "sourceDocumentId",
                    "contentUnitId",
                    "assetSha256",
                )
                for field in immutable_fields:
                    if reviewed_record.get(field) != machine_record.get(field):
                        raise ExtractionWorkflowError(f"A corrected record cannot change immutable field {field}.")
                for field in ("sourceCopedent", "sourceStructure", "provenance", "rightsAndAccess", "derivative"):
                    if reviewed_record.get(field) != machine_record.get(field):
                        raise ExtractionWorkflowError(f"A corrected record cannot change protected field {field}.")
                _revalidate_corrected_record(reviewed_record, profile)
            elif action == "accept":
                reviewed_record = copy.deepcopy(machine_record)

            reviewed_record_path: str | None = None
            reviewed_record_digest: str | None = None
            if reviewed_record is not None:
                blockers = _hard_review_blockers(reviewed_record)
                if blockers:
                    kinds = ", ".join(str(item["kind"]) for item in blockers)
                    raise ExtractionWorkflowError(
                        f"The review for {input_id} cannot be approved until hard blockers are corrected: {kinds}."
                    )
                reviewed_record["revision"] = int(machine_record.get("revision") or 1) + 1
                score_capture_complete = _score_tab_attack_counts_complete(reviewed_record)
                approval_scope = (
                    "complete_page"
                    if score_capture_complete
                    else "tab_only_score_audit_required"
                )
                reviewed_record["reviewState"] = (
                    "human_approved"
                    if score_capture_complete
                    else "partially_human_approved"
                )
                reviewed_record["humanApprovalComplete"] = score_capture_complete
                reviewed_record["humanReview"] = {
                    "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
                    "reviewDecisionId": review_decision_id,
                    "reviewerReference": reviewer_reference,
                    "reviewedAt": reviewed_at,
                    "machineRecordDigest": machine_digest,
                    "approvedSections": list(
                        CORE_APPROVAL_SECTIONS
                        if score_capture_complete
                        else TAB_ONLY_APPROVAL_SECTIONS
                    ),
                    "approvalScope": approval_scope,
                    "scoreAuditRequired": not score_capture_complete,
                    "unresolvedExcludedFromTrainingCount": len(reviewed_record.get("unresolved") or []),
                }
                if score_capture_complete:
                    _mark_reviewed_objects(reviewed_record)
                else:
                    _mark_tab_only_reviewed_objects(reviewed_record)
                approved_dir = review_dir / "approved-records"
                approved_path = approved_dir / f"{input_id}-r{reviewed_record['revision']}.json"
                _write_json(approved_path, reviewed_record)
                reviewed_record_path = str(approved_path.relative_to(output_root))
                reviewed_record_digest = _sha256_json(reviewed_record)
                index_by_input[input_id] = {
                    "inputId": input_id,
                    "status": "human_approved",
                    "action": action,
                    "reviewDecisionId": review_decision_id,
                    "recordRevision": reviewed_record["revision"],
                    "reviewedRecordPath": reviewed_record_path,
                    "reviewedRecordDigest": reviewed_record_digest,
                    "assetSha256": reviewed_record["assetSha256"],
                    "approvalScope": approval_scope,
                    "scoreAuditRequired": not score_capture_complete,
                }
            else:
                index_by_input[input_id] = {
                    "inputId": input_id,
                    "status": "excluded",
                    "action": action,
                    "reviewDecisionId": review_decision_id,
                    "assetSha256": machine_record["assetSha256"],
                }
            log_entry = {
                "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
                "reviewDecisionId": review_decision_id,
                "batchId": batch_id,
                "partition": partition,
                "inputId": input_id,
                "machineRecordDigest": machine_digest,
                "action": action,
                "reviewerReference": reviewer_reference,
                "approvedSections": approved_sections,
                "notes": decision.get("notes"),
                "reviewedAt": reviewed_at,
                "reviewedRecordPath": reviewed_record_path,
                "reviewedRecordDigest": reviewed_record_digest,
                "approvalScope": (
                    index_by_input.get(input_id, {}).get("approvalScope")
                    if reviewed_record is not None
                    else "excluded"
                ),
            }
            new_log_entries.append(log_entry)
            logged_ids.add(review_decision_id)
            reviewed_machine_records.add((input_id, machine_digest))

        all_decisions = existing_decisions + new_log_entries
        all_feedback = existing_feedback + new_feedback_entries
        index = [index_by_input[key] for key in sorted(index_by_input)]
        _write_jsonl(decision_log_path, all_decisions)
        _write_jsonl(feedback_log_path, all_feedback)
        _write_jsonl(existing_index_path, index)
        total_pages = len(work)
        approved_count = sum(item["status"] == "human_approved" for item in index)
        tab_only_approved_count = sum(
            item.get("approvalScope") == "tab_only_score_audit_required" for item in index
        )
        excluded_count = sum(item["status"] == "excluded" for item in index)
        summary = {
            "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "totalPageCount": total_pages,
            "reviewedPageCount": len(index),
            "humanApprovedPageCount": approved_count,
            "tabOnlyApprovedPageCount": tab_only_approved_count,
            "excludedPageCount": excluded_count,
            "remainingPageCount": total_pages - len(index),
            "humanApprovalComplete": (
                len(index) == total_pages and tab_only_approved_count == 0
            ),
            "feedbackSubmissionCount": len(all_feedback),
            "feedbackPageCount": len({str(item["inputId"]) for item in all_feedback}),
            "feedbackLogDigest": _sha256_json(all_feedback),
            "decisionLogDigest": _sha256_json(all_decisions),
            "approvedIndexDigest": _sha256_json(index),
            "sealedTestAccessed": False,
        }
        _write_json(review_dir / "human-review-summary.json", summary)
        _mark_review_submission_applied(source_path, summary)
        return summary

    def apply_feedback_corrections(
        self,
        batch_id: str,
        source: Path | str,
        *,
        partition: str = "discovery",
        dry_run: bool = False,
    ) -> dict[str, Any]:
        """Apply digest-pinned machine corrections without granting human approval."""

        batch_dir, manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        source_path = Path(source).expanduser().resolve()
        plans = _read_jsonl(source_path)
        if not plans:
            raise ExtractionWorkflowError("The feedback correction plan contains no page corrections.")
        plan_digest = _sha256_json(plans)
        correction_log_path = review_dir / "machine-correction-log.jsonl"
        existing_log = _read_jsonl(correction_log_path) if correction_log_path.exists() else []
        existing_for_plan = [item for item in existing_log if item.get("correctionPlanDigest") == plan_digest]
        if existing_for_plan:
            return {
                "schemaVersion": FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION,
                "batchId": batch_id,
                "partition": partition,
                "correctionPlanDigest": plan_digest,
                "correctedPageCount": len(existing_for_plan),
                "deduplicated": True,
                "dryRun": dry_run,
                "humanApprovalGranted": False,
                "sealedTestAccessed": False,
            }

        feedback_log_path = review_dir / "human-review-feedback.jsonl"
        feedback_log = _read_jsonl(feedback_log_path) if feedback_log_path.exists() else []
        feedback_by_input: dict[str, list[dict[str, Any]]] = {}
        for submission in feedback_log:
            feedback_by_input.setdefault(str(submission.get("inputId") or ""), []).append(submission)
        combined_review_dir = review_dir / "combined-score-tab-audit"
        combined_feedback_path = combined_review_dir / "application" / "feedback-queue.jsonl"
        resolved_combined_feedback_ids = {
            str(feedback_item_id)
            for item in existing_log
            for feedback_item_id in (
                list(item.get("feedbackItemIds") or [])
                + [
                    value
                    for value in item.get("feedbackSubmissionIds") or []
                    if str(value).startswith("combined-score-tab-feedback-")
                ]
            )
        }
        if combined_feedback_path.exists():
            packet_cache: dict[str, dict[str, Any]] = {}
            for feedback in _read_jsonl(combined_feedback_path):
                if feedback.get("status") != "unresolved_requires_structured_correction":
                    continue
                input_id = str(feedback.get("inputId") or "")
                feedback_id = str(feedback.get("feedbackId") or "")
                if feedback_id in resolved_combined_feedback_ids:
                    continue
                feedback_packet_digest = str(feedback.get("packetDigest") or "")
                if not feedback_packet_digest:
                    raise ExtractionWorkflowError(
                        "A combined score/tab feedback item lost its packet digest."
                    )
                if feedback_packet_digest not in packet_cache:
                    try:
                        packet_cache[feedback_packet_digest], _ = _load_combined_score_tab_packet(
                            combined_review_dir,
                            feedback_packet_digest,
                        )
                    except ExtractionWorkflowError:
                        # Legacy feedback can predate immutable packet snapshots.  It must
                        # never be rebound to a later packet; an already-applied correction
                        # is identified above by its feedback ID, while an unresolved legacy
                        # item stays fail-closed until its original packet is restored.
                        continue
                combined_systems = {
                    (
                        str(system.get("inputId") or ""),
                        str(system.get("scoreSystemId") or ""),
                    ): system
                    for page in packet_cache[feedback_packet_digest].get("pages") or []
                    for system in page.get("systems") or []
                }
                packet_system = combined_systems.get(
                    (input_id, str(feedback.get("scoreSystemId") or ""))
                )
                if packet_system is None or not feedback_id:
                    raise ExtractionWorkflowError(
                        "A combined score/tab feedback item lost its packet provenance."
                    )
                feedback_by_input.setdefault(input_id, []).append(
                    {
                        "feedbackSubmissionId": feedback_id,
                        "inputId": input_id,
                        "machineRecordDigest": str(
                            packet_system.get("machineRecordDigest") or ""
                        ),
                        "notes": str(feedback.get("comment") or ""),
                        "eventFeedback": [
                            {
                                "feedbackItemId": feedback_id,
                                "targetType": "tab_system",
                                "targetId": str(feedback.get("tabSystemId") or ""),
                            }
                        ],
                        "source": "combined_score_tab_review",
                    }
                )
        final_index_path = review_dir / "approved-record-index.jsonl"
        final_index = _read_jsonl(final_index_path) if final_index_path.exists() else []
        finalized_inputs = {str(item.get("inputId") or "") for item in final_index}
        work_inputs = {str(item.get("inputId") or "") for item in work}
        profile = get_e9_copedent_profile(str(manifest["sourceCopedentId"]))
        corrected_records: dict[str, dict[str, Any]] = {}
        prior_records: dict[str, dict[str, Any]] = {}
        new_log_entries: list[dict[str, Any]] = []
        seen_inputs: set[str] = set()

        for plan in plans:
            if plan.get("schemaVersion") != FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION:
                raise ExtractionWorkflowError("Unsupported feedback correction plan schema version.")
            input_id = str(plan.get("inputId") or "")
            if input_id not in work_inputs:
                raise ExtractionWorkflowError(f"Correction plan references unknown {partition} input {input_id!r}.")
            if input_id in finalized_inputs:
                raise ExtractionWorkflowError(f"Correction plan cannot revise finalized input {input_id!r}.")
            if input_id in seen_inputs:
                raise ExtractionWorkflowError(f"Correction plan contains duplicate input {input_id!r}.")
            seen_inputs.add(input_id)
            page_path = pages_dir / f"{input_id}.json"
            machine_record = _read_json(page_path)
            machine_digest = _sha256_json(machine_record)
            if str(plan.get("expectedMachineRecordDigest") or "") != machine_digest:
                raise ExtractionWorkflowError(f"Correction plan targets a stale machine record for {input_id}.")
            matching_feedback = [
                item
                for item in feedback_by_input.get(input_id, [])
                if str(item.get("machineRecordDigest") or "") == machine_digest
            ]
            if not matching_feedback:
                raise ExtractionWorkflowError(f"Correction plan for {input_id} has no current reviewer feedback.")
            expected_submission_ids = {str(item["feedbackSubmissionId"]) for item in matching_feedback}
            supplied_submission_ids = {str(value) for value in plan.get("feedbackSubmissionIds") or []}
            if supplied_submission_ids != expected_submission_ids:
                raise ExtractionWorkflowError(
                    f"Correction plan for {input_id} does not pin every current feedback submission."
                )
            expected_feedback_items = {
                str(item["feedbackItemId"])
                for submission in matching_feedback
                for item in submission.get("eventFeedback") or []
            }
            operations = list(plan.get("operations") or [])
            if not operations:
                raise ExtractionWorkflowError(f"Correction plan for {input_id} contains no operations.")
            covered_feedback_items = {
                str(feedback_item_id)
                for operation in operations
                for feedback_item_id in operation.get("feedbackItemIds") or []
            }
            if covered_feedback_items != expected_feedback_items:
                missing = len(expected_feedback_items - covered_feedback_items)
                extra = len(covered_feedback_items - expected_feedback_items)
                raise ExtractionWorkflowError(
                    f"Correction plan feedback coverage mismatch for {input_id}: {missing} missing, {extra} extra."
                )
            has_page_note = any(str(item.get("notes") or "").strip() for item in matching_feedback)
            if has_page_note and not bool(plan.get("acknowledgedPageNote")):
                raise ExtractionWorkflowError(f"Correction plan for {input_id} does not acknowledge its page note.")

            corrected = copy.deepcopy(machine_record)
            protected = {
                field: copy.deepcopy(corrected.get(field))
                for field in (
                    "objectId",
                    "batchId",
                    "inputId",
                    "datasetPartition",
                    "sourceDocumentId",
                    "contentUnitId",
                    "assetSha256",
                    "sourceCopedent",
                    "sourceStructure",
                    "provenance",
                    "rightsAndAccess",
                    "derivative",
                )
            }
            for operation in operations:
                operation_feedback_ids = [str(value) for value in operation.get("feedbackItemIds") or []]
                if not set(operation_feedback_ids).issubset(expected_feedback_items):
                    raise ExtractionWorkflowError("Correction operation references unrelated feedback evidence.")
                _apply_feedback_correction_operation(
                    corrected,
                    operation,
                    feedback_item_ids=operation_feedback_ids,
                )
            for field, value in protected.items():
                if corrected.get(field) != value:
                    raise ExtractionWorkflowError(f"Feedback correction cannot change protected field {field}.")
            _reindex_corrected_tab_events(corrected)
            try:
                _revalidate_corrected_record(corrected, profile)
            except ExtractionWorkflowError as exc:
                raise ExtractionWorkflowError(
                    f"Corrected machine record for {input_id} failed deterministic decoding: {exc}"
                ) from exc
            blockers = _hard_review_blockers(corrected)
            if blockers:
                kinds = ", ".join(str(item.get("kind")) for item in blockers)
                raise ExtractionWorkflowError(
                    f"Corrected machine record for {input_id} still has hard blockers: {kinds}."
                )
            corrected["revision"] = int(machine_record.get("revision") or 1) + 1
            corrected["eventExecutionSchemaVersion"] = EVENT_EXECUTION_SCHEMA_VERSION
            corrected["reviewState"] = "needs_human_review"
            corrected["humanApprovalComplete"] = False
            corrected.pop("humanReview", None)
            correction_id = _stable_id(
                "machine-feedback-correction",
                batch_id,
                partition,
                input_id,
                machine_digest,
                plan_digest,
            )
            corrected["machineCorrection"] = {
                "schemaVersion": FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION,
                "correctionId": correction_id,
                "correctionPlanDigest": plan_digest,
                "priorMachineRecordDigest": machine_digest,
                "feedbackSubmissionIds": sorted(expected_submission_ids),
                "feedbackItemIds": sorted(expected_feedback_items),
                "operationCount": len(operations),
                "evidenceClass": "direct_visual_observation",
                "reviewState": "needs_human_review",
                "humanApprovalGranted": False,
            }
            corrected_digest = _sha256_json(corrected)
            prior_records[input_id] = machine_record
            corrected_records[input_id] = corrected
            new_log_entries.append(
                {
                    "schemaVersion": FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION,
                    "correctionId": correction_id,
                    "batchId": batch_id,
                    "partition": partition,
                    "inputId": input_id,
                    "priorMachineRecordDigest": machine_digest,
                    "correctedMachineRecordDigest": corrected_digest,
                    "correctionPlanDigest": plan_digest,
                    "feedbackSubmissionIds": sorted(expected_submission_ids),
                    "feedbackItemIds": sorted(expected_feedback_items),
                    "feedbackItemCount": len(expected_feedback_items),
                    "operationCount": len(operations),
                    "humanApprovalGranted": False,
                    "correctedAt": _utc_now(),
                }
            )

        result = {
            "schemaVersion": FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "correctionPlanDigest": plan_digest,
            "correctedPageCount": len(corrected_records),
            "feedbackItemCount": sum(int(item["feedbackItemCount"]) for item in new_log_entries),
            "operationCount": sum(int(item["operationCount"]) for item in new_log_entries),
            "deduplicated": False,
            "dryRun": dry_run,
            "humanApprovalGranted": False,
            "sealedTestAccessed": False,
        }
        if dry_run:
            return result

        revisions_root = review_dir / "machine-record-revisions"
        for input_id, corrected in corrected_records.items():
            prior_record = prior_records[input_id]
            prior_digest = _sha256_json(prior_record)
            prior_revision = int(prior_record.get("revision") or 1)
            prior_path = (
                revisions_root
                / input_id
                / f"revision-{prior_revision:04d}-{prior_digest}.json"
            )
            if prior_path.exists():
                if _sha256_json(_read_json(prior_path)) != prior_digest:
                    raise ExtractionWorkflowError(
                        f"Archived machine revision digest mismatch for {input_id}."
                    )
            else:
                _write_json(prior_path, prior_record)
            _write_json(pages_dir / f"{input_id}.json", corrected)
        _write_jsonl(correction_log_path, existing_log + new_log_entries)
        summary_path = output_root / "summary.json"
        extraction_summary = _read_json(summary_path)
        extraction_summary["feedbackCorrections"] = {
            "schemaVersion": FEEDBACK_CORRECTION_PLAN_SCHEMA_VERSION,
            "correctionPlanDigest": plan_digest,
            "correctedPageCount": len(corrected_records),
            "humanApprovalGranted": False,
            "reviewState": "needs_human_review",
        }
        _write_json(summary_path, extraction_summary)
        return result

    def review_metrics(self, batch_id: str, *, partition: str = "discovery") -> dict[str, Any]:
        batch_dir, _manifest, work = self._batch_paths(batch_id, partition)
        output_root = batch_dir / "extraction" / partition
        pages_dir = output_root / "pages"
        review_dir = output_root / "review"
        index = _read_jsonl(review_dir / "approved-record-index.jsonl")
        index_by_input = {str(item["inputId"]): item for item in index}
        score_audit_index_path = review_dir / "score-audit" / "approved-score-index.jsonl"
        score_audit_by_input = {
            str(item.get("inputId") or ""): item
            for item in (_read_jsonl(score_audit_index_path) if score_audit_index_path.exists() else [])
            if item.get("status") == "human_approved"
        }
        totals: Counter[str] = Counter()
        approved_page_count = 0
        corrected_page_count = 0
        excluded_page_count = 0
        score_audit_eligible_page_count = 0
        score_audited_page_count = 0
        for item in work:
            input_id = str(item["inputId"])
            review = index_by_input.get(input_id)
            if review is None:
                continue
            if review.get("status") == "excluded":
                excluded_page_count += 1
                continue
            reviewed_path_value = str(review.get("reviewedRecordPath") or "")
            expected_digest = str(review.get("reviewedRecordDigest") or "")
            reviewed_path = output_root / reviewed_path_value
            if not reviewed_path_value or not reviewed_path.exists():
                raise ExtractionWorkflowError(f"Approved review record is missing for {input_id}.")
            reviewed_record = _read_json(reviewed_path)
            if _sha256_json(reviewed_record) != expected_digest:
                raise ExtractionWorkflowError(f"Approved review digest mismatch for {input_id}.")
            if reviewed_record.get("scoreSystems"):
                score_audit_eligible_page_count += 1
                audit = score_audit_by_input.get(input_id)
                if audit and str(audit.get("reviewedRecordDigest") or "") == expected_digest:
                    score_audited_page_count += 1
            machine_record = _read_json(pages_dir / f"{input_id}.json")
            totals.update(_review_record_counts(machine_record, reviewed_record))
            approved_page_count += 1
            corrected_page_count += review.get("action") == "correct"

        reviewed_page_count = approved_page_count + excluded_page_count
        score_audit_complete = score_audited_page_count == score_audit_eligible_page_count

        def ratio(numerator: str, denominator: str, *, empty: float = 1.0) -> float:
            value = int(totals[denominator])
            return round(int(totals[numerator]) / value, 6) if value else empty

        score_system_tp = int(totals["scoreSystemsTruePositive"])
        tab_system_tp = int(totals["tabSystemsTruePositive"])
        system_tp = score_system_tp + tab_system_tp
        system_predicted = int(totals["scoreSystemsPredicted"] + totals["tabSystemsPredicted"])
        system_reference = int(totals["scoreSystemsReference"] + totals["tabSystemsReference"])
        metrics = {
            "pageOrientationAccuracy": ratio("pageOrientationExact", "pageOrientationReference"),
            "systemDetectionF1AtIou80": round(_f1(system_tp, system_predicted, system_reference), 6),
            "scoreTabSystemPairingAccuracy": ratio("scoreTabPairingExact", "scoreTabPairingReference"),
            "measureAlignmentAccuracy": ratio("measureAlignmentExact", "scoreEventReference"),
            "stringRecognitionAccuracy": ratio("stringExact", "tabActionReference"),
            "fretRecognitionAccuracy": ratio("fretExact", "tabActionReference"),
            "pedalLeverRecognitionAccuracy": ratio("controlsExact", "tabActionReference"),
            "scorePitchAccuracy": ratio("scorePitchExact", "scoreEventReference"),
            "scoreDurationAccuracyDiagnostic": ratio(
                "scoreDurationExact", "scoreEventReference"
            ),
            "scorePitchDurationAccuracyDiagnostic": ratio(
                "scorePitchAndDurationExact", "scoreEventReference"
            ),
            "chordContextAccuracy": ratio("chordContextExact", "chordContextReference"),
            "soundingPitchAgreement": ratio(
                "notationAdjustedPitchAgreement",
                "approvedAlignmentReference",
            ),
            "approvedMechanicalValidity": ratio(
                "approvedMechanicalAction",
                "approvedMechanicalActionReference",
            ),
            "conceptAcceptanceWithoutEditRate": round(
                int(totals["conceptPageAcceptedWithoutEdit"]) / max(1, approved_page_count),
                6,
            ),
            "provenanceCompleteness": round(
                int(totals["provenanceCompletePage"]) / max(1, approved_page_count),
                6,
            ),
            "rightsAccessCompleteness": round(
                int(totals["rightsCompletePage"]) / max(1, approved_page_count),
                6,
            ),
            "atomicFieldManualCorrectionRate": ratio(
                "atomicFieldChanged",
                "atomicFieldReference",
                empty=0.0,
            ),
            "eventAlignmentManualCorrectionRate": round(
                1.0 - ratio("eventAlignmentExact", "eventAlignmentReference"),
                6,
            ),
            "pageManualCorrectionRate": round(
                corrected_page_count / max(1, reviewed_page_count),
                6,
            ),
        }
        acceptance = {
            "pageOrientation": metrics["pageOrientationAccuracy"] == 1.0,
            "systemDetection": score_audit_complete and metrics["systemDetectionF1AtIou80"] >= 0.95,
            "scoreTabPairing": score_audit_complete and metrics["scoreTabSystemPairingAccuracy"] >= 0.98,
            "measureAlignment": score_audit_complete and metrics["measureAlignmentAccuracy"] >= 0.95,
            "stringAndFret": (
                metrics["stringRecognitionAccuracy"] >= 0.98 and metrics["fretRecognitionAccuracy"] >= 0.98
            ),
            "pedalLever": metrics["pedalLeverRecognitionAccuracy"] >= 0.95,
            "scorePitch": score_audit_complete and metrics["scorePitchAccuracy"] >= 0.97,
            "chordContext": score_audit_complete and metrics["chordContextAccuracy"] >= 0.95,
            "soundingPitch": score_audit_complete and metrics["soundingPitchAgreement"] >= 0.98,
            "mechanicalValidity": metrics["approvedMechanicalValidity"] == 1.0,
            "conceptAcceptance": metrics["conceptAcceptanceWithoutEditRate"] >= 0.8,
            "provenanceAndRights": (
                metrics["provenanceCompleteness"] == 1.0 and metrics["rightsAccessCompleteness"] == 1.0
            ),
            "atomicCorrectionRate": metrics["atomicFieldManualCorrectionRate"] <= 0.15,
            "alignmentCorrectionRate": metrics["eventAlignmentManualCorrectionRate"] <= 0.25,
        }
        result = {
            "schemaVersion": EXTRACTION_REVIEW_SCHEMA_VERSION,
            "batchId": batch_id,
            "partition": partition,
            "pageCount": len(work),
            "reviewedPageCount": reviewed_page_count,
            "humanApprovedPageCount": approved_page_count,
            "correctedPageCount": corrected_page_count,
            "excludedPageCount": excluded_page_count,
            "remainingPageCount": len(work) - reviewed_page_count,
            "humanApprovalComplete": reviewed_page_count == len(work),
            "scoreAuditEligiblePageCount": score_audit_eligible_page_count,
            "scoreAuditedPageCount": score_audited_page_count,
            "scoreAuditComplete": score_audit_complete,
            "scoreMetricsRequireExplicitAudit": True,
            "scoreDurationIsDiagnosticOnly": True,
            "metrics": metrics,
            "acceptance": acceptance,
            "allAcceptanceCriteriaPassed": reviewed_page_count == len(work) and all(acceptance.values()),
            "sealedTestAccessed": False,
        }
        _write_json(review_dir / "review-metrics.json", result)
        return result

    def _extract_page(
        self,
        manifest: Mapping[str, Any],
        item: Mapping[str, Any],
        *,
        page_number: int,
        output_root: Path,
        derivatives_dir: Path,
        profile: Any,
        run_digest: str,
        use_ocr: bool,
        use_omr: bool,
        use_tab_vision: bool,
        rights_and_access: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        source_path = Path(str(manifest["sourceRoot"])) / str(item["relativePath"])
        if not source_path.exists() or _sha256_bytes(source_path.read_bytes()) != item["sha256"]:
            raise ExtractionWorkflowError("The immutable source asset is missing or changed.")
        page_id = _stable_id("source-page", manifest["batchId"], item["inputId"], item["sha256"])
        with Image.open(source_path) as raw:
            normalized = ImageOps.exif_transpose(raw).convert("RGB")
        gray = np.asarray(normalized.convert("L"))
        gray, skew_angle = _deskew(gray)
        normalized = Image.fromarray(gray).convert("RGB")
        derivative_path = derivatives_dir / f"{item['inputId']}.jpg"
        normalized.save(derivative_path, format="JPEG", quality=94, optimize=True, exif=b"")
        os.chmod(derivative_path, 0o600)
        derivative_sha = _sha256_bytes(derivative_path.read_bytes())
        width, height = normalized.size
        grids = detect_tab_grids(gray)
        unresolved: list[dict[str, Any]] = []
        ocr_lines: list[dict[str, Any]] = []
        if use_ocr:
            try:
                raw_ocr = self.ocr.read(derivative_path)
                for index, item_ocr in enumerate(raw_ocr, start=1):
                    x = float(item_ocr.get("x") or 0.0) * width
                    y = (1.0 - float(item_ocr.get("y") or 0.0) - float(item_ocr.get("height") or 0.0)) * height
                    region = _normalized_region(
                        x,
                        y,
                        float(item_ocr.get("width") or 0.0) * width,
                        float(item_ocr.get("height") or 0.0) * height,
                        width,
                        height,
                    )
                    ocr_lines.append(
                        {
                            "explicitTextId": _stable_id("explicit-text", page_id, index, item_ocr.get("text")),
                            "pageRegionId": _stable_id("page-region", page_id, "explicit-text", index),
                            "text": str(item_ocr.get("text") or ""),
                            "confidence": round(float(item_ocr.get("confidence") or 0.0), 4),
                            "pageRegion": region,
                            "evidenceClass": "explicit_text",
                            "extractor": "apple-vision",
                            "reviewState": "needs_human_review",
                        }
                    )
            except ExtractionWorkflowError as exc:
                unresolved.append(
                    {
                        "kind": "page_ocr_failure",
                        "message": str(exc),
                        "blocking": False,
                        "evidenceClass": "unknown_or_unresolved",
                    }
                )
        score_systems: list[dict[str, Any]] = []
        tab_systems: list[dict[str, Any]] = []
        all_tab_events: list[dict[str, Any]] = []
        previous_grid_bottom = 0
        for system_index, grid in enumerate(grids, start=1):
            tab_system_id = _stable_id("tab-system", page_id, system_index, grid.x0, grid.y0, grid.x1, grid.y1)
            tab_region_id = _stable_id("page-region", page_id, "tab-system", system_index)
            tab_region = _normalized_region(grid.x0, grid.y0, grid.x1 - grid.x0, grid.y1 - grid.y0, width, height)
            tab_measure_boundaries = _tab_measure_boundaries(grid)
            tab_measures = [
                {
                    "tabMeasureId": _stable_id("tab-measure", tab_system_id, measure_index),
                    "measure": measure_index,
                    "horizontalStart": round(left / max(1, grid.x1 - grid.x0), 7),
                    "horizontalEnd": round(right / max(1, grid.x1 - grid.x0), 7),
                    "evidenceClass": "direct_visual_observation",
                    "confidence": grid.confidence,
                    "reviewState": "needs_human_review",
                }
                for measure_index, (left, right) in enumerate(
                    zip(tab_measure_boundaries, tab_measure_boundaries[1:], strict=False),
                    start=1,
                )
            ]
            candidates = _tab_event_candidates(gray, grid)
            tab_events: list[dict[str, Any]] = []
            token_cells: dict[str, dict[str, Any]] = {}
            contact_sheet_records: list[dict[str, Any]] = []
            if use_tab_vision and candidates:
                sheets = _contact_sheets(
                    normalized,
                    grid,
                    candidates,
                    output_root / "contact-sheets" / str(item["inputId"]),
                    system_index,
                )
                for sheet in sheets:
                    try:
                        values = self._read_tab_cells(sheet)
                        token_cells.update(values)
                        contact_sheet_records.append(
                            {
                                "relativePath": str(sheet["path"].relative_to(output_root)),
                                "sha256": _sha256_bytes(sheet["path"].read_bytes()),
                                "labels": sheet["labels"],
                            }
                        )
                    except ExtractionWorkflowError as exc:
                        unresolved.append(
                            {
                                "kind": "tab_cell_vision_failure",
                                "tabSystemId": tab_system_id,
                                "message": str(exc),
                                "blocking": True,
                                "evidenceClass": "unknown_or_unresolved",
                            }
                        )
            candidate_event_records: list[dict[str, Any]] = []
            next_event_index = 1
            for candidate in candidates:
                action_sequences: dict[int, list[dict[str, Any]]] = {}
                candidate_issues: list[dict[str, Any]] = []
                tab_measure, measure_position = _tab_measure_context(grid, int(candidate["x"]))
                for string in candidate["candidateStrings"]:
                    label = f"e{candidate['eventIndex']}s{string}"
                    cell = token_cells.get(label, {"token": None, "confidence": 0.0, "uncertain": True})
                    region_id = _stable_id("page-region", tab_system_id, candidate["eventIndex"], string)
                    sequence, issue = _tab_action_sequence_from_cell(
                        cell,
                        string=int(string),
                        profile=profile,
                        region_id=region_id,
                    )
                    if sequence:
                        center_y = grid.string_centers[int(string) - 1]
                        for action in sequence:
                            action["pageRegion"] = _normalized_region(
                                grid.x0 + int(candidate["x"]) - grid.cell_height * 2,
                                center_y - grid.cell_height * 0.5,
                                grid.cell_height * 4,
                                grid.cell_height,
                                width,
                                height,
                            )
                        action_sequences[int(string)] = sequence
                    if issue is not None:
                        candidate_issues.append(
                            {
                                **issue,
                                "inputId": item["inputId"],
                                "tabSystemId": tab_system_id,
                                "sourceCandidateEventIndex": int(candidate["eventIndex"]),
                                "horizontalPosition": round(
                                    int(candidate["x"]) / max(1, grid.x1 - grid.x0),
                                    7,
                                ),
                            }
                        )
                sequence_length = max((len(sequence) for sequence in action_sequences.values()), default=0)
                if candidate_issues:
                    unresolved.extend(candidate_issues)
                elif sequence_length == 0:
                    unresolved.append(
                        {
                            "kind": "unresolved_tab_event_candidate",
                            "inputId": item["inputId"],
                            "tabSystemId": tab_system_id,
                            "sourceCandidateEventIndex": int(candidate["eventIndex"]),
                            "horizontalPosition": round(
                                int(candidate["x"]) / max(1, grid.x1 - grid.x0),
                                7,
                            ),
                            "candidateStrings": list(candidate["candidateStrings"]),
                            "candidateMeaning": "printed_event_column_with_no_recognized_tab_state",
                            "evidenceClass": "unknown_or_unresolved",
                            "blocking": True,
                        }
                    )
                candidate_event_records.append(
                    {
                        "sourceCandidateEventIndex": int(candidate["eventIndex"]),
                        "horizontalPosition": round(int(candidate["x"]) / max(1, grid.x1 - grid.x0), 7),
                        "candidateStrings": list(candidate["candidateStrings"]),
                        "recognizedStrings": sorted(action_sequences),
                        "recognizedSequenceLength": sequence_length,
                        "recognitionState": "recognized" if sequence_length else "unresolved",
                        "evidenceClass": "direct_visual_observation",
                        "reviewState": "needs_human_review",
                    }
                )
                for sequence_step in range(sequence_length):
                    actions: list[dict[str, Any]] = []
                    for string, sequence in sorted(action_sequences.items()):
                        if sequence_step < len(sequence):
                            action = copy.deepcopy(sequence[sequence_step])
                        else:
                            action = copy.deepcopy(sequence[-1])
                            action["attack"] = False
                            action["sustain"] = True
                            action["sourceSequenceStep"] = sequence_step + 1
                            action["steelActionId"] = _stable_id(
                                "steel-action-sustain",
                                action.get("steelActionId"),
                                sequence_step + 1,
                            )
                        actions.append(action)
                    event_id = _stable_id(
                        "tab-event",
                        tab_system_id,
                        candidate["eventIndex"],
                        sequence_step + 1,
                    )
                    event = {
                        "tabEventId": event_id,
                        "eventIndex": next_event_index,
                        "sourceCandidateEventIndex": int(candidate["eventIndex"]),
                        "sourceSequenceStep": sequence_step + 1,
                        "sourceSequenceLength": sequence_length,
                        "measure": tab_measure,
                        "measureHorizontalPosition": measure_position,
                        "horizontalPosition": round(int(candidate["x"]) / max(1, grid.x1 - grid.x0), 7),
                        "candidateStrings": candidate["candidateStrings"],
                        "steelActions": actions,
                        "simultaneous": len(actions) > 1,
                        "gripId": _stable_id("grip", event_id) if len(actions) > 1 else None,
                        "evidenceClass": "direct_visual_observation",
                        "confidence": round(min([float(item["confidence"]) for item in actions] or [0.0]), 4),
                        "reviewState": "needs_human_review",
                    }
                    _refresh_event_execution(event)
                    tab_events.append(event)
                    all_tab_events.append(event)
                    next_event_index += 1
            tab_systems.append(
                {
                    "tabSystemId": tab_system_id,
                    "pageRegionId": tab_region_id,
                    "systemIndex": system_index,
                    "pageRegion": tab_region,
                    "lineCount": len(grid.line_ys),
                    "barlineHorizontalPositions": [
                        round((value - grid.x0) / max(1, grid.x1 - grid.x0), 7)
                        for value in grid.barline_xs
                        if grid.x0 <= value <= grid.x1
                    ],
                    "measures": tab_measures,
                    "stringCenters": [round(value, 3) for value in grid.string_centers],
                    "detectionConfidence": grid.confidence,
                    "tabEvents": tab_events,
                    "tabEventCandidates": candidate_event_records,
                    "highRecallCandidateCount": len(candidate_event_records),
                    "expandedMovementEventCount": sum(
                        max(0, int(candidate.get("recognizedSequenceLength") or 0) - 1)
                        for candidate in candidate_event_records
                    ),
                    "eventCounts": {
                        "printedCandidateColumns": len(candidate_event_records),
                        "recognizedSoundingStates": len(tab_events),
                        "pickedStates": sum(
                            1
                            for event in tab_events
                            if any(bool(action.get("attack", True)) for action in event.get("steelActions") or [])
                        ),
                        "movementOnlyStates": sum(
                            1 for event in tab_events if event.get("executionType") == "movement_only"
                        ),
                        "unresolvedCandidateColumns": sum(
                            1
                            for candidate in candidate_event_records
                            if candidate.get("recognitionState") == "unresolved"
                        ),
                    },
                    "contactSheets": contact_sheet_records,
                    "evidenceClass": "direct_visual_observation",
                    "reviewState": "needs_human_review",
                }
            )
            score_height = max(int(grid.cell_height * 13), int((grid.y1 - grid.y0) * 1.35))
            score_y1 = max(previous_grid_bottom, grid.y0 - max(4, int(grid.cell_height * 0.35)))
            score_y0 = max(previous_grid_bottom, score_y1 - score_height)
            previous_grid_bottom = grid.y1 + max(4, int(grid.cell_height * 0.4))
            if score_y1 - score_y0 < max(80, grid.cell_height * 5):
                continue
            score_system_id = _stable_id("score-system", page_id, system_index, score_y0, score_y1)
            score_region_id = _stable_id("page-region", page_id, "score-system", system_index)
            score_crop_path = (
                output_root / "score-crops" / str(item["inputId"]) / f"score-system-{system_index:02d}.png"
            )
            score_crop_path.parent.mkdir(parents=True, exist_ok=True)
            os.chmod(score_crop_path.parent, 0o700)
            normalized.crop((0, score_y0, width, score_y1)).save(score_crop_path, format="PNG")
            os.chmod(score_crop_path, 0o600)
            score_omr_crop_path = (
                output_root / "score-omr-crops" / str(item["inputId"]) / f"score-system-{system_index:02d}.png"
            )
            omr_prepared_derivative: dict[str, Any] | None = None
            music_xml: dict[str, Any] | None = None
            score_payload: dict[str, Any] = {
                "measures": [],
                "scoreEvents": [],
                "chordContexts": [],
                "tempoMarkings": [],
                "repeatStructures": [],
                "keyFifths": None,
                "timeSignature": None,
            }
            omr_status = "not_requested"
            if use_omr:
                try:
                    omr_prepared_derivative = _prepare_score_omr_crop(
                        score_crop_path,
                        score_omr_crop_path,
                        grid=grid,
                        tab_events=tab_events,
                    )
                    omr_prepared_derivative["relativePath"] = str(score_omr_crop_path.relative_to(output_root))
                    score_payload = self.omr.read(
                        score_omr_crop_path,
                        output_root / "omr-v13" / str(item["inputId"]) / f"system-{system_index:02d}",
                        score_system_id,
                    )
                    raw_music_xml_path = score_payload.pop("_musicXmlPath", None)
                    if raw_music_xml_path:
                        music_xml_path = Path(str(raw_music_xml_path)).resolve()
                        music_xml = {
                            "relativePath": str(music_xml_path.relative_to(output_root.resolve())),
                            "sha256": _sha256_bytes(music_xml_path.read_bytes()),
                            "format": music_xml_path.suffix.lower().lstrip("."),
                            "reader": "audiveris-musicxml-v1",
                        }
                    omr_status = "machine_extracted"
                except ExtractionWorkflowError as exc:
                    omr_status = "needs_human_review"
                    unresolved.append(
                        {
                            "kind": "score_omr_failure",
                            "scoreSystemId": score_system_id,
                            "message": str(exc),
                            "blocking": True,
                            "evidenceClass": "unknown_or_unresolved",
                        }
                    )
            score_systems.append(
                {
                    "scoreSystemId": score_system_id,
                    "pageRegionId": score_region_id,
                    "systemIndex": system_index,
                    "pairedTabSystemId": tab_system_id,
                    "pageRegion": _normalized_region(0, score_y0, width, score_y1 - score_y0, width, height),
                    "cropSha256": _sha256_bytes(score_crop_path.read_bytes()),
                    "omrPreparedDerivative": omr_prepared_derivative,
                    "musicXml": music_xml,
                    "omrStatus": omr_status,
                    **score_payload,
                    "scoreAttackCount": len(_score_attack_groups(score_payload.get("scoreEvents", []))),
                    "reviewState": "needs_human_review",
                }
            )
        tab_systems_by_id = {str(system["tabSystemId"]): system for system in tab_systems}
        alignment_candidates: list[dict[str, Any]] = []
        for score_system in score_systems:
            paired_tab = tab_systems_by_id.get(str(score_system.get("pairedTabSystemId")))
            if paired_tab is None:
                continue
            alignment_candidates.extend(
                _align_events(
                    score_system.get("scoreEvents", []),
                    paired_tab.get("tabEvents", []),
                )
            )
        alignments, alignment_unresolved = _separate_verified_alignments(alignment_candidates)
        unresolved.extend(
            {**candidate, "inputId": candidate.get("inputId") or item["inputId"]}
            for candidate in alignment_unresolved
        )
        page_classification = _classify_page(ocr_lines, grids, tab_systems)
        grip_candidates = _derive_grips(tab_systems)
        grips, grip_unresolved, ineligible_grip_events = _separate_verified_grips(grip_candidates)
        _mark_grip_event_eligibility(tab_systems, ineligible_grip_events)
        unresolved.extend(
            {**candidate, "inputId": candidate.get("inputId") or item["inputId"]}
            for candidate in grip_unresolved
        )
        movement_sequences = _derive_movement_sequences(tab_systems, page_id)
        concepts = _derive_teaching_concepts(ocr_lines, tab_systems, movement_sequences, page_id)
        exercises = _derive_exercises(page_classification, ocr_lines, tab_systems, concepts, page_id)
        decision_record_context = {
            "batchId": manifest["batchId"],
            "inputId": item["inputId"],
            "datasetPartition": item["datasetPartition"],
            "sourceDocumentId": item["sourceDocumentId"],
            "sourceStructure": copy.deepcopy(item.get("structuralMetadata") or {}),
            "pageClassification": page_classification,
            "scoreSystems": score_systems,
            "tabSystems": tab_systems,
            "eventAlignments": alignments,
            "movementSequences": movement_sequences,
            "teachingConcepts": concepts,
            "unresolved": unresolved,
        }
        derived_decisions = derive_decision_annotations(decision_record_context, profile)
        page_regions = _collect_page_regions(page_id, ocr_lines, score_systems, tab_systems)
        if not grids:
            unresolved.append(
                {
                    "kind": "no_tab_grid_detected",
                    "inputId": item["inputId"],
                    "blocking": False,
                    "evidenceClass": "direct_visual_observation",
                }
            )
        mechanical_actions = [action for event in all_tab_events for action in event.get("steelActions", [])]
        return {
            "schemaVersion": EXTRACTION_SCHEMA_VERSION,
            "knowledgeSchemaVersion": KNOWLEDGE_SCHEMA_VERSION,
            "extractorVersion": EXTRACTOR_VERSION,
            "runDigest": run_digest,
            "objectId": page_id,
            "revision": 1,
            "batchId": manifest["batchId"],
            "inputId": item["inputId"],
            "datasetPartition": item["datasetPartition"],
            "sourceDocumentId": item["sourceDocumentId"],
            "contentUnitId": item["contentUnitId"],
            "assetSha256": item["sha256"],
            "sourceStructure": copy.deepcopy(item.get("structuralMetadata") or {}),
            "sourceCopedent": {
                "id": profile.id,
                "revision": profile.revision,
                "digest": _profile_digest(profile),
            },
            "provenance": {
                "sourcePageId": page_id,
                "imageFilename": item["relativePath"],
                "assetSha256": item["sha256"],
                "pageNumberInBatch": page_number,
                "extractedAt": _utc_now(),
                "extractorVersion": EXTRACTOR_VERSION,
            },
            "rightsAndAccess": _normalized_rights_and_access(rights_and_access),
            "derivative": {
                "relativePath": str(derivative_path.relative_to(output_root)),
                "sha256": derivative_sha,
                "width": width,
                "height": height,
                "exifStripped": True,
                "deskewDegrees": skew_angle,
                "coordinateTransformRetained": True,
            },
            "pageOrientation": {
                "upright": True,
                "orientation": "landscape" if width > height else "portrait",
                "exifOrientationApplied": True,
                "deskewDegrees": skew_angle,
                "evidenceClass": "direct_visual_observation",
                "confidence": 0.98,
                "reviewState": "needs_human_review",
            },
            "pageClassification": page_classification,
            "pageRegions": page_regions,
            "explicitText": ocr_lines,
            "scoreSystems": score_systems,
            "tabSystems": tab_systems,
            "grips": grips,
            "eventAlignments": alignments,
            "movementSequences": movement_sequences,
            "derivedDecisions": derived_decisions,
            "teachingConcepts": concepts,
            "exercises": exercises,
            "validationSummary": {
                "steelActionCount": len(mechanical_actions),
                "mechanicallyValidCount": sum(
                    bool(action.get("mechanicalValidation", {}).get("valid")) for action in mechanical_actions
                ),
                "soundingPitchAgreementCount": sum(
                    bool(alignment.get("soundingPitchAgreement")) for alignment in alignments
                ),
                "notationAdjustedPitchAgreementCount": sum(
                    bool(alignment.get("notationAdjustedPitchAgreement")) for alignment in alignments
                ),
                "alignmentCount": len(alignments),
                "provenanceComplete": True,
                "rightsAndAccessComplete": True,
            },
            "unresolved": unresolved,
            "reviewState": "needs_human_review",
            "humanApprovalComplete": False,
        }


